/// Validate request fields the PR 4 orchestrator and stage bodies rely on.
pub fn validate_request(req: &PipelineRequest) -> Result<(), RequestValidationError> {
    if req.container.as_os_str().is_empty() {
        return Err(RequestValidationError::MissingContainer);
    }
    if !req.container.exists() {
        return Err(RequestValidationError::MissingContainer);
    }
    if !req.container.is_file() && !req.container.is_dir() {
        return Err(RequestValidationError::InvalidOutputRoot(format!(
            "container is neither a regular file nor a directory: {}",
            req.container.display()
        )));
    }

    validate_root_dir(&req.output_root, "output_root")?;
    validate_root_dir(&req.log.root, "log.root")?;
    if req.naming.template.trim().is_empty() {
        return Err(RequestValidationError::InvalidTemplate(
            "template must not be empty".to_string(),
        ));
    }
    validate_template(&req.naming.template).map_err(RequestValidationError::InvalidTemplate)?;
    if let Some(folder_template) = &req.naming.folder_template {
        validate_template(folder_template).map_err(RequestValidationError::InvalidTemplate)?;
    }

    match &req.source.track_selection {
        TrackSelection::All => {}
        TrackSelection::Range { start, end } => {
            if *start == 0 || *end == 0 || start > end {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "invalid track selection range {start}..={end}"
                )));
            }
        }
        TrackSelection::Set(set) => {
            if set.is_empty() || set.iter().any(|n| *n == 0) {
                return Err(RequestValidationError::InvalidStagePolicy(
                    "track selection set must contain positive track numbers".to_string(),
                ));
            }
        }
    }

    if let Some(password) = &req.source.archive_password {
        if password.expose().is_empty() {
            return Err(RequestValidationError::InvalidSecretState(
                "archive password is present but empty".to_string(),
            ));
        }
    }

    if let MetadataTextOverride::Set(value) = &req.metadata_overrides.album_artist {
        if value.trim().is_empty() {
            return Err(RequestValidationError::InvalidStagePolicy(
                "album-artist override must be non-empty when set".to_string(),
            ));
        }
    }

    for override_set in &req.archive_metadata_overrides {
        if override_set.source_ordinal == 0 {
            return Err(RequestValidationError::InvalidStagePolicy(
                "archive metadata override source_ordinal must be positive".to_string(),
            ));
        }
        if override_set.relative_path.as_os_str().is_empty()
            || override_set.relative_path.is_absolute()
            || override_set.relative_path.components().any(|component| {
                matches!(
                    component,
                    Component::Prefix(_) | Component::RootDir | Component::ParentDir
                )
            })
        {
            return Err(RequestValidationError::InvalidStagePolicy(format!(
                "archive metadata override path must be a safe relative path: {}",
                override_set.relative_path.display()
            )));
        }
        if !override_set.has_changes() {
            return Err(RequestValidationError::InvalidStagePolicy(
                "archive metadata override must contain at least one changed field".to_string(),
            ));
        }
    }

    if let Some(album_batch) = &req.album_batch {
        validate_album_batch_context(album_batch)
            .map_err(RequestValidationError::InvalidStagePolicy)?;
        let track = req.album_batch_track.as_ref().ok_or_else(|| {
            RequestValidationError::InvalidStagePolicy(
                "album_batch requests must also carry album_batch_track for pre-materialization failure fragments".to_string(),
            )
        })?;
        validate_album_batch_track_context(track)
            .map_err(RequestValidationError::InvalidStagePolicy)?;
    }

    Ok(())
}

fn validate_album_batch_context(album_batch: &AlbumBatchContext) -> Result<(), String> {
    if album_batch.conversion_log_batch_id.trim().is_empty() {
        return Err("album_batch.conversion_log_batch_id must not be empty".to_string());
    }
    if !is_generated_conversion_log_batch_id(album_batch.conversion_log_batch_id.trim()) {
        return Err("album_batch.conversion_log_batch_id must be a run-unique id generated for this album dispatch attempt".to_string());
    }
    if album_batch.expected_track_count == 0 {
        return Err("album_batch.expected_track_count must be greater than zero".to_string());
    }
    if album_batch.album_output_dir.as_os_str().is_empty() {
        return Err("album_batch.album_output_dir must not be empty".to_string());
    }
    if album_batch.source_grouping_root.as_os_str().is_empty() {
        return Err("album_batch.source_grouping_root must not be empty".to_string());
    }
    Ok(())
}

fn validate_album_batch_track_context(track: &AlbumBatchTrackContext) -> Result<(), String> {
    if track.source_ordinal == 0 {
        return Err("album_batch_track.source_ordinal must be greater than zero".to_string());
    }
    if track.track_number == 0 {
        return Err("album_batch_track.track_number must be greater than zero".to_string());
    }
    Ok(())
}

/// Detect source kind for PR 4. Later PRs add CUE image and SACD ISO arms.
pub fn detect_source_kind(req: &PipelineRequest) -> Result<SourceKind, SourceDetectError> {
    let ext = req
        .container
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    let name = req
        .container
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();

    if is_sacd_iso_candidate(req)? {
        return Ok(SourceKind::SacdIso);
    }
    if is_dvda_candidate(req)? {
        return Ok(SourceKind::DvdAudio);
    }
    if is_dvdv_candidate(req)? {
        return Ok(SourceKind::DvdVideo);
    }
    if is_bluray_candidate(req)? {
        return Ok(SourceKind::BluRay);
    }
    if !matches!(req.source.cue_sidecar, CueSidecarPolicy::IgnoreCue) && is_cue_image_candidate(req)? {
        return Ok(SourceKind::CueImage);
    }
    if matches!(ext.as_str(), "7z" | "zip" | "rar" | "tar" | "iso" | "cab" | "dmg" | "tgz" | "tbz2" | "txz")
        || name.ends_with(".tar.gz")
        || name.ends_with(".tar.bz2")
        || name.ends_with(".tar.xz")
        || name.ends_with(".tar.zst")
        || name.ends_with(".tar.lz")
        || name.ends_with(".tar.lzma")
    {
        return Ok(SourceKind::Archive);
    }
    if is_single_audio_extension(&ext) {
        return Ok(SourceKind::SingleFile);
    }
    Err(SourceDetectError::UnknownSource)
}

fn is_single_audio_extension(ext: &str) -> bool {
    matches!(
        ext,
        "flac" | "wav" | "wave" | "aiff" | "aif" | "aifc" | "wv" | "mp3" | "m4a" | "mp4"
            | "aac" | "opus" | "ogg" | "ape" | "w64" | "rf64" | "dsf" | "dff"
    )
}

/// Generate a run-unique conversion-log batch id for one album dispatch
/// attempt. The id is intentionally not derived from artist/album/path tags;
/// stale fragments from a crashed or cancelled run must not be eligible for a
/// later retry of the same album with the same output directory and settings.
fn new_conversion_log_batch_id() -> String {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|value| value.as_nanos())
        .unwrap_or_default();
    let sequence = CONVERSION_LOG_BATCH_ID_COUNTER.fetch_add(1, Ordering::Relaxed);
    format!(
        "{CONVERSION_LOG_BATCH_ID_PREFIX}-{:x}-{:x}-{:x}",
        std::process::id(),
        nanos,
        sequence
    )
}

fn is_generated_conversion_log_batch_id(value: &str) -> bool {
    let Some(suffix) = value
        .strip_prefix(CONVERSION_LOG_BATCH_ID_PREFIX)
        .and_then(|value| value.strip_prefix('-'))
    else {
        return false;
    };
    let mut parts = suffix.split('-');
    let Some(process_or_test) = parts.next() else { return false; };
    let Some(nonce) = parts.next() else { return false; };
    let Some(sequence) = parts.next() else { return false; };
    if parts.next().is_some() {
        return false;
    }
    [process_or_test, nonce, sequence]
        .into_iter()
        .all(|part| !part.is_empty() && part.as_bytes().iter().all(u8::is_ascii_hexdigit))
}

/// Build the production album-batch contract for independent single-file
/// folder dispatch and attach it to every per-track request before scheduler
/// enqueue. This is the only supported way for folder batches to enter
/// fragment-backed conversion-log mode; individual track jobs must not infer
/// album completion from tags or from their one prepared source track.
///
/// A fresh `conversion_log_batch_id` is generated for every call. Callers must
/// not pass a deterministic artist/album/path id, because a rerun of the same
/// album after a crash could otherwise reuse old fragments and assemble early.
///
/// Every request must already carry a dispatcher-authored
/// `AlbumBatchTrackContext`. This helper deliberately refuses to synthesize a
/// track number from request enumeration order, because filesystem and queue
/// iteration order are not authoritative album track order.
#[derive(serde::Serialize)]
struct IndependentSingleFileBatchLifecycleContract<'a> {
    actions: &'a ActionPipeline,
    failure_policy: &'a FailurePolicy,
    publish: &'a PublishPolicy,
    log: &'a LogPolicy,
    stages: &'a StagePolicy,
    companion: &'a CompanionCopyPolicy,
    metadata_overrides: &'a RequestMetadataOverrides,
    merge: bool,
    source_track_selection: &'a TrackSelection,
}

/// Canonical compatibility identity for every per-item policy that can affect
/// album-level election, participant drain, cleanup, or visible terminal
/// semantics. Folder dispatch must split requests when this value differs.
pub(crate) fn independent_single_file_album_batch_lifecycle_key(
    req: &PipelineRequest,
) -> Result<String, RequestValidationError> {
    serde_json::to_string(&IndependentSingleFileBatchLifecycleContract {
        actions: &req.actions,
        failure_policy: &req.failure_policy,
        publish: &req.publish,
        log: &req.log,
        stages: &req.stages,
        companion: &req.companion,
        metadata_overrides: &req.metadata_overrides,
        merge: req.merge,
        source_track_selection: &req.source.track_selection,
    })
    .map_err(|error| {
        RequestValidationError::InvalidStagePolicy(format!(
            "could not serialize independent album-batch lifecycle contract: {error}"
        ))
    })
}

pub fn prepare_independent_single_file_album_batch_for_dispatch(
    requests: Vec<PipelineRequest>,
    album_output_dir: PathBuf,
    source_grouping_root: PathBuf,
) -> Result<AlbumBatchDispatch, RequestValidationError> {
    prepare_independent_single_file_album_batch_for_dispatch_with_batch_id(
        requests,
        new_conversion_log_batch_id(),
        album_output_dir,
        source_grouping_root,
    )
}

/// Internal/test hook for constructing explicit old/new run identities. The
/// production dispatch entry point above always generates a fresh id.
fn prepare_independent_single_file_album_batch_for_dispatch_with_batch_id(
    requests: Vec<PipelineRequest>,
    conversion_log_batch_id: impl Into<String>,
    album_output_dir: PathBuf,
    source_grouping_root: PathBuf,
) -> Result<AlbumBatchDispatch, RequestValidationError> {
    prepare_independent_single_file_album_batch_for_dispatch_with_policy(
        requests,
        conversion_log_batch_id.into(),
        album_output_dir,
        source_grouping_root,
        AlbumBatchOrdering::ProvenTrackOrder,
        true,
    )
}

pub(crate) fn prepare_independent_single_file_album_batch_for_completion_order_dispatch(
    requests: Vec<PipelineRequest>,
    album_output_dir: PathBuf,
    source_grouping_root: PathBuf,
) -> Result<AlbumBatchDispatch, RequestValidationError> {
    prepare_independent_single_file_album_batch_for_dispatch_with_policy(
        requests,
        new_conversion_log_batch_id(),
        album_output_dir,
        source_grouping_root,
        AlbumBatchOrdering::CompletionOrder,
        false,
    )
}

/// Structural safety net for an already-grouped independent single-file album.
///
/// The queue dispatcher has already established that these requests are siblings
/// for one album output root. This helper intentionally re-checks only the
/// invariants needed to make shared publication safe, rather than rerunning all
/// request validation that caused the primary completion-order dispatch to fail.
/// It never widens grouping or publish collision policy.
pub(crate) fn prepare_verified_single_file_album_batch_completion_order_fallback(
    mut requests: Vec<PipelineRequest>,
    album_output_dir: PathBuf,
    source_grouping_root: PathBuf,
) -> Result<AlbumBatchDispatch, RequestValidationError> {
    if requests.is_empty() {
        return Err(RequestValidationError::InvalidStagePolicy(
            "completion-order fallback requires at least one request".to_string(),
        ));
    }

    let normalized_grouping_root = normalize_path(&source_grouping_root);
    let mut source_paths = Vec::with_capacity(requests.len());
    for request in &requests {
        match detect_source_kind(request) {
            Ok(SourceKind::SingleFile) => {}
            Ok(kind) => {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "completion-order fallback accepts only independent single-file jobs, got {kind:?} for {}",
                    request.container.display()
                )));
            }
            Err(error) => {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "completion-order fallback could not classify {}: {error}",
                    request.container.display()
                )));
            }
        }
        let Some(track) = request.album_batch_track.as_ref() else {
            return Err(RequestValidationError::InvalidStagePolicy(format!(
                "completion-order fallback for {} requires dispatcher-supplied album_batch_track",
                request.item_id
            )));
        };
        if track.source_ordinal == 0 || track.track_number == 0 {
            return Err(RequestValidationError::InvalidStagePolicy(format!(
                "completion-order fallback track context for {} must use nonzero source_ordinal and track_number",
                request.item_id
            )));
        }
        if request.album_batch.is_some() {
            return Err(RequestValidationError::InvalidStagePolicy(format!(
                "completion-order fallback for {} refuses to replace an existing album_batch",
                request.item_id
            )));
        }
        let normalized_container = normalize_path(&request.container);
        if normalized_container != normalized_grouping_root
            && !path_is_under_root(&normalized_container, &normalized_grouping_root)
        {
            return Err(RequestValidationError::InvalidStagePolicy(format!(
                "completion-order fallback source {} is not under source grouping root {}",
                normalized_container.display(),
                normalized_grouping_root.display()
            )));
        }
        source_paths.push(normalized_container);
    }

    let mut album_batch = AlbumBatchContext::from_dispatcher_source_count(
        new_conversion_log_batch_id(),
        requests.len(),
        album_output_dir,
        source_grouping_root,
    )
    .map_err(RequestValidationError::InvalidStagePolicy)?
    .with_source_paths(source_paths)
    .with_ordering(AlbumBatchOrdering::CompletionOrder);
    if let Some(identity) = requests
        .iter()
        .find_map(|request| request.batch_resolved_identity.clone())
    {
        album_batch = album_batch.with_resolved_identity(identity);
    }

    for request in &mut requests {
        request.album_batch = Some(album_batch.clone());
        request.expected_album_track_count = None;
        request.suppress_incremental_conversion_log_append = false;
    }

    Ok(AlbumBatchDispatch {
        album_batch,
        requests,
    })
}

fn prepare_independent_single_file_album_batch_for_dispatch_with_policy(
    mut requests: Vec<PipelineRequest>,
    conversion_log_batch_id: String,
    album_output_dir: PathBuf,
    source_grouping_root: PathBuf,
    ordering: AlbumBatchOrdering,
    require_uniform_lifecycle: bool,
) -> Result<AlbumBatchDispatch, RequestValidationError> {
    if requests.is_empty() {
        return Err(RequestValidationError::InvalidStagePolicy(
            "independent single-file album batch dispatch requires at least one request".to_string(),
        ));
    }

    if !is_generated_conversion_log_batch_id(&conversion_log_batch_id) {
        return Err(RequestValidationError::InvalidStagePolicy(
            "conversion_log_batch_id must be generated per album dispatch attempt; deterministic album/path ids are not allowed".to_string(),
        ));
    }

    if require_uniform_lifecycle {
        let expected_lifecycle = independent_single_file_album_batch_lifecycle_key(&requests[0])?;
        for request in requests.iter().skip(1) {
            let lifecycle = independent_single_file_album_batch_lifecycle_key(request)?;
            if lifecycle != expected_lifecycle {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "independent single-file album batch contains incompatible action/lifecycle policy at {}; requests must be split before ordered-fragment dispatch",
                    request.container.display()
                )));
            }
        }
    }

    let mut expected_track_count = 0_usize;
    for req in &requests {
        let kind = detect_source_kind(req).map_err(|err| {
            RequestValidationError::InvalidStagePolicy(format!(
                "album batch fragment dispatch could not classify {} as a supported source: {err}",
                req.container.display()
            ))
        })?;
        expected_track_count = expected_track_count
            .checked_add(dispatcher_album_batch_expected_track_count(req, kind)?)
            .ok_or_else(|| {
                RequestValidationError::InvalidStagePolicy(
                    "album batch expected track count overflowed usize".to_string(),
                )
            })?;
    }
    if expected_track_count == 0 {
        return Err(RequestValidationError::InvalidStagePolicy(
            "album batch dispatch requires at least one expected source track".to_string(),
        ));
    }
    let normalized_grouping_root = normalize_path(&source_grouping_root);
    let batch_source_paths = requests
        .iter()
        .map(|req| normalize_path(&req.container))
        .collect::<Vec<_>>();
    let resolved_identity = requests
        .iter()
        .find_map(|req| req.batch_resolved_identity.clone());
    let mut album_batch = AlbumBatchContext::from_dispatcher_source_count(
        conversion_log_batch_id,
        expected_track_count,
        album_output_dir,
        source_grouping_root,
    )
    .map_err(RequestValidationError::InvalidStagePolicy)?;
    if let Some(identity) = resolved_identity {
        album_batch = album_batch.with_resolved_identity(identity);
    }
    album_batch = album_batch
        .with_source_paths(batch_source_paths)
        .with_ordering(ordering);

    for req in requests.iter_mut() {
        let Some(dispatcher_track_context) = req.album_batch_track.clone() else {
            return Err(RequestValidationError::InvalidStagePolicy(format!(
                "album batch fragment dispatch for {} requires dispatcher-supplied album_batch_track; refusing to invent track order from request enumeration",
                req.item_id
            )));
        };
        if dispatcher_track_context.source_ordinal == 0 || dispatcher_track_context.track_number == 0 {
            return Err(RequestValidationError::InvalidStagePolicy(format!(
                "album batch track context for {} must use nonzero source_ordinal and track_number",
                req.item_id
            )));
        }

        match detect_source_kind(req) {
            Ok(SourceKind::SingleFile | SourceKind::CueImage) => {}
            Ok(kind) => {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "album batch fragment dispatch accepts only independent single-file or CUE-image jobs, got {kind:?} for {}",
                    req.container.display()
                )));
            }
            Err(err) => {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "album batch fragment dispatch could not classify {} as a supported album-batch source: {err}",
                    req.container.display()
                )));
            }
        }

        let normalized_container = normalize_path(&req.container);
        if normalized_container != normalized_grouping_root
            && !path_is_under_root(&normalized_container, &normalized_grouping_root)
        {
            return Err(RequestValidationError::InvalidStagePolicy(format!(
                "album batch source {} is not under source grouping root {}",
                normalized_container.display(),
                normalized_grouping_root.display()
            )));
        }

        if let Some(existing) = &req.album_batch {
            if existing != &album_batch {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "request {} already has a different album_batch; refusing to mix dispatcher contracts",
                    req.item_id
                )));
            }
        }

        req.album_batch = Some(album_batch.clone());
        req.album_batch_track = Some(dispatcher_track_context);
        // The dispatcher-authored AlbumBatchContext is authoritative. Clear the
        // deprecated compatibility field so downstream code and tests cannot
        // accidentally treat it as a second completion threshold.
        req.expected_album_track_count = None;
        validate_request(req)?;
    }

    Ok(AlbumBatchDispatch {
        album_batch,
        requests,
    })
}

fn dispatcher_album_batch_expected_track_count(
    req: &PipelineRequest,
    kind: SourceKind,
) -> Result<usize, RequestValidationError> {
    match kind {
        SourceKind::SingleFile => Ok(1),
        SourceKind::CueImage => {
            let cue = crate::convert::cue_parser::parse_cue_file(&req.container).map_err(|err| {
                RequestValidationError::InvalidStagePolicy(format!(
                    "album batch CUE source {} could not be parsed for expected track count: {err}",
                    req.container.display()
                ))
            })?;
            let count = selected_album_batch_cue_track_count(
                cue.tracks.len(),
                &req.source.track_selection,
                &req.container,
            )?;
            Ok(count)
        }
        other => Err(RequestValidationError::InvalidStagePolicy(format!(
            "album batch fragment dispatch does not support source kind {other:?} for {}",
            req.container.display()
        ))),
    }
}


fn selected_album_batch_cue_track_count(
    track_count: usize,
    selection: &TrackSelection,
    path: &Path,
) -> Result<usize, RequestValidationError> {
    if track_count == 0 {
        return Err(RequestValidationError::InvalidStagePolicy(format!(
            "album batch CUE source {} contains no audio tracks",
            path.display()
        )));
    }
    match selection {
        TrackSelection::All => Ok(track_count),
        TrackSelection::Range { start, end } => {
            if *start == 0 || *end == 0 || start > end {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "album batch CUE source {} has invalid track-selection range {start}-{end}",
                    path.display()
                )));
            }
            let max_ordinal = u32::try_from(track_count).unwrap_or(u32::MAX);
            if *start > max_ordinal {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "album batch CUE source {} track-selection range start {start} exceeds track count {max_ordinal}",
                    path.display()
                )));
            }
            Ok(((*end).min(max_ordinal) - *start + 1) as usize)
        }
        TrackSelection::Set(indices) => {
            if indices.is_empty() {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "album batch CUE source {} has empty track-selection set",
                    path.display()
                )));
            }
            let max_ordinal = u32::try_from(track_count).unwrap_or(u32::MAX);
            if let Some(invalid) = indices.iter().find(|idx| **idx == 0 || **idx > max_ordinal) {
                return Err(RequestValidationError::InvalidStagePolicy(format!(
                    "album batch CUE source {} track-selection entry {invalid} is outside valid range 1-{max_ordinal}",
                    path.display()
                )));
            }
            Ok(indices.len())
        }
    }
}

/// Dispatch a supported source kind to its materializer.
pub fn materializer_for(kind: SourceKind) -> Result<Box<dyn Materializer>, SourceDispatchError> {
    match kind {
        SourceKind::SingleFile => Ok(Box::new(SingleFileMaterializer)),
        SourceKind::Archive => Ok(Box::new(ArchiveMaterializer)),
        SourceKind::CueImage => Ok(Box::new(CueImageMaterializer)),
        SourceKind::SacdIso => Ok(Box::new(SacdIsoMaterializer)),
        SourceKind::DvdAudio => Ok(Box::new(DvdaAudioMaterializer)),
        SourceKind::DvdVideo => Ok(Box::new(DvdVideoMaterializer)),
        SourceKind::BluRay => Ok(Box::new(BlurayMaterializer)),
    }
}

// ===========================================================================
// Per-track realize  (PR 4 = StagedFile arm; PR 8 = ImageSegment;
// PR 9 = SacdTrack)
// ===========================================================================

/// Realize a materialized track as a file the encoder can consume.
pub async fn realize_track(
    src: &TrackSourceRef,
    req: &PipelineRequest,
    staging: &StagingDir,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    progress_tracker: Option<&mut OperationProgressTracker<'_>>,
) -> Result<PathBuf, ConvertError> {
    realize_track_with_tool_limits(
        src,
        req,
        staging,
        runner,
        cancel,
        None,
        progress_tracker,
    )
    .await
}

pub async fn realize_track_with_tool_limits(
    src: &TrackSourceRef,
    req: &PipelineRequest,
    staging: &StagingDir,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    progress_tracker: Option<&mut OperationProgressTracker<'_>>,
) -> Result<PathBuf, ConvertError> {
    realize_track_with_tool_limits_and_stats(
        src,
        None,
        req,
        staging,
        runner,
        cancel,
        tool_concurrency_limits,
        progress_tracker,
    )
    .await
    .map(|realized| realized.path)
}

async fn realize_track_with_tool_limits_and_stats(
    src: &TrackSourceRef,
    prepared_track: Option<&PreparedTrack>,
    req: &PipelineRequest,
    staging: &StagingDir,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    progress_tracker: Option<&mut OperationProgressTracker<'_>>,
) -> Result<RealizedTrackInfo, ConvertError> {
    if cancel.is_cancelled() {
        return Err(ConvertError::Realize("cancelled".to_string()));
    }

    match src {
        TrackSourceRef::StagedFile(path) => {
            if !path.exists() {
                return Err(ConvertError::TrackValidation(format!(
                    "staged track does not exist: {}",
                    path.display()
                )));
            }
            if !path.is_file() {
                return Err(ConvertError::TrackValidation(format!(
                    "staged track is not a regular file: {}",
                    path.display()
                )));
            }
            Ok(RealizedTrackInfo {
                path: path.clone(),
                dsd_dst_stats: dsd_dst_stats_from_file(path, Some(file_len(path).unwrap_or(0)), None),
            })
        }
        TrackSourceRef::CueStreamSegment {
            fallback_path,
            decode_path,
            start_sample,
            samples,
            carrier,
            ..
        } => {
            let sample_rate = prepared_track
                .and_then(PreparedTrack::scalar_sample_rate)
                .ok_or_else(|| ConvertError::TrackValidation(
                    "streamable CUE segment is missing its source sample rate".to_string(),
                ))?;
            super::materializer_cue::realize_cue_stream_segment_fallback(
                decode_path,
                *start_sample,
                *samples,
                sample_rate,
                *carrier,
                fallback_path,
                runner,
                cancel,
            )
            .await
            .map(RealizedTrackInfo::without_stats)
            .map_err(|err| ConvertError::Realize(err.to_string()))
        }
        TrackSourceRef::CueSegmentCarrier { path, .. } => {
            if !path.exists() {
                return Err(ConvertError::TrackValidation(format!(
                    "staged CUE segment carrier does not exist: {}",
                    path.display()
                )));
            }
            if !path.is_file() {
                return Err(ConvertError::TrackValidation(format!(
                    "staged CUE segment carrier is not a regular file: {}",
                    path.display()
                )));
            }
            Ok(RealizedTrackInfo::without_stats(path.clone()))
        }
        TrackSourceRef::ImageSegment {
            image,
            start_sample,
            samples,
        } => {
            realize_image_segment(
                image,
                *start_sample,
                *samples,
                req,
                staging,
                runner,
                cancel,
                tool_concurrency_limits.as_ref(),
            )
            .await
            .map(RealizedTrackInfo::without_stats)
        }
        TrackSourceRef::SacdTrack {
            iso,
            track_index,
            area,
        } if tonepoet_pipeline::selects_reference_dsd_to_pcm(&req.settings, true)
            && req.settings.dsd.from_dsd.pathway
                == tonepoet_pipeline::DsdSourcePathway::Reference =>
        {
            // Reference SACD admission must remain pure until the immutable
            // policy/toolchain attestation has passed. Return a typed,
            // deterministic carrier placeholder; the executor performs the
            // qualified extraction inside its private work directory after
            // attestation and re-plans against the resulting DSF.
            let area_label = sacd_area_label(*area);
            let path_hash = stable_path_hash(iso);
            Ok(RealizedTrackInfo::without_stats(
                staging.root.join("reference-deferred-sacd").join(format!(
                    "sacd_{path_hash:016x}_{area_label}_track_{:03}.dsf",
                    track_index + 1
                )),
            ))
        }
        TrackSourceRef::SacdTrack {
            iso,
            track_index,
            area,
        } => realize_sacd_track(
            iso,
            *track_index,
            *area,
            &req.settings.target_format,
            staging,
            cancel,
            progress_tracker,
        )
        .await,
        TrackSourceRef::DvdVideoTrack { .. } => realize_dvdv_track(
            src,
            staging,
            runner,
            cancel,
            tool_concurrency_limits.as_ref(),
            progress_tracker,
        )
        .await
        .map(RealizedTrackInfo::without_stats),
        TrackSourceRef::BluRayTrack { .. } => realize_bluray_track(
            src,
            staging,
            runner,
            cancel,
            tool_concurrency_limits.as_ref(),
            progress_tracker,
        )
        .await
        .map(RealizedTrackInfo::without_stats),
        TrackSourceRef::DvdaTrack { dvda_downmix_policy, .. } => {
            let expected_audio = DvdaSourceAudioExpectation::from_prepared_track_and_source(prepared_track, src);
            let audio_policy = DvdaRealizationAudioPolicy::new(
                bit_depth_target_label(req.settings.target_bit_depth).to_string(),
                prepared_track.and_then(|track| resolved_target_bit_depth(track, req.settings.target_bit_depth)),
                *dvda_downmix_policy,
            );
            realize_dvda_track(
                src,
                expected_audio,
                audio_policy,
                staging,
            runner,
            cancel,
            tool_concurrency_limits.as_ref(),
                progress_tracker,
            )
            .await
            .map(RealizedTrackInfo::without_stats)
        }
    }
}

fn cue_segment_output_name(image: &Path, start_sample: u64, samples: u64) -> String {
    let stem = sanitize_segment_component(
        image
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("image"),
    );
    format!("{stem}_{start_sample:012}_{samples:012}.wav")
}

fn sanitize_segment_component(value: &str) -> String {
    let sanitized: String = value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.') {
                ch
            } else {
                '_'
            }
        })
        .collect();
    if sanitized.is_empty() {
        "image".to_string()
    } else {
        sanitized
    }
}

async fn realize_image_segment(
    image: &Path,
    start_sample: u64,
    samples: u64,
    _req: &PipelineRequest,
    staging: &StagingDir,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<PathBuf, ConvertError> {
    if samples == 0 {
        return Err(ConvertError::TrackValidation(
            "image segment has zero samples".to_string(),
        ));
    }
    if !image.is_file() {
        return Err(ConvertError::TrackValidation(format!(
            "image file does not exist: {}",
            image.display()
        )));
    }

    let realized_dir = staging.root.join("realized-image-segments");
    fs::create_dir_all(&realized_dir)?;
    let out_path = realized_dir.join(cue_segment_output_name(image, start_sample, samples));
    let _ = fs::remove_file(&out_path);

    let direct = cut_segment_with_ffmpeg(
        image,
        start_sample,
        samples,
        &out_path,
        runner,
        cancel,
        tool_concurrency_limits,
    )
    .await;
    if let Err(err) = direct {
        let _ = fs::remove_file(&out_path);
        if !has_path_extension(image, "wv") {
            return Err(err);
        }

        let fallback = async {
            let wav_path = ensure_decoded_wavpack_image(
                image,
                &realized_dir,
                runner,
                cancel,
                tool_concurrency_limits,
            )
            .await?;
            cut_segment_with_ffmpeg(
                &wav_path,
                start_sample,
                samples,
                &out_path,
                runner,
                cancel,
                tool_concurrency_limits,
            )
            .await?;

            Ok(())
        }
        .await;

        if let Err(err) = fallback {
            let _ = fs::remove_file(&out_path);
            return Err(err);
        }
    }

    if let Err(err) = validate_realized_segment(
        &out_path,
        samples,
        runner,
        cancel,
        tool_concurrency_limits,
    )
    .await
    {
        let _ = fs::remove_file(&out_path);
        return Err(err);
    }

    Ok(out_path)
}

fn cut_segment_ffmpeg_args(input: &Path, filter: &str, out_path: &Path) -> Vec<String> {
    vec![
        "-y".into(),
        "-hide_banner".into(),
        "-loglevel".into(),
        "error".into(),
        "-i".into(),
        input.to_string_lossy().into_owned(),
        "-map".into(),
        "0:a:0".into(),
        "-vn".into(),
        "-sn".into(),
        "-dn".into(),
        "-af".into(),
        filter.to_string(),
        "-f".into(),
        "wav".into(),
        "-c:a".into(),
        "pcm_s32le".into(),
        out_path.to_string_lossy().into_owned(),
    ]
}

#[cfg(test)]
mod cue_image_segment_command_tests {
    use super::*;

    #[test]
    fn cue_segment_command_decodes_to_pcm_s32le_wav_without_stream_copy() {
        let args = cut_segment_ffmpeg_args(
            Path::new("album.flac"),
            "atrim=start_sample=0:end_sample=44100,asetpts=N/SR/TB",
            Path::new("segment.wav"),
        );

        assert!(has_adjacent_arg(&args, "-map", "0:a:0"));
        assert!(has_adjacent_arg(&args, "-f", "wav"));
        assert!(has_adjacent_arg(&args, "-c:a", "pcm_s32le"));
        assert!(args.iter().any(|arg| arg == "-vn"));
        assert!(args.iter().any(|arg| arg == "-sn"));
        assert!(args.iter().any(|arg| arg == "-dn"));
        assert!(!has_adjacent_arg(&args, "-map", "0:v?"));
        assert!(!has_adjacent_arg(&args, "-map_metadata", "0"));
        assert!(!has_adjacent_arg(&args, "-c:a", "copy"));
        assert!(!has_adjacent_arg(&args, "-c:a", "flac"));
    }

    #[test]
    fn legacy_image_segment_realization_uses_wav_carrier_name_not_flac() {
        let name = cue_segment_output_name(Path::new("album.flac"), 0, 44_100);
        assert!(name.ends_with(".wav"));
        assert!(!name.ends_with(".flac"));
    }

    #[test]
    fn streamed_cue_decoder_is_one_raw_pcm_stream_from_sample_zero() {
        let command = cue_stream_decoder_command(
            Path::new("album.flac"),
            CueSegmentCarrier::PcmS32LeWav,
        );

        assert!(has_adjacent_arg(&command.args, "-i", "album.flac"));
        assert!(has_adjacent_arg(&command.args, "-f", "s32le"));
        assert!(has_adjacent_arg(&command.args, "-c:a", "pcm_s32le"));
        assert_eq!(command.args.last().map(String::as_str), Some("pipe:1"));
        assert!(!command.args.iter().any(|arg| arg == "-ss" || arg == "-af"));
    }

    #[test]
    fn streamed_cue_byte_ranges_are_frame_exact_and_fail_closed_on_overflow() {
        assert_eq!(
            cue_stream_byte_range(44_100, 88_200, 2, CueSegmentCarrier::PcmS32LeWav),
            Some((44_100 * 8, 88_200 * 8))
        );
        assert!(cue_stream_byte_range(
            u64::MAX,
            1,
            2,
            CueSegmentCarrier::PcmS32LeWav,
        )
        .is_none());
    }


    #[test]
    fn source_replaygain_pcm_header_uses_exact_riff_lengths_for_small_tracks() {
        let header = cue_stream_analysis_wav_header(44_100, 2, CueSegmentCarrier::PcmS32LeWav, 100)
            .expect("small PCM stream header");
        assert_eq!(&header[..4], b"RIFF");
        assert_eq!(header.len(), 44);
        assert_eq!(u32::from_le_bytes(header[4..8].try_into().unwrap()), 836);
        assert_eq!(&header[36..40], b"data");
        assert_eq!(u32::from_le_bytes(header[40..44].try_into().unwrap()), 800);
    }

    #[test]
    fn source_replaygain_pcm_header_switches_to_rf64_without_truncating_lengths() {
        let samples = (u64::from(u32::MAX) / 8) + 1;
        let header = cue_stream_analysis_wav_header(48_000, 2, CueSegmentCarrier::PcmS32LeWav, samples)
            .expect("large PCM stream header");
        assert_eq!(&header[..4], b"RF64");
        assert_eq!(header.len(), 80);
        assert_eq!(u32::from_le_bytes(header[4..8].try_into().unwrap()), u32::MAX);
        assert_eq!(&header[12..16], b"ds64");
        assert_eq!(u64::from_le_bytes(header[28..36].try_into().unwrap()), samples * 8);
        assert_eq!(u64::from_le_bytes(header[36..44].try_into().unwrap()), samples);
        assert_eq!(&header[72..76], b"data");
        assert_eq!(u32::from_le_bytes(header[76..80].try_into().unwrap()), u32::MAX);
    }

    fn has_adjacent_arg(args: &[String], left: &str, right: &str) -> bool {
        args.windows(2).any(|window| window[0] == left && window[1] == right)
    }
}

async fn cut_segment_with_ffmpeg(
    input: &Path,
    start_sample: u64,
    samples: u64,
    out_path: &Path,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<(), ConvertError> {
    let end_sample = start_sample.checked_add(samples).ok_or_else(|| {
        ConvertError::TrackValidation("image segment sample range overflows".to_string())
    })?;

    // Keep the legacy ImageSegment arm byte-for-byte aligned with the live CUE
    // splitter's sample-timeline semantics. In particular: no input `-ss`, and
    // reset timestamps with `N/SR/TB` after absolute sample trimming.
    let filter =
        format!("atrim=start_sample={start_sample}:end_sample={end_sample},asetpts=N/SR/TB");
    let cmd = ToolCommand {
        environment_policy: tonepoet_pipeline::CommandEnvironmentPolicy::InheritAndSet,
        binary: ToolBinary::Ffmpeg,
        args: cut_segment_ffmpeg_args(input, &filter, out_path),
        secret_args: vec![],
        cwd: None,
        env: vec![],
        timeout: DEFAULT_CONVERT_TIMEOUT,
    };

    match run_tool_command_with_concurrency(cmd, runner, cancel, tool_concurrency_limits).await {
        Ok(_) => Ok(()),
        Err(ToolRunnerError::Cancelled { .. }) => {
            Err(ConvertError::Realize("cancelled".to_string()))
        }
        Err(err) => Err(ConvertError::Tool(err)),
    }
}

async fn ensure_decoded_wavpack_image(
    input: &Path,
    realized_dir: &Path,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<PathBuf, ConvertError> {
    let cache_dir = realized_dir.join("decoded-image-cache");
    fs::create_dir_all(&cache_dir)?;

    let wav_path = cache_dir.join(decoded_wavpack_cache_name(input));
    if cached_audio_is_ready(&wav_path) {
        return Ok(wav_path);
    }

    let lock_path = wav_path.with_extension("wav.lock");
    let lock_file = fs::OpenOptions::new()
        .create(true)
        .write(true)
        .open(&lock_path)?;
    lock_file.lock_exclusive()?;

    let result = async {
        if cached_audio_is_ready(&wav_path) {
            return Ok(wav_path.clone());
        }

        let tmp_path = wav_path.with_file_name(format!(
            ".{}.{}.tmp",
            wav_path
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("decoded.wav"),
            std::process::id()
        ));
        let _ = fs::remove_file(&tmp_path);

        if let Err(err) = decode_wavpack_image(
            input,
            &tmp_path,
            runner,
            cancel,
            tool_concurrency_limits,
        )
        .await
        {
            let _ = fs::remove_file(&tmp_path);
            return Err(err);
        }

        fs::rename(&tmp_path, &wav_path)?;
        Ok(wav_path.clone())
    }
    .await;

    let _ = lock_file.unlock();
    result
}

fn cached_audio_is_ready(path: &Path) -> bool {
    fs::metadata(path)
        .map(|metadata| metadata.is_file() && metadata.len() > 0)
        .unwrap_or(false)
}

fn decoded_wavpack_cache_name(input: &Path) -> String {
    let stem = sanitize_segment_component(
        input
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("image"),
    );
    let hash = stable_path_hash(input);
    format!("{stem}_{hash:016x}.wav")
}

fn stable_path_hash(path: &Path) -> u64 {
    let mut hash = 0xcbf29ce484222325_u64;
    for byte in path.to_string_lossy().as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

async fn decode_wavpack_image(
    input: &Path,
    out_path: &Path,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<(), ConvertError> {
    let cmd = ToolCommand {
        environment_policy: tonepoet_pipeline::CommandEnvironmentPolicy::InheritAndSet,
        binary: ToolBinary::Wvunpack,
        args: vec![
            "-q".into(),
            "-o".into(),
            out_path.to_string_lossy().into_owned(),
            input.to_string_lossy().into_owned(),
        ],
        secret_args: vec![],
        cwd: None,
        env: vec![],
        timeout: DEFAULT_CONVERT_TIMEOUT,
    };

    match run_tool_command_with_concurrency(cmd, runner, cancel, tool_concurrency_limits).await {
        Ok(_) => Ok(()),
        Err(ToolRunnerError::Cancelled { .. }) => {
            Err(ConvertError::Realize("cancelled".to_string()))
        }
        Err(err) => Err(ConvertError::Tool(err)),
    }
}

async fn validate_realized_segment(
    out_path: &Path,
    expected_samples: u64,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<(), ConvertError> {
    let metadata = fs::metadata(out_path).map_err(|err| {
        ConvertError::TrackValidation(format!(
            "realized image segment missing: {} ({err})",
            out_path.display()
        ))
    })?;
    if metadata.len() == 0 {
        return Err(ConvertError::TrackValidation(format!(
            "realized image segment is empty: {}",
            out_path.display()
        )));
    }

    let probe = probe_realized_segment_with_tool_limits(
        out_path,
        runner,
        cancel,
        tool_concurrency_limits,
    )
    .await?;
    let actual_samples = probe.samples.ok_or_else(|| {
        ConvertError::TrackValidation(format!(
            "could not measure realized segment samples: {}",
            out_path.display()
        ))
    })?;
    let delta = actual_samples.abs_diff(expected_samples);
    let allowed = if probe.exact {
        0
    } else {
        (probe.sample_rate / 75).max(1) as u64
    };
    if delta > allowed {
        return Err(ConvertError::TrackValidation(format!(
            "realized segment sample drift: expected {expected_samples}, got {actual_samples}, allowed {allowed}"
        )));
    }

    Ok(())
}

#[derive(Debug, Clone)]
struct RealizedProbe {
    sample_rate: u32,
    samples: Option<u64>,
    exact: bool,
    codec_name: Option<String>,
    sample_fmt: Option<String>,
    channels: Option<u32>,
    bits_per_raw_sample: Option<u32>,
    bits_per_sample: Option<u32>,
}

#[allow(dead_code)]
async fn probe_realized_segment(
    path: &Path,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
) -> Result<RealizedProbe, ConvertError> {
    probe_realized_segment_with_tool_limits(path, runner, cancel, None).await
}

async fn probe_realized_segment_with_tool_limits(
    path: &Path,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<RealizedProbe, ConvertError> {
    let cmd = ToolCommand {
        environment_policy: tonepoet_pipeline::CommandEnvironmentPolicy::InheritAndSet,
        binary: ToolBinary::Ffprobe,
        args: vec![
            "-v".into(),
            "error".into(),
            "-select_streams".into(),
            "a:0".into(),
            "-show_entries".into(),
            "stream=sample_rate,channels,duration_ts,time_base,duration,codec_name,sample_fmt,bits_per_raw_sample,bits_per_sample".into(),
            "-show_entries".into(),
            "format=duration".into(),
            "-of".into(),
            "json".into(),
            path.to_string_lossy().into_owned(),
        ],
        secret_args: vec![],
        cwd: None,
        env: vec![],
        timeout: Duration::from_secs(30),
    };

    let output = match run_tool_command_with_concurrency(cmd, runner, cancel, tool_concurrency_limits).await {
        Ok(output) => output,
        Err(ToolRunnerError::Cancelled { .. }) => {
            return Err(ConvertError::Realize("cancelled".to_string()))
        }
        Err(err) => return Err(ConvertError::Tool(err)),
    };
    parse_realized_probe_json(&output.stdout_tail)
}

fn parse_realized_probe_json(json: &str) -> Result<RealizedProbe, ConvertError> {
    let value: serde_json::Value = serde_json::from_str(json).map_err(|err| {
        ConvertError::TrackValidation(format!("ffprobe JSON parse failed: {err}"))
    })?;
    let stream = value.pointer("/streams/0").ok_or_else(|| {
        ConvertError::TrackValidation("ffprobe returned no audio stream".to_string())
    })?;
    let sample_rate = stream
        .get("sample_rate")
        .and_then(|value| value.as_str())
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(0);
    if sample_rate == 0 {
        return Err(ConvertError::TrackValidation(
            "ffprobe returned no valid sample_rate".to_string(),
        ));
    }

    if let Some(samples) = samples_from_stream_duration_ts(stream, sample_rate) {
        return Ok(RealizedProbe {
            sample_rate,
            samples: Some(samples),
            exact: true,
            codec_name: json_string(stream, "codec_name"),
            sample_fmt: json_string(stream, "sample_fmt"),
            channels: json_u32_field(stream, "channels"),
            bits_per_raw_sample: json_u32_field(stream, "bits_per_raw_sample"),
            bits_per_sample: json_u32_field(stream, "bits_per_sample"),
        });
    }

    let duration_secs = stream
        .get("duration")
        .and_then(|value| value.as_str())
        .and_then(|value| value.parse::<f64>().ok())
        .or_else(|| {
            value
                .pointer("/format/duration")
                .and_then(|value| value.as_str())
                .and_then(|value| value.parse::<f64>().ok())
        });
    let samples = duration_secs.map(|duration| (duration * f64::from(sample_rate)).round() as u64);
    Ok(RealizedProbe {
        sample_rate,
        samples,
        exact: false,
        codec_name: json_string(stream, "codec_name"),
        sample_fmt: json_string(stream, "sample_fmt"),
        channels: json_u32_field(stream, "channels"),
        bits_per_raw_sample: json_u32_field(stream, "bits_per_raw_sample"),
        bits_per_sample: json_u32_field(stream, "bits_per_sample"),
    })
}

/// Validate the encoded output's sample count against expected samples.
///
/// Lossless PCM-preserving targets (FLAC, WAV, AIFF, WavPack, ALAC) must
/// preserve the staged segment's duration after final encode. Same-rate
/// encodes validate against the source-rate sample count exactly when ffprobe
/// reports exact `duration_ts`, except for the precisely computed terminal
/// alignment padding exposed by FFmpeg's W64 integer-PCM demuxer. Resampled
/// encodes validate against the target-rate sample count with a one-sample
/// endpoint tolerance. Duration-only probes get a narrow one-millisecond
/// sample tolerance to cover container/probe rounding. Lossy formats and DSD
/// are skipped because codec padding or a different sample model makes strict
/// comparison invalid. Headerless raw PCM outputs are also skipped because
/// ffprobe cannot infer their format, sample rate, or channels from the bytes
/// alone.
///
/// Returns the actual probed sample count on success, the original expected
/// sample count when validation is intentionally skipped, or a track-validation
/// error when a probeable lossless final output drifts or lands at the wrong
/// sample rate.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PostEncodeSampleExpectation {
    samples: u64,
    sample_rate: Option<u32>,
    resampled: bool,
    /// SSRC filter tail allowance. SSRC's brick-wall FIR appends up to
    /// `fft_length - 1` samples to the output. `None` for non-SSRC paths.
    ssrc_fft_length: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PostEncodeValidation {
    samples: Option<u64>,
    measured_depth: Option<tonepoet_pipeline::PcmBitDepth>,
}

fn expected_post_encode_depth_for_track(
    track: &PreparedTrack,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> Option<PostEncodeDepthExpectation> {
    match settings.target_bit_depth {
        tonepoet_pipeline::BitDepthTarget::Pcm(depth) => Some(PostEncodeDepthExpectation {
            depth,
            // Explicit user request: the sample-format CLASS (int vs float)
            // must match exactly.
            class_strict: true,
        }),
        tonepoet_pipeline::BitDepthTarget::Source => {
            if !settings.target_format.is_pcm_lossless() {
                return None;
            }
            super::plan_bridge::resolve_source_pcm_depth(track).map(|depth| PostEncodeDepthExpectation {
                depth,
                // Source resolution preserves integer-versus-float class
                // as well as width. Unknown source representation is rejected
                // by the bridge before planning; validation never invents a
                // target-format default and labels it as source-derived.
                class_strict: true,
            })
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct PostEncodeDepthExpectation {
    depth: tonepoet_pipeline::PcmBitDepth,
    class_strict: bool,
}


impl PostEncodeSampleExpectation {
    fn same_rate(samples: u64, sample_rate: Option<u32>) -> Self {
        Self {
            samples,
            sample_rate,
            resampled: false,
            ssrc_fft_length: None,
        }
    }
}

#[allow(dead_code)]
async fn validate_encoded_output(
    out_path: &Path,
    expected_samples: Option<u64>,
    target_format: &tonepoet_pipeline::AudioFormat,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
) -> Result<Option<u64>, ConvertError> {
    validate_encoded_output_with_tool_limits(
        out_path,
        expected_samples.map(|samples| PostEncodeSampleExpectation::same_rate(samples, None)),
        None,
        target_format,
        runner,
        cancel,
        None,
    )
    .await
    .map(|validation| validation.samples)
}

async fn validate_encoded_output_with_tool_limits(
    out_path: &Path,
    expected_samples: Option<PostEncodeSampleExpectation>,
    expected_depth: Option<PostEncodeDepthExpectation>,
    target_format: &tonepoet_pipeline::AudioFormat,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<PostEncodeValidation, ConvertError> {
    if !requires_lossless_post_encode_sample_validation(target_format)
        || ffmpeg_raw_pcm_muxer_for_path(out_path).is_some()
    {
        return Ok(PostEncodeValidation {
            samples: expected_samples.map(|expected| expected.samples),
            measured_depth: None,
        });
    }

    if expected_samples.is_none() && expected_depth.is_none() {
        return Ok(PostEncodeValidation {
            samples: None,
            measured_depth: None,
        });
    }

    let probe = probe_realized_segment_with_tool_limits(
        out_path,
        runner,
        cancel,
        tool_concurrency_limits,
    )
    .await
    .map_err(|err| {
        ConvertError::TrackValidation(format!(
            "post-encode sample validation failed for lossless output {}: {err}",
            out_path.display()
        ))
    })?;

    let actual = probe.samples;

    if let Some(expected) = expected_samples {
        let actual = actual.ok_or_else(|| {
            ConvertError::TrackValidation(format!(
                "post-encode sample validation failed for lossless output {}: ffprobe returned no sample count or duration",
                out_path.display()
            ))
        })?;
        if let Some(expected_rate) = expected.sample_rate {
            if probe.sample_rate != expected_rate {
                return Err(ConvertError::TrackValidation(format!(
                    "post-encode sample rate mismatch for lossless output {}: expected {expected_rate}, got {}",
                    out_path.display(),
                    probe.sample_rate
                )));
            }
        }

        let delta = actual.abs_diff(expected.samples);
        let mut allowed = encoded_output_sample_tolerance(&probe, &expected);
        if actual >= expected.samples {
            allowed = allowed.max(w64_integer_pcm_padding_sample_tolerance(
                out_path,
                &probe,
                &expected,
            ));
        }

        if delta > allowed {
            return Err(ConvertError::TrackValidation(format!(
                "post-encode sample drift for lossless output {}: expected {}, got {actual}, allowed {allowed}",
                out_path.display(),
                expected.samples
            )));
        }
    }

    let measured_depth = if expected_depth.is_some()
        || matches!(target_format, tonepoet_pipeline::AudioFormat::WavPack)
    {
        measured_pcm_depth_with_tool_limits(
            out_path,
            target_format,
            &probe,
            runner,
            cancel,
            tool_concurrency_limits,
        )
        .await?
    } else {
        measured_pcm_depth(&probe)
    };

    if let Some(expectation) = expected_depth {
        let Some(measured) = measured_depth else {
            return Err(ConvertError::TrackValidation(format!(
                "post-encode depth validation failed for {}: no usable sample format/depth (codec={:?}, sample_fmt={:?})",
                out_path.display(), probe.codec_name, probe.sample_fmt
            )));
        };
        let matches = if expectation.class_strict {
            measured == expectation.depth
        } else {
            measured.bits() == expectation.depth.bits()
        };
        if !matches {
            return Err(ConvertError::TrackValidation(format!(
                "post-encode depth mismatch for {}: requested {:?}, measured {:?} (codec={:?}, sample_fmt={:?}, bits_per_raw_sample={:?})",
                out_path.display(), expectation.depth, measured, probe.codec_name, probe.sample_fmt, probe.bits_per_raw_sample
            )));
        }
    }

    Ok(PostEncodeValidation {
        samples: actual,
        measured_depth,
    })
}

fn requires_lossless_post_encode_sample_validation(target_format: &tonepoet_pipeline::AudioFormat) -> bool {
    !matches!(
        target_format,
        tonepoet_pipeline::AudioFormat::Dsf | tonepoet_pipeline::AudioFormat::Dff
    ) && target_format.is_pcm_lossless()
}

fn encoded_output_sample_tolerance(
    probe: &RealizedProbe,
    expected: &PostEncodeSampleExpectation,
) -> u64 {
    let probe_tolerance = if probe.exact {
        0
    } else {
        // Duration-only probes are a fallback for containers/tools that do not
        // expose exact `duration_ts`; allow at most one millisecond of sample
        // rounding at the probed sample rate.
        (probe.sample_rate / 1000).max(1) as u64
    };

    let resampler_tolerance = match expected.ssrc_fft_length {
        // SSRC's brick-wall FIR filter appends up to FFT_length - 1 samples
        // of filter tail to the output. The exact tail depends on the rate
        // ratio but never exceeds this bound.
        Some(fft_len) => fft_len.saturating_sub(1),
        // Non-SSRC resamplers (soxr, sox): ±1 for endpoint rounding.
        None if expected.resampled => 1,
        None => 0,
    };

    probe_tolerance.max(resampler_tolerance)
}

/// FFmpeg pads Wave64 chunks to an 8-byte boundary. For integer PCM, its W64
/// demuxer can expose the terminal zero padding through `duration_ts` as one or
/// more extra sample frames. Compute only the frames that the required
/// alignment can explain for this exact sample count and PCM layout; every
/// other W64 drift remains a validation error.
fn w64_integer_pcm_padding_sample_tolerance(
    out_path: &Path,
    probe: &RealizedProbe,
    expected: &PostEncodeSampleExpectation,
) -> u64 {
    if !has_path_extension(out_path, "w64") {
        return 0;
    }

    let Some(codec) = probe.codec_name.as_deref() else {
        return 0;
    };
    if !(codec.starts_with("pcm_s") || codec.starts_with("pcm_u")) {
        return 0;
    }

    let Some(channels) = probe.channels.map(u64::from).filter(|channels| *channels > 0) else {
        return 0;
    };
    let Some(bytes_per_sample) = integer_pcm_storage_bytes_per_sample(codec, probe) else {
        return 0;
    };
    let Some(frame_bytes) = channels.checked_mul(bytes_per_sample) else {
        return 0;
    };
    if frame_bytes == 0 {
        return 0;
    }

    // The W64 data-chunk header is itself 8-byte aligned, so only the PCM
    // payload length determines the terminal zero padding. Work modulo eight
    // to avoid overflow even for very long sources.
    let payload_mod_8 = (expected.samples % 8).saturating_mul(frame_bytes % 8) % 8;
    let padding_bytes = (8 - payload_mod_8) % 8;
    if padding_bytes == 0 {
        return 0;
    }

    // FFmpeg derives integer-PCM W64 duration_ts by rounding the aligned data
    // extent to the nearest sample frame. Reproduce that bounded artifact from
    // the padding alone, rather than granting a fixed W64 drift budget.
    padding_bytes
        .saturating_add(frame_bytes / 2)
        .checked_div(frame_bytes)
        .unwrap_or(0)
}

fn integer_pcm_storage_bytes_per_sample(codec: &str, probe: &RealizedProbe) -> Option<u64> {
    let bytes = if codec.starts_with("pcm_s8") || codec.starts_with("pcm_u8") {
        1
    } else if codec.starts_with("pcm_s16") || codec.starts_with("pcm_u16") {
        2
    } else if codec.starts_with("pcm_s24") || codec.starts_with("pcm_u24") {
        3
    } else if codec.starts_with("pcm_s32") || codec.starts_with("pcm_u32") {
        4
    } else if codec.starts_with("pcm_s64") || codec.starts_with("pcm_u64") {
        8
    } else {
        let bits = probe.bits_per_sample?;
        if bits == 0 || bits % 8 != 0 {
            return None;
        }
        u64::from(bits / 8)
    };
    Some(bytes)
}

fn samples_from_stream_duration_ts(stream: &serde_json::Value, sample_rate: u32) -> Option<u64> {
    let duration_ts = stream.get("duration_ts").and_then(json_u64)?;
    let time_base = stream.get("time_base")?.as_str()?;
    let (num, den) = time_base.split_once('/')?;
    let num = num.parse::<u64>().ok()?;
    let den = den.parse::<u64>().ok()?;
    if den == 0 {
        return None;
    }
    let samples = (duration_ts as u128)
        .checked_mul(num as u128)?
        .checked_mul(sample_rate as u128)?
        .checked_div(den as u128)?;
    u64::try_from(samples).ok()
}

fn json_u64(value: &serde_json::Value) -> Option<u64> {
    value
        .as_u64()
        .or_else(|| value.as_str().and_then(|text| text.parse().ok()))
}

fn json_string(object: &serde_json::Value, key: &str) -> Option<String> {
    object.get(key)?.as_str().map(str::to_owned).filter(|value| !value.is_empty() && value != "N/A")
}

fn json_u32_field(object: &serde_json::Value, key: &str) -> Option<u32> {
    object.get(key).and_then(json_u64).and_then(|value| u32::try_from(value).ok()).filter(|value| *value > 0)
}

async fn measured_pcm_depth_with_tool_limits(
    out_path: &Path,
    target_format: &tonepoet_pipeline::AudioFormat,
    probe: &RealizedProbe,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<Option<tonepoet_pipeline::PcmBitDepth>, ConvertError> {
    if matches!(target_format, tonepoet_pipeline::AudioFormat::WavPack) {
        return probe_wavpack_depth_with_tool_limits(
            out_path,
            runner,
            cancel,
            tool_concurrency_limits,
        )
        .await;
    }

    Ok(measured_pcm_depth(probe))
}

async fn probe_wavpack_depth_with_tool_limits(
    out_path: &Path,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> Result<Option<tonepoet_pipeline::PcmBitDepth>, ConvertError> {
    let cmd = ToolCommand {
        environment_policy: tonepoet_pipeline::CommandEnvironmentPolicy::InheritAndSet,
        binary: ToolBinary::Wvunpack,
        args: vec![
            "-q".into(),
            "-s".into(),
            out_path.to_string_lossy().into_owned(),
        ],
        secret_args: vec![],
        cwd: None,
        env: vec![],
        timeout: Duration::from_secs(30),
    };

    let output = match run_tool_command_with_concurrency(cmd, runner, cancel, tool_concurrency_limits).await {
        Ok(output) => output,
        Err(ToolRunnerError::Cancelled { .. }) => {
            return Err(ConvertError::Realize("cancelled".to_string()));
        }
        Err(ToolRunnerError::Spawn { .. }) => {
            // wvunpack is the only authoritative oracle that distinguishes
            // integer WavPack depths from FFmpeg's decoded s32p view. An
            // explicit or Source-resolved depth must therefore fail closed
            // when the oracle is unavailable; publishing an unmeasured file
            // would turn the conversion log into a repetition of intent.
            return Err(ConvertError::TrackValidation(format!(
                "post-encode WavPack depth validation failed for {}: wvunpack is required for authoritative depth measurement",
                out_path.display()
            )));
        }
        Err(err) => {
            return Err(ConvertError::TrackValidation(format!(
                "post-encode WavPack depth validation failed for {}: wvunpack probe failed: {err}",
                out_path.display()
            )));
        }
    };

    let summary_text = if output.stderr_tail.trim().is_empty() {
        output.stdout_tail.clone()
    } else if output.stdout_tail.trim().is_empty() {
        output.stderr_tail.clone()
    } else {
        format!("{}\n{}", output.stdout_tail, output.stderr_tail)
    };

    parse_wvunpack_source_depth(&summary_text).ok_or_else(|| {
        ConvertError::TrackValidation(format!(
            "post-encode WavPack depth validation failed for {}: wvunpack did not report a parseable source depth",
            out_path.display()
        ))
    }).map(Some)
}

fn parse_wvunpack_source_depth(text: &str) -> Option<tonepoet_pipeline::PcmBitDepth> {
    use tonepoet_pipeline::PcmBitDepth;

    for line in text.lines() {
        let trimmed = line.trim();
        if !trimmed.to_ascii_lowercase().starts_with("source:") {
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        let Some(bit_pos) = lower.find("-bit") else {
            continue;
        };
        let prefix = lower[..bit_pos].trim_end();
        let digits = prefix
            .chars()
            .rev()
            .take_while(|ch| ch.is_ascii_digit())
            .collect::<String>()
            .chars()
            .rev()
            .collect::<String>();
        let bits: u32 = digits.parse().ok()?;
        let is_float = lower.contains("float");
        return match (bits, is_float) {
            (8, false) => Some(PcmBitDepth::Int8),
            (16, false) => Some(PcmBitDepth::Int16),
            (24, false) => Some(PcmBitDepth::Int24),
            (32, false) => Some(PcmBitDepth::Int32),
            (32, true) => Some(PcmBitDepth::Float32),
            (64, true) => Some(PcmBitDepth::Float64),
            _ => None,
        };
    }

    None
}

/// Log-side WavPack depth without the wvunpack oracle (no expectation to
/// enforce, so an oracle failure must not fail the track). ffprobe decodes
/// integer WavPack to sample_fmt s32p regardless of depth, so
/// measured_pcm_depth's fallback chain cannot be trusted here;
/// bits_per_raw_sample, when present, is container-accurate for INTEGER
/// WavPack (verified against wvunpack -s). Float WavPack probes as fltp
/// with bits_per_raw_sample=32 (bytes-per-sample, not an int width), so
/// float is classified first. Anything else stays unmeasured.
fn measured_pcm_depth(probe: &RealizedProbe) -> Option<tonepoet_pipeline::PcmBitDepth> {
    use tonepoet_pipeline::PcmBitDepth;
    let sample_fmt = probe.sample_fmt.as_deref().unwrap_or_default();
    if sample_fmt.starts_with("flt") {
        return Some(PcmBitDepth::Float32);
    }
    if sample_fmt.starts_with("dbl") {
        return Some(PcmBitDepth::Float64);
    }

    let codec = probe.codec_name.as_deref().unwrap_or_default();
    if codec.starts_with("pcm_f32") {
        return Some(PcmBitDepth::Float32);
    }
    if codec.starts_with("pcm_f64") {
        return Some(PcmBitDepth::Float64);
    }

    let bits = probe.bits_per_raw_sample.or(probe.bits_per_sample).or_else(|| {
        [
            ("pcm_u8", 8),
            ("pcm_s16", 16),
            ("pcm_s24", 24),
            ("pcm_s32", 32),
        ]
        .into_iter()
        .find_map(|(prefix, bits)| codec.starts_with(prefix).then_some(bits))
    })?;
    match bits {
        8 => Some(PcmBitDepth::Int8),
        16 => Some(PcmBitDepth::Int16),
        24 => Some(PcmBitDepth::Int24),
        32 => Some(PcmBitDepth::Int32),
        _ => None,
    }
}

fn has_path_extension(path: &Path, ext: &str) -> bool {
    path.extension()
        .and_then(|value| value.to_str())
        .map(|value| value.eq_ignore_ascii_case(ext))
        .unwrap_or(false)
}

// ===========================================================================
// SACD track realization  (PR 9)
// ===========================================================================

async fn realize_sacd_track(
    iso: &Path,
    track_index: u32,
    area: SacdArea,
    target_format: &tonepoet_pipeline::AudioFormat,
    staging: &StagingDir,
    cancel: &CancellationToken,
    progress_tracker: Option<&mut OperationProgressTracker<'_>>,
) -> Result<RealizedTrackInfo, ConvertError> {
    if cancel.is_cancelled() {
        return Err(ConvertError::Realize("cancelled".to_string()));
    }
    if !iso.is_file() {
        return Err(ConvertError::TrackValidation(format!(
            "SACD ISO does not exist: {}",
            iso.display()
        )));
    }

    let iso = iso.to_path_buf();
    let staging_root = staging.root.clone();
    let target_format = target_format.clone();

    let output = match progress_tracker {
        Some(tracker) => {
            heartbeat::run_with_heartbeat(
                async {
                    let iso = iso.clone();
                    let staging_root = staging_root.clone();
                    let target_format = target_format.clone();
                    tokio::task::spawn_blocking(move || {
                        realize_sacd_track_blocking(&iso, track_index, area, &target_format, &staging_root)
                    })
                    .await
                    .map_err(|err| {
                        ConvertError::Realize(format!("SACD extraction task failed: {err}"))
                    })?
                },
                tracker,
                "sacd-extraction",
                "Extracting DSD audio\u{2026}",
                Duration::from_secs(5),
            )
            .await?
        }
        None => tokio::task::spawn_blocking(move || {
            realize_sacd_track_blocking(&iso, track_index, area, &target_format, &staging_root)
        })
        .await
        .map_err(|err| ConvertError::Realize(format!("SACD extraction task failed: {err}")))??,
    };

    if cancel.is_cancelled() {
        return Err(ConvertError::Realize("cancelled".to_string()));
    }

    Ok(output)
}

fn realize_sacd_track_blocking(
    iso: &Path,
    track_index: u32,
    area: SacdArea,
    target_format: &tonepoet_pipeline::AudioFormat,
    staging_root: &Path,
) -> Result<RealizedTrackInfo, ConvertError> {
    realize_sacd_track_blocking_with_cancel(
        iso,
        track_index,
        area,
        target_format,
        SacdRealizationPaths::StagingRoot(staging_root),
        || false,
    )
}

pub(super) fn realize_reference_sacd_track_blocking<F>(
    iso: &Path,
    track_index: u32,
    area: SacdArea,
    output_path: &Path,
    temporary_path: &Path,
    is_cancelled: F,
) -> Result<PathBuf, ConvertError>
where
    F: FnMut() -> bool,
{
    realize_sacd_track_blocking_with_cancel(
        iso,
        track_index,
        area,
        &tonepoet_pipeline::AudioFormat::Dsf,
        SacdRealizationPaths::Explicit {
            output: output_path,
            temporary: temporary_path,
        },
        is_cancelled,
    )
    .map(|realized| realized.path)
}

enum SacdRealizationPaths<'a> {
    StagingRoot(&'a Path),
    Explicit {
        output: &'a Path,
        temporary: &'a Path,
    },
}

fn realize_sacd_track_blocking_with_cancel<F>(
    iso: &Path,
    track_index: u32,
    area: SacdArea,
    target_format: &tonepoet_pipeline::AudioFormat,
    paths: SacdRealizationPaths<'_>,
    mut is_cancelled: F,
) -> Result<RealizedTrackInfo, ConvertError>
where
    F: FnMut() -> bool,
{
    let metadata = parse_sacd_iso(iso).map_err(sacd_error_to_convert)?;
    let area_info = sacd_area_info(&metadata, area).ok_or_else(|| {
        ConvertError::TrackValidation(format!(
            "requested SACD area {} is not present in {}",
            sacd_area_label(area),
            iso.display()
        ))
    })?;
    let entry = area_info.tracks.get(track_index as usize).ok_or_else(|| {
        ConvertError::TrackValidation(format!(
            "SACD track index {} outside area {} track count {}",
            track_index,
            sacd_area_label(area),
            area_info.tracks.len()
        ))
    })?;

    if entry.length_lsn == 0 {
        return Err(ConvertError::TrackValidation(format!(
            "SACD track index {} has zero sectors",
            track_index
        )));
    }
    if !matches!(area_info.header.channel_count, 2 | 5 | 6) {
        return Err(ConvertError::TrackValidation(format!(
            "SACD area {} has unsupported channel count {}",
            sacd_area_label(area),
            area_info.header.channel_count
        )));
    }

    let output_format = match target_format {
        tonepoet_pipeline::AudioFormat::Dff => OutputFormat::Dff,
        _ => OutputFormat::Dsf,
    };
    let output_ext = match output_format {
        OutputFormat::Dff => "dff",
        _ => "dsf",
    };

    let (out_path, tmp_path) = match paths {
        SacdRealizationPaths::StagingRoot(staging_root) => {
            let realized_dir = staging_root.join("realized-sacd-tracks");
            fs::create_dir_all(&realized_dir)?;
            let out_path = realized_dir
                .join(sacd_track_output_name(iso, area, track_index, entry, output_ext));
            let tmp_path = unique_sacd_tmp_path(&out_path);
            (out_path, tmp_path)
        }
        SacdRealizationPaths::Explicit { output, temporary } => {
            if let Some(parent) = output.parent() {
                fs::create_dir_all(parent)?;
            }
            (output.to_path_buf(), temporary.to_path_buf())
        }
    };

    if sacd_output_is_ready(&out_path, output_format, area_info, entry.duration) {
        let stats = dsd_dst_stats_from_file(
            &out_path,
            None,
            Some(file_len(&out_path).unwrap_or(0)),
        );
        return Ok(RealizedTrackInfo {
            path: out_path,
            dsd_dst_stats: stats,
        });
    }

    match fs::remove_file(&tmp_path) {
        Ok(()) => {}
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(error) => return Err(ConvertError::Io(error)),
    }

    let extraction_result = (|| {
        let mut iso_reader = IsoReader::open(iso).map_err(|err| {
            ConvertError::Realize(format!("could not open SACD ISO {}: {err}", iso.display()))
        })?;
        let mut writer = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&tmp_path)?;

        let options = area_info
            .track_extract_options(track_index as usize, output_format)
            .map_err(|err| ConvertError::TrackValidation(err.to_string()))?;
        let report = sacd_rs::extract::extract_track_with_area_frame_format_and_cancel(
            &mut iso_reader,
            &mut writer,
            options,
            area_info.extraction_frame_format(),
            ExtractIntegrityOptions::strict(),
            || is_cancelled(),
        )
        .map_err(|err| {
            ConvertError::Realize(format!(
                "SACD extraction failed for {} track {}: {err}",
                iso.display(),
                track_index + 1
            ))
        })?;
        if report.integrity_loss_detected() {
            return Err(ConvertError::Realize(format!(
                "SACD extraction lost integrity for {} track {}: {:?}",
                iso.display(),
                track_index + 1,
                report.integrity
            )));
        }
        writer.sync_all()?;
        drop(writer);

        validate_sacd_realization(&tmp_path, output_format, area_info, entry.duration, report.stats)?;
        Ok(dsd_dst_stats_from_extract_report(&report, Some(file_len(&tmp_path).unwrap_or(0))))
    })();

    let mut dsd_dst_stats = match extraction_result {
        Ok(stats) => stats,
        Err(err) => {
            let _ = fs::remove_file(&tmp_path);
            return Err(err);
        }
    };

    match fs::rename(&tmp_path, &out_path) {
        Ok(()) => {
            if let Some(stats) = dsd_dst_stats.as_mut() {
                stats.bytes_written = file_len(&out_path).unwrap_or(stats.bytes_written);
            }
            Ok(RealizedTrackInfo {
                path: out_path,
                dsd_dst_stats,
            })
        }
        Err(first_err) if out_path.exists() => {
            let _ = fs::remove_file(&out_path);
            fs::rename(&tmp_path, &out_path).map_err(|second_err| {
                ConvertError::Io(io::Error::new(
                    second_err.kind(),
                    format!(
                        "failed to replace {} after successful SACD extraction: {}; first rename error: {}",
                        out_path.display(),
                        second_err,
                        first_err
                    ),
                ))
            })?;
            if let Some(stats) = dsd_dst_stats.as_mut() {
                stats.bytes_written = file_len(&out_path).unwrap_or(stats.bytes_written);
            }
            Ok(RealizedTrackInfo {
                path: out_path,
                dsd_dst_stats,
            })
        }
        Err(err) => {
            let _ = fs::remove_file(&tmp_path);
            Err(ConvertError::Io(err))
        }
    }
}

fn sacd_area_info(metadata: &SacdMetadata, area: SacdArea) -> Option<&AreaInfo> {
    match area {
        SacdArea::Stereo => metadata.stereo.as_ref(),
        SacdArea::MultiChannel => metadata.multi_channel.as_ref(),
    }
}

fn sacd_area_label(area: SacdArea) -> &'static str {
    match area {
        SacdArea::Stereo => "stereo",
        SacdArea::MultiChannel => "multichannel",
    }
}

fn sacd_track_output_name(
    iso: &Path,
    area: SacdArea,
    track_index: u32,
    entry: &TrackEntry,
    ext: &str,
) -> String {
    let stem = sanitize_segment_component(
        iso.file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("sacd"),
    );
    let path_hash = stable_path_hash(iso);
    format!(
        "{stem}_{path_hash:016x}_{}_track_{:03}_{:08x}_{:08x}.{ext}",
        sacd_area_label(area),
        track_index + 1,
        entry.start_lsn,
        entry.length_lsn
    )
}

fn unique_sacd_tmp_path(out_path: &Path) -> PathBuf {
    let file_name = out_path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("track");
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|value| value.as_nanos())
        .unwrap_or_default();
    out_path.with_file_name(format!(".{file_name}.{}.{}.tmp", std::process::id(), stamp))
}

#[derive(Debug, Clone, Copy)]
struct DsfExpectation {
    channel_count: u32,
    sample_frequency: u32,
    sample_count: u64,
}

impl DsfExpectation {
    fn from_area(area_info: &AreaInfo, duration: PlayTime) -> Self {
        Self {
            channel_count: u32::from(area_info.header.channel_count),
            sample_frequency: SACD_SAMPLE_RATE_HZ,
            sample_count: sacd_dsf_sample_count(duration),
        }
    }
}

fn sacd_output_is_ready(
    path: &Path,
    format: OutputFormat,
    area_info: &AreaInfo,
    duration: PlayTime,
) -> bool {
    match format {
        OutputFormat::Dsf => {
            let expectation = DsfExpectation::from_area(area_info, duration);
            dsf_output_is_ready_for(path, expectation)
        }
        _ => {
            // For DFF/DFF-DST: basic existence + non-empty check.
            // The extraction already validates via ExtractStats.
            path.metadata()
                .map(|m| m.is_file() && m.len() > 0)
                .unwrap_or(false)
        }
    }
}

#[derive(Debug, Clone, Copy)]
#[allow(dead_code)]
struct DsfHeader {
    file_size: u64,
    metadata_offset: u64,
    channel_count: u32,
    sample_frequency: u32,
    bits_per_sample: u32,
    sample_count: u64,
    block_size_per_channel: u32,
    data_chunk_size: u64,
}

fn dsf_output_is_ready_for(path: &Path, expectation: DsfExpectation) -> bool {
    validate_dsf_container(path, Some(expectation)).is_ok()
}

fn validate_sacd_realization(
    path: &Path,
    format: OutputFormat,
    area_info: &AreaInfo,
    duration: PlayTime,
    stats: ExtractStats,
) -> Result<(), ConvertError> {
    if stats.frames_read == 0 || stats.audio_bytes == 0 {
        return Err(ConvertError::TrackValidation(format!(
            "SACD extraction produced no audio for {}",
            path.display()
        )));
    }
    if stats.audio_bytes % u64::from(area_info.header.channel_count) != 0 {
        return Err(ConvertError::TrackValidation(format!(
            "SACD extraction produced audio bytes not divisible by channel count: {} bytes / {} channels",
            stats.audio_bytes,
            area_info.header.channel_count
        )));
    }

    let expectation = DsfExpectation::from_area(area_info, duration);
    if matches!(format, OutputFormat::Dsf) {
        validate_dsf_container(path, Some(expectation))?;
    }

    let expected_frames = u64::from(playtime_to_frame_count(duration));
    if expected_frames > 0 {
        let delta = stats.frames_read.abs_diff(expected_frames);
        if delta > 1 {
            log::warn!(
                "SACD frame count drift for {}: TOC expected {}, extractor emitted {}",
                path.display(),
                expected_frames,
                stats.frames_read
            );
        }
    }

    // Duration sanity check: TOC-derived duration can drift from the
    // byte-derived DSF sample count. Report the drift but keep the realized
    // file when container structure and extracted audio bytes are valid.
    let stats_sample_count = stats
        .audio_bytes
        .checked_div(u64::from(area_info.header.channel_count))
        .unwrap_or(0)
        .saturating_mul(8);
    if expectation.sample_count != 0 {
        let one_toc_frame_samples = u64::from(SACD_SAMPLE_RATE_HZ / 75);
        let delta = stats_sample_count.abs_diff(expectation.sample_count);
        if delta > one_toc_frame_samples {
            log::warn!(
                "SACD DSF sample-count drift for {}: TOC expected approximately {}, extractor emitted {}, delta {} samples",
                path.display(),
                expectation.sample_count,
                stats_sample_count,
                delta,
            );
        }
    }

    Ok(())
}

fn validate_dsf_container(
    path: &Path,
    expectation: Option<DsfExpectation>,
) -> Result<DsfHeader, ConvertError> {
    let metadata = fs::metadata(path).map_err(|err| {
        ConvertError::TrackValidation(format!(
            "realized SACD track missing: {} ({err})",
            path.display()
        ))
    })?;
    if !metadata.is_file() || metadata.len() <= 92 {
        return Err(ConvertError::TrackValidation(format!(
            "realized SACD track is empty or missing DSF payload: {}",
            path.display()
        )));
    }

    let mut file = fs::File::open(path)?;
    let mut header = [0_u8; 92];
    use std::io::Read;
    file.read_exact(&mut header)?;

    if &header[0..4] != b"DSD " || &header[28..32] != b"fmt " || &header[80..84] != b"data" {
        return Err(ConvertError::TrackValidation(format!(
            "realized SACD track is not a complete DSF container: {}",
            path.display()
        )));
    }

    let parsed = DsfHeader {
        file_size: read_u64_le(&header, 12),
        metadata_offset: read_u64_le(&header, 20),
        channel_count: read_u32_le(&header, 52),
        sample_frequency: read_u32_le(&header, 56),
        bits_per_sample: read_u32_le(&header, 60),
        sample_count: read_u64_le(&header, 64),
        block_size_per_channel: read_u32_le(&header, 72),
        data_chunk_size: read_u64_le(&header, 84),
    };

    if parsed.file_size != metadata.len() {
        return Err(ConvertError::TrackValidation(format!(
            "DSF header file size {} does not match actual size {} for {}",
            parsed.file_size,
            metadata.len(),
            path.display()
        )));
    }
    if parsed.bits_per_sample != 1 || parsed.block_size_per_channel == 0 {
        return Err(ConvertError::TrackValidation(format!(
            "DSF header has invalid DSD format fields for {}",
            path.display()
        )));
    }
    if parsed.data_chunk_size < 12 || parsed.data_chunk_size > parsed.file_size.saturating_sub(80) {
        return Err(ConvertError::TrackValidation(format!(
            "DSF data chunk size is invalid for {}",
            path.display()
        )));
    }
    if parsed.metadata_offset != 0 && parsed.metadata_offset >= parsed.file_size {
        return Err(ConvertError::TrackValidation(format!(
            "DSF metadata offset is outside the file for {}",
            path.display()
        )));
    }

    if let Some(expectation) = expectation {
        if parsed.channel_count != expectation.channel_count {
            return Err(ConvertError::TrackValidation(format!(
                "DSF channel count mismatch: expected {}, got {} for {}",
                expectation.channel_count,
                parsed.channel_count,
                path.display()
            )));
        }
        if parsed.sample_frequency != expectation.sample_frequency {
            return Err(ConvertError::TrackValidation(format!(
                "DSF sample frequency mismatch: expected {}, got {} for {}",
                expectation.sample_frequency,
                parsed.sample_frequency,
                path.display()
            )));
        }
        // SACD TOC PlayTime has 75 fps granularity. DSF sample counts
        // come from realized DSD payload bytes, so TOC-derived duration is
        // advisory rather than a container invariant.
        if expectation.sample_count != 0 {
            let one_toc_frame_samples = u64::from(expectation.sample_frequency / 75);
            let delta = parsed.sample_count.abs_diff(expectation.sample_count);
            if delta > one_toc_frame_samples {
                log::warn!(
                    "DSF sample-count drift for {}: TOC expected approximately {}, header contains {}, delta {} samples",
                    path.display(),
                    expectation.sample_count,
                    parsed.sample_count,
                    delta,
                );
            }
        }
    }

    Ok(parsed)
}

fn read_u32_le(bytes: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes(bytes[offset..offset + 4].try_into().unwrap())
}

fn read_u64_le(bytes: &[u8], offset: usize) -> u64 {
    u64::from_le_bytes(bytes[offset..offset + 8].try_into().unwrap())
}

fn sacd_dsf_sample_count(time: PlayTime) -> u64 {
    u64::from(playtime_to_frame_count(time)) * u64::from(SACD_SAMPLE_RATE_HZ)
        / u64::from(SACD_FRAME_RATE)
}

fn playtime_to_frame_count(time: PlayTime) -> u32 {
    u32::from(time.minutes) * 60 * SACD_FRAME_RATE
        + u32::from(time.seconds) * SACD_FRAME_RATE
        + u32::from(time.frames)
}

fn sacd_error_to_convert(err: SacdError) -> ConvertError {
    match err {
        SacdError::NotSacdIso => ConvertError::Realize(
            "SACD ISO is encrypted, corrupt, or missing Master TOC magic".to_string(),
        ),
        SacdError::Malformed(message) if looks_encrypted_sacd(&message) => {
            ConvertError::Realize("SACD ISO is encrypted or scrambled".to_string())
        }
        SacdError::Malformed(message) => ConvertError::Realize(message),
        SacdError::TooSmall { .. } => ConvertError::Realize(err.to_string()),
        SacdError::Io(message) => ConvertError::Realize(message),
    }
}

fn looks_encrypted_sacd(message: &str) -> bool {
    let lower = message.to_ascii_lowercase();
    lower.contains("encrypted") || lower.contains("scrambled") || lower.contains("cipher")
}

