    fn assert_closed_metadata_environment(command: &ToolCommand, locale: &str) {
        assert_eq!(
            command.environment_policy,
            tonepoet_pipeline::CommandEnvironmentPolicy::ClearAndSet
        );
        assert_eq!(command.env.len(), 1);
        assert_eq!(command.env[0].key, "LC_ALL");
        assert_eq!(command.env[0].value.expose(), locale);
        assert!(!command.env[0].secret);
    }

    #[test]
    fn source_provenance_with_ape_nul_values_is_scalarized_only_at_output_boundary() {
        let mut track = TrackMetadata {
            artist: vec!["A".to_string(), "B".to_string(), "A".to_string()].into(),
            ..TrackMetadata::default()
        };
        insert_source_text_tag(&mut track.extra, "MY_NOTE", "one\0two\0one");
        assert_eq!(
            track.extra.get("my_note").map(String::as_str),
            Some("one\0two\0one"),
            "ingestion keeps immutable source provenance intact",
        );

        let tags = authoritative_metadata_tags(&track, &AlbumMetadata::default());
        let values = |key: &str| {
            tags.iter()
                .filter(|(candidate, _)| candidate == key)
                .map(|(_, value)| value.as_str())
                .collect::<Vec<_>>()
        };
        assert_eq!(values("ARTIST"), vec!["A", "B", "A"]);
        assert_eq!(values("MY_NOTE"), vec!["one; two; one"]);
        assert!(tags.iter().all(|(_, value)| !value.contains('\0')));

        let (command, _) = metadata_tag_command(
            Path::new("track.flac"),
            "flac",
            &tags,
            &BTreeSet::new(),
        )
        .expect("sanitized source provenance must produce a legal native command");
        assert!(command.args.iter().all(|arg| !arg.contains('\0')));
        assert_eq!(
            command
                .args
                .iter()
                .filter(|arg| arg.starts_with("--set-tag=ARTIST="))
                .count(),
            3,
            "typed list values remain independent native entries",
        );
        assert!(command
            .args
            .iter()
            .any(|arg| arg == "--set-tag=MY_NOTE=one; two; one"));
        assert!(source_provenance_requires_scalar_projection(
            &track,
            &AlbumMetadata::default(),
            &tags,
        ));

        let mut writer_owned = TrackMetadata {
            title: Some("Canonical title".to_string()),
            ..TrackMetadata::default()
        };
        insert_source_text_tag(&mut writer_owned.extra, "TITLE", "one\0two");
        let writer_owned_tags =
            authoritative_metadata_tags(&writer_owned, &AlbumMetadata::default());
        assert!(
            !source_provenance_requires_scalar_projection(
                &writer_owned,
                &AlbumMetadata::default(),
                &writer_owned_tags,
            ),
            "writer-owned source provenance must not create a second obligation",
        );

        let mut invalid_key = TrackMetadata::default();
        insert_source_text_tag(&mut invalid_key.extra, "BAD=KEY", "one\0two");
        let invalid_key_tags = authoritative_metadata_tags(&invalid_key, &AlbumMetadata::default());
        assert!(
            !source_provenance_requires_scalar_projection(
                &invalid_key,
                &AlbumMetadata::default(),
                &invalid_key_tags,
            ),
            "provenance that cannot become a legal output key must not force a pass",
        );

        let mut fallback_track = TrackMetadata::default();
        insert_fallback_source_tag(&mut fallback_track.extra, "MY_NOTE", "one\0two\0one");
        let fallback_album = AlbumMetadata {
            extra: BTreeMap::from([(
                FALLBACK_RECOVERED_METADATA_EXTRA_KEY.to_string(),
                "native-apev2".to_string(),
            )]),
            ..AlbumMetadata::default()
        };
        let fallback_tags = authoritative_metadata_tags(&fallback_track, &fallback_album);
        assert!(fallback_tags.contains(&(
            "MY_NOTE".to_string(),
            "one; two; one".to_string(),
        )));
        assert!(fallback_tags.iter().all(|(_, value)| !value.contains('\0')));
    }

    #[test]
    fn production_metadata_commands_use_closed_locale_environment() {
        let temp = tempfile::tempdir().expect("metadata test tempdir");
        let input = temp.path().join("track.wav");
        fs::write(&input, b"RIFF\0\0\0\0WAVE").expect("write RIFF marker");
        let tags = vec![("TITLE".to_string(), "Reference 25・3P-426".to_string())];
        let (ffmpeg, _) = metadata_tag_command(&input, "wav", &tags, &BTreeSet::new())
            .expect("build FFmpeg metadata command");
        assert_closed_metadata_environment(&ffmpeg, "C.UTF-8");
        assert!(ffmpeg.args.iter().any(|arg| arg.contains("25・3P-426")));

        let metaflac_discovery = native_existing_tag_list_command(Path::new("track.flac"), "flac")
            .expect("build metaflac discovery command");
        assert_closed_metadata_environment(&metaflac_discovery, "C");
        let (metaflac_mutation, metaflac_temporary) = metadata_tag_command(
            Path::new("track.flac"),
            "flac",
            &tags,
            &BTreeSet::new(),
        )
        .expect("build metaflac mutation command");
        assert_eq!(metaflac_mutation.binary, ToolBinary::Metaflac);
        assert!(metaflac_temporary.is_none());
        assert_closed_metadata_environment(&metaflac_mutation, "C.UTF-8");

        let wvtag_discovery = native_existing_tag_list_command(Path::new("track.wv"), "wv")
            .expect("build wvtag discovery command");
        assert_closed_metadata_environment(&wvtag_discovery, "C");
        let (wvtag_mutation, wvtag_temporary) = metadata_tag_command(
            Path::new("track.wv"),
            "wv",
            &tags,
            &BTreeSet::new(),
        )
        .expect("build wvtag mutation command");
        assert_eq!(wvtag_mutation.binary, ToolBinary::Wvtag);
        assert!(wvtag_temporary.is_none());
        assert_closed_metadata_environment(&wvtag_mutation, "C.UTF-8");

        let atomic_parsley = m4a_freeform_tag_command(
            Path::new("track.m4a"),
            &[("MY_NOTE".to_string(), "Reference".to_string())],
        );
        assert_closed_metadata_environment(&atomic_parsley, "C.UTF-8");
    }

    #[test]
    fn aiff_metadata_rewrite_enables_id3v24_only_for_aiff_destinations() {
        let temp = tempfile::tempdir().expect("metadata test tempdir");
        let tags = vec![("TITLE".to_string(), "AIFF metadata".to_string())];

        for ext in ["aiff", "aif"] {
            let input = temp.path().join(format!("track.{ext}"));
            fs::write(&input, b"FORM\0\0\0\0AIFF").expect("write AIFF marker");
            let (command, temporary) =
                metadata_tag_command(&input, ext, &tags, &BTreeSet::new())
                    .expect("build AIFF metadata command");
            assert_eq!(command.binary, ToolBinary::Ffmpeg);
            assert_pair(&command.args, "-write_id3v2", "1");
            assert_pair(&command.args, "-id3v2_version", "4");
            assert!(temporary.is_some());
        }

        for ext in ["mp3", "m4a"] {
            let input = temp.path().join(format!("track.{ext}"));
            fs::write(&input, b"source audio").expect("write metadata source");
            let (command, temporary) =
                metadata_tag_command(&input, ext, &tags, &BTreeSet::new())
                    .expect("build non-AIFF metadata command");
            assert!(!command.args.iter().any(|arg| arg == "-write_id3v2"));
            assert!(!command.args.iter().any(|arg| arg == "-id3v2_version"));
            assert!(temporary.is_some());
        }

        let wav = temp.path().join("track.wav");
        fs::write(&wav, b"RIFF\0\0\0\0WAVE").expect("write WAV marker");
        let (command, temporary) = metadata_tag_command(&wav, "wav", &tags, &BTreeSet::new())
            .expect("build WAV metadata command");
        assert!(!command.args.iter().any(|arg| arg == "-write_id3v2"));
        assert!(!command.args.iter().any(|arg| arg == "-id3v2_version"));
        assert!(temporary.is_some());
    }

