fn conversion_log_batch_cleanup_lifecycle_is_complete(
    coord_dir: &Path,
    batch_id: &str,
) -> io::Result<bool> {
    if !conversion_log_batch_drain_is_complete(coord_dir, batch_id)? {
        return Ok(false);
    }
    let manifest = read_conversion_log_batch_drain_manifest(coord_dir, batch_id)?;
    if !manifest.post_actions_required {
        return Ok(true);
    }
    Ok(read_conversion_log_batch_post_action_terminal(coord_dir, &manifest)?.is_some())
}

fn conversion_log_batch_drain_stable_path(path: &Path) -> String {
    normalize_path(path)
        .to_string_lossy()
        .replace('\\', "/")
}

fn conversion_log_batch_drain_participant_id(path: &Path) -> String {
    let body = format!(
        "tonepoet-conversion-log-batch-participant-v1\n{}",
        conversion_log_batch_drain_stable_path(path)
    );
    super::manifest::sha256_hex(body.as_bytes())
}

fn conversion_log_batch_drain_hex_identity_is_valid(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn conversion_log_batch_drain_ordinal_participant_id(
    batch_id: &str,
    source_ordinal: u32,
) -> String {
    let body = format!(
        "tonepoet-conversion-log-batch-ordinal-participant-v1\n{batch_id}\n{source_ordinal}"
    );
    super::manifest::sha256_hex(body.as_bytes())
}

fn conversion_log_batch_drain_expected_participants(
    req: &PipelineRequest,
) -> io::Result<(Vec<String>, String)> {
    let batch = req.album_batch.as_ref().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "batch participant drain authority requires album batch context",
        )
    })?;

    if !batch.source_paths().is_empty() {
        let mut expected = batch
            .source_paths()
            .iter()
            .map(|path| conversion_log_batch_drain_participant_id(path))
            .collect::<Vec<_>>();
        expected.sort();
        expected.dedup();
        if expected.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "album batch participant drain authority has no expected participants",
            ));
        }
        let current = conversion_log_batch_drain_participant_id(&req.container);
        if expected.binary_search(&current).is_err() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "request source {} is not a dispatcher-authored participant in album batch {}",
                    req.container.display(),
                    batch.conversion_log_batch_id
                ),
            ));
        }
        return Ok((expected, current));
    }

    // Compatibility for queue records written before `source_paths` became
    // durable. A CUE-image batch is one worker even when it yields many tracks.
    // Independent single-file batches can use the dispatcher-authored source
    // ordinal/count contract. Any shape that cannot be proven is preserved for
    // manual recovery rather than guessed from mutable paths or tags.
    match detect_source_kind(req) {
        Ok(SourceKind::CueImage) => {
            let current = conversion_log_batch_drain_participant_id(&req.container);
            Ok((vec![current.clone()], current))
        }
        Ok(SourceKind::SingleFile) => {
            let track = req.album_batch_track.as_ref().ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "legacy single-file album batch {} has no dispatcher track identity for participant drain recovery",
                        batch.conversion_log_batch_id
                    ),
                )
            })?;
            if track.source_ordinal == 0
                || track.source_ordinal as usize > batch.expected_track_count
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "legacy single-file batch participant source ordinal is outside the expected range",
                ));
            }
            let expected_count = u32::try_from(batch.expected_track_count).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "legacy single-file batch participant count exceeds the durable ordinal range",
                )
            })?;
            let expected = (1..=expected_count)
                .map(|ordinal| {
                    conversion_log_batch_drain_ordinal_participant_id(
                        &batch.conversion_log_batch_id,
                        ordinal,
                    )
                })
                .collect::<Vec<_>>();
            let current = conversion_log_batch_drain_ordinal_participant_id(
                &batch.conversion_log_batch_id,
                track.source_ordinal,
            );
            Ok((expected, current))
        }
        _ if batch.expected_track_count == 1 => {
            let current = conversion_log_batch_drain_participant_id(&req.container);
            Ok((vec![current.clone()], current))
        }
        _ => Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "album batch {} has no dispatcher-authored source_paths and its participant set cannot be reconstructed safely",
                batch.conversion_log_batch_id
            ),
        )),
    }
}

fn conversion_log_batch_drain_request_authority(
    req: &PipelineRequest,
) -> io::Result<ConversionLogBatchDrainRequestAuthority> {
    let batch = req.album_batch.as_ref().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "batch participant drain authority requires album batch context",
        )
    })?;
    let batch_id = batch.conversion_log_batch_id.trim();
    if !is_generated_conversion_log_batch_id(batch_id) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "batch participant drain authority requires a generated dispatch batch id",
        ));
    }
    let (expected_participants, participant_id) =
        conversion_log_batch_drain_expected_participants(req)?;
    let action_pipeline = req.actions.canonical_serialization().map_err(|error| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("could not canonicalize action pipeline for batch drain authority: {error}"),
        )
    })?;
    let settings_fingerprint =
        tonepoet_pipeline::fingerprint::settings_fingerprint(&req.settings).to_string();
    let body = format!(
        concat!(
            "tonepoet-conversion-log-batch-drain-v1\n",
            "batch_id={}\n",
            "expected_track_count={}\n",
            "album_output_dir={}\n",
            "source_grouping_root={}\n",
            "output_root={}\n",
            "settings_fingerprint={}\n",
            "action_pipeline={}\n",
            "participants={}\n"
        ),
        batch_id,
        batch.expected_track_count,
        conversion_log_batch_drain_stable_path(&batch.album_output_dir),
        conversion_log_batch_drain_stable_path(&batch.source_grouping_root),
        conversion_log_batch_drain_stable_path(&req.output_root),
        settings_fingerprint,
        action_pipeline,
        expected_participants.join(","),
    );
    Ok(ConversionLogBatchDrainRequestAuthority {
        manifest: ConversionLogBatchDrainManifest {
            schema_version: CONVERSION_LOG_BATCH_DRAIN_SCHEMA_VERSION,
            batch_id: batch_id.to_string(),
            pipeline_sha256: super::manifest::sha256_hex(body.as_bytes()),
            post_actions_required: !req.actions.post.is_empty()
                && conversion_actions_effective_for_request(req)?,
            expected_participants,
        },
        participant_id,
    })
}

fn ensure_no_follow_directory(path: &Path) -> io::Result<()> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if metadata.is_dir() && !metadata.file_type().is_symlink() => Ok(()),
        Ok(_) => Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("expected a no-follow directory: {}", path.display()),
        )),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            fs::create_dir(path)?;
            let metadata = fs::symlink_metadata(path)?;
            if !metadata.is_dir() || metadata.file_type().is_symlink() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("created path is not a no-follow directory: {}", path.display()),
                ));
            }
            sync_parent_dir(path)
        }
        Err(error) => Err(error),
    }
}

fn read_regular_file_no_follow(path: &Path) -> io::Result<Vec<u8>> {
    use std::io::Read;

    let path_metadata = fs::symlink_metadata(path)?;
    if path_metadata.file_type().is_symlink() || !path_metadata.is_file() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("expected a regular no-follow file: {}", path.display()),
        ));
    }
    let mut options = fs::OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.custom_flags(libc::O_NOFOLLOW);
    }
    let mut file = options.open(path)?;
    let opened_metadata = file.metadata()?;
    if !opened_metadata.is_file() || !lock_handle_is_current(&opened_metadata, path) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("file changed while opening no-follow authority: {}", path.display()),
        ));
    }
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes)?;
    Ok(bytes)
}

fn validate_conversion_log_batch_drain_manifest(
    manifest: &ConversionLogBatchDrainManifest,
    expected_batch_id: &str,
) -> io::Result<()> {
    if manifest.schema_version != CONVERSION_LOG_BATCH_DRAIN_SCHEMA_VERSION
        || manifest.batch_id != expected_batch_id
        || !is_generated_conversion_log_batch_id(&manifest.batch_id)
        || !conversion_log_batch_drain_hex_identity_is_valid(&manifest.pipeline_sha256)
        || manifest.expected_participants.is_empty()
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "invalid conversion-log batch participant drain manifest identity",
        ));
    }
    let mut canonical = manifest.expected_participants.clone();
    if canonical
        .iter()
        .any(|value| !conversion_log_batch_drain_hex_identity_is_valid(value))
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "conversion-log batch participant drain manifest contains an invalid participant id",
        ));
    }
    canonical.sort();
    canonical.dedup();
    if canonical != manifest.expected_participants {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "conversion-log batch participant drain manifest is not sorted and unique",
        ));
    }
    Ok(())
}

fn read_conversion_log_batch_drain_manifest(
    coord_dir: &Path,
    batch_id: &str,
) -> io::Result<ConversionLogBatchDrainManifest> {
    let path = conversion_log_batch_drain_manifest_path(coord_dir);
    let bytes = read_regular_file_no_follow(&path)?;
    let manifest: ConversionLogBatchDrainManifest = serde_json::from_slice(&bytes).map_err(|error| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("could not parse batch participant drain manifest {}: {error}", path.display()),
        )
    })?;
    validate_conversion_log_batch_drain_manifest(&manifest, batch_id)?;
    Ok(manifest)
}

fn validate_conversion_log_batch_drain_ack(
    ack: &ConversionLogBatchDrainAck,
    manifest: &ConversionLogBatchDrainManifest,
    expected_participant_id: &str,
) -> io::Result<()> {
    if ack.schema_version != CONVERSION_LOG_BATCH_DRAIN_SCHEMA_VERSION
        || ack.batch_id != manifest.batch_id
        || ack.pipeline_sha256 != manifest.pipeline_sha256
        || ack.participant_id != expected_participant_id
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "invalid conversion-log batch drain acknowledgment for participant {expected_participant_id}"
            ),
        ));
    }
    Ok(())
}

fn read_conversion_log_batch_drain_ack(
    coord_dir: &Path,
    manifest: &ConversionLogBatchDrainManifest,
    participant_id: &str,
) -> io::Result<ConversionLogBatchDrainAck> {
    let path = conversion_log_batch_drain_ack_path(coord_dir, participant_id);
    let bytes = read_regular_file_no_follow(&path)?;
    let ack: ConversionLogBatchDrainAck = serde_json::from_slice(&bytes).map_err(|error| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("could not parse batch participant drain acknowledgment {}: {error}", path.display()),
        )
    })?;
    validate_conversion_log_batch_drain_ack(&ack, manifest, participant_id)?;
    Ok(ack)
}

fn validate_conversion_log_batch_drain_inventory(
    coord_dir: &Path,
    manifest: &ConversionLogBatchDrainManifest,
) -> io::Result<BTreeSet<String>> {
    let drain_dir = conversion_log_batch_drain_dir(coord_dir);
    let metadata = fs::symlink_metadata(&drain_dir)?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("batch participant drain authority is not a no-follow directory: {}", drain_dir.display()),
        ));
    }
    let expected_names = manifest
        .expected_participants
        .iter()
        .map(|participant| conversion_log_batch_drain_ack_file_name(participant))
        .collect::<BTreeSet<_>>();
    let mut observed = BTreeSet::new();
    for entry in fs::read_dir(&drain_dir)? {
        let entry = entry?;
        let name = entry.file_name().into_string().map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("batch participant drain authority contains a non-UTF-8 entry: {}", drain_dir.display()),
            )
        })?;
        let file_type = entry.file_type()?;
        if file_type.is_symlink() || !file_type.is_file() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("batch participant drain authority contains a non-regular entry: {}", entry.path().display()),
            ));
        }
        if name == CONVERSION_LOG_BATCH_DRAIN_MANIFEST_FILE {
            continue;
        }
        if !expected_names.contains(&name) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("batch participant drain authority contains an unrecognized entry: {}", entry.path().display()),
            ));
        }
        observed.insert(name);
    }
    Ok(observed)
}

#[allow(dead_code)] // bundle-provided API surface, not yet wired to a caller
fn ensure_conversion_log_batch_drain_manifest_for_request(
    req: &PipelineRequest,
) -> io::Result<ConversionLogBatchDrainRequestAuthority> {
    let coord_dir = conversion_log_batch_coordination_album_dir(req).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "batch participant drain authority requires a coordination directory",
        )
    })?;
    ensure_conversion_log_batch_drain_manifest_for_request_at(req, &coord_dir)
}

fn ensure_conversion_log_batch_drain_manifest_for_request_at(
    req: &PipelineRequest,
    coord_dir: &Path,
) -> io::Result<ConversionLogBatchDrainRequestAuthority> {
    let authority = conversion_log_batch_drain_request_authority(req)?;
    let _ownership_lock = acquire_conversion_log_batch_workspace_ownership_lock(
        &coord_dir,
        &authority.manifest.batch_id,
    )?;
    let state = read_conversion_log_batch_workspace_state(&coord_dir)?.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::NotFound,
            format!("batch workspace state is missing: {}", coord_dir.display()),
        )
    })?;
    if state.batch_id != authority.manifest.batch_id
        || state.status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
        || !state
            .owner
            .as_ref()
            .is_some_and(|owner| owner_is_current_process(owner).unwrap_or(false))
    {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!("batch participant drain authority is not owned by the current process: {}", coord_dir.display()),
        ));
    }

    let drain_dir = conversion_log_batch_drain_dir(&coord_dir);
    ensure_no_follow_directory(&drain_dir)?;
    let manifest_path = conversion_log_batch_drain_manifest_path(&coord_dir);
    match fs::symlink_metadata(&manifest_path) {
        Ok(_) => {
            let existing = read_conversion_log_batch_drain_manifest(
                &coord_dir,
                &authority.manifest.batch_id,
            )?;
            if existing != authority.manifest {
                return Err(io::Error::new(
                    io::ErrorKind::AlreadyExists,
                    format!("batch participant drain manifest conflicts with the current request: {}", manifest_path.display()),
                ));
            }
        }
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            let bytes = serde_json::to_vec_pretty(&authority.manifest).map_err(|error| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("could not serialize batch participant drain manifest: {error}"),
                )
            })?;
            write_bytes_atomically(&manifest_path, &bytes)?;
            sync_parent_dir(&manifest_path)?;
        }
        Err(error) => return Err(error),
    }
    validate_conversion_log_batch_drain_inventory(&coord_dir, &authority.manifest)?;
    Ok(authority)
}

fn conversion_log_batch_drain_is_complete(
    coord_dir: &Path,
    batch_id: &str,
) -> io::Result<bool> {
    let drain_dir = conversion_log_batch_drain_dir(coord_dir);
    match fs::symlink_metadata(&drain_dir) {
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(false),
        Ok(metadata) if metadata.is_dir() && !metadata.file_type().is_symlink() => {}
        Ok(_) => {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("batch participant drain authority is not a no-follow directory: {}", drain_dir.display()),
            ));
        }
        Err(error) => return Err(error),
    }
    let manifest = read_conversion_log_batch_drain_manifest(coord_dir, batch_id)?;
    let observed = validate_conversion_log_batch_drain_inventory(coord_dir, &manifest)?;
    for participant_id in &manifest.expected_participants {
        let name = conversion_log_batch_drain_ack_file_name(participant_id);
        if !observed.contains(&name) {
            return Ok(false);
        }
        read_conversion_log_batch_drain_ack(coord_dir, &manifest, participant_id)?;
    }
    Ok(true)
}

fn record_conversion_log_batch_participant_drained(
    req: &PipelineRequest,
) -> io::Result<bool> {
    if req.album_batch.is_none() {
        return Ok(true);
    }
    let coord_dir = conversion_log_batch_coordination_album_dir(req).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "batch participant drain acknowledgment requires a coordination directory",
        )
    })?;
    record_conversion_log_batch_participant_drained_at(req, &coord_dir)
}

fn record_conversion_log_batch_participant_drained_at(
    req: &PipelineRequest,
    coord_dir: &Path,
) -> io::Result<bool> {
    if req.album_batch.is_none() {
        return Ok(true);
    }
    ensure_conversion_log_batch_workspace_owned_for_request_at(req, coord_dir)?;
    let authority = ensure_conversion_log_batch_drain_manifest_for_request_at(req, coord_dir)?;
    let _ownership_lock = acquire_conversion_log_batch_workspace_ownership_lock(
        &coord_dir,
        &authority.manifest.batch_id,
    )?;
    let state = read_conversion_log_batch_workspace_state(&coord_dir)?.ok_or_else(|| {
        io::Error::new(io::ErrorKind::NotFound, "batch workspace state disappeared")
    })?;
    if state.status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
        || !state
            .owner
            .as_ref()
            .is_some_and(|owner| owner_is_current_process(owner).unwrap_or(false))
    {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            "batch participant drain acknowledgment refused without current ownership",
        ));
    }
    let manifest = read_conversion_log_batch_drain_manifest(
        &coord_dir,
        &authority.manifest.batch_id,
    )?;
    if manifest != authority.manifest {
        return Err(io::Error::new(
            io::ErrorKind::AlreadyExists,
            "batch participant drain manifest changed before acknowledgment",
        ));
    }

    let ack = ConversionLogBatchDrainAck {
        schema_version: CONVERSION_LOG_BATCH_DRAIN_SCHEMA_VERSION,
        batch_id: manifest.batch_id.clone(),
        pipeline_sha256: manifest.pipeline_sha256.clone(),
        participant_id: authority.participant_id.clone(),
    };
    let ack_path = conversion_log_batch_drain_ack_path(&coord_dir, &authority.participant_id);
    match fs::symlink_metadata(&ack_path) {
        Ok(_) => {
            let existing = read_conversion_log_batch_drain_ack(
                &coord_dir,
                &manifest,
                &authority.participant_id,
            )?;
            if existing != ack {
                return Err(io::Error::new(
                    io::ErrorKind::AlreadyExists,
                    format!("conflicting batch participant drain acknowledgment: {}", ack_path.display()),
                ));
            }
        }
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            use std::io::Write;
            let bytes = serde_json::to_vec_pretty(&ack).map_err(|error| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("could not serialize batch participant drain acknowledgment: {error}"),
                )
            })?;
            let mut options = fs::OpenOptions::new();
            options.create_new(true).write(true);
            #[cfg(unix)]
            {
                use std::os::unix::fs::OpenOptionsExt;
                options.custom_flags(libc::O_NOFOLLOW);
            }
            let mut file = options.open(&ack_path)?;
            let write_result = file.write_all(&bytes).and_then(|()| file.sync_all());
            if let Err(error) = write_result {
                drop(file);
                let removed = match fs::remove_file(&ack_path) {
                    Ok(()) => sync_parent_dir(&ack_path).is_ok(),
                    Err(remove_error) if remove_error.kind() == io::ErrorKind::NotFound => true,
                    Err(_) => false,
                };
                if !removed {
                    log::warn!(
                        "failed batch drain acknowledgment remained visible after write failure: {}",
                        ack_path.display()
                    );
                }
                return Err(error);
            }
            sync_parent_dir(&ack_path)?;
        }
        Err(error) => return Err(error),
    }
    conversion_log_batch_drain_is_complete(&coord_dir, &manifest.batch_id)
}

fn cleanup_conversion_log_batch_drain_authority(
    coord_dir: &Path,
    batch_id: &str,
) -> io::Result<()> {
    let drain_dir = conversion_log_batch_drain_dir(coord_dir);
    let metadata = match fs::symlink_metadata(&drain_dir) {
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(()),
        Ok(metadata) => metadata,
        Err(error) => return Err(error),
    };
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("batch participant drain authority is not a no-follow directory: {}", drain_dir.display()),
        ));
    }

    let manifest_path = conversion_log_batch_drain_manifest_path(coord_dir);
    let manifest = match fs::symlink_metadata(&manifest_path) {
        Ok(_) => Some(read_conversion_log_batch_drain_manifest(coord_dir, batch_id)?),
        Err(error) if error.kind() == io::ErrorKind::NotFound => None,
        Err(error) => return Err(error),
    };
    let Some(manifest) = manifest else {
        let mut entries = fs::read_dir(&drain_dir)?;
        if entries.next().transpose()?.is_some() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("batch drain manifest is missing while authority entries remain: {}", drain_dir.display()),
            ));
        }
        fs::remove_dir(&drain_dir)?;
        sync_parent_dir(&drain_dir)?;
        return Ok(());
    };

    validate_conversion_log_batch_drain_inventory(coord_dir, &manifest)?;
    for participant_id in &manifest.expected_participants {
        let ack_path = conversion_log_batch_drain_ack_path(coord_dir, participant_id);
        match fs::remove_file(&ack_path) {
            Ok(()) => sync_parent_dir(&ack_path)?,
            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
            Err(error) => return Err(error),
        }
    }

    // The manifest is the last object removed from the drain authority. Once
    // the parent workspace is durably `cleaning`, its absence means the drain
    // gate was already satisfied and cleanup may resume after a crash.
    fs::remove_file(&manifest_path)?;
    sync_parent_dir(&manifest_path)?;
    fs::remove_dir(&drain_dir)?;
    sync_parent_dir(&drain_dir)
}

fn sweep_stale_completed_conversion_log_batch_coordination_for_request_best_effort(
    req: &PipelineRequest,
    context: &str,
) {
    sweep_stale_completed_conversion_log_batch_coordination_for_request_at_best_effort(
        req,
        &req.output_root,
        context,
    );
}

fn sweep_stale_completed_conversion_log_batch_coordination_for_request_at_best_effort(
    req: &PipelineRequest,
    output_root: &Path,
    context: &str,
) {
    let current_batch_id = req
        .album_batch
        .as_ref()
        .map(|batch| batch.conversion_log_batch_id.trim())
        .filter(|value| !value.is_empty());
    let current_source_grouping_root = req
        .album_batch
        .as_ref()
        .map(|batch| batch.source_grouping_root.to_string_lossy().into_owned());
    sweep_stale_completed_conversion_log_batch_coordination_dirs_with_scope_best_effort(
        output_root,
        current_batch_id,
        current_source_grouping_root.as_deref(),
        context,
    );
}

fn sweep_stale_completed_conversion_log_batch_coordination_for_identity_best_effort(
    identity: &ConversionLogBatchIdentity,
    context: &str,
) {
    if let Some(output_root) = conversion_log_batch_output_root_from_identity(identity) {
        sweep_stale_completed_conversion_log_batch_coordination_dirs_with_scope_best_effort(
            &output_root,
            Some(identity.conversion_log_batch_id.as_str()),
            Some(identity.source_grouping_root.as_str()),
            context,
        );
    }
}

#[allow(dead_code)] // bundle-provided API surface, not yet wired to a caller
fn sweep_stale_completed_conversion_log_batch_coordination_dirs_best_effort(
    output_root: &Path,
    current_batch_id: Option<&str>,
    context: &str,
) {
    sweep_stale_completed_conversion_log_batch_coordination_dirs_with_scope_best_effort(
        output_root,
        current_batch_id,
        None,
        context,
    )
}

fn sweep_stale_completed_conversion_log_batch_coordination_dirs_with_scope_best_effort(
    output_root: &Path,
    current_batch_id: Option<&str>,
    current_source_grouping_root: Option<&str>,
    context: &str,
) {
    let coord_root = normalize_path(output_root).join(CONVERSION_LOG_BATCH_COORDINATION_DIR);
    let entries = match fs::read_dir(&coord_root) {
        Ok(entries) => entries,
        Err(err) if err.kind() == io::ErrorKind::NotFound => return,
        Err(err) => {
            log::warn!(
                "conversion-log batch cleanup could not scan stale coordination root for {context}: {}: {err}",
                coord_root.display()
            );
            return;
        }
    };

    for entry in entries {
        let entry = match entry {
            Ok(entry) => entry,
            Err(err) => {
                // A stale-workspace sweep is destructive. A directory-entry
                // error means the scan is incomplete, so this entire pass must
                // fail closed rather than silently skipping an unknown child.
                log::warn!(
                    "conversion-log batch cleanup aborted incomplete scan for {context}: {}: {err}",
                    coord_root.display()
                );
                return;
            }
        };
        let path = entry.path();
        let file_type = match entry.file_type() {
            Ok(file_type) => file_type,
            Err(err) => {
                log::warn!(
                    "conversion-log batch cleanup aborted because entry type could not be read for {context}: {}: {err}",
                    path.display()
                );
                return;
            }
        };
        if !file_type.is_dir() || file_type.is_symlink() {
            if file_type.is_file() {
                let name = entry.file_name();
                let name = name.to_string_lossy();
                if name.starts_with('.') && name.ends_with(".workspace-ownership.lock") {
                    remove_unheld_lock_file_best_effort(&path);
                }
            }
            continue;
        }
        let Some(batch_id) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        if current_batch_id.is_some_and(|current| current == batch_id) {
            continue;
        }
        if !is_generated_conversion_log_batch_id(batch_id) {
            continue;
        }
        if conversion_log_batch_workspace_registered_active(batch_id) {
            continue;
        }

        let state = match read_conversion_log_batch_workspace_state(&path) {
            Ok(state) => state,
            Err(err) => {
                log::warn!(
                    "conversion-log batch cleanup skipped unreadable workspace state for {context}: {}: {err}",
                    path.display()
                );
                continue;
            }
        };
        if state
            .as_ref()
            .is_some_and(|state| state.batch_id != batch_id)
        {
            log::warn!(
                "conversion-log batch cleanup skipped mismatched workspace state for {context}: dir {} contains batch id {}",
                path.display(),
                state.as_ref().map(|state| state.batch_id.as_str()).unwrap_or("<unknown>")
            );
            continue;
        }

        // Ownership is the first and load-bearing deletion/repair gate. Do
        // not even repair a transaction marker in a workspace whose owner is
        // alive, remote, legacy, absent, or otherwise unknown: on shared
        // storage that would mutate another host's live coordination state.
        if conversion_log_batch_workspace_owner_may_be_live(batch_id, state.as_ref()) {
            let current_owner_inactive = |state: &ConversionLogBatchWorkspaceState| {
                state
                    .owner
                    .as_ref()
                    .is_some_and(|owner| owner_is_current_process(owner).unwrap_or(false))
                    && !conversion_log_batch_workspace_registered_active(batch_id)
            };
            let resumable_current_cleaning = state.as_ref().is_some_and(|state| {
                state.status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
                    && current_owner_inactive(state)
            });
            // A TERMINAL workspace still claimed by this very process may be
            // retired only by an OWNED RETRY: the pipeline wrappers pass a
            // batch scope exactly when a real coordinated publish for this
            // output root is underway in this process, which supersedes our
            // own earlier terminal attempts. Bare/diagnostic sweeps pass no
            // scope and preserve terminal recovery context (pinned by
            // same_process_terminal_workspace_is_preserved_until_owned_retry).
            let terminal_current_owner = current_source_grouping_root.is_some()
                && state.as_ref().is_some_and(|state| {
                    conversion_log_batch_workspace_status_is_terminal(&state.status)
                        && current_owner_inactive(state)
                });
            if !resumable_current_cleaning && !terminal_current_owner {
                continue;
            }
        }

        if workspace_has_unresolved_action_state(&path) {
            log::warn!(
                "conversion-log batch cleanup preserved stale workspace with unresolved or unreadable action state for {context}: {}",
                path.display()
            );
            continue;
        }

        // Every retirement goes through the ownership-lock-protected,
        // participant-drain-gated, state-last cleanup protocol. Dead active
        // workspaces remain recoverable and are never reclassified as garbage
        // merely because their original process exited.
        if state.is_some() {
            cleanup_conversion_log_batch_coordination_dir_after_success_best_effort(
                &path,
                context,
                ConversionLogBatchCleanupAuthority::CurrentOrProvenDeadLocalOwner,
            );
        }
    }

    match fs::remove_dir(&coord_root) {
        Ok(()) => sync_parent_dir_best_effort(&coord_root),
        Err(err) if err.kind() == io::ErrorKind::NotFound => {}
        Err(err) if err.kind() == io::ErrorKind::DirectoryNotEmpty => {}
        Err(err) => log::warn!(
            "conversion-log batch cleanup could not remove empty coordination root for {context}: {}: {err}",
            coord_root.display()
        ),
    }
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
struct ConversionLogBatchWorkspaceState {
    schema_version: u8,
    batch_id: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    owner: Option<ProcessOwnerIdentity>,
    /// Schema-1 compatibility only. A PID without machine/boot/process-start
    /// identity is never sufficient evidence of staleness on shared storage.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    owner_pid: Option<u32>,
    #[serde(default)]
    ownership_generation: u64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    previous_owner_claim_id: Option<String>,
    status: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    cleanup_started_unix_ms: Option<u128>,
    updated_unix_ms: u128,
}

fn conversion_log_batch_workspace_state_path(coord_dir: &Path) -> PathBuf {
    coord_dir.join(CONVERSION_LOG_BATCH_WORKSPACE_STATE_FILE)
}

fn conversion_log_batch_workspace_ownership_lock_path(
    coord_dir: &Path,
    batch_id: &str,
) -> io::Result<PathBuf> {
    let parent = coord_dir.parent().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("conversion-log workspace has no coordination root: {}", coord_dir.display()),
        )
    })?;
    Ok(parent.join(format!(
        ".{}.workspace-ownership.lock",
        sanitize_component(batch_id)
    )))
}

fn acquire_conversion_log_batch_workspace_ownership_lock(
    coord_dir: &Path,
    batch_id: &str,
) -> io::Result<FileLock> {
    let path = conversion_log_batch_workspace_ownership_lock_path(coord_dir, batch_id)?;
    acquire_blocking_file_lock(&path, true)
}

fn conversion_log_batch_workspace_updated_unix_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

fn persist_conversion_log_batch_workspace_state_locked(
    coord_dir: &Path,
    state: &ConversionLogBatchWorkspaceState,
    creating: bool,
    newly_registered_claim_id: Option<&str>,
) -> io::Result<()> {
    let path = conversion_log_batch_workspace_state_path(coord_dir);
    let bytes = serde_json::to_vec_pretty(state).map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("could not serialize conversion-log batch workspace state: {err}"),
        )
    })?;

    // Keep claim registration and durable publication coupled. In particular,
    // do not release a newly registered claim if create_new made the ownership
    // record visible but a later write/fsync failed: that record is ambiguous
    // authority and must remain associated with this live process until a
    // future locked recovery pass proves what happened.
    let mut owner_record_published = false;
    let result: io::Result<()> = (|| {
        if creating {
            use std::io::Write;
            let mut file = fs::OpenOptions::new()
                .create_new(true)
                .write(true)
                .open(&path)?;
            owner_record_published = true;
            file.write_all(&bytes)?;
            file.sync_all()?;
            sync_parent_dir(&path)?;
        } else {
            // Atomic replacement keeps the old complete ownership record in
            // place if publication fails before rename. Once replacement has
            // succeeded, however, the new claim may already be visible even
            // if the following strict directory fsync fails. Mark it published
            // before that fsync so we never release a live claim that durable
            // recovery may subsequently observe.
            write_bytes_atomically(&path, &bytes)?;
            owner_record_published = true;
            sync_parent_dir(&path)?;
        }
        Ok(())
    })();

    if result.is_err() {
        if let Some(claim_id) = newly_registered_claim_id {
            if creating && owner_record_published {
                // We still hold the ownership lock and created this exact path.
                // Retract the incomplete authority only if unlink + parent sync
                // succeeds; otherwise retain the live claim so an ambiguous
                // visible record cannot appear ownerless.
                let retracted = match fs::remove_file(&path) {
                    Ok(()) => sync_parent_dir(&path).is_ok(),
                    Err(error) if error.kind() == io::ErrorKind::NotFound => true,
                    Err(_) => false,
                };
                if retracted {
                    release_current_process_owner_claim(claim_id);
                } else {
                    log::warn!(
                        "conversion-log workspace ownership publication failed after the state path became visible and could not be retracted; retaining in-process claim {} for fail-closed recovery: {}",
                        claim_id,
                        path.display()
                    );
                }
            } else if owner_record_published {
                // An atomic replacement became visible but its final parent
                // sync failed. The old authority may already be gone, so do
                // not release the newly published takeover claim. Retaining
                // it is the only fail-closed relationship between the visible
                // state and this live process.
                log::warn!(
                    "conversion-log workspace ownership replacement became visible but did not complete durably; retaining in-process claim {} for fail-closed recovery: {}",
                    claim_id,
                    path.display()
                );
            } else {
                release_current_process_owner_claim(claim_id);
            }
        }
    }
    result
}

fn write_conversion_log_batch_workspace_state_locked(
    coord_dir: &Path,
    batch_id: &str,
    status: &str,
) -> io::Result<ConversionLogBatchWorkspaceState> {
    if !conversion_log_batch_workspace_status_is_valid(status) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid conversion-log workspace status: {status}"),
        ));
    }
    fs::create_dir_all(coord_dir)?;
    sync_parent_dir(coord_dir)?;
    if let Some(coordination_root) = coord_dir.parent() {
        sync_parent_dir(coordination_root)?;
    }

    let existing = read_conversion_log_batch_workspace_state(coord_dir)?;
    let creating = existing.is_none();
    if creating {
        for entry in fs::read_dir(coord_dir)? {
            let entry = entry?;
            let name = entry.file_name();
            let name = name.to_string_lossy();
            // The journal-root BOOTSTRAP artifacts legitimately precede
            // ownership: the pre-action flow pins the recoverable journal
            // root (creating `.tonepoet-action-journals` plus its durable
            // materialization-authority marker) before the first ownership
            // claim (round-3 pre-first-journal window design). Anything
            // else is unowned payload and fails closed.
            let bootstrap_artifact = name == ".tonepoet-action-journals"
                || name.starts_with(".tonepoet-root-authority-");
            if !bootstrap_artifact {
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    format!(
                        "conversion-log workspace {} contains unowned state and cannot be claimed automatically",
                        coord_dir.display()
                    ),
                ));
            }
        }
    }

    let mut takeover_from = None;
    let (owner, ownership_generation, previous_owner_claim_id, cleanup_started_unix_ms) =
        match existing.as_ref() {
            Some(existing) => {
                if existing.batch_id != batch_id {
                    return Err(io::Error::new(
                        io::ErrorKind::AlreadyExists,
                        format!(
                            "conversion-log workspace {} belongs to batch {}, not {}",
                            coord_dir.display(),
                            existing.batch_id,
                            batch_id
                        ),
                    ));
                }
                if !conversion_log_batch_workspace_transition_allowed(&existing.status, status) {
                    return Err(io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        format!(
                            "conversion-log workspace {} cannot transition from status {:?} to {:?}",
                            coord_dir.display(),
                            existing.status,
                            status
                        ),
                    ));
                }
                let existing_owner = existing.owner.as_ref().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        format!(
                            "conversion-log workspace {} has legacy/unknown ownership and cannot be claimed automatically",
                            coord_dir.display()
                        ),
                    )
                })?;
                let owner = if owner_is_current_process(existing_owner).map_err(|error| {
                    io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        format!("could not validate conversion-log workspace owner: {error}"),
                    )
                })? {
                    existing_owner.clone()
                } else {
                    match owner_liveness(existing_owner).map_err(|error| {
                        io::Error::new(
                            io::ErrorKind::PermissionDenied,
                            format!("could not establish conversion-log workspace owner liveness: {error}"),
                        )
                    })? {
                        OwnerLiveness::DeadLocal => {
                            takeover_from = Some(existing_owner.claim_id.clone());
                            current_process_owner().map_err(|error| {
                                io::Error::new(
                                    io::ErrorKind::Other,
                                    format!("could not establish takeover owner: {error}"),
                                )
                            })?
                        }
                        OwnerLiveness::Alive | OwnerLiveness::RemoteOrUnknown => {
                            return Err(io::Error::new(
                                io::ErrorKind::PermissionDenied,
                                format!(
                                    "conversion-log workspace {} is owned by a live, remote, or indeterminate process claim {}",
                                    coord_dir.display(),
                                    existing_owner.claim_id
                                ),
                            ));
                        }
                    }
                };
                let generation = existing.ownership_generation.max(1)
                    + u64::from(takeover_from.is_some());
                let previous = takeover_from
                    .clone()
                    .or_else(|| existing.previous_owner_claim_id.clone());
                let cleanup_started = if status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING {
                    existing.cleanup_started_unix_ms.or_else(|| {
                        Some(conversion_log_batch_workspace_updated_unix_ms())
                    })
                } else {
                    existing.cleanup_started_unix_ms
                };
                (owner, generation, previous, cleanup_started)
            }
            None => {
                let owner = current_process_owner().map_err(|error| {
                    io::Error::new(
                        io::ErrorKind::Other,
                        format!("could not establish conversion-log workspace owner: {error}"),
                    )
                })?;
                let cleanup_started = (status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING)
                    .then(conversion_log_batch_workspace_updated_unix_ms);
                (owner, 1, None, cleanup_started)
            }
        };

    let newly_registered_claim_id =
        (creating || takeover_from.is_some()).then(|| owner.claim_id.clone());
    let state = ConversionLogBatchWorkspaceState {
        schema_version: CONVERSION_LOG_BATCH_WORKSPACE_STATE_SCHEMA_VERSION,
        batch_id: batch_id.to_string(),
        owner: Some(owner),
        owner_pid: None,
        ownership_generation,
        previous_owner_claim_id,
        status: status.to_string(),
        cleanup_started_unix_ms,
        updated_unix_ms: conversion_log_batch_workspace_updated_unix_ms(),
    };
    persist_conversion_log_batch_workspace_state_locked(
        coord_dir,
        &state,
        creating,
        newly_registered_claim_id.as_deref(),
    )?;
    Ok(state)
}

fn write_conversion_log_batch_workspace_state(
    coord_dir: &Path,
    batch_id: &str,
    status: &str,
) -> io::Result<()> {
    let _ownership_lock =
        acquire_conversion_log_batch_workspace_ownership_lock(coord_dir, batch_id)?;
    write_conversion_log_batch_workspace_state_locked(coord_dir, batch_id, status).map(|_| ())
}

fn ensure_conversion_log_batch_workspace_owned_for_request(
    req: &PipelineRequest,
) -> io::Result<()> {
    let coord_dir = conversion_log_batch_coordination_album_dir(req).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "conversion-log batch workspace ownership requires a coordination directory",
        )
    })?;
    ensure_conversion_log_batch_workspace_owned_for_request_at(req, &coord_dir)
}

fn ensure_conversion_log_batch_workspace_owned_for_request_at(
    req: &PipelineRequest,
    coord_dir: &Path,
) -> io::Result<()> {
    let batch = req.album_batch.as_ref().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "conversion-log batch workspace ownership requires album batch context",
        )
    })?;
    let batch_id = batch.conversion_log_batch_id.trim();
    if !is_generated_conversion_log_batch_id(batch_id) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "conversion-log batch workspace ownership requires a generated dispatch batch id",
        ));
    }
    ensure_conversion_log_batch_workspace_owned(coord_dir, batch_id)?;
    if conversion_actions_effective_for_request(req)? {
        ensure_conversion_log_batch_drain_manifest_for_request_at(req, coord_dir)?;
    }
    Ok(())
}

fn ensure_conversion_log_batch_workspace_owned(
    coord_dir: &Path,
    batch_id: &str,
) -> io::Result<()> {
    let _ownership_lock =
        acquire_conversion_log_batch_workspace_ownership_lock(coord_dir, batch_id)?;
    match read_conversion_log_batch_workspace_state(coord_dir)? {
        Some(state) if state.status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING => {
            Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!(
                    "conversion-log workspace {} is completing durable cleanup and cannot accept new mutations",
                    coord_dir.display()
                ),
            ))
        }
        Some(state) => write_conversion_log_batch_workspace_state_locked(
            coord_dir,
            batch_id,
            &state.status,
        )
        .map(|_| ()),
        None => write_conversion_log_batch_workspace_state_locked(
            coord_dir,
            batch_id,
            CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ACTIVE,
        )
        .map(|_| ()),
    }
}

fn read_conversion_log_batch_workspace_state(
    coord_dir: &Path,
) -> io::Result<Option<ConversionLogBatchWorkspaceState>> {
    let path = conversion_log_batch_workspace_state_path(coord_dir);
    let bytes = match read_regular_file_no_follow(&path) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(error),
    };
    let state = serde_json::from_slice::<ConversionLogBatchWorkspaceState>(&bytes).map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("could not parse conversion-log batch workspace state {}: {err}", path.display()),
        )
    })?;
    if !matches!(state.schema_version, 1 | 2 | 3 | CONVERSION_LOG_BATCH_WORKSPACE_STATE_SCHEMA_VERSION) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "unsupported conversion-log batch workspace state schema {} in {}",
                state.schema_version,
                path.display()
            ),
        ));
    }
    if !conversion_log_batch_workspace_status_is_valid(&state.status) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "conversion-log batch workspace state {} has invalid status {:?}",
                path.display(),
                state.status
            ),
        ));
    }
    let directory_batch_id = coord_dir.file_name().and_then(|name| name.to_str());
    if state.batch_id.trim().is_empty()
        || directory_batch_id != Some(state.batch_id.as_str())
        || !is_generated_conversion_log_batch_id(&state.batch_id)
        || state.updated_unix_ms == 0
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "conversion-log batch workspace state {} has inconsistent directory/batch/timestamp identity",
                path.display()
            ),
        ));
    }
    if state.schema_version == 1 {
        if state.owner.is_some() || !matches!(state.owner_pid, Some(pid) if pid > 0) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "legacy conversion-log batch workspace state {} has malformed PID-only ownership",
                    path.display()
                ),
            ));
        }
    }
    if matches!(state.schema_version, 2 | 3 | CONVERSION_LOG_BATCH_WORKSPACE_STATE_SCHEMA_VERSION) {
        if state.owner_pid.is_some() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "conversion-log batch workspace state {} mixes strong and legacy ownership",
                    path.display()
                ),
            ));
        }
        let owner = state.owner.as_ref().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "conversion-log batch workspace state {} is missing strong owner identity",
                    path.display()
                ),
            )
        })?;
        validate_owner_identity(owner).map_err(|error| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "conversion-log batch workspace state {} has invalid owner identity: {error}",
                    path.display()
                ),
            )
        })?;
    }
    if state.schema_version == 2
        && (state.status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
            || state.cleanup_started_unix_ms.is_some()
            || state.ownership_generation != 0
            || state.previous_owner_claim_id.is_some())
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "schema-2 conversion-log workspace state {} contains schema-3 lifecycle fields",
                path.display()
            ),
        ));
    }
    if matches!(state.schema_version, 3 | CONVERSION_LOG_BATCH_WORKSPACE_STATE_SCHEMA_VERSION) {
        if state.ownership_generation == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "conversion-log workspace state {} has no ownership generation",
                    path.display()
                ),
            ));
        }
        if state.status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
            && state.cleanup_started_unix_ms.is_none()
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "cleaning conversion-log workspace state {} has no cleanup start timestamp",
                    path.display()
                ),
            ));
        }
    }
    Ok(Some(state))
}

fn conversion_log_batch_workspace_status_is_valid(status: &str) -> bool {
    status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ACTIVE
        || status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_COMPLETE
        || status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_FAILED
        || status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ABANDONED
        || status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
}

fn conversion_log_batch_workspace_status_is_terminal(status: &str) -> bool {
    status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_COMPLETE
        || status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_FAILED
        || status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ABANDONED
}

fn conversion_log_batch_workspace_transition_allowed(from: &str, to: &str) -> bool {
    match from {
        CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ACTIVE => {
            to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ACTIVE
                || to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_COMPLETE
                || to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_FAILED
                || to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ABANDONED
        }
        CONVERSION_LOG_BATCH_WORKSPACE_STATUS_COMPLETE => {
            to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_COMPLETE
                || to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
        }
        CONVERSION_LOG_BATCH_WORKSPACE_STATUS_FAILED => {
            to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_FAILED
                || to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_COMPLETE
                || to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
        }
        CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ABANDONED => {
            to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ABANDONED
                || to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_COMPLETE
                || to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
        }
        CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING => {
            to == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING
        }
        _ => false,
    }
}

fn mark_conversion_log_batch_workspace_status_for_identity_best_effort(
    identity: &ConversionLogBatchIdentity,
    status: &str,
    context: &str,
) {
    let coord_dir = conversion_log_batch_coordination_album_dir_from_identity(identity);
    if let Err(err) = write_conversion_log_batch_workspace_state(
        &coord_dir,
        &identity.conversion_log_batch_id,
        status,
    ) {
        log::warn!(
            "conversion-log batch coordination could not mark workspace {status} for {context}: {}: {err}",
            coord_dir.display()
        );
    }
}

fn mark_conversion_log_batch_workspace_failed_for_identity_best_effort(
    identity: &ConversionLogBatchIdentity,
    context: &str,
) {
    mark_conversion_log_batch_workspace_status_for_identity_best_effort(
        identity,
        CONVERSION_LOG_BATCH_WORKSPACE_STATUS_FAILED,
        context,
    );
}

fn active_conversion_log_batch_workspaces() -> &'static Mutex<BTreeMap<String, usize>> {
    ACTIVE_CONVERSION_LOG_BATCH_WORKSPACES.get_or_init(|| Mutex::new(BTreeMap::new()))
}

fn conversion_log_batch_workspace_registered_active(batch_id: &str) -> bool {
    active_conversion_log_batch_workspaces()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(batch_id)
        .copied()
        .unwrap_or(0)
        > 0
}

struct ConversionLogBatchWorkspaceActiveGuard {
    batch_id: String,
    failure_mark_on_drop: Option<ConversionLogBatchWorkspaceFailureMark>,
}

struct ConversionLogBatchWorkspaceFailureMark {
    coord_dir: PathBuf,
    context: String,
}

impl ConversionLogBatchWorkspaceActiveGuard {
    fn mark_failed_on_drop(&mut self, coord_dir: PathBuf, context: &str) {
        self.failure_mark_on_drop = Some(ConversionLogBatchWorkspaceFailureMark {
            coord_dir,
            context: context.to_string(),
        });
    }

    fn disarm_failure_mark(&mut self) {
        self.failure_mark_on_drop = None;
    }
}

impl Drop for ConversionLogBatchWorkspaceActiveGuard {
    fn drop(&mut self) {
        let mut guard = active_conversion_log_batch_workspaces()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(count) = guard.get_mut(&self.batch_id) {
            if *count > 1 {
                *count -= 1;
            } else {
                guard.remove(&self.batch_id);
            }
        }
        drop(guard);

        if let Some(mark) = self.failure_mark_on_drop.take() {
            if let Err(err) = write_conversion_log_batch_workspace_state(
                &mark.coord_dir,
                &self.batch_id,
                CONVERSION_LOG_BATCH_WORKSPACE_STATUS_FAILED,
            ) {
                log::warn!(
                    "conversion-log batch coordination could not mark failed workspace after {}: {}: {err}",
                    mark.context,
                    mark.coord_dir.display()
                );
            }
        }
    }
}

fn write_active_conversion_log_batch_workspace_state_unless_terminal_best_effort(
    coord_dir: &Path,
    batch_id: &str,
    context: &str,
) {
    match read_conversion_log_batch_workspace_state(coord_dir) {
        Ok(Some(state)) if state.batch_id == batch_id && conversion_log_batch_workspace_status_is_terminal(state.status.as_str()) => {
            // Do not resurrect failed/abandoned/complete workspaces as active:
            // a handled failure in a long-running process must remain sweepable
            // even if a sibling worker reaches a short publish hook later.
            return;
        }
        Ok(Some(state)) if state.batch_id != batch_id => {
            log::warn!(
                "conversion-log batch coordination refused to overwrite mismatched workspace state for {context}: {} contains batch id {} while activating {batch_id}",
                coord_dir.display(),
                state.batch_id
            );
            return;
        }
        Ok(_) => {}
        Err(err) => {
            log::warn!(
                "conversion-log batch coordination refused to activate unreadable workspace state for {context}: {}: {err}",
                coord_dir.display()
            );
            return;
        }
    }

    if let Err(err) = write_conversion_log_batch_workspace_state(
        coord_dir,
        batch_id,
        CONVERSION_LOG_BATCH_WORKSPACE_STATUS_ACTIVE,
    ) {
        log::warn!(
            "conversion-log batch coordination could not write active workspace state for {context}: {}: {err}",
            coord_dir.display()
        );
    }
}

fn activate_conversion_log_batch_workspace_for_identity_best_effort(
    identity: &ConversionLogBatchIdentity,
    context: &str,
) -> ConversionLogBatchWorkspaceActiveGuard {
    let batch_id = identity.conversion_log_batch_id.clone();
    {
        let mut guard = active_conversion_log_batch_workspaces()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        *guard.entry(batch_id.clone()).or_insert(0) += 1;
    }

    let coord_dir = conversion_log_batch_coordination_album_dir_from_identity(identity);
    write_active_conversion_log_batch_workspace_state_unless_terminal_best_effort(
        &coord_dir,
        &batch_id,
        context,
    );

    ConversionLogBatchWorkspaceActiveGuard { batch_id, failure_mark_on_drop: None }
}

fn activate_conversion_log_batch_publish_attempt_for_identity_best_effort(
    identity: &ConversionLogBatchIdentity,
    context: &str,
) -> ConversionLogBatchWorkspaceActiveGuard {
    let coord_dir = conversion_log_batch_coordination_album_dir_from_identity(identity);
    let mut guard = activate_conversion_log_batch_workspace_for_identity_best_effort(identity, context);
    guard.mark_failed_on_drop(coord_dir, context);
    guard
}

fn activate_conversion_log_batch_workspace_for_request_best_effort(
    req: &PipelineRequest,
    context: &str,
) -> Option<ConversionLogBatchWorkspaceActiveGuard> {
    let coord_dir = conversion_log_batch_coordination_album_dir(req)?;
    activate_conversion_log_batch_workspace_for_request_at_best_effort(
        req,
        &coord_dir,
        context,
    )
}

fn activate_conversion_log_batch_workspace_for_request_at_best_effort(
    req: &PipelineRequest,
    coord_dir: &Path,
    context: &str,
) -> Option<ConversionLogBatchWorkspaceActiveGuard> {
    let batch_id = req
        .album_batch
        .as_ref()?
        .conversion_log_batch_id
        .trim()
        .to_string();
    if batch_id.is_empty() || !is_generated_conversion_log_batch_id(&batch_id) {
        return None;
    }
    {
        let mut guard = active_conversion_log_batch_workspaces()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        *guard.entry(batch_id.clone()).or_insert(0) += 1;
    }
    write_active_conversion_log_batch_workspace_state_unless_terminal_best_effort(
        coord_dir,
        &batch_id,
        context,
    );
    Some(ConversionLogBatchWorkspaceActiveGuard { batch_id, failure_mark_on_drop: None })
}

fn conversion_log_batch_workspace_owner_may_be_live(
    batch_id: &str,
    state: Option<&ConversionLogBatchWorkspaceState>,
) -> bool {
    if conversion_log_batch_workspace_registered_active(batch_id) {
        return true;
    }
    if let Some(state) = state {
        let Some(owner) = state.owner.as_ref() else {
            // Schema-1 state carries only a PID. On shared storage that PID is
            // not local-authority evidence, so unknown ownership fails closed.
            return true;
        };
        return match owner_liveness(owner) {
            Ok(OwnerLiveness::Alive | OwnerLiveness::RemoteOrUnknown) => true,
            Ok(OwnerLiveness::DeadLocal) => false,
            Err(error) => {
                log::warn!(
                    "conversion-log batch cleanup could not establish owner liveness for {}: {error}",
                    batch_id
                );
                true
            }
        };
    }
    true
}

#[derive(Debug, Clone, Copy)]
enum ConversionLogBatchCleanupAuthority {
    CurrentProcessOwner,
    CurrentProcessOwnerActionless,
    CurrentOrProvenDeadLocalOwner,
}

fn cleanup_conversion_log_batch_coordination_after_success_best_effort(
    req: &PipelineRequest,
    context: &str,
) {
    let Some(coord_dir) = conversion_log_batch_coordination_album_dir(req) else {
        return;
    };
    cleanup_conversion_log_batch_coordination_after_success_best_effort_at(req, &coord_dir, context);
}

fn cleanup_conversion_log_batch_coordination_after_success_best_effort_at(
    req: &PipelineRequest,
    coord_dir: &Path,
    context: &str,
) {
    cleanup_conversion_log_batch_coordination_dir_after_success_best_effort(
        coord_dir,
        context,
        match conversion_actions_effective_for_request(req) {
            Ok(false) => ConversionLogBatchCleanupAuthority::CurrentProcessOwnerActionless,
            Ok(true) | Err(_) => ConversionLogBatchCleanupAuthority::CurrentProcessOwner,
        },
    );
}

fn cleanup_conversion_log_batch_coordination_dir_after_success_best_effort(
    coord_dir: &Path,
    context: &str,
    authority: ConversionLogBatchCleanupAuthority,
) {
    match fs::symlink_metadata(coord_dir) {
        Err(error) if error.kind() == io::ErrorKind::NotFound => return,
        Ok(metadata) if metadata.is_dir() && !metadata.file_type().is_symlink() => {}
        Ok(_) => {
            log::warn!(
                "conversion-log batch coordination cleanup preserved non-directory or symlink workspace for {context}: {}",
                coord_dir.display()
            );
            return;
        }
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup preserved unreadable workspace for {context}: {}: {error}",
                coord_dir.display()
            );
            return;
        }
    }

    let initial_state = match read_conversion_log_batch_workspace_state(coord_dir) {
        Ok(Some(state)) => state,
        Ok(None) => {
            // The ownership record is deliberately the last object removed.
            // Therefore an ownerless empty directory is a proven interrupted
            // final rmdir and may be retired; any payload fails closed.
            match fs::read_dir(coord_dir) {
                Ok(mut entries) => {
                    if entries.next().is_none() {
                        match fs::remove_dir(coord_dir) {
                            Ok(()) => sync_parent_dir_best_effort(coord_dir),
                            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
                            Err(error) => log::warn!(
                                "conversion-log batch coordination could not remove empty ownerless workspace for {context}: {}: {error}",
                                coord_dir.display()
                            ),
                        }
                    } else {
                        log::warn!(
                            "conversion-log batch coordination cleanup preserved nonempty ownerless workspace for {context}: {}",
                            coord_dir.display()
                        );
                    }
                }
                Err(error) => log::warn!(
                    "conversion-log batch coordination cleanup preserved unreadable ownerless workspace for {context}: {}: {error}",
                    coord_dir.display()
                ),
            }
            return;
        }
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup preserved unreadable workspace state for {context}: {}: {error}",
                coord_dir.display()
            );
            return;
        }
    };
    let batch_id = initial_state.batch_id.clone();
    let ownership_lock = match acquire_conversion_log_batch_workspace_ownership_lock(
        coord_dir,
        &batch_id,
    ) {
        Ok(lock) => lock,
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup could not acquire ownership lock for {context}: {}: {error}",
                coord_dir.display()
            );
            return;
        }
    };

    let state = match read_conversion_log_batch_workspace_state(coord_dir) {
        Ok(Some(state)) if state.batch_id == batch_id => state,
        Ok(Some(state)) => {
            log::warn!(
                "conversion-log batch coordination cleanup preserved changed batch identity for {context}: {} now contains {}",
                coord_dir.display(),
                state.batch_id
            );
            return;
        }
        Ok(None) => return,
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup could not revalidate state for {context}: {}: {error}",
                coord_dir.display()
            );
            return;
        }
    };
    let Some(owner) = state.owner.as_ref() else {
        log::warn!(
            "conversion-log batch coordination cleanup preserved legacy/unknown owner for {context}: {}",
            coord_dir.display()
        );
        return;
    };
    let ownership_authorized = match authority {
        ConversionLogBatchCleanupAuthority::CurrentProcessOwner
        | ConversionLogBatchCleanupAuthority::CurrentProcessOwnerActionless => {
            owner_is_current_process(owner).unwrap_or(false)
        }
        ConversionLogBatchCleanupAuthority::CurrentOrProvenDeadLocalOwner => {
            owner_is_current_process(owner).unwrap_or(false)
                || matches!(owner_liveness(owner), Ok(OwnerLiveness::DeadLocal))
        }
    };
    if !ownership_authorized {
        log::warn!(
            "conversion-log batch coordination cleanup preserved workspace without required ownership authority for {context}: {}",
            coord_dir.display()
        );
        return;
    }
    if conversion_log_batch_workspace_registered_active(&batch_id) {
        log::debug!(
            "conversion-log batch coordination cleanup deferred until in-process batch participants drain for {context}: {}",
            coord_dir.display()
        );
        return;
    }

    // Re-publish the same lifecycle state while holding the ownership lock.
    // This is the atomic dead-local takeover point used by restored queues and
    // interrupted cleanup. Remote, live, legacy, or indeterminate ownership
    // remains unclaimable.
    let owned_state = match write_conversion_log_batch_workspace_state_locked(
        coord_dir,
        &batch_id,
        &state.status,
    ) {
        Ok(state) => state,
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup could not take durable ownership for {context}: {}: {error}",
                coord_dir.display()
            );
            return;
        }
    };
    let resuming_cleaning =
        owned_state.status == CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING;

    if workspace_has_unresolved_action_state(coord_dir) {
        log::warn!(
            "conversion-log batch coordination cleanup preserved unresolved or unreadable action state for {context}: {}",
            coord_dir.display()
        );
        return;
    }

    let cleaning_state = if resuming_cleaning {
        owned_state
    } else {
        if !conversion_log_batch_workspace_status_is_terminal(&owned_state.status) {
            // A dead active workspace is recovery state, not garbage. It may be
            // taken over by the restored queue, but a sweeper must never turn
            // mere owner death into terminal authorization. The one exception:
            // an abandoned attempt of THIS live process (identity tuple is
            // ours, claim released) — same-process retry supersedes it and no
            // restart recovery can ever want it.
            let abandoned_same_process = matches!(
                authority,
                ConversionLogBatchCleanupAuthority::CurrentOrProvenDeadLocalOwner
            ) && owned_state
                .owner
                .as_ref()
                .is_some_and(
                    crate::convert::pipeline::actions::owner_is_abandoned_current_process_attempt,
                );
            if !abandoned_same_process {
                log::warn!(
                    "conversion-log batch coordination cleanup preserved non-terminal workspace for {context}: {} ({})",
                    coord_dir.display(),
                    owned_state.status
                );
                return;
            }
        }

        if !matches!(
            authority,
            ConversionLogBatchCleanupAuthority::CurrentProcessOwnerActionless
        ) {
            match conversion_log_batch_cleanup_lifecycle_is_complete(coord_dir, &batch_id) {
                Ok(true) => {}
                // A proven-dead LOCAL owner whose workspace never created a
                // drain authority can never satisfy the drain gate — its
                // participants were threads of the dead process. The durable
                // terminal status is the only signal such a workspace will
                // ever produce; without this, pre-drain-era leftovers are
                // retained forever (the task-12 leak, reborn).
                Ok(false)
                    if matches!(
                        authority,
                        ConversionLogBatchCleanupAuthority::CurrentOrProvenDeadLocalOwner
                    ) && !conversion_log_batch_drain_dir(coord_dir).exists() => {}
                Ok(false) => {
                    log::debug!(
                        "conversion-log batch coordination cleanup deferred until every participant has drained and the post-action lifecycle is terminal for {context}: {}",
                        coord_dir.display()
                    );
                    return;
                }
                Err(error) => {
                    log::warn!(
                        "conversion-log batch coordination cleanup preserved invalid or unreadable participant/post-action lifecycle authority for {context}: {}: {error}",
                        coord_dir.display()
                    );
                    return;
                }
            }
        }

        let marker_path = coord_dir.join(CONVERSION_LOG_VISIBLE_COMMIT_MARKER_FILE);
        if let Err(error) = repair_interrupted_visible_conversion_log_publish_marker(&marker_path) {
            log::warn!(
                "conversion-log batch coordination cleanup could not repair visible-log transaction for {context}: {}: {error:?}",
                marker_path.display()
            );
            return;
        }

        match write_conversion_log_batch_workspace_state_locked(
            coord_dir,
            &batch_id,
            CONVERSION_LOG_BATCH_WORKSPACE_STATUS_CLEANING,
        ) {
            Ok(state) => state,
            Err(error) => {
                log::warn!(
                    "conversion-log batch coordination cleanup could not durably enter cleaning state for {context}: {}: {error}",
                    coord_dir.display()
                );
                return;
            }
        }
    };

    #[cfg(test)]
    if test_interrupt_terminal_cleanup(
        TerminalCleanupInterruptionPoint::AfterCleaningStateCommitted,
    ) {
        return;
    }

    // The terminal authority-retirement record is validated against the drain
    // manifest before `cleaning` is committed. Remove it now, while that
    // manifest is still present. From this durable boundary onward the cleaning
    // state itself proves that authority records, authority-scoped temporaries,
    // and the stable authority lock pathname were retired successfully. This
    // ordering keeps every crash state resumable: before this unlink, retry can
    // validate the record through the manifest; after it, retry can rely on the
    // cleaning state without needing drain metadata that may be removed next.
    let authority_retirement_record =
        conversion_log_batch_materialization_authority_retirement_path(coord_dir);
    match fs::remove_file(&authority_retirement_record) {
        Ok(()) => sync_parent_dir_best_effort(&authority_retirement_record),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup could not remove materialization-authority retirement record for {context}: {}: {error}",
                authority_retirement_record.display()
            );
            return;
        }
    }

    #[cfg(test)]
    if test_interrupt_terminal_cleanup(
        TerminalCleanupInterruptionPoint::AfterRetirementRecordRemoved,
    ) {
        return;
    }

    // `cleaning` is durable proof that the complete participant set had
    // drained. A resumed cleanup may therefore remove acknowledgments that
    // disappeared before the crash; the manifest remains last within this
    // sub-authority, and the workspace owner record remains last overall.
    if !matches!(
        authority,
        ConversionLogBatchCleanupAuthority::CurrentProcessOwnerActionless
    ) {
        if let Err(error) = cleanup_conversion_log_batch_drain_authority(coord_dir, &batch_id) {
            log::warn!(
                "conversion-log batch coordination cleanup could not retire participant drain authority for {context}: {}: {error}",
                coord_dir.display()
            );
            return;
        }
    }

    // Remove validated terminal action authority only after the fail-closed
    // unresolved-state veto and durable cleaning transition above.
    super::actions::prune_terminal_action_journals_best_effort(coord_dir, 0);
    let action_journals = coord_dir.join(".tonepoet-action-journals");
    match fs::remove_dir(&action_journals) {
        Ok(()) => sync_parent_dir_best_effort(&action_journals),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(error) if error.kind() == io::ErrorKind::DirectoryNotEmpty => {
            log::warn!(
                "conversion-log batch coordination cleanup retained nonempty action authority for {context}: {}",
                action_journals.display()
            );
            return;
        }
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup could not remove action authority directory for {context}: {}: {error}",
                action_journals.display()
            );
            return;
        }
    }

    for path in [
        coord_dir.join(CONVERSION_LOG_BATCH_COMPLETION_MARKER_FILE),
        coord_dir.join(CONVERSION_LOG_BATCH_POST_ACTION_TERMINAL_FILE),
        coord_dir.join(CONVERSION_LOG_VISIBLE_COMMIT_MARKER_FILE),
        coord_dir.join("conversion.log"),
        coord_dir.join(CONVERSION_LOG_BATCH_FINALIZATION_LOCK_FILE),
    ] {
        match fs::remove_file(&path) {
            Ok(()) => sync_parent_dir_best_effort(&path),
            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
            Err(error) => {
                log::warn!(
                    "conversion-log batch coordination cleanup could not remove artifact for {context}: {}: {error}",
                    path.display()
                );
                return;
            }
        }
    }

    // Terminal action phase results (`actions-<phase>-<sha256>.result.json`)
    // are part of the completed lifecycle this cleanup is retiring.
    if let Ok(entries) = fs::read_dir(coord_dir) {
        for entry in entries.flatten() {
            let name = entry.file_name();
            let name = name.to_string_lossy();
            let terminal_result = name.starts_with("actions-")
                && name.ends_with(".result.json");
            if !terminal_result {
                continue;
            }
            let path = entry.path();
            match fs::remove_file(&path) {
                Ok(()) => sync_parent_dir_best_effort(&path),
                Err(error) if error.kind() == io::ErrorKind::NotFound => {}
                Err(error) => {
                    log::warn!(
                        "conversion-log batch coordination cleanup could not remove terminal action result for {context}: {}: {error}",
                        path.display()
                    );
                    return;
                }
            }
        }
    }

    for path in [
        conversion_log_fragment_dir(coord_dir),
        coord_dir.join(CONVERSION_LOG_FRAGMENT_QUARANTINE_DIR),
    ] {
        match fs::remove_dir_all(&path) {
            Ok(()) => sync_parent_dir_best_effort(&path),
            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
            Err(error) => {
                log::warn!(
                    "conversion-log batch coordination cleanup could not remove directory for {context}: {}: {error}",
                    path.display()
                );
                return;
            }
        }
    }

    if workspace_has_unresolved_action_state(coord_dir) {
        log::warn!(
            "conversion-log batch coordination cleanup observed new unresolved action authority during cleaning for {context}: {}",
            coord_dir.display()
        );
        return;
    }

    let state_file = conversion_log_batch_workspace_state_path(coord_dir);
    let only_state_remains = match fs::read_dir(coord_dir) {
        Ok(entries) => {
            let mut only_state = true;
            let mut saw_state = false;
            for entry in entries {
                let entry = match entry {
                    Ok(entry) => entry,
                    Err(error) => {
                        log::warn!(
                            "conversion-log batch coordination cleanup could not complete final inventory for {context}: {}: {error}",
                            coord_dir.display()
                        );
                        return;
                    }
                };
                if entry.path() == state_file {
                    saw_state = true;
                } else {
                    only_state = false;
                }
            }
            only_state && saw_state
        }
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup could not inventory final workspace for {context}: {}: {error}",
                coord_dir.display()
            );
            return;
        }
    };
    if !only_state_remains {
        log::warn!(
            "conversion-log batch coordination cleanup preserved cleaning workspace with unrecognized remaining artifacts for {context}: {}",
            coord_dir.display()
        );
        return;
    }

    // The owner/state record is the last object removed from the workspace.
    match fs::remove_file(&state_file) {
        Ok(()) => {
            sync_parent_dir_best_effort(&state_file);
            if let Some(owner) = cleaning_state.owner.as_ref() {
                release_current_process_owner_claim(&owner.claim_id);
            }
        }
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            log::warn!(
                "conversion-log batch coordination cleanup lost its final ownership state before authorized removal for {context}: {}",
                state_file.display()
            );
            return;
        }
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup could not remove final ownership state for {context}: {}: {error}",
                state_file.display()
            );
            return;
        }
    }
    match fs::remove_dir(coord_dir) {
        Ok(()) => sync_parent_dir_best_effort(coord_dir),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(error) => {
            log::warn!(
                "conversion-log batch coordination cleanup removed ownership state but could not remove now-empty workspace for {context}: {}: {error}",
                coord_dir.display()
            );
            return;
        }
    }

    drop(ownership_lock);
    if let Some(parent) = coord_dir.parent() {
        match fs::remove_dir(parent) {
            Ok(()) => sync_parent_dir_best_effort(parent),
            Err(error)
                if matches!(
                    error.kind(),
                    io::ErrorKind::NotFound | io::ErrorKind::DirectoryNotEmpty
                ) => {}
            Err(error) => log::warn!(
                "conversion-log batch coordination could not remove empty coordination root for {context}: {}: {error}",
                parent.display()
            ),
        }
    }
}
fn conversion_log_fragment_quarantine_dir(album_dir: &Path, reason: &str) -> PathBuf {
    album_dir
        .join(CONVERSION_LOG_FRAGMENT_QUARANTINE_DIR)
        .join(sanitize_component(reason))
}

fn conversion_log_candidate_album_dirs_for_incomplete_batch(req: &PipelineRequest) -> Vec<PathBuf> {
    // Album-batch completion is coordinated by the stable output-root workspace
    // keyed by conversion_log_batch_id. Do not scan or fall back to rendered or
    // provisional album roots here: that can split failure/cancellation
    // fragments for user-authored per-disc album-folder templates.
    conversion_log_batch_coordination_album_dir(req)
        .into_iter()
        .collect()
}


fn read_conversion_log_fragment_file(path: &Path) -> Result<ConversionLogFragment, PublishError> {
    let bytes = fs::read(path).map_err(PublishError::io_at("reading conversion log fragment", path))?;
    let fragment: ConversionLogFragment = serde_json::from_slice(&bytes).map_err(|err| {
        PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("invalid conversion log fragment {}: {err}", path.display()),
        ))
    })?;
    if fragment.version != CONVERSION_LOG_FRAGMENT_SCHEMA_VERSION {
        return Err(PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "unsupported conversion log fragment version {} in {}",
                fragment.version,
                path.display()
            ),
        )));
    }
    if !is_generated_conversion_log_batch_id(&fragment.batch_identity.conversion_log_batch_id) {
        return Err(PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "conversion log fragment {} has non-run-unique batch id {}; refusing to use album-stable ids",
                path.display(),
                fragment.batch_identity.conversion_log_batch_id
            ),
        )));
    }
    Ok(fragment)
}

fn quarantine_conversion_log_fragment_file(path: &Path, reason: &str) {
    let Some(fragment_dir) = path.parent() else {
        return;
    };
    let album_dir = fragment_dir.parent().unwrap_or(fragment_dir);
    let quarantine_dir = conversion_log_fragment_quarantine_dir(album_dir, reason);
    if let Err(err) = fs::create_dir_all(&quarantine_dir) {
        log::warn!(
            "conversion log fragment quarantine directory creation failed for {}: {err}",
            quarantine_dir.display()
        );
        return;
    }

    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .map(sanitize_component)
        .unwrap_or_else(|| "fragment.json".to_string());
    let dst = unique_path(&quarantine_dir, &file_name);
    match fs::rename(path, &dst) {
        Ok(()) => {
            sync_parent_dir_best_effort(path);
            sync_parent_dir_best_effort(&dst);
            log::warn!(
                "quarantined conversion log fragment {} -> {} ({reason})",
                path.display(),
                dst.display()
            );
        }
        Err(err) if err.kind() == io::ErrorKind::NotFound => {}
        Err(err) => {
            log::warn!(
                "conversion log fragment quarantine failed for {}: {err}",
                path.display()
            );
        }
    }
}

fn read_matching_conversion_log_fragment_files(
    album_dir: &Path,
    target_identity: &ConversionLogBatchIdentity,
) -> Result<Vec<ConversionLogFragmentFile>, PublishError> {
    let dir = conversion_log_fragment_dir(album_dir);
    let entries = match fs::read_dir(&dir) {
        Ok(entries) => entries,
        Err(err) if err.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(err) => return Err(PublishError::Io(err)),
    };

    let mut paths = Vec::new();
    for entry in entries {
        let entry = entry.map_err(PublishError::io_at("listing conversion log fragment dir", &dir))?;
        let path = entry.path();
        if path.extension().and_then(|ext| ext.to_str()) == Some("json") {
            paths.push(path);
        }
    }
    paths.sort();

    let mut files = Vec::with_capacity(paths.len());
    for path in paths {
        match read_conversion_log_fragment_file(&path) {
            Ok(mut fragment) => {
                fragment.batch_identity.runtime_coordination_dir = Some(album_dir.to_path_buf());
                if conversion_log_batch_identities_match(&fragment.batch_identity, target_identity) {
                    files.push(ConversionLogFragmentFile { path, fragment });
                } else {
                    let reason = if fragment.batch_identity.conversion_log_batch_id == target_identity.conversion_log_batch_id {
                        "mismatched-fragment-batch-fingerprint"
                    } else {
                        "stale-fragment-batch"
                    };
                    quarantine_conversion_log_fragment_file(&path, reason);
                }
            }
            Err(err) => {
                log::warn!("ignoring unreadable conversion log fragment {}: {err}", path.display());
                quarantine_conversion_log_fragment_file(&path, "invalid-fragment");
            }
        }
    }
    Ok(deduplicate_conversion_log_fragment_files(files))
}

fn deduplicate_conversion_log_fragment_files(
    files: Vec<ConversionLogFragmentFile>,
) -> Vec<ConversionLogFragmentFile> {
    let mut by_track: BTreeMap<ConversionLogTrackSortKey, ConversionLogFragmentFile> = BTreeMap::new();
    for file in files {
        match by_track.get(&file.fragment.sort_key) {
            Some(existing) if conversion_log_fragment_file_preferred(&file, existing) => {
                let replaced = by_track.insert(file.fragment.sort_key, file).expect("existing fragment");
                quarantine_conversion_log_fragment_file(&replaced.path, "superseded-duplicate-fragment");
            }
            Some(_) => {
                quarantine_conversion_log_fragment_file(&file.path, "older-duplicate-fragment");
            }
            None => {
                by_track.insert(file.fragment.sort_key, file);
            }
        }
    }
    by_track.into_values().collect()
}

fn conversion_log_fragment_file_preferred(
    candidate: &ConversionLogFragmentFile,
    existing: &ConversionLogFragmentFile,
) -> bool {
    (candidate.fragment.generated_at, candidate.path.to_string_lossy().to_string())
        > (existing.fragment.generated_at, existing.path.to_string_lossy().to_string())
}

fn conversion_log_fragment_count(fragments: &[ConversionLogFragment]) -> usize {
    fragments
        .iter()
        .map(|fragment| fragment.sort_key)
        .collect::<BTreeSet<_>>()
        .len()
}

fn conversion_log_fragment_expected_track_count_for_render(
    fragments: &[ConversionLogFragment],
) -> usize {
    debug_assert!(!fragments.is_empty());
    let expected = fragments
        .first()
        .map(|fragment| fragment.expected_track_count)
        .unwrap_or(0);
    debug_assert!(expected > 0);
    debug_assert!(fragments
        .iter()
        .all(|fragment| fragment.expected_track_count == expected));
    expected
}

fn complete_conversion_log_fragments(
    album_dir: &Path,
    expected_track_count: usize,
    target_identity: Option<&ConversionLogBatchIdentity>,
) -> Result<Option<Vec<ConversionLogFragment>>, PublishError> {
    let Some(target_identity) = target_identity else {
        return Ok(None);
    };
    let files = read_matching_conversion_log_fragment_files(album_dir, target_identity)?;
    if files.is_empty() {
        return Ok(None);
    }
    let fragments: Vec<ConversionLogFragment> = files
        .into_iter()
        .map(|file| file.fragment)
        .collect();
    if expected_track_count == 0 {
        return Err(PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "conversion log expected track count is zero for batch {}",
                target_identity.conversion_log_batch_id
            ),
        )));
    }
    let expected = expected_track_count;
    if let Some(mismatched) = fragments
        .iter()
        .find(|fragment| fragment.expected_track_count != expected)
    {
        return Err(PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "conversion log fragment for batch {} carries expected track count {}, but current publish expects {expected}",
                mismatched.batch_identity.conversion_log_batch_id,
                mismatched.expected_track_count
            ),
        )));
    }
    let fragment_count = conversion_log_fragment_count(&fragments);
    if fragment_count < expected {
        return Ok(None);
    }
    if fragment_count > expected {
        return Err(PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "conversion log fragment count {fragment_count} exceeds expected track count {expected} for batch {}",
                target_identity.conversion_log_batch_id
            ),
        )));
    }
    Ok(Some(fragments))
}

fn assemble_conversion_log_from_fragments(
    album_dir: &Path,
    expected_track_count: usize,
    target_identity: Option<&ConversionLogBatchIdentity>,
) -> Result<Option<String>, PublishError> {
    let Some(fragments) = complete_conversion_log_fragments(album_dir, expected_track_count, target_identity)? else {
        return Ok(None);
    };
    Ok(Some(build_conversion_log_from_fragments(&fragments)))
}

fn build_conversion_log_from_fragments(fragments: &[ConversionLogFragment]) -> String {
    build_conversion_log_from_fragments_with_status(fragments, None)
}

fn build_conversion_log_from_fragments_with_status(
    fragments: &[ConversionLogFragment],
    assembly_status: Option<ConversionLogAssemblyStatus>,
) -> String {
    debug_assert!(!fragments.is_empty());
    let mut ordered = fragments.to_vec();
    ordered.sort_by_key(|fragment| fragment.sort_key);

    // Ordering/header identity comes from the canonical first track in the
    // assembled album ordering: lowest disc number, then lowest track number,
    // then lowest source ordinal. Do not use that same fragment blindly for all
    // common album metadata, though: Disc 1 Track 1 can be a pre-materialization
    // failure fragment with request-only settings and no album/provenance data.
    // Merge common display fields from the best available validated fragments
    // while preserving the ordering representative's job/item identity.
    let representative = ordered
        .first()
        .expect("fragment assembly requires at least one validated fragment");
    let common = merge_conversion_log_common_fragments(&ordered, &representative.common);
    let generated_at = ordered
        .iter()
        .map(|fragment| fragment.generated_at)
        .max()
        .unwrap_or_else(chrono::Utc::now);
    let fingerprint = representative
        .settings_fingerprint
        .clone()
        .or_else(|| ordered.iter().find_map(|fragment| fragment.settings_fingerprint.clone()));
    let total_track_count = assembly_status
        .map(ConversionLogAssemblyStatus::expected_track_count)
        .unwrap_or_else(|| conversion_log_fragment_expected_track_count_for_render(&ordered));
    let successful_count = ordered
        .iter()
        .filter(|fragment| fragment.summary.outcome == ConversionLogTrackOutcome::Success)
        .count();
    let failed_count = ordered.len().saturating_sub(successful_count);
    let total_bytes_in = ordered
        .iter()
        .filter_map(|fragment| fragment.summary.bytes_in)
        .fold(0_u64, u64::saturating_add);
    let total_bytes_out = ordered
        .iter()
        .filter_map(|fragment| fragment.summary.bytes_out)
        .fold(0_u64, u64::saturating_add);
    let missing_input_sizes = ordered
        .iter()
        .filter(|fragment| fragment.summary.bytes_in.is_none())
        .count();
    let missing_output_sizes = ordered
        .iter()
        .filter(|fragment| fragment.summary.bytes_out.is_none())
        .count();
    let missing_durations = ordered
        .iter()
        .filter(|fragment| fragment.summary.duration_millis.is_none())
        .count();
    let total_duration = total_fragment_duration(&ordered);
    let track_sections = ordered
        .iter()
        .map(|fragment| fragment.track.section.clone())
        .collect();
    let stage_records = aggregate_fragment_stage_records(&ordered);
    let batch_status = assembly_status.map(|status| match status {
        ConversionLogAssemblyStatus::CancelledPartial { expected_track_count } => {
            format!(
                "cancelled before album batch completed; assembled partial log from {} of {expected_track_count} expected track fragment(s)",
                ordered.len()
            )
        }
        ConversionLogAssemblyStatus::TerminalFailurePartial {
            expected_track_count,
            reason,
        } => {
            format!(
                "terminal batch failure before album batch completed ({reason}); assembled partial log from {} of {expected_track_count} expected track fragment(s)",
                ordered.len()
            )
        }
    });
    let result_label = fragment_result_label(
        &ordered,
        successful_count,
        failed_count,
        total_track_count,
        assembly_status,
    );

    render_conversion_log(&ConversionLogRenderInput {
        generated_at,
        job_id: common.representative_job_id,
        item_id: common.representative_item_id,
        settings_fingerprint: fingerprint,
        container_path: representative.batch_identity.source_context_path.clone(),
        source_kind: representative.batch_identity.source_context_kind.clone(),
        track_count: total_track_count,
        album_artist: common.album_artist,
        album: common.album,
        year: common.year,
        genre: common.genre,
        catalog_number: common.catalog_number,
        source_blocking_lines: common.source_blocking_lines,
        provenance_section: common.provenance_section,
        artwork_section: common.artwork_section,
        conversion_settings_section: common.conversion_settings_section,
        track_sections,
        stage_records,
        total_summary: ConversionLogTotalSummary {
            successful_count,
            failed_count,
            total_track_count,
            total_bytes_in,
            total_bytes_out,
            missing_input_sizes,
            missing_output_sizes,
            total_duration,
            missing_durations,
        },
        batch_status,
        result_label,
    })
}

fn merge_conversion_log_common_fragments(
    ordered: &[ConversionLogFragment],
    ordering_common: &ConversionLogCommonFragment,
) -> ConversionLogCommonFragment {
    debug_assert!(!ordered.is_empty());

    let best_source_aware_common = ordered
        .iter()
        .map(|fragment| &fragment.common)
        .find(|common| conversion_log_common_has_source_context(common));

    ConversionLogCommonFragment {
        // Keep job/item identity anchored to the canonical first sorted
        // fragment so the header remains deterministic and matches the
        // ordering representative contract.
        representative_job_id: ordering_common.representative_job_id.clone(),
        representative_item_id: ordering_common.representative_item_id.clone(),
        album_artist: first_non_empty_common_option(
            ordered.iter().filter_map(|fragment| fragment.common.album_artist.as_deref()),
        ),
        album: first_non_empty_common_option(
            ordered.iter().filter_map(|fragment| fragment.common.album.as_deref()),
        ),
        year: first_non_empty_common_option(
            ordered.iter().filter_map(|fragment| fragment.common.year.as_deref()),
        ),
        genre: first_non_empty_common_option(
            ordered.iter().filter_map(|fragment| fragment.common.genre.as_deref()),
        ),
        catalog_number: first_non_empty_common_option(
            ordered.iter().filter_map(|fragment| fragment.common.catalog_number.as_deref()),
        ),
        source_blocking_lines: first_non_empty_common_string(
            ordered.iter().map(|fragment| fragment.common.source_blocking_lines.as_str()),
        )
        .unwrap_or_default(),
        provenance_section: merge_conversion_log_provenance_sections(ordered),
        artwork_section: first_non_empty_common_string(
            ordered.iter().map(|fragment| fragment.common.artwork_section.as_str()),
        )
        .unwrap_or_default(),
        conversion_settings_section: best_source_aware_common
            .and_then(|common| non_empty_common_string(&common.conversion_settings_section).map(str::to_string))
            .or_else(|| {
                first_non_empty_common_string(
                    ordered.iter().map(|fragment| fragment.common.conversion_settings_section.as_str()),
                )
            })
            .unwrap_or_else(|| ordering_common.conversion_settings_section.clone()),
    }
}

fn conversion_log_common_has_source_context(common: &ConversionLogCommonFragment) -> bool {
    non_empty_optional_common_string(common.album_artist.as_deref()).is_some()
        || non_empty_optional_common_string(common.album.as_deref()).is_some()
        || non_empty_optional_common_string(common.year.as_deref()).is_some()
        || non_empty_optional_common_string(common.genre.as_deref()).is_some()
        || non_empty_optional_common_string(common.catalog_number.as_deref()).is_some()
        || non_empty_common_string(&common.source_blocking_lines).is_some()
        || non_empty_common_string(&common.provenance_section).is_some()
        || non_empty_common_string(&common.artwork_section).is_some()
}

fn merge_conversion_log_provenance_sections(ordered: &[ConversionLogFragment]) -> String {
    let mut merged_tool_versions = BTreeMap::new();
    let mut first_with_tool_versions: Option<&str> = None;

    for fragment in ordered {
        let parsed = parse_conversion_log_tool_versions(&fragment.common.provenance_section);
        if first_with_tool_versions.is_none() && !parsed.is_empty() {
            first_with_tool_versions = Some(fragment.common.provenance_section.as_str());
        }
        for (tool, version) in parsed {
            merge_conversion_log_tool_version_value(&mut merged_tool_versions, tool, version);
        }
    }

    let base_owned: String;
    let base = if let Some(s) = first_with_tool_versions {
        s
    } else if let Some(s) = first_non_empty_common_string(
        ordered.iter().map(|fragment| fragment.common.provenance_section.as_str()),
    ) {
        base_owned = s;
        base_owned.as_str()
    } else {
        ""
    };

    if merged_tool_versions.is_empty() {
        return base.to_string();
    }

    provenance_section_with_tool_versions(base, &merged_tool_versions)
}

fn parse_conversion_log_tool_versions(section: &str) -> BTreeMap<String, String> {
    let mut versions = BTreeMap::new();
    for line in section.lines() {
        let Some(rest) = line.strip_prefix("Tool versions: ") else {
            continue;
        };
        for entry in rest.split(',') {
            let entry = entry.trim();
            let Some((tool, version)) = entry.rsplit_once(' ') else {
                continue;
            };
            let tool = tool.trim();
            let version = version.trim();
            if tool.is_empty() || version.is_empty() {
                continue;
            }
            versions.insert(tool.to_string(), version.to_string());
        }
    }
    versions
}

fn merge_conversion_log_tool_version_value(
    versions: &mut BTreeMap<String, String>,
    tool: String,
    version: String,
) {
    let incoming = version.trim();
    if incoming.is_empty() {
        return;
    }
    match versions.get(tool.as_str()).map(|existing| existing.trim()) {
        Some(existing) if !existing.is_empty() && existing != "in-process" => {}
        Some(_) | None => {
            versions.insert(tool, incoming.to_string());
        }
    }
}

fn provenance_section_with_tool_versions(
    base: &str,
    tool_versions: &BTreeMap<String, String>,
) -> String {
    let version_entries = tool_versions
        .iter()
        .filter_map(|(tool, version)| {
            let tool = tool.trim();
            let version = version.trim();
            if tool.is_empty() || version.is_empty() {
                None
            } else {
                Some(format!("{tool} {version}"))
            }
        })
        .collect::<Vec<_>>();

    if version_entries.is_empty() {
        return base.to_string();
    }

    let version_line = format!("Tool versions: {}", version_entries.join(", "));
    let mut merged = String::new();
    let mut inserted = false;

    for line in base.lines() {
        if line.strip_prefix("Tool versions: ").is_some() {
            continue;
        }
        merged.push_str(line);
        merged.push('\n');
        if !inserted && line.strip_prefix("Extracted at: ").is_some() {
            merged.push_str(&version_line);
            merged.push('\n');
            inserted = true;
        }
    }

    if !inserted {
        if !merged.ends_with('\n') {
            merged.push('\n');
        }
        merged.push_str(&version_line);
        merged.push('\n');
    }

    if !merged.ends_with("\n\n") {
        merged.push('\n');
    }
    merged
}

fn first_non_empty_common_option<'a>(values: impl Iterator<Item = &'a str>) -> Option<String> {
    values
        .filter_map(non_empty_common_string)
        .map(str::to_string)
        .next()
}

fn first_non_empty_common_string<'a>(values: impl Iterator<Item = &'a str>) -> Option<String> {
    values
        .filter_map(non_empty_common_string)
        .map(str::to_string)
        .next()
}

fn non_empty_optional_common_string(value: Option<&str>) -> Option<&str> {
    value.and_then(non_empty_common_string)
}

fn non_empty_common_string(value: &str) -> Option<&str> {
    if value.trim().is_empty() {
        None
    } else {
        Some(value)
    }
}

fn total_fragment_duration(fragments: &[ConversionLogFragment]) -> Duration {
    let mut total = Duration::ZERO;
    for duration in fragments
        .iter()
        .filter_map(|fragment| fragment.summary.duration_millis.map(duration_from_millis))
    {
        total = total
            .checked_add(duration)
            .unwrap_or_else(|| Duration::from_secs(u64::MAX));
    }
    total
}

fn fragment_result_label(
    fragments: &[ConversionLogFragment],
    successful_count: usize,
    failed_count: usize,
    total_track_count: usize,
    assembly_status: Option<ConversionLogAssemblyStatus>,
) -> String {
    let observed_count = successful_count.saturating_add(failed_count);
    let missing_count = total_track_count.saturating_sub(observed_count);
    match assembly_status {
        Some(ConversionLogAssemblyStatus::CancelledPartial { .. }) => {
            return format!(
                "Cancelled partial ({successful_count}/{total_track_count} ok, {failed_count} failed, {missing_count} missing)"
            );
        }
        Some(ConversionLogAssemblyStatus::TerminalFailurePartial { reason, .. }) => {
            return format!(
                "Aborted partial ({successful_count}/{total_track_count} ok, {failed_count} failed, {missing_count} missing; {reason})"
            );
        }
        None => {}
    }

    // Match the canonical AlbumOutcome result semantics for the all-blocked
    // fragment case instead of reducing it to a generic Partial label. A folder
    // batch whose completed fragment set contains only blocked track records is
    // an album-level block, not a partial success.
    let complete_observed_set = observed_count == total_track_count && missing_count == 0;
    let all_observed_tracks_blocked = !fragments.is_empty()
        && fragments
            .iter()
            .all(|fragment| fragment.summary.outcome == ConversionLogTrackOutcome::Blocked);
    if complete_observed_set && all_observed_tracks_blocked {
        return format!("Blocked ({})", block_reason_label(&BlockReason::TrackFailures));
    }

    if failed_count == 0 && successful_count == total_track_count {
        format!("Complete ({successful_count}/{total_track_count} ok)")
    } else if failed_count == 0 {
        format!("Partial ({successful_count}/{total_track_count} ok, {missing_count} missing)")
    } else if missing_count == 0 {
        format!("Partial ({successful_count}/{total_track_count} ok, {failed_count} failed)")
    } else {
        format!(
            "Partial ({successful_count}/{total_track_count} ok, {failed_count} failed, {missing_count} missing)"
        )
    }
}

fn aggregate_fragment_stage_records(fragments: &[ConversionLogFragment]) -> Vec<StageRecord> {
    let mut stages = Vec::new();
    for fragment in fragments {
        for stage in &fragment.stages {
            if let Some(index) = stages.iter().position(|existing: &StageRecord| existing.stage == stage.stage) {
                merge_stage_record(&mut stages[index], stage);
            } else {
                stages.push(stage.clone());
            }
        }
    }
    stages
}

fn merge_stage_record(existing: &mut StageRecord, next: &StageRecord) {
    existing.outcome = merge_stage_outcome(&existing.outcome, &next.outcome);
    match (&mut existing.dsd_dst_stats, &next.dsd_dst_stats) {
        (Some(existing_stats), Some(next_stats)) => existing_stats.merge(next_stats),
        (None, Some(next_stats)) => existing.dsd_dst_stats = Some(next_stats.clone()),
        _ => {}
    }
}

fn merge_stage_outcome(existing: &StageOutcome, next: &StageOutcome) -> StageOutcome {
    match (existing, next) {
        (StageOutcome::Failed(left), StageOutcome::Failed(right)) if left != right => {
            StageOutcome::Failed(format!("{left}; {right}"))
        }
        (StageOutcome::Failed(reason), _) | (_, StageOutcome::Failed(reason)) => {
            StageOutcome::Failed(reason.clone())
        }
        (StageOutcome::Ok, _) | (_, StageOutcome::Ok) => StageOutcome::Ok,
        (StageOutcome::SkippedWithReason(left), StageOutcome::SkippedWithReason(right)) => {
            if left == right {
                StageOutcome::SkippedWithReason(left.clone())
            } else {
                StageOutcome::SkippedWithReason(format!("{left}; {right}"))
            }
        }
        (StageOutcome::SkippedWithReason(reason), StageOutcome::Skipped)
        | (StageOutcome::Skipped, StageOutcome::SkippedWithReason(reason)) => {
            StageOutcome::SkippedWithReason(format!(
                "{reason}; reason unavailable for one or more inputs"
            ))
        }
        (StageOutcome::SkippedWithReason(reason), StageOutcome::NotRequested)
        | (StageOutcome::NotRequested, StageOutcome::SkippedWithReason(reason)) => {
            StageOutcome::SkippedWithReason(format!(
                "{reason}; not requested for one or more inputs"
            ))
        }
        (StageOutcome::Skipped, StageOutcome::Skipped) => StageOutcome::Skipped,
        (StageOutcome::Skipped, StageOutcome::NotRequested)
        | (StageOutcome::NotRequested, StageOutcome::Skipped) => StageOutcome::Skipped,
        (StageOutcome::NotRequested, StageOutcome::NotRequested) => StageOutcome::NotRequested,
    }
}

fn write_assembled_conversion_log_from_fragments(
    album_dir: &Path,
    log_path: &Path,
    expected_track_count: usize,
    target_identity: Option<&ConversionLogBatchIdentity>,
) -> Result<bool, PublishError> {
    let Some(log) = assemble_conversion_log_from_fragments(album_dir, expected_track_count, target_identity)? else {
        return Ok(false);
    };
    write_bytes_atomically(log_path, log.as_bytes()).map_err(PublishError::io_at("writing assembled conversion log", log_path))?;
    Ok(true)
}

fn conversion_log_entry_predicate(entry: &PublishedEntry) -> bool {
    matches!(&entry.role, PublishRole::Sidecar(SidecarKind::ConversionLog))
}

fn record_assembled_conversion_log_entry(
    published_entries: &mut Vec<PublishedEntry>,
    final_log_path: &Path,
    bytes: u64,
) {
    if let Some(existing) = published_entries
        .iter_mut()
        .find(|entry| conversion_log_entry_predicate(entry))
    {
        existing.final_path = final_log_path.to_path_buf();
        existing.bytes = bytes;
    } else {
        published_entries.push(PublishedEntry {
            final_path: final_log_path.to_path_buf(),
            role: PublishRole::Sidecar(SidecarKind::ConversionLog),
            bytes,
        });
    }
}

fn finalize_staged_conversion_log_for_publish(
    work_album_dir: &Path,
    final_album_dir: &Path,
    expected_track_count: usize,
    fragment_mode: bool,
    write_conversion_log: bool,
    target_identity: Option<&ConversionLogBatchIdentity>,
    published_entries: &mut Vec<PublishedEntry>,
) -> Result<bool, PublishError> {
    if !fragment_mode {
        return Ok(false);
    }

    let staged_log_path = work_album_dir.join("conversion.log");
    let final_log_path = final_album_dir.join("conversion.log");

    if !write_conversion_log {
        // The user disabled the conversion log: never assemble the visible
        // file, but still report batch completion so post-publish cleanup can
        // consume the hidden fragments once the album batch is complete.
        remove_file_if_exists(&staged_log_path).map_err(PublishError::io_at("removing staged conversion log", &staged_log_path))?;
        published_entries.retain(|entry| !conversion_log_entry_predicate(entry));
        let complete = complete_conversion_log_fragments(
            work_album_dir,
            expected_track_count,
            target_identity,
        )?
        .is_some();
        return Ok(complete);
    }

    match write_assembled_conversion_log_from_fragments(
        work_album_dir,
        &staged_log_path,
        expected_track_count,
        target_identity,
    )? {
        true => {
            let bytes = fs::metadata(&staged_log_path).map_err(PublishError::io_at("reading staged conversion log metadata", &staged_log_path))?.len();
            record_assembled_conversion_log_entry(published_entries, &final_log_path, bytes);
            Ok(true)
        }
        false => {
            remove_file_if_exists(&staged_log_path).map_err(PublishError::io_at("removing staged conversion log", &staged_log_path))?;
            published_entries.retain(|entry| !conversion_log_entry_predicate(entry));
            Ok(false)
        }
    }
}

fn publish_incremental_assembled_conversion_log_from_fragments(
    album_dir: &Path,
    expected_track_count: usize,
    write_conversion_log: bool,
    target_identity: Option<&ConversionLogBatchIdentity>,
    rollback: &mut IncrementalPublishRollback,
) -> Result<bool, PublishError> {
    let Some(fragments) = complete_conversion_log_fragments(
        album_dir,
        expected_track_count,
        target_identity,
    )? else {
        return Ok(false);
    };

    if !write_conversion_log {
        // Batch complete but the user disabled the conversion log: report
        // completion so post-publish cleanup consumes the hidden fragments,
        // and write nothing visible.
        return Ok(true);
    }

    let log_path = album_dir.join("conversion.log");
    rollback.snapshot_destination(&log_path)?;
    let log = build_conversion_log_from_fragments(&fragments);
    write_bytes_atomically(&log_path, log.as_bytes()).map_err(PublishError::io_at("writing assembled conversion log", &log_path))?;
    sync_parent_dir_best_effort(&log_path);
    Ok(true)
}


fn cancelled_conversion_log_target_identity(
    album_dir: &Path,
    req: &PipelineRequest,
    settings_fingerprint: Option<&str>,
) -> Result<ConversionLogBatchIdentity, PublishError> {
    conversion_log_batch_identity(req, album_dir, settings_fingerprint).map_err(PublishError::Io)
}

fn read_cancelled_conversion_log_fragment_files(
    album_dir: &Path,
    req: &PipelineRequest,
) -> Result<Vec<ConversionLogFragmentFile>, PublishError> {
    let album_batch = conversion_log_album_batch(req).map_err(PublishError::Io)?;
    let expected = conversion_log_expected_track_count(req).map_err(PublishError::Io)?;
    if expected != album_batch.expected_track_count {
        return Err(PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            "conversion log cancellation finalization expected-count contract mismatch",
        )));
    }
    let settings_fingerprint = tonepoet_pipeline::fingerprint::settings_fingerprint(&req.settings).to_string();
    let target_identity = cancelled_conversion_log_target_identity(
        album_dir,
        req,
        Some(settings_fingerprint.as_str()),
    )?;

    // Cancellation finalization must use the same strict batch identity as
    // ordinary completion. In particular, source_context_path and
    // source_context_kind are part of the identity; a cancelled partial log must
    // not assemble fragments that normal completion would reject.
    read_matching_conversion_log_fragment_files(album_dir, &target_identity)
}

fn cancelled_conversion_log_fragments(
    album_dir: &Path,
    req: &PipelineRequest,
) -> Result<Vec<ConversionLogFragmentFile>, PublishError> {
    let expected = conversion_log_expected_track_count(req).map_err(PublishError::Io)?;
    let files = read_cancelled_conversion_log_fragment_files(album_dir, req)?;
    if files.is_empty() {
        return Ok(Vec::new());
    }
    let fragments: Vec<ConversionLogFragment> = files.iter().map(|file| file.fragment.clone()).collect();
    if fragments.iter().any(|fragment| fragment.expected_track_count != expected) {
        return Err(PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            "conversion log cancellation finalization found a fragment with mismatched expected track count",
        )));
    }
    let fragment_count = conversion_log_fragment_count(&fragments);
    if fragment_count > expected {
        return Err(PublishError::Io(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "conversion log cancellation finalization found {fragment_count} fragments, exceeding expected track count {expected}"
            ),
        )));
    }
    Ok(files)
}

fn remove_conversion_log_fragment_files_and_empty_dir(
    album_dir: &Path,
    files: &[ConversionLogFragmentFile],
    context: &str,
) {
    for file in files {
        if let Err(err) = fs::remove_file(&file.path) {
            if err.kind() != io::ErrorKind::NotFound {
                log::warn!(
                    "conversion log fragment cleanup failed during {context} for {}: {err}",
                    file.path.display()
                );
                return;
            }
        }
    }

    let dir = conversion_log_fragment_dir(album_dir);
    match fs::remove_dir(&dir) {
        Ok(()) => sync_parent_dir_best_effort(&dir),
        Err(err) if err.kind() == io::ErrorKind::NotFound => {}
        Err(err) if err.kind() == io::ErrorKind::DirectoryNotEmpty => {}
        Err(err) => log::warn!(
            "conversion log fragment directory cleanup failed during {context}: {}: {err}",
            dir.display()
        ),
    }
}

fn quarantined_conversion_log_fragment_belongs_to_finalized_album(
    fragment: &ConversionLogFragment,
    target_identity: &ConversionLogBatchIdentity,
) -> bool {
    conversion_log_batch_identities_match(&fragment.batch_identity, target_identity)
        || fragment.batch_identity.conversion_log_batch_id == target_identity.conversion_log_batch_id
        || (fragment.batch_identity.output_album_dir == target_identity.output_album_dir
            && fragment.batch_identity.source_grouping_root == target_identity.source_grouping_root
            && fragment.batch_identity.target_format == target_identity.target_format)
}

fn remove_quarantined_conversion_log_fragment_file(path: &Path, context: &str) {
    match fs::remove_file(path) {
        Ok(()) => {
            sync_parent_dir_best_effort(path);
            log::debug!(
                "removed quarantined conversion log fragment during {context}: {}",
                path.display()
            );
        }
        Err(err) if err.kind() == io::ErrorKind::NotFound => {}
        Err(err) => log::warn!(
            "quarantined conversion log fragment cleanup failed during {context} for {}: {err}",
            path.display()
        ),
    }
}

fn cleanup_conversion_log_fragment_quarantine_after_finalization(
    album_dir: &Path,
    target_identity: Option<&ConversionLogBatchIdentity>,
    context: &str,
) {
    let Some(target_identity) = target_identity else {
        return;
    };
    let quarantine_root = album_dir.join(CONVERSION_LOG_FRAGMENT_QUARANTINE_DIR);
    let entries = match fs::read_dir(&quarantine_root) {
        Ok(entries) => entries,
        Err(err) if err.kind() == io::ErrorKind::NotFound => return,
        Err(err) => {
            log::warn!(
                "conversion log fragment quarantine cleanup skipped during {context}: {}: {err}",
                quarantine_root.display()
            );
            return;
        }
    };

    let mut dirs = vec![quarantine_root.clone()];
    let mut stack = vec![quarantine_root.clone()];
    drop(entries);

    while let Some(dir) = stack.pop() {
        let entries = match fs::read_dir(&dir) {
            Ok(entries) => entries,
            Err(err) if err.kind() == io::ErrorKind::NotFound => continue,
            Err(err) => {
                log::warn!(
                    "conversion log fragment quarantine cleanup skipped directory during {context}: {}: {err}",
                    dir.display()
                );
                continue;
            }
        };

        for entry in entries {
            let entry = match entry {
                Ok(entry) => entry,
                Err(err) => {
                    log::warn!(
                        "conversion log fragment quarantine cleanup skipped entry during {context}: {err}"
                    );
                    continue;
                }
            };
            let path = entry.path();
            let file_type = match entry.file_type() {
                Ok(file_type) => file_type,
                Err(err) => {
                    log::warn!(
                        "conversion log fragment quarantine cleanup could not stat {} during {context}: {err}",
                        path.display()
                    );
                    continue;
                }
            };
            if file_type.is_dir() {
                dirs.push(path.clone());
                stack.push(path);
                continue;
            }
            if !file_type.is_file() {
                continue;
            }

            // Quarantined fragments are written through `unique_path()`, which
            // appends a uniqueness suffix after the original file name. A file
            // that entered quarantine as `track.json` therefore becomes, for
            // example, `track.json-<nanos>-0`; relying on `Path::extension()`
            // here silently skips exactly the stale/corrupt fragments this
            // cleanup pass is responsible for removing. The quarantine tree is
            // private to conversion-log fragments, so attempt to parse every
            // regular file and remove unreadable entries once an authoritative
            // final or cancelled partial log exists for the album batch.
            match read_conversion_log_fragment_file(&path) {
                Ok(fragment) if quarantined_conversion_log_fragment_belongs_to_finalized_album(
                    &fragment,
                    target_identity,
                ) => {
                    remove_quarantined_conversion_log_fragment_file(&path, context);
                }
                Ok(_) => {}
                Err(err) => {
                    // Invalid quarantine entries cannot be validated into any
                    // future batch. Once an authoritative final or cancelled
                    // partial log exists for this album directory, retaining
                    // unreadable hidden JSON only extends the privacy and stale
                    // state risks the quarantine was meant to contain.
                    log::warn!(
                        "removing unreadable quarantined conversion log fragment during {context}: {}: {err}",
                        path.display()
                    );
                    remove_quarantined_conversion_log_fragment_file(&path, context);
                }
            }
        }
    }

    dirs.sort_by_key(|dir| std::cmp::Reverse(dir.components().count()));
    for dir in dirs {
        match fs::remove_dir(&dir) {
            Ok(()) => sync_parent_dir_best_effort(&dir),
            Err(err) if err.kind() == io::ErrorKind::NotFound => {}
            Err(err) if err.kind() == io::ErrorKind::DirectoryNotEmpty => {}
            Err(err) => log::warn!(
                "conversion log fragment quarantine directory cleanup failed during {context}: {}: {err}",
                dir.display()
            ),
        }
    }
}

fn finalize_incomplete_conversion_log_batch_if_needed(
    req: &PipelineRequest,
    terminal_failure_reason: Option<&'static str>,
    context: &'static str,
) -> Option<PublishedAlbum> {
    let album_batch = req.album_batch.as_ref()?;
    for album_dir in conversion_log_candidate_album_dirs_for_incomplete_batch(req) {
        let _publish_lock = match acquire_publish_lock(&album_dir) {
            Ok(lock) => lock,
            Err(err) => {
                log::warn!(
                    "conversion log {context} skipped candidate because publish lock failed for {}: {err}",
                    album_dir.display()
                );
                continue;
            }
        };

        let files = match cancelled_conversion_log_fragments(&album_dir, req) {
            Ok(files) => files,
            Err(err) => {
                log::warn!(
                    "conversion log {context} skipped candidate {}: {err}",
                    album_dir.display()
                );
                continue;
            }
        };
        if files.is_empty() {
            continue;
        }

        let fragments: Vec<ConversionLogFragment> = files.iter().map(|file| file.fragment.clone()).collect();

        if !req.log.write_conversion_log {
            // The user disabled the conversion log: consume the interrupted
            // batch's fragments without writing a partial visible log.
            let target_identity = fragments
                .first()
                .map(|fragment| fragment.batch_identity.clone());
            remove_conversion_log_fragment_files_and_empty_dir(
                &album_dir,
                &files,
                context,
            );
            cleanup_conversion_log_fragment_quarantine_after_finalization(
                &album_dir,
                target_identity.as_ref(),
                context,
            );
            return Some(PublishedAlbum {
                album_dir,
                entries: Vec::new(),
                manifest_path: None,
                batch_completion: None,
            });
        }

        let assembly_status = match terminal_failure_reason {
            Some(reason) => ConversionLogAssemblyStatus::TerminalFailurePartial {
                expected_track_count: album_batch.expected_track_count,
                reason,
            },
            None => ConversionLogAssemblyStatus::CancelledPartial {
                expected_track_count: album_batch.expected_track_count,
            },
        };
        let log = build_conversion_log_from_fragments_with_status(
            &fragments,
            Some(assembly_status),
        );
        let target_identity = fragments
            .first()
            .map(|fragment| fragment.batch_identity.clone());
        let Some(target_identity_ref) = target_identity.as_ref() else {
            continue;
        };
        let visible_dirs = match visible_conversion_log_album_dirs_from_fragments(
            target_identity_ref,
            &fragments,
        ) {
            Ok(dirs) if !dirs.is_empty() => dirs,
            Ok(_) => {
                if conversion_log_batch_coordination_album_dir(req)
                    .is_some_and(|coord| normalize_path(&coord) == normalize_path(&album_dir))
                {
                    log::warn!(
                        "conversion log {context} skipped hidden coordination candidate without a rendered visible album root: {}",
                        album_dir.display()
                    );
                    continue;
                }
                vec![album_dir.clone()]
            }
            Err(err) => {
                log::warn!(
                    "conversion log {context} could not resolve visible log destinations for {}: {err}",
                    album_dir.display()
                );
                continue;
            }
        };

        let mut entries = Vec::with_capacity(visible_dirs.len());
        let bytes = log.as_bytes().len() as u64;
        let mut write_failed = false;
        for visible_dir in visible_dirs {
            if let Err(err) = fs::create_dir_all(&visible_dir) {
                log::warn!(
                    "conversion log {context} failed to create visible log root {}: {err}",
                    visible_dir.display()
                );
                write_failed = true;
                break;
            }
            let log_path = visible_dir.join("conversion.log");
            if let Err(err) = write_bytes_atomically(&log_path, log.as_bytes()) {
                log::warn!(
                    "conversion log {context} failed to write {}: {err}",
                    log_path.display()
                );
                write_failed = true;
                break;
            }
            sync_parent_dir_best_effort(&log_path);
            entries.push(PublishedEntry {
                final_path: log_path,
                role: PublishRole::Sidecar(SidecarKind::ConversionLog),
                bytes,
            });
        }
        if write_failed {
            continue;
        }

        remove_conversion_log_fragment_files_and_empty_dir(
            &album_dir,
            &files,
            context,
        );
        cleanup_conversion_log_fragment_quarantine_after_finalization(
            &album_dir,
            target_identity.as_ref(),
            context,
        );
        if conversion_log_batch_coordination_album_dir(req)
            .is_some_and(|coord| normalize_path(&coord) == normalize_path(&album_dir))
        {
            cleanup_conversion_log_batch_coordination_dir_after_success_best_effort(
                &album_dir,
                context,
                ConversionLogBatchCleanupAuthority::CurrentProcessOwner,
            );
        }

        return Some(PublishedAlbum {
            album_dir,
            entries,
            manifest_path: None,
            batch_completion: None,
        });
    }

    None
}

fn finalize_cancelled_conversion_log_batch_if_needed(req: &PipelineRequest) -> Option<PublishedAlbum> {
    finalize_incomplete_conversion_log_batch_if_needed(req, None, "cancellation finalization")
}

fn finalize_terminal_batch_failure_conversion_log_batch_if_needed(
    req: &PipelineRequest,
    reason: &'static str,
) -> Option<PublishedAlbum> {
    finalize_incomplete_conversion_log_batch_if_needed(
        req,
        Some(reason),
        "terminal infrastructure failure finalization",
    )
}

fn publish_cancelled_conversion_log_fragment_and_finalize(
    req: &PipelineRequest,
    source: Option<&PreparedSource>,
    artifacts: Option<&ArtifactSet>,
    outcome: &AlbumOutcome,
    staging: StagingDir,
    runner: Option<&dyn ToolRunner>,
) -> Option<PublishedAlbum> {
    let fragment_publish = publish_terminal_conversion_log_fragment_if_needed(
        req,
        source,
        artifacts,
        outcome,
        staging,
        runner,
    );
    finalize_cancelled_conversion_log_batch_if_needed(req).or(fragment_publish)
}

fn cleanup_complete_conversion_log_fragments(
    album_dir: &Path,
    expected_track_count: usize,
    require_assembled_log: bool,
    target_identity: Option<&ConversionLogBatchIdentity>,
) {
    let Some(target_identity) = target_identity else {
        return;
    };
    let files = match read_matching_conversion_log_fragment_files(album_dir, target_identity) {
        Ok(files) => files,
        Err(err) => {
            log::warn!("conversion log fragment cleanup skipped after unreadable fragments: {err}");
            return;
        }
    };

    if files.is_empty() {
        let log_path = album_dir.join("conversion.log");
        if log_path.is_file() {
            cleanup_conversion_log_fragment_quarantine_after_finalization(
                album_dir,
                Some(target_identity),
                "authoritative final assembly",
            );
        }
        return;
    }

    let fragments: Vec<ConversionLogFragment> = files
        .iter()
        .map(|file| file.fragment.clone())
        .collect();
    if expected_track_count == 0 {
        log::warn!(
            "conversion log fragment cleanup skipped after zero expected-count for batch {}",
            target_identity.conversion_log_batch_id
        );
        return;
    }
    let expected = expected_track_count;
    if fragments
        .iter()
        .any(|fragment| fragment.expected_track_count != expected)
    {
        log::warn!(
            "conversion log fragment cleanup skipped after expected-count mismatch for batch {}",
            target_identity.conversion_log_batch_id
        );
        return;
    }
    let fragment_count = conversion_log_fragment_count(&fragments);
    if fragment_count < expected {
        return;
    }
    if fragment_count > expected {
        log::warn!(
            "conversion log fragment cleanup skipped after fragment count {fragment_count} exceeded expected track count {expected} for batch {}",
            target_identity.conversion_log_batch_id
        );
        return;
    }

    // Only remove fragments after the visible authoritative forensic log has
    // been assembled. Do not discard fragments merely because the hidden sidecar
    // directory is complete. When the user disabled the conversion log there is
    // deliberately no assembled file: the complete batch's fragments are
    // consumed silently instead.
    if require_assembled_log {
        let log_path = album_dir.join("conversion.log");
        if !log_path.is_file() {
            log::warn!(
                "conversion log fragment cleanup skipped because assembled log is missing: {}",
                log_path.display()
            );
            return;
        }
    }

    remove_conversion_log_fragment_files_and_empty_dir(
        album_dir,
        &files,
        "successful final assembly",
    );
    cleanup_conversion_log_fragment_quarantine_after_finalization(
        album_dir,
        Some(target_identity),
        "successful final assembly",
    );
}

fn append_source_blocking_lines(log: &mut String, source: &PreparedSource) {
    let extra = &source.album_metadata.extra;
    let cppm = extra
        .get("dvda_cppm_detected")
        .map(|value| value == "true")
        .unwrap_or(false);
    let mkb = extra
        .get("dvda_mkb_present")
        .map(|value| value == "true")
        .unwrap_or(false);
    if !cppm && !mkb {
        return;
    }

    if cppm {
        push_kv_line(log, "Copy protection", "CPPM blocked");
    } else {
        push_kv_line(
            log,
            "Copy protection",
            "DVDAUDIO.MKB present; AOB probe did not detect encrypted audio data",
        );
    }
    if let Some(source) = extra.get("dvda_copy_protection_source") {
        push_kv_line(log, "Copy protection evidence", source);
    }
    if let Some(policy) = extra.get("dvda_mkb_aob_probe_policy") {
        push_kv_line(log, "MKB handling", policy);
    }
    if let Some(policy) = extra.get("dvda_copy_protection_policy") {
        push_kv_line(log, "Copy protection policy", policy);
    }
    if let Some(supported) = extra.get("dvda_cppm_decryption_supported") {
        push_kv_line(log, "CPPM decryption supported", supported);
    }
    if let Some(reason) = extra.get("dvda_copy_protection_skip_reason") {
        push_kv_line(log, "Copy protection skip reason", reason);
    }
    if let Some(file) = extra.get("dvda_copy_protection_file") {
        push_kv_line(log, "Copy protection source", file);
    } else if mkb {
        push_kv_line(log, "Copy protection source", "DVDAUDIO.MKB");
    }
}

fn build_source_track_index<'a>(source: &'a PreparedSource) -> BTreeMap<u32, &'a PreparedTrack> {
    let mut tracks_by_ordinal = BTreeMap::new();
    for track in &source.tracks {
        tracks_by_ordinal
            .entry(track.id.source_ordinal)
            .or_insert(track);
    }
    tracks_by_ordinal
}

fn build_track_artifact_index<'a>(artifacts: &'a ArtifactSet) -> BTreeMap<TrackId, &'a TrackArtifact> {
    let mut artifacts_by_track_id = BTreeMap::new();
    if let AudioArtifacts::Tracks(tracks) = &artifacts.audio {
        for artifact in tracks {
            artifacts_by_track_id
                .entry(artifact.track_id.clone())
                .or_insert(artifact);
        }
    }
    artifacts_by_track_id
}

fn append_track_log(
    log: &mut String,
    record: &TrackRecord,
    prepared: Option<&PreparedTrack>,
    source: Option<&PreparedSource>,
    artifact: Option<&TrackArtifact>,
    req: &PipelineRequest,
    metadata_stage_result: Option<&StageOutcome>,
) {
    log.push_str(&escape_log_value(&track_display_label(record, prepared)));
    log.push('\n');
    match &record.outcome {
        TrackOutcome::Ok => log.push_str("  Status: Success\n"),
        TrackOutcome::Err(error) => {
            log.push_str("  Status: Failure\n");
            push_kv_line(log, "  Error", error);
        }
        TrackOutcome::Blocked(reason) => {
            log.push_str("  Status: Blocked\n");
            push_kv_line(log, "  Block reason", reason);
        }
    }

    if let Some(track) = prepared {
        push_optional_kv_line(log, "  Artist", track.metadata.artist.as_deref());
        push_optional_kv_line(log, "  Composer", track.metadata.composer.as_deref());
        push_kv_line(log, "  Source audio", source_audio_description(track));
        push_kv_line(
            log,
            "  Conversion",
            conversion_summary(
                track,
                req,
                record.verified_output_bit_depth,
                Some(command_records_prove_dither_for_track(track, record, &req.settings)),
            ),
        );
        for warning in &track.warnings {
            push_kv_line(log, "  Warning", warning);
        }
        if let Some(disclosure) = per_track_dither_disclosure(track, record, req) {
            push_kv_line(log, "  Warning", disclosure);
        }
    }

    if let Some(pipeline) = planned_pipeline_label(&record.commands)
        .or_else(|| passthrough_pipeline_label(record, prepared, req))
    {
        push_kv_line(log, "  Pipeline", pipeline);
    }

    if let Some(metadata) = metadata_satisfaction_label(
        artifact,
        prepared,
        source,
        req.stages.metadata,
        metadata_stage_result,
    ) {
        push_kv_line(log, "  Metadata", metadata);
    }
    if let Some(metadata_source) = req.source.sidecar_cue_track_metadata.as_ref() {
        push_kv_line(
            log,
            "  Metadata source",
            format!(
                "Sidecar CUE: {} (track {})",
                path_log_value(&metadata_source.cue_path),
                metadata_source.cue_track_number,
            ),
        );
    }

    push_kv_line(
        log,
        "  Source ref",
        track_source_ref_label(&record.source_ref),
    );
    if let Some(realized_input) = &record.realized_input {
        push_kv_line(log, "  Realized input", path_log_value(realized_input));
    }
    if let Some(output_file) = &record.output_file {
        push_kv_line(log, "  Output file", path_log_value(output_file));
    }

    match (record.bytes_in, record.bytes_out) {
        (Some(bytes_in), Some(bytes_out)) => push_kv_line(
            log,
            "  Size",
            format!(
                "{} -> {} ({})",
                format_bytes(bytes_in),
                format_bytes(bytes_out),
                compression_ratio(bytes_in, bytes_out)
            ),
        ),
        (Some(bytes_in), None) => push_kv_line(log, "  Input size", format_bytes(bytes_in)),
        (None, Some(bytes_out)) => push_kv_line(log, "  Output size", format_bytes(bytes_out)),
        (None, None) => log.push_str("  Size: unknown\n"),
    }

    if let Some(stats) = record.dsd_dst_stats.as_ref() {
        push_kv_line(log, "  DSD/DST stats", format_dsd_dst_stats_inline(stats));
    }

    if let Some(duration) = record.duration {
        push_kv_line(log, "  Encode duration", format_duration(duration));
    }

    if record.commands.is_empty() {
        log.push_str("  Commands: none recorded\n");
    } else {
        log.push_str("  Commands:\n");
        for (index, command) in record.commands.iter().enumerate() {
            log.push_str(&format!(
                "    {}. {} [{}; {}]\n",
                index + 1,
                command_line_label(command),
                format_duration(command.elapsed),
                process_exit_label(command.exit)
            ));
        }
    }
    log.push('\n');
}


fn conversion_log_tool_name(binary: ToolBinary) -> Option<&'static str> {
    match binary {
        ToolBinary::SevenZip => Some("7z"),
        ToolBinary::Ffmpeg => Some("ffmpeg"),
        ToolBinary::Ffprobe => Some("ffprobe"),
        ToolBinary::Sox => Some("sox"),
        ToolBinary::Ssrc => Some("ssrc"),
        ToolBinary::Loudgain => Some("loudgain"),
        ToolBinary::Metaflac => Some("metaflac"),
        ToolBinary::Flac => Some("flac"),
        ToolBinary::Opustags => Some("opustags"),
        ToolBinary::Wvunpack => Some("wvunpack"),
        ToolBinary::Wvtag => Some("wvtag"),
        ToolBinary::AtomicParsley => Some("AtomicParsley"),
        ToolBinary::Tar => Some("tar"),
        ToolBinary::Rar => Some("rar"),
    }
}

fn merge_detected_tool_version(
    tool_versions: &mut BTreeMap<String, String>,
    runner: &dyn ToolRunner,
    binary: ToolBinary,
) {
    let Some(tool_name) = conversion_log_tool_name(binary) else {
        return;
    };
    if tool_versions
        .get(tool_name)
        .map(|version| {
            let version = version.trim();
            !version.is_empty() && version != "in-process"
        })
        .unwrap_or(false)
    {
        return;
    }
    if let Some(version) = runner.tool_version(binary) {
        tool_versions.insert(tool_name.to_string(), version);
    }
}

fn effective_conversion_log_provenance(
    source: &PreparedSource,
    tracks: &[&TrackRecord],
    runner: Option<&dyn ToolRunner>,
) -> ExtractionProvenance {
    let mut provenance = source.provenance.clone();
    let Some(runner) = runner else {
        return provenance;
    };

    for track in tracks {
        for command in &track.commands {
            merge_detected_tool_version(&mut provenance.tool_versions, runner, command.binary);
        }
    }
    provenance
}

fn append_provenance_section(log: &mut String, provenance: &ExtractionProvenance) {
    log.push_str("Provenance\n");
    log.push_str("----------\n");
    if let Some(sha256) = provenance
        .source_sha256
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        push_kv_line(log, "Source SHA-256", sha256);
    }
    push_kv_line(
        log,
        "Extracted at",
        provenance
            .extracted_at
            .format("%Y-%m-%d %H:%M:%S UTC")
            .to_string(),
    );
    if !provenance.tool_versions.is_empty() {
        let versions = provenance
            .tool_versions
            .iter()
            .filter_map(|(tool, version)| {
                let tool = tool.trim();
                let version = version.trim();
                if tool.is_empty() || version.is_empty() {
                    None
                } else {
                    Some(format!("{tool} {version}"))
                }
            })
            .collect::<Vec<_>>();
        if !versions.is_empty() {
            push_kv_line(log, "Tool versions", versions.join(", "));
        }
    }
    log.push('\n');
}

fn append_artwork_section(
    log: &mut String,
    source: &PreparedSource,
    req: &PipelineRequest,
    outcome: &AlbumOutcome,
    artifacts: &ArtifactSet,
) {
    let Some(artwork) = cue_artwork_sidecar_from_album_metadata(&source.album_metadata) else {
        return;
    };
    let artwork_format = artwork
        .mime_type
        .as_deref()
        .map(artwork_mime_label)
        .unwrap_or("artwork");
    push_kv_line(
        log,
        "Artwork",
        format!(
            "extracted {artwork_format} from source image → {}",
            cue_artwork_log_outcome(req, outcome, artifacts)
        ),
    );
    log.push('\n');
}

fn append_conversion_settings_section(
    log: &mut String,
    source: &PreparedSource,
    req: &PipelineRequest,
    tracks: &[&TrackRecord],
    replaygain_stage_result: Option<&StageOutcome>,
    resampling_applies: bool,
    bit_depth_change_applies: bool,
    dithering_applies: bool,
) {
    let settings = &req.settings;
    push_kv_line(log, "Target format", settings.target_format.display_name());
    push_kv_line(
        log,
        "Resampling",
        resampling_log_line(source, settings, tracks, resampling_applies),
    );
    push_kv_line(
        log,
        "Bit-depth conversion",
        bit_depth_conversion_log_line(source, settings, tracks, bit_depth_change_applies),
    );
    push_kv_line(
        log,
        "Dither",
        dither_log_line(source, settings, tracks, dithering_applies),
    );
    push_kv_line(log, "Force encode", yes_no(settings.force_encode));
    push_kv_line(log, "Merge mode", yes_no(req.merge));

    append_target_format_settings(log, settings);
    if resampling_applies {
        append_resampler_settings(log, settings);
    }
    if source_is_dsd(source) || settings.target_format.is_dsd() {
        append_dsd_settings(log, source, settings);
    }

    push_kv_line(log, "Metadata", stage_requirement_label(req.stages.metadata));
    push_kv_line(log, "ReplayGain", stage_requirement_label(req.stages.replaygain));
    let successful_output_count = tracks
        .iter()
        .filter(|track| matches!(track.outcome, TrackOutcome::Ok))
        .count();
    push_kv_line(
        log,
        "ReplayGain policy",
        replaygain_policy_log_label(
            source,
            req,
            successful_output_count,
            replaygain_stage_result,
        ),
    );
    push_kv_line(
        log,
        "ReplayGain clipping prevention",
        yes_no(settings.replay_gain.prevent_clipping),
    );
    push_kv_line(log, "Features", stage_requirement_label(req.stages.features));
    match &req.naming.folder_template {
        Some(template) => push_kv_line(log, "Folder template", template),
        None => push_kv_line(log, "Folder template", "album-name fallback"),
    }
    push_kv_line(log, "Filename template", &req.naming.template);
}

fn sample_rate_transition_log_label(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> String {
    let transitions = source
        .tracks
        .iter()
        .filter_map(|track| {
            let source_rate = track.scalar_sample_rate()?;
            let target_rate = resolved_target_rate_hz(track, settings)?;
            (source_rate != target_rate).then(|| {
                let source_label = source_track_dsd_rate(track)
                    .map(dsd_rate_label)
                    .map(str::to_string)
                    .unwrap_or_else(|| format_sample_rate(source_rate));
                let target_label = if settings.target_format.is_dsd() {
                    DsdRate::from_hz(target_rate)
                        .map(dsd_rate_label)
                        .map(str::to_string)
                        .unwrap_or_else(|| format_sample_rate(target_rate))
                } else {
                    format_sample_rate(target_rate)
                };
                format!("{source_label} → {target_label}")
            })
        })
        .collect::<BTreeSet<_>>();
    if transitions.is_empty() {
        target_sample_rate_setting_label(source, settings)
    } else {
        transitions.into_iter().collect::<Vec<_>>().join(", ")
    }
}

fn resampling_log_line(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
    tracks: &[&TrackRecord],
    applies: bool,
) -> String {
    if !applies {
        return "no (source rate preserved)".to_string();
    }

    let transition = sample_rate_transition_log_label(source, settings);
    if tonepoet_pipeline::selects_reference_dsd_to_pcm(settings, source_is_dsd(source)) {
        return format!("yes (sox_ng rate, Reference policy, {transition})");
    }
    let detail = match actual_resampler_label(tracks, settings) {
        "soxr" => {
            let precision = tonepoet_pipeline::mapping::soxr_precision(settings.resample_quality);
            let cutoff = settings
                .soxr_resampler
                .cutoff
                .unwrap_or_else(|| {
                    tonepoet_pipeline::mapping::ffmpeg_cutoff(settings.nyquist_transition)
                });
            let mut fields = vec![
                "soxr via ffmpeg aresample".to_string(),
                format!("precision={precision}"),
                format!("cutoff={cutoff:.3}"),
            ];
            if settings.soxr_resampler.chebyshev {
                fields.push("cheby=1".to_string());
            }
            if let Some(phase) = settings.soxr_resampler.phase {
                fields.push(format!("phase_shift={phase}"));
            }
            fields.join(", ")
        }
        "SoX" => {
            let sox = settings.sox_resampler;
            let mut fields = vec![format!(
                "SoX rate {}",
                tonepoet_pipeline::mapping::sox_rate_quality_flag(settings.resample_quality)
            )];
            if sox.chebyshev {
                fields.push("chebyshev".to_string());
            } else if let Some(bandwidth) = sox.bandwidth_pct {
                fields.push(format!("bandwidth={}", decimal_label(bandwidth)));
            } else if let Some(bandwidth) =
                tonepoet_pipeline::mapping::sox_bandwidth_percent(settings.nyquist_transition)
            {
                fields.push(format!("bandwidth={bandwidth}"));
            }
            if let Some(phase) = sox.phase {
                fields.push(format!("phase={phase}"));
            }
            if sox.allow_aliasing {
                fields.push("allow_aliasing=yes".to_string());
            }
            if let Some(taps) = sox.sinc_taps {
                fields.push(format!("sinc_taps={taps}"));
            }
            if let Some(attenuation) = sox.sinc_attenuation_db {
                fields.push(format!("sinc_attenuation={attenuation} dB"));
            }
            if let Some(passband) = sox.sinc_passband_hz {
                fields.push(format!("sinc_passband={} Hz", decimal_label(passband)));
            }
            if let Some(transition) = sox.sinc_transition_hz {
                fields.push(format!(
                    "sinc_transition={} Hz",
                    decimal_label(transition)
                ));
            }
            if let Some(beta) = sox.sinc_kaiser_beta {
                fields.push(format!("sinc_kaiser_beta={}", decimal_label(beta)));
            }
            if let Some(phase) = sox.sinc_phase {
                fields.push(format!("sinc_phase={}", sox_sinc_phase_label(phase)));
            }
            fields.join(", ")
        }
        "SSRC" => {
            let mut fields = vec![format!(
                "SSRC profile={}",
                ssrc_profile_label(
                    settings.ssrc.profile,
                    settings.resample_quality,
                    settings.ssrc.insane_mode,
                )
            )];
            if let Some(attenuation) = settings.ssrc.attenuation_db {
                fields.push(format!(
                    "attenuation={} dB",
                    decimal_label(attenuation)
                ));
            }
            fields.push(format!(
                "phase={}",
                if settings.ssrc.min_phase {
                    "minimum"
                } else {
                    "linear"
                }
            ));
            fields.join(", ")
        }
        other => other.to_string(),
    };
    format!("yes ({detail}, {transition})")
}

fn bit_depth_transition_log_label(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> String {
    let transitions = source
        .tracks
        .iter()
        .filter_map(|track| {
            let target_depth = resolved_target_pcm_depth(track, settings.target_bit_depth)
                .or_else(|| {
                    source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth)
                })?;
            let target_label = pcm_bit_depth_label(target_depth);
            match super::plan_bridge::resolve_source_pcm_depth(track) {
                Some(source_depth) if source_depth != target_depth => Some(format!(
                    "{} → {target_label}",
                    pcm_bit_depth_label(source_depth)
                )),
                Some(_) => None,
                None => match track
                    .source_audio
                    .coding
                    .unwrap_or(SourceAudioCoding::Unknown)
                {
                    SourceAudioCoding::Dsd => Some(format!("DSD → {target_label}")),
                    SourceAudioCoding::Lossy => {
                        Some(format!("decoded lossy source → {target_label}"))
                    }
                    SourceAudioCoding::Pcm
                    | SourceAudioCoding::DvdaUnknown
                    | SourceAudioCoding::Unknown => (settings.target_bit_depth
                        != BitDepthTarget::Source)
                        .then(|| format!("unknown source depth → {target_label}")),
                },
            }
        })
        .collect::<BTreeSet<_>>();
    if transitions.is_empty() {
        bit_depth_target_label(settings.target_bit_depth)
    } else {
        transitions.into_iter().collect::<Vec<_>>().join(", ")
    }
}

fn command_record_emits_dither(command: &CommandRecord) -> bool {
    match command.binary {
        ToolBinary::Ffmpeg => command
            .sanitized_args
            .iter()
            .any(|arg| arg.contains("dither_method=")),
        ToolBinary::Sox => command.sanitized_args.iter().any(|arg| arg == "dither"),
        ToolBinary::Ssrc => {
            let dither_id = command
                .sanitized_args
                .windows(2)
                .find(|pair| pair[0] == "--dither")
                .map(|pair| pair[1].as_str());
            let has_pdf = command
                .sanitized_args
                .windows(2)
                .any(|pair| pair[0] == "--pdf");
            // SSRC ID 99 is the no-shaper terminal quantizer. It represents
            // actual dither only when paired with an explicit PDF; all other
            // IDs select a dither/noise-shaping stage themselves.
            dither_id.is_some_and(|id| id != "99" || has_pdf)
        }
        _ => false,
    }
}

fn command_record_proves_dither_for_target(
    command: &CommandRecord,
    target_depth: Option<tonepoet_pipeline::PcmBitDepth>,
    reference_dsd: bool,
) -> bool {
    // A trailing SoX `dither` token is not sufficient evidence for ordinary
    // Int32 output: SoX 14.4.2 accepts that command while producing
    // byte-identical samples. The qualified DSD Reference route is separately
    // identity-bound and may use command evidence for its policy-fixed stage.
    if command.binary == ToolBinary::Sox
        && target_depth == Some(tonepoet_pipeline::PcmBitDepth::Int32)
        && !reference_dsd
    {
        return false;
    }
    command_record_emits_dither(command)
}

fn command_records_prove_dither_for_track(
    track: &PreparedTrack,
    record: &TrackRecord,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> bool {
    let target_depth = resolved_target_pcm_depth(track, settings.target_bit_depth)
        .or_else(|| source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth));
    let reference_dsd = tonepoet_pipeline::selects_reference_dsd_to_pcm(
        settings,
        track.source_audio.coding == Some(SourceAudioCoding::Dsd),
    );
    record
        .commands
        .iter()
        .any(|command| command_record_proves_dither_for_target(command, target_depth, reference_dsd))
}

fn command_records_prove_dither_for_source(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
    tracks: &[&TrackRecord],
) -> bool {
    tracks.iter().enumerate().any(|(index, record)| {
        if let Some(prepared) = source.tracks.get(index) {
            return command_records_prove_dither_for_track(prepared, record, settings);
        }
        // A malformed or partial record/source pairing must not let an
        // unqualified SoX Int32 token become affirmative evidence. Fall back
        // to the global target only, with no Reference-policy exemption.
        let target_depth = source_has_int32_target(source, settings)
            .then_some(tonepoet_pipeline::PcmBitDepth::Int32);
        record.commands.iter().any(|command| {
            command_record_proves_dither_for_target(command, target_depth, false)
        })
    })
}

fn command_records_use_tool(tracks: &[&TrackRecord], binary: ToolBinary) -> bool {
    tracks
        .iter()
        .any(|track| track.commands.iter().any(|command| command.binary == binary))
}

fn processing_tool_label(
    tracks: &[&TrackRecord],
    settings: &tonepoet_pipeline::PipelineSettings,
) -> &'static str {
    // Prefer the terminal resampler over preparatory decode commands. SSRC
    // pipelines commonly contain an ffmpeg decode before the SSRC process,
    // and Reference/SoX paths may likewise contain auxiliary commands.
    if command_records_use_tool(tracks, ToolBinary::Ssrc) {
        return "SSRC";
    }
    for track in tracks {
        for command in &track.commands {
            if !command_record_performs_resampling(command) {
                continue;
            }
            return match command.binary {
                ToolBinary::Sox => "SoX",
                ToolBinary::Ffmpeg => "ffmpeg aresample",
                ToolBinary::Ssrc => "SSRC",
                _ => preferred_resampler_label(settings),
            };
        }
    }
    if command_records_use_tool(tracks, ToolBinary::Sox) {
        "SoX"
    } else if command_records_use_tool(tracks, ToolBinary::Ffmpeg) {
        "ffmpeg aresample"
    } else {
        match preferred_resampler_family(settings) {
            ResamplerFamily::Sox => "SoX",
            ResamplerFamily::Ssrc => "SSRC",
            ResamplerFamily::Soxr | ResamplerFamily::Auto => "ffmpeg aresample",
        }
    }
}

fn applied_dither_tool_label(
    source: &PreparedSource,
    tracks: &[&TrackRecord],
    settings: &tonepoet_pipeline::PipelineSettings,
) -> String {
    let mut tools = BTreeSet::new();
    for (index, record) in tracks.iter().enumerate() {
        let prepared = source.tracks.get(index);
        let target_depth = prepared
            .and_then(|track| resolved_target_pcm_depth(track, settings.target_bit_depth)
                .or_else(|| source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth)))
            .or_else(|| source_has_int32_target(source, settings)
                .then_some(tonepoet_pipeline::PcmBitDepth::Int32));
        let reference_dsd = prepared.is_some_and(|track| {
            tonepoet_pipeline::selects_reference_dsd_to_pcm(
                settings,
                track.source_audio.coding == Some(SourceAudioCoding::Dsd),
            )
        });
        for command in &record.commands {
            if command_record_proves_dither_for_target(command, target_depth, reference_dsd) {
                tools.insert(match command.binary {
                    ToolBinary::Ffmpeg => "ffmpeg aresample",
                    ToolBinary::Sox => "SoX",
                    ToolBinary::Ssrc => "SSRC",
                    _ => unreachable!("only dither-capable tools are inserted"),
                });
            }
        }
    }
    if tools.is_empty() {
        processing_tool_label(tracks, settings).to_string()
    } else {
        tools.into_iter().collect::<Vec<_>>().join(" + ")
    }
}

fn ssrc_dither_command_settings(command: &CommandRecord) -> Option<String> {
    if command.binary != ToolBinary::Ssrc || !command_record_emits_dither(command) {
        return None;
    }
    let dither_id = command
        .sanitized_args
        .windows(2)
        .find(|pair| pair[0] == "--dither")
        .map(|pair| pair[1].as_str())?;
    let mut fields = vec![format!("dither_id={dither_id}")];
    if let Some(pdf) = command
        .sanitized_args
        .windows(2)
        .find(|pair| pair[0] == "--pdf")
        .map(|pair| pair[1].as_str())
    {
        fields.push(format!("pdf={pdf}"));
    }
    Some(fields.join(", "))
}

fn applied_dither_description(
    source: &PreparedSource,
    tracks: &[&TrackRecord],
    settings: &tonepoet_pipeline::PipelineSettings,
) -> String {
    let algorithm = if settings.dither_type == DitherType::None {
        "command-selected dither/noise shaping".to_string()
    } else {
        dither_type_label(settings.dither_type).to_string()
    };
    let tools = applied_dither_tool_label(source, tracks, settings);
    let ssrc_settings = tracks
        .iter()
        .flat_map(|track| track.commands.iter())
        .filter_map(ssrc_dither_command_settings)
        .collect::<BTreeSet<_>>();
    let mut description = format!("{algorithm} via {tools}");
    if !ssrc_settings.is_empty() {
        if let Some(note) =
            tonepoet_pipeline::mapping::ssrc_dither_approximation_note(settings.dither_type)
        {
            description.push_str("; ");
            description.push_str(note);
        }
        description.push_str(", ");
        description.push_str(&ssrc_settings.into_iter().collect::<Vec<_>>().join(" + "));
    }
    description
}

fn bit_depth_processing_label(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
    tracks: &[&TrackRecord],
) -> String {
    let tool = processing_tool_label(tracks, settings);
    let mut all_known_integer_changes_are_widening = true;
    let mut saw_known_integer_change = false;
    let mut has_float_target = false;

    for track in &source.tracks {
        let target_depth = resolved_target_pcm_depth(track, settings.target_bit_depth)
            .or_else(|| {
                source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth)
            });
        let Some(target_depth) = target_depth else {
            continue;
        };
        if target_depth.is_float() {
            has_float_target = true;
            continue;
        }
        match super::plan_bridge::resolve_source_pcm_depth(track) {
            Some(source_depth) if source_depth != target_depth => {
                saw_known_integer_change = true;
                if target_depth.bits() <= source_depth.bits() {
                    all_known_integer_changes_are_widening = false;
                }
            }
            Some(_) => {}
            None => {
                // DSD, decoded lossy, and unknown-width PCM sources require an
                // actual terminal integer quantization step, not mere widening.
                all_known_integer_changes_are_widening = false;
            }
        }
    }

    if has_float_target {
        match tool {
            "SoX" => "SoX floating-point sample-format conversion".to_string(),
            "SSRC" => "SSRC floating-point sample-format conversion".to_string(),
            _ => "swresample floating-point sample-format conversion".to_string(),
        }
    } else if saw_known_integer_change && all_known_integer_changes_are_widening {
        match tool {
            "SoX" => "SoX integer widening".to_string(),
            "SSRC" => "SSRC integer widening".to_string(),
            _ => "swresample integer widening".to_string(),
        }
    } else {
        match tool {
            "SoX" => "SoX output quantization".to_string(),
            "SSRC" => "SSRC quantization".to_string(),
            _ => "swresample quantization".to_string(),
        }
    }
}

fn bit_depth_conversion_log_line(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
    tracks: &[&TrackRecord],
    applies: bool,
) -> String {
    if settings.target_format.is_dsd() {
        return "no (PCM bit depth not applicable — DSD target)".to_string();
    }
    if settings.target_format.is_lossy() {
        return "no (not applicable — lossy encoder has no fixed PCM output depth)".to_string();
    }
    if !applies {
        return "no (source depth preserved)".to_string();
    }
    format!(
        "yes ({}, {})",
        bit_depth_transition_log_label(source, settings),
        bit_depth_processing_label(source, settings, tracks)
    )
}

fn source_has_float_target(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> bool {
    source.tracks.iter().any(|track| {
        resolved_target_pcm_depth(track, settings.target_bit_depth)
            .or_else(|| source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth))
            .is_some_and(PcmBitDepth::is_float)
    })
}

fn source_has_int32_target(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> bool {
    source.tracks.iter().any(|track| {
        resolved_target_pcm_depth(track, settings.target_bit_depth)
            .or_else(|| source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth))
            == Some(PcmBitDepth::Int32)
    })
}

fn track_depth_reduction_requires_dither(
    track: &PreparedTrack,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> bool {
    let target_depth = resolved_target_pcm_depth(track, settings.target_bit_depth)
        .or_else(|| source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth));
    let Some(target) = target_depth else {
        return false;
    };
    if !matches!(
        target,
        tonepoet_pipeline::PcmBitDepth::Int8
            | tonepoet_pipeline::PcmBitDepth::Int16
            | tonepoet_pipeline::PcmBitDepth::Int24
    ) {
        return false;
    }
    super::plan_bridge::resolve_dither_source_pcm_depth(track)
        .map(|source| target.bits() < source.bits())
        .unwrap_or(true)
}

fn source_depth_reduction_requires_dither(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> bool {
    source
        .tracks
        .iter()
        .any(|track| track_depth_reduction_requires_dither(track, settings))
}

fn dither_log_line(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
    tracks: &[&TrackRecord],
    applies: bool,
) -> String {
    if tonepoet_pipeline::selects_reference_dsd_to_pcm(settings, source_is_dsd(source)) {
        if source_has_float_target(source, settings) {
            return "no (float terminal; Reference policy)".to_string();
        }
        if !tracks.is_empty() && !applies {
            return "requested (TPDF, Reference policy) — not applied (executed command did not emit the policy dither stage)"
                .to_string();
        }
        return "yes (TPDF, sox_ng, Reference policy)".to_string();
    }
    if applies {
        return format!("yes ({})", applied_dither_description(source, tracks, settings));
    }
    if settings.dither_type == DitherType::None {
        return "no (not requested)".to_string();
    }
    let requested = dither_type_label(settings.dither_type);
    if settings.target_format.is_dsd() {
        return format!(
            "requested ({requested}) — not applied (PCM dither is not applicable to a DSD target)"
        );
    }
    if settings.target_format.is_lossy() {
        return format!(
            "requested ({requested}) — not applied (lossy encoder has no fixed PCM target depth)"
        );
    }
    if source_has_float_target(source, settings) {
        return format!(
            "requested ({requested}) — not applied (float targets are not dithered)"
        );
    }
    if source_has_int32_target(source, settings) {
        if !settings.dither_explicit {
            return format!(
                "requested ({requested}) — not applied (32-bit default gate; selection was not explicit)"
            );
        }
        let tool = processing_tool_label(tracks, settings);
        if tool == "SSRC" {
            return format!(
                "requested ({requested}) — not applied (SSRC has no 32-bit dither stage)"
            );
        }
        if tool == "SoX" {
            return format!(
                "requested ({requested}) — not applied (ordinary SoX Int32 dither is not behavior-qualified)"
            );
        }
        if tool == "ffmpeg aresample"
            && tonepoet_pipeline::mapping::soxr_dither_method(settings.dither_type).is_none()
        {
            return format!(
                "requested ({requested}) — not applied (not supported by the ffmpeg/soxr resampler)"
            );
        }
        return format!(
            "requested ({requested}) — not applied (executed command did not emit a dither stage)"
        );
    }
    if source_depth_reduction_requires_dither(source, settings) {
        return format!(
            "requested ({requested}) — not applied (executed command did not emit a dither stage)"
        );
    }
    format!(
        "requested ({requested}) — not applied (not needed — no bit-depth reduction)"
    )
}

fn append_target_format_settings(log: &mut String, settings: &tonepoet_pipeline::PipelineSettings) {
    match &settings.target_format {
        PlannerAudioFormat::Flac => {
            push_kv_line(log, "FLAC compression", settings.flac.compression_level.to_string());
        }
        PlannerAudioFormat::Mp3 => {
            push_kv_line(log, "MP3 mode", mp3_mode_label(settings.mp3.mode));
            push_kv_line(log, "MP3 bitrate", format!("{} kbps", settings.mp3.bitrate_kbps));
            match settings.mp3.mode {
                Mp3Mode::Vbr => push_kv_line(log, "MP3 VBR quality", settings.mp3.vbr_quality.to_string()),
                Mp3Mode::Cbr | Mp3Mode::Abr => {}
            }
        }
        PlannerAudioFormat::Aac => {
            push_kv_line(log, "AAC profile", aac_profile_label(settings.aac.profile));
            push_kv_line(log, "AAC bitrate", format!("{} kbps", settings.aac.bitrate_kbps));
        }
        PlannerAudioFormat::Opus => {
            push_kv_line(log, "Opus bitrate", format!("{} kbps", settings.opus.bitrate_kbps));
            push_kv_line(log, "Opus application", opus_content_type_label(settings.opus.content_type));
            push_kv_line(log, "Opus complexity", settings.opus.complexity.to_string());
        }
        PlannerAudioFormat::WavPack => {
            push_kv_line(log, "WavPack mode", wavpack_mode_label(settings.wavpack.mode));
            if settings.wavpack.hybrid {
                push_kv_line(
                    log,
                    "WavPack hybrid bitrate",
                    format!("{} kbps/ch", settings.wavpack.hybrid_bitrate_kbps),
                );
                push_kv_line(
                    log,
                    "WavPack correction file",
                    yes_no(settings.wavpack.correction_file),
                );
            }
        }
        PlannerAudioFormat::Alac
        | PlannerAudioFormat::Wav
        | PlannerAudioFormat::Aiff
        | PlannerAudioFormat::Dsf
        | PlannerAudioFormat::Dff
        | PlannerAudioFormat::Dts
        | PlannerAudioFormat::Ac3
        | PlannerAudioFormat::Custom { .. } => {}
    }
}

fn append_resampler_settings(log: &mut String, settings: &tonepoet_pipeline::PipelineSettings) {
    match preferred_resampler_family(settings) {
        ResamplerFamily::Ssrc => append_ssrc_settings(log, settings),
        ResamplerFamily::Sox => append_sox_resampler_settings(log, settings),
        ResamplerFamily::Soxr => append_soxr_resampler_settings(log, settings),
        ResamplerFamily::Auto => {
            push_kv_line(log, "Resample quality", resample_quality_label(settings.resample_quality));
            push_kv_line(log, "Nyquist transition", nyquist_transition_label(settings.nyquist_transition));
            append_non_default_resampler_overrides(log, settings);
        }
    }
}

fn append_ssrc_settings(log: &mut String, settings: &tonepoet_pipeline::PipelineSettings) {
    let ssrc = settings.ssrc;
    push_kv_line(log, "SSRC profile", ssrc_profile_label(ssrc.profile, settings.resample_quality, ssrc.insane_mode));
    if let Some(attenuation) = ssrc.attenuation_db {
        push_kv_line(log, "SSRC attenuation", format!("{} dB", decimal_label(attenuation)));
    }
    push_kv_line(log, "SSRC minimum phase", yes_no(ssrc.min_phase));
    if let Some(dither_id) = ssrc.dither_id {
        push_kv_line(log, "SSRC dither ID", dither_id.to_string());
    }
    if let Some(pdf_type) = ssrc.pdf_type {
        push_kv_line(log, "SSRC PDF type", ssrc_pdf_type_label(pdf_type));
    }
}

fn append_sox_resampler_settings(log: &mut String, settings: &tonepoet_pipeline::PipelineSettings) {
    let sox = settings.sox_resampler;
    push_kv_line(log, "SoX quality", resample_quality_label(settings.resample_quality));
    push_kv_line(log, "SoX Nyquist transition", nyquist_transition_label(settings.nyquist_transition));
    if sox.chebyshev {
        push_kv_line(log, "SoX steep/Chebyshev", "yes");
    }
    if let Some(bandwidth) = sox.bandwidth_pct {
        push_kv_line(log, "SoX bandwidth", format!("{}%", decimal_label(bandwidth)));
    }
    if let Some(phase) = sox.phase {
        push_kv_line(log, "SoX phase response", phase.to_string());
    }
    if sox.allow_aliasing {
        push_kv_line(log, "SoX allow aliasing", "yes");
    }
    append_sox_sinc_settings(log, settings);
}

fn append_soxr_resampler_settings(log: &mut String, settings: &tonepoet_pipeline::PipelineSettings) {
    let soxr = settings.soxr_resampler;
    push_kv_line(
        log,
        "Soxr quality preset",
        resample_quality_label(settings.resample_quality),
    );
    if let Some(phase) = soxr.phase {
        push_kv_line(log, "Soxr phase response", phase.to_string());
    }
    if let Some(cutoff) = soxr.cutoff {
        push_kv_line(log, "Soxr cutoff override", decimal_label(cutoff));
    }
    if soxr.chebyshev {
        push_kv_line(log, "Soxr Chebyshev", "yes");
    }
}

fn append_non_default_resampler_overrides(log: &mut String, settings: &tonepoet_pipeline::PipelineSettings) {
    if settings.ssrc.force
        || settings.ssrc.insane_mode
        || settings.ssrc.profile.is_some()
        || settings.ssrc.attenuation_db.is_some()
        || settings.ssrc.min_phase
        || settings.ssrc.dither_id.is_some()
        || settings.ssrc.pdf_type.is_some()
    {
        append_ssrc_settings(log, settings);
    }
    if settings.sox_resampler.chebyshev
        || settings.sox_resampler.bandwidth_pct.is_some()
        || settings.sox_resampler.phase.is_some()
        || settings.sox_resampler.allow_aliasing
        || settings.sox_resampler.sinc_taps.is_some()
        || settings.sox_resampler.sinc_attenuation_db.is_some()
        || settings.sox_resampler.sinc_passband_hz.is_some()
        || settings.sox_resampler.sinc_transition_hz.is_some()
        || settings.sox_resampler.sinc_kaiser_beta.is_some()
        || settings.sox_resampler.sinc_phase.is_some()
    {
        append_sox_resampler_settings(log, settings);
    }
    if settings.soxr_resampler.chebyshev
        || settings.soxr_resampler.cutoff.is_some()
        || settings.soxr_resampler.phase.is_some()
    {
        append_soxr_resampler_settings(log, settings);
    }
}

fn append_sox_sinc_settings(log: &mut String, settings: &tonepoet_pipeline::PipelineSettings) {
    let sox = settings.sox_resampler;
    if sox.sinc_taps.is_none()
        && sox.sinc_attenuation_db.is_none()
        && sox.sinc_passband_hz.is_none()
        && sox.sinc_transition_hz.is_none()
        && sox.sinc_kaiser_beta.is_none()
        && sox.sinc_phase.is_none()
    {
        return;
    }
    if let Some(taps) = sox.sinc_taps {
        push_kv_line(log, "SoX sinc taps", taps.to_string());
    }
    if let Some(attenuation) = sox.sinc_attenuation_db {
        push_kv_line(log, "SoX sinc attenuation", format!("{attenuation} dB"));
    }
    if let Some(passband) = sox.sinc_passband_hz {
        push_kv_line(log, "SoX sinc passband", format!("{} Hz", decimal_label(passband)));
    }
    if let Some(transition) = sox.sinc_transition_hz {
        push_kv_line(log, "SoX sinc transition", format!("{} Hz", decimal_label(transition)));
    }
    if let Some(beta) = sox.sinc_kaiser_beta {
        push_kv_line(log, "SoX sinc Kaiser beta", decimal_label(beta));
    }
    if let Some(phase) = sox.sinc_phase {
        push_kv_line(log, "SoX sinc phase", sox_sinc_phase_label(phase));
    }
}

fn append_dsd_settings(
    log: &mut String,
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) {
    if source_is_dsd(source) && !settings.target_format.is_dsd() {
        if let Some(legacy) = settings.dsd.legacy_behavior() {
            push_kv_line(log, "DSD path", "legacy-v1 compatibility");
            push_kv_line(log, "DSD gain mode", dsd_gain_mode_label(legacy.gain_mode));
            if legacy.gain_mode == tonepoet_pipeline::DsdToPcmGainMode::Auto {
                push_kv_line(
                    log,
                    "DSD auto gain margin",
                    format!("{} dB", decimal_label(legacy.auto_gain_margin_db)),
                );
            }
            if legacy.gain_mode == tonepoet_pipeline::DsdToPcmGainMode::Manual {
                if let Some(gain) = legacy.gain_db {
                    push_kv_line(log, "DSD manual gain", format!("{} dB", decimal_label(gain)));
                }
            }
            push_kv_line(
                log,
                "DSD→PCM lowpass method",
                dsd_lowpass_method_label(legacy.lowpass),
            );
        } else {
            let native = settings.dsd.from_dsd;
            push_kv_line(
                log,
                "DSD path",
                match native.pathway {
                    tonepoet_pipeline::DsdSourcePathway::Reference => "reference",
                    tonepoet_pipeline::DsdSourcePathway::Manual => "manual (not available)",
                },
            );
            push_kv_line(
                log,
                "DSD profile",
                match native.profile {
                    tonepoet_pipeline::DsdReconstructionSelection::Reference => "reference",
                    tonepoet_pipeline::DsdReconstructionSelection::Wideband => "wideband",
                },
            );
            push_kv_line(
                log,
                "DSD gain mode",
                match native.gain_mode {
                    tonepoet_pipeline::DsdSourceGainMode::Reference => "reference",
                    tonepoet_pipeline::DsdSourceGainMode::NativeLevel => "native",
                    tonepoet_pipeline::DsdSourceGainMode::Fixed => "fixed",
                    tonepoet_pipeline::DsdSourceGainMode::NormalizePeak => "normalize",
                },
            );
            if native.gain_mode == tonepoet_pipeline::DsdSourceGainMode::Fixed {
                if let Some(gain) = native.fixed_gain_db {
                    push_kv_line(log, "DSD fixed gain", format!("{} dB", gain));
                }
            }
            if native.gain_mode == tonepoet_pipeline::DsdSourceGainMode::NormalizePeak {
                push_kv_line(
                    log,
                    "DSD normalize target",
                    format!("{} dBFS", native.normalize_peak_target_dbfs),
                );
            }
            push_kv_line(
                log,
                "DSD Reference policy",
                tonepoet_pipeline::DSD_REFERENCE_POLICY_V1_KEY,
            );
        }
    }

    if settings.target_format.is_dsd() {
        push_kv_line(
            log,
            "PCM→DSD filter preset",
            format!("{:?}", settings.dsd.pcm_to_dsd.filter),
        );
    }
}

fn planned_pipeline_label(commands: &[CommandRecord]) -> Option<String> {
    if commands.is_empty() {
        return None;
    }
    let parts = commands
        .iter()
        .map(|command| {
            command
                .description
                .as_deref()
                .map(str::trim)
                .filter(|description| !description.is_empty())
                .map(ToOwned::to_owned)
                .unwrap_or_else(|| command_line_label(command))
        })
        .collect::<Vec<_>>();
    Some(parts.join(" → "))
}

fn passthrough_pipeline_label(
    record: &TrackRecord,
    prepared: Option<&PreparedTrack>,
    req: &PipelineRequest,
) -> Option<String> {
    if !record.commands.is_empty() || !matches!(record.outcome, TrackOutcome::Ok) {
        return None;
    }

    let track = prepared?;
    if source_audio_matches_target_for_passthrough(track, &req.settings) {
        Some("passthrough copy".to_string())
    } else {
        None
    }
}

fn source_audio_matches_target_for_passthrough(
    track: &PreparedTrack,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> bool {
    if settings.force_encode || !source_track_format_matches_target(track, &settings.target_format) {
        return false;
    }

    let Some(target_rate) = resolved_target_rate_hz(track, settings) else {
        return false;
    };
    if track.scalar_sample_rate() != Some(target_rate) {
        return false;
    }

    if settings.target_format.is_dsd() {
        return true;
    }

    match settings.target_bit_depth {
        BitDepthTarget::Source => true,
        BitDepthTarget::Pcm(target_depth) => {
            super::plan_bridge::resolve_source_pcm_depth(track) == Some(target_depth)
        }
    }
}

fn source_track_format_matches_target(track: &PreparedTrack, target: &PlannerAudioFormat) -> bool {
    let extension = source_ref_extension(&track.source_ref)
        .unwrap_or_default()
        .trim_start_matches('.')
        .to_ascii_lowercase();

    match target {
        PlannerAudioFormat::Flac => extension == "flac",
        PlannerAudioFormat::Mp3 => extension == "mp3",
        PlannerAudioFormat::Aac | PlannerAudioFormat::Alac => false,
        PlannerAudioFormat::Opus => matches!(extension.as_str(), "opus" | "ogg"),
        PlannerAudioFormat::WavPack => extension == "wv",
        PlannerAudioFormat::Wav => matches!(extension.as_str(), "wav" | "wave" | "rf64"),
        PlannerAudioFormat::Aiff => matches!(extension.as_str(), "aiff" | "aif"),
        PlannerAudioFormat::Dsf => extension == "dsf",
        PlannerAudioFormat::Dff => extension == "dff",
        PlannerAudioFormat::Dts => extension == "dts",
        PlannerAudioFormat::Ac3 => extension == "ac3",
        PlannerAudioFormat::Custom { .. } => false,
    }
}

fn metadata_satisfaction_label(
    artifact: Option<&TrackArtifact>,
    prepared: Option<&PreparedTrack>,
    source: Option<&PreparedSource>,
    metadata_stage: StageRequirement,
    metadata_stage_result: Option<&StageOutcome>,
) -> Option<String> {
    let artifact = artifact?;
    let satisfied = artifact.metadata_satisfaction;
    let required = artifact.metadata_required;

    let m4a_freeform_required = prepared
        .zip(source)
        .is_some_and(|(track, source)| {
            !m4a_freeform_tag_pairs_for_file(
                &artifact.staged_path,
                &track.metadata,
                &source.album_metadata,
            )
            .is_empty()
        });
    if m4a_freeform_required {
        let prefix = if satisfied.source_tags_transferred {
            "planner transferred native source tags; "
        } else {
            ""
        };
        let outcome = match metadata_stage {
            StageRequirement::Disabled => {
                "non-native m4a tags were not applied because the metadata stage is disabled"
                    .to_string()
            }
            StageRequirement::Enabled => match metadata_stage_result {
                Some(StageOutcome::Ok) => {
                    "metadata stage applied non-native m4a tags via AtomicParsley after artwork"
                        .to_string()
                }
                Some(StageOutcome::NotRequested) => {
                    "non-native m4a tags were not applied because the metadata stage was not requested"
                        .to_string()
                }
                Some(StageOutcome::Skipped) => {
                    "non-native m4a tags were not applied because the metadata stage was skipped"
                        .to_string()
                }
                Some(StageOutcome::SkippedWithReason(reason)) => format!(
                    "non-native m4a tags were not applied because the metadata stage was skipped: {}",
                    escape_log_value(reason)
                ),
                Some(StageOutcome::Failed(reason)) => format!(
                    "non-native m4a tag application failed: {}",
                    escape_log_value(reason)
                ),
                None => "non-native m4a tag application outcome is unavailable".to_string(),
            },
        };
        return Some(format!("{prefix}{outcome}"));
    }

    if !satisfied.any() || satisfied.satisfies(required) {
        return None;
    }

    let mut parts = metadata_satisfied_parts(satisfied);
    parts.extend(metadata_remaining_requirement_parts(
        metadata_stage,
        metadata_stage_result,
        satisfied,
        required,
    ));
    if parts.is_empty() {
        None
    } else {
        Some(parts.join("; "))
    }
}

fn metadata_satisfied_parts(value: PlannedMetadataSatisfaction) -> Vec<String> {
    let mut parts = Vec::new();
    if value.source_tags_transferred {
        parts.push("planner transferred source tags".to_string());
    }
    if value.artwork_transferred {
        parts.push("planner transferred artwork".to_string());
    }
    if value.source_audio_md5_written {
        parts.push("planner wrote source audio MD5".to_string());
    }
    if value.authoritative_tags_applied {
        parts.push("authoritative materializer tags already applied".to_string());
    }
    parts
}

fn metadata_remaining_requirement_parts(
    metadata_stage: StageRequirement,
    metadata_stage_result: Option<&StageOutcome>,
    satisfied: PlannedMetadataSatisfaction,
    required: PlannedMetadataSatisfaction,
) -> Vec<String> {
    let remaining = PlannedMetadataSatisfaction {
        source_tags_transferred: required.source_tags_transferred && !satisfied.source_tags_transferred,
        artwork_transferred: required.artwork_transferred && !satisfied.artwork_transferred,
        source_audio_md5_written: required.source_audio_md5_written && !satisfied.source_audio_md5_written,
        authoritative_tags_applied: required.authoritative_tags_applied && !satisfied.authoritative_tags_applied,
    };
    if !remaining.any() {
        return Vec::new();
    }

    let dimensions = metadata_dimension_labels(remaining).join(", ");
    let status = match metadata_stage {
        StageRequirement::Disabled => "metadata stage disabled".to_string(),
        StageRequirement::Enabled => match metadata_stage_result {
            Some(StageOutcome::Ok) => {
                "metadata stage completed; per-track writes not recorded".to_string()
            }
            Some(StageOutcome::NotRequested) => "metadata stage not requested".to_string(),
            Some(StageOutcome::Skipped) => "metadata stage skipped".to_string(),
            Some(StageOutcome::SkippedWithReason(reason)) => {
                format!("metadata stage skipped: {}", escape_log_value(reason))
            }
            Some(StageOutcome::Failed(reason)) => {
                format!("metadata stage failed: {}", escape_log_value(reason))
            }
            None => "metadata stage outcome unavailable".to_string(),
        },
    };

    vec![format!("remaining required metadata: {dimensions} ({status})")]
}

fn metadata_dimension_labels(value: PlannedMetadataSatisfaction) -> Vec<&'static str> {
    let mut labels = Vec::new();
    if value.source_tags_transferred {
        labels.push("source tags");
    }
    if value.artwork_transferred {
        labels.push("artwork");
    }
    if value.source_audio_md5_written {
        labels.push("source audio MD5");
    }
    if value.authoritative_tags_applied {
        labels.push("authoritative materializer tags");
    }
    labels
}

fn per_track_dither_disclosure(
    track: &PreparedTrack,
    record: &TrackRecord,
    req: &PipelineRequest,
) -> Option<String> {
    let settings = &req.settings;
    if settings.dither_type == DitherType::None
        || tonepoet_pipeline::selects_reference_dsd_to_pcm(
            settings,
            track.source_audio.coding == Some(SourceAudioCoding::Dsd),
        )
    {
        return None;
    }

    let target_depth = resolved_target_pcm_depth(track, settings.target_bit_depth)
        .or_else(|| source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth));
    if command_records_prove_dither_for_track(track, record, settings) {
        return None;
    }

    let requested = dither_type_label(settings.dither_type);
    if settings.target_format.is_dsd() {
        return Some(format!(
            "Dither requested ({requested}) — not applied (PCM dither is not applicable to a DSD target)"
        ));
    }
    if settings.target_format.is_lossy() {
        return Some(format!(
            "Dither requested ({requested}) — not applied (lossy encoder has no fixed PCM target depth)"
        ));
    }

    let reason = match target_depth {
        Some(depth) if depth.is_float() => "float targets are not dithered",
        Some(tonepoet_pipeline::PcmBitDepth::Int32) if !settings.dither_explicit => {
            "32-bit default gate; selection was not explicit"
        }
        Some(tonepoet_pipeline::PcmBitDepth::Int32)
            if command_records_use_tool(&[record], ToolBinary::Ssrc) =>
        {
            "SSRC has no 32-bit dither stage"
        }
        Some(tonepoet_pipeline::PcmBitDepth::Int32)
            if command_records_use_tool(&[record], ToolBinary::Sox) =>
        {
            "ordinary SoX Int32 dither is not behavior-qualified"
        }
        Some(tonepoet_pipeline::PcmBitDepth::Int32)
            if command_records_use_tool(&[record], ToolBinary::Ffmpeg)
                && tonepoet_pipeline::mapping::soxr_dither_method(settings.dither_type).is_none() =>
        {
            "not supported by the ffmpeg/soxr resampler"
        }
        Some(tonepoet_pipeline::PcmBitDepth::Int32) if settings.dither_explicit => {
            "executed command did not emit a dither stage"
        }
        _ if track_depth_reduction_requires_dither(track, settings) => {
            "executed command did not emit a dither stage"
        }
        _ => "not needed — no bit-depth reduction",
    };
    Some(format!(
        "Dither requested ({requested}) — not applied ({reason})"
    ))
}

fn conversion_summary(
    track: &PreparedTrack,
    req: &PipelineRequest,
    verified_output_bit_depth: Option<tonepoet_pipeline::PcmBitDepth>,
    actual_dither_applied: Option<bool>,
) -> String {
    let source_rate = track.scalar_sample_rate();
    let source_depth_bits = track.bit_depth.or(track.source_audio.bit_depth);
    let source_pcm_depth = super::plan_bridge::resolve_source_pcm_depth(track);
    let source_depth = source_pcm_depth
        .map(tonepoet_pipeline::PcmBitDepth::bits)
        .or_else(|| source_depth_bits.filter(|bits| *bits < 100));
    let source_format = source_track_format_label(track);
    let target_rate = resolved_target_rate_hz(track, &req.settings).or(source_rate);
    let defaulted_source_target = source_default_pcm_depth_for_track(track, &req.settings);
    let planned_target_pcm_depth = if req.settings.target_format.is_dsd() {
        None
    } else {
        resolved_target_pcm_depth(track, req.settings.target_bit_depth)
            .or(defaulted_source_target.map(|(depth, _)| depth))
    };
    let planned_target_depth = planned_target_pcm_depth.map(tonepoet_pipeline::PcmBitDepth::bits);
    let target_depth = verified_output_bit_depth
        .map(tonepoet_pipeline::PcmBitDepth::bits)
        .or(planned_target_depth);
    let planned_float_target = planned_target_pcm_depth.filter(|depth| depth.is_float());
    let output_depth_unverified = verified_output_bit_depth.is_none()
        && req.settings.target_format.is_pcm_lossless();
    let target_stream = verified_output_bit_depth
        .or(planned_float_target)
        .map(|depth| measured_target_stream_description(depth, target_rate))
        .unwrap_or_else(|| target_stream_description(track, target_depth, target_rate, &req.settings));
    let target_stream = if let Some((depth, reason)) = defaulted_source_target {
        if verified_output_bit_depth.is_some() {
            // The output WAS measured: keep the measured description and
            // note the default as the plan choice it is — the label must
            // accompany the verified fact, never replace it.
            format!("{target_stream} ({}-bit default for {reason} source)", depth.bits())
        } else {
            let rate = target_rate
                .map(|hz| format!(" at {}", format_sample_rate(hz)))
                .unwrap_or_default();
            format!(
                "requested {}-bit (default for {reason} source){rate}",
                depth.bits()
            )
        }
    } else if output_depth_unverified {
        format!("requested {target_stream}")
    } else {
        target_stream
    };
    let mut summary = format!(
        "{} {} → {} {}",
        source_pcm_depth
            .map(|depth| measured_target_stream_description(depth, source_rate))
            .unwrap_or_else(|| stream_description(source_depth, source_rate, Some(&source_format))),
        source_format,
        target_stream,
        req.settings.target_format.display_name(),
    );
    if output_depth_unverified {
        summary.push_str(" [output depth unverified]");
    }
    if req.settings.target_bit_depth == BitDepthTarget::Source
        && req.settings.target_format.is_pcm_lossless()
        && matches!(track.bit_depth.or(track.source_audio.bit_depth), Some(20))
    {
        // Only PCM-lossless targets actually store a 24-bit container; lossy
        // targets have no stored width and must not carry this claim.
        summary.push_str(" [source is 20-bit; stored as 24-bit]");
    }
    let mut transforms = Vec::new();
    if let (Some(source_rate), Some(target_rate)) = (source_rate, target_rate) {
        if source_rate != target_rate {
            transforms.push(format!("{} resampling", preferred_resampler_label(&req.settings)));
        }
    }
    let dither_applied = actual_dither_applied.unwrap_or_else(|| {
        dither_applies(
            super::plan_bridge::resolve_dither_source_pcm_depth(track),
            planned_target_pcm_depth,
            req.settings.dither_type,
            req.settings.dither_explicit,
            preferred_resampler_family(&req.settings),
        )
    });
    if dither_applied {
        let label = if req.settings.dither_type == DitherType::None {
            "command-selected".to_string()
        } else {
            dither_type_label(req.settings.dither_type).to_string()
        };
        transforms.push(format!("{label} dither"));
    } else if actual_dither_applied == Some(false)
        && req.settings.dither_type != DitherType::None
        && !tonepoet_pipeline::selects_reference_dsd_to_pcm(
            &req.settings,
            track.source_audio.coding == Some(SourceAudioCoding::Dsd),
        )
    {
        transforms.push("dither requested but not applied".to_string());
    }
    if !transforms.is_empty() {
        summary.push_str(&format!(" ({})", transforms.join(", ")));
    }
    summary
}

fn stream_description(
    bit_depth: Option<u32>,
    sample_rate: Option<u32>,
    dsd_format_hint: Option<&str>,
) -> String {
    if dsd_format_hint == Some("DSD") {
        if let Some(rate) = sample_rate.and_then(DsdRate::from_hz) {
            return dsd_rate_label(rate).to_string();
        }
    }
    let rate = sample_rate
        .map(format_sample_rate)
        .unwrap_or_else(|| "unknown rate".to_string());
    match bit_depth {
        Some(bits) => format!("{bits}-bit/{rate}"),
        None => rate,
    }
}

fn target_stream_description(
    track: &PreparedTrack,
    bit_depth: Option<u32>,
    sample_rate: Option<u32>,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> String {
    if settings.target_format.is_dsd() {
        let target_dsd_rate = match settings.target_sample_rate {
            RateTarget::Dsd(rate) => Some(rate),
            RateTarget::Source => source_track_dsd_rate(track),
            RateTarget::PcmHz(_) => None,
        }
        .or_else(|| sample_rate.and_then(DsdRate::from_hz));
        if let Some(rate) = target_dsd_rate {
            return dsd_rate_label(rate).to_string();
        }
    }
    stream_description(bit_depth, sample_rate, None)
}

fn measured_target_stream_description(
    depth: tonepoet_pipeline::PcmBitDepth,
    sample_rate: Option<u32>,
) -> String {
    let rate = sample_rate
        .map(format_sample_rate)
        .unwrap_or_else(|| "unknown rate".to_string());
    match depth {
        tonepoet_pipeline::PcmBitDepth::Float32 | tonepoet_pipeline::PcmBitDepth::Float64 => {
            format!("{}/{rate}", pcm_bit_depth_label(depth))
        }
        _ => format!("{}-bit/{rate}", depth.bits()),
    }
}

fn resampling_applies_for_source(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> bool {
    source.tracks.iter().any(|track| {
        match (track.scalar_sample_rate(), resolved_target_rate_hz(track, settings)) {
            (Some(source_rate), Some(target_rate)) => source_rate != target_rate,
            _ => false,
        }
    })
}

fn bit_depth_change_applies_for_source(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> bool {
    if settings.target_format.is_dsd() {
        return false;
    }
    source.tracks.iter().any(|track| {
        let target_depth = resolved_target_pcm_depth(track, settings.target_bit_depth)
            .or_else(|| source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth));
        let Some(target_depth) = target_depth else {
            return false;
        };
        match super::plan_bridge::resolve_source_pcm_depth(track) {
            Some(source_depth) => source_depth != target_depth,
            None => match track
                .source_audio
                .coding
                .unwrap_or(SourceAudioCoding::Unknown)
            {
                SourceAudioCoding::Dsd | SourceAudioCoding::Lossy => true,
                SourceAudioCoding::Pcm
                | SourceAudioCoding::DvdaUnknown
                | SourceAudioCoding::Unknown => {
                    settings.target_bit_depth != BitDepthTarget::Source
                }
            },
        }
    })
}

fn dithering_applies_for_source(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
    tracks: &[&TrackRecord],
) -> bool {
    if settings.target_format.is_dsd() {
        return false;
    }
    if !tracks.is_empty() {
        return command_records_prove_dither_for_source(source, settings, tracks);
    }
    if source.tracks.iter().any(|track| {
        tonepoet_pipeline::selects_reference_dsd_to_pcm(
            settings,
            track.source_audio.coding == Some(SourceAudioCoding::Dsd),
        )
    }) {
        return !source_has_float_target(source, settings);
    }
    source.tracks.iter().any(|track| {
        dither_applies(
            super::plan_bridge::resolve_dither_source_pcm_depth(track),
            resolved_target_pcm_depth(track, settings.target_bit_depth)
                .or_else(|| source_default_pcm_depth_for_track(track, settings).map(|(depth, _)| depth)),
            settings.dither_type,
            settings.dither_explicit,
            preferred_resampler_family(settings),
        )
    })
}

fn dither_applies(
    source_depth: Option<tonepoet_pipeline::PcmBitDepth>,
    target_depth: Option<tonepoet_pipeline::PcmBitDepth>,
    dither: DitherType,
    dither_explicit: bool,
    resampler: ResamplerFamily,
) -> bool {
    if dither == DitherType::None {
        return false;
    }
    match target_depth {
        Some(
            target @ (tonepoet_pipeline::PcmBitDepth::Int8
            | tonepoet_pipeline::PcmBitDepth::Int16
            | tonepoet_pipeline::PcmBitDepth::Int24),
        ) => source_depth
            .map(|source| target.bits() < source.bits())
            .unwrap_or(true),
        Some(tonepoet_pipeline::PcmBitDepth::Int32) => {
            // Ordinary SoX Int32 dither is not behavior-qualified: supported
            // installations may accept the effect while producing unchanged
            // samples. Only the mapped ffmpeg/soxr path may claim application
            // without executed command records. Reference DSD is handled by
            // its separate qualified-policy branch above.
            dither_explicit
                && matches!(resampler, ResamplerFamily::Soxr | ResamplerFamily::Auto)
                && tonepoet_pipeline::mapping::soxr_dither_method(dither).is_some()
        }
        Some(
            tonepoet_pipeline::PcmBitDepth::Float32
            | tonepoet_pipeline::PcmBitDepth::Float64,
        )
        | None => false,
    }
}

fn source_default_pcm_depth_for_track(
    track: &PreparedTrack,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> Option<(tonepoet_pipeline::PcmBitDepth, &'static str)> {
    if settings.target_bit_depth != BitDepthTarget::Source
        || !settings.target_format.is_pcm_lossless()
    {
        return None;
    }
    match track.source_audio.coding.unwrap_or(SourceAudioCoding::Unknown) {
        SourceAudioCoding::Dsd => Some((
            tonepoet_pipeline::default_pcm_depth_for_format(&settings.target_format),
            "DSD",
        )),
        SourceAudioCoding::Lossy => Some((
            tonepoet_pipeline::default_pcm_depth_for_format(&settings.target_format),
            "lossy",
        )),
        SourceAudioCoding::Pcm
        | SourceAudioCoding::DvdaUnknown
        | SourceAudioCoding::Unknown => None,
    }
}

fn resolved_target_rate_hz(
    track: &PreparedTrack,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> Option<u32> {
    match settings.target_sample_rate {
        RateTarget::Source if !settings.target_format.is_dsd() => source_track_dsd_rate(track)
            .map(DsdRate::default_pcm_target_hz)
            .or_else(|| track.scalar_sample_rate()),
        RateTarget::Source => track.scalar_sample_rate(),
        RateTarget::PcmHz(hz) => Some(hz),
        RateTarget::Dsd(rate) => Some(rate.hz()),
    }
}

fn resolved_target_pcm_depth(
    track: &PreparedTrack,
    target: BitDepthTarget,
) -> Option<tonepoet_pipeline::PcmBitDepth> {
    match target {
        BitDepthTarget::Source => super::plan_bridge::resolve_source_pcm_depth(track),
        BitDepthTarget::Pcm(depth) => Some(depth),
    }
}

fn resolved_target_bit_depth(track: &PreparedTrack, target: BitDepthTarget) -> Option<u32> {
    resolved_target_pcm_depth(track, target).map(tonepoet_pipeline::PcmBitDepth::bits)
}

fn source_is_dsd(source: &PreparedSource) -> bool {
    source.kind == SourceKind::SacdIso
        || source
            .tracks
            .iter()
            .any(|track| source_track_dsd_rate(track).is_some())
}

fn source_track_dsd_rate(track: &PreparedTrack) -> Option<DsdRate> {
    let rate = DsdRate::from_hz(track.scalar_sample_rate()?)?;
    if track.bit_depth.is_none() || matches!(track.source_ref, TrackSourceRef::SacdTrack { .. }) {
        Some(rate)
    } else {
        None
    }
}

fn source_audio_description(track: &PreparedTrack) -> String {
    if !track.source_audio.channel_groups.is_empty() {
        let coding = track
            .source_audio
            .coding
            .map(source_audio_coding_label)
            .unwrap_or("source");
        let groups = track
            .source_audio
            .channel_groups
            .iter()
            .map(channel_group_description)
            .collect::<Vec<_>>()
            .join("; ");
        let mut label = format!("{coding} [{groups}]");
        if let Some(expected_samples) = track.expected_samples {
            label.push_str(&format!(", {expected_samples} expected samples"));
        }
        return label;
    }

    let rate = track
        .scalar_sample_rate()
        .map(format_sample_rate)
        .unwrap_or_else(|| "unknown rate".to_string());
    let mut parts = vec![rate];
    if let Some(depth) = super::plan_bridge::resolve_source_pcm_depth(track) {
        parts.push(pcm_bit_depth_label(depth).to_string());
    } else {
        parts.push("unknown depth".to_string());
    }
    let mut label = parts.join(", ");
    if let Some(expected_samples) = track.expected_samples {
        label.push_str(&format!(", {expected_samples} expected samples"));
    }
    label
}

fn source_audio_coding_label(coding: SourceAudioCoding) -> &'static str {
    match coding {
        SourceAudioCoding::Pcm => "PCM",
        SourceAudioCoding::Dsd => "DSD",
        SourceAudioCoding::Lossy => "lossy",
        SourceAudioCoding::DvdaUnknown => "DVD-Audio",
        SourceAudioCoding::Unknown => "source",
    }
}

fn channel_group_description(group: &ChannelGroupDescriptor) -> String {
    let rate = group
        .sample_rate
        .map(format_sample_rate)
        .unwrap_or_else(|| "unknown rate".to_string());
    let depth = group
        .bit_depth
        .map(|bits| format!("{bits}-bit"))
        .unwrap_or_else(|| "unknown depth".to_string());
    let channels = group
        .assignment
        .as_deref()
        .map(str::to_string)
        .or_else(|| group.channels.map(|count| format!("{count}ch")))
        .unwrap_or_else(|| "unknown channels".to_string());
    format!("group {}: {channels}, {depth}/{rate}", group.group_nr)
}

fn source_track_format_label(track: &PreparedTrack) -> String {
    if source_track_dsd_rate(track).is_some() {
        return "DSD".to_string();
    }
    source_ref_extension(&track.source_ref)
        .as_deref()
        .map(audio_extension_label)
        .unwrap_or("source")
        .to_string()
}

fn source_ref_extension(source_ref: &TrackSourceRef) -> Option<String> {
    let path = match source_ref {
        TrackSourceRef::StagedFile(path) => path,
        TrackSourceRef::CueStreamSegment { source_image, .. }
        | TrackSourceRef::CueSegmentCarrier { source_image, .. } => source_image,
        TrackSourceRef::ImageSegment { image, .. } => image,
        TrackSourceRef::SacdTrack { .. } => return Some("dsd".to_string()),
        TrackSourceRef::DvdaTrack { .. } => return Some("dvda".to_string()),
        TrackSourceRef::DvdVideoTrack { .. } => return Some("dvdv".to_string()),
        TrackSourceRef::BluRayTrack { .. } => return Some("bluray".to_string()),
    };
    path.extension()
        .and_then(|value| value.to_str())
        .map(|value| value.to_ascii_lowercase())
}

fn audio_extension_label(extension: &str) -> &'static str {
    match extension.trim_start_matches('.').to_ascii_lowercase().as_str() {
        "flac" => "FLAC",
        "wav" | "wave" => "WAV",
        "aiff" | "aif" => "AIFF",
        "wv" => "WavPack",
        "mp3" => "MP3",
        "m4a" | "mp4" | "aac" => "AAC/ALAC",
        "opus" | "ogg" => "Opus",
        "dsf" | "dff" | "dsd" | "iso" => "DSD",
        _ => "source",
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResamplerFamily {
    Auto,
    Ssrc,
    Sox,
    Soxr,
}

fn preferred_resampler_family(settings: &tonepoet_pipeline::PipelineSettings) -> ResamplerFamily {
    if settings.ssrc.force || settings.nyquist_transition == NyquistTransition::BrickWall {
        return ResamplerFamily::Ssrc;
    }
    match &settings.preferred_tool {
        PreferredTool::Ssrc => ResamplerFamily::Ssrc,
        PreferredTool::Sox => ResamplerFamily::Sox,
        PreferredTool::Ffmpeg => ResamplerFamily::Soxr,
        PreferredTool::Auto | PreferredTool::Custom(_) => ResamplerFamily::Auto,
    }
}

fn preferred_resampler_label(settings: &tonepoet_pipeline::PipelineSettings) -> &'static str {
    match preferred_resampler_family(settings) {
        ResamplerFamily::Ssrc => "SSRC",
        ResamplerFamily::Sox => "SoX",
        ResamplerFamily::Soxr => "soxr",
        ResamplerFamily::Auto => "Auto",
    }
}

/// Derive the actual resampler tool from executed track commands.
///
/// Scans track records for the command that performed PCM resampling, DSD→PCM,
/// or PCM→DSD rate conversion and returns its tool name. Falls back to the user's preference
/// if no resampling command is found (defensive — shouldn't happen when
/// `resampling_applies` is true).
fn command_record_performs_resampling(command: &CommandRecord) -> bool {
    let description_matches = command
        .description
        .as_deref()
        .map(str::to_ascii_lowercase)
        .is_some_and(|description| {
            description.contains("resampl")
                || description.contains("dsd to pcm")
                || description.contains("pcm to dsd")
        });
    if description_matches {
        return true;
    }

    match command.binary {
        ToolBinary::Ssrc => true,
        ToolBinary::Sox => command.sanitized_args.iter().any(|arg| arg == "rate"),
        ToolBinary::Ffmpeg => command.sanitized_args.iter().any(|arg| {
            arg.contains("aresample=") || arg.contains("out_sample_rate=")
        }),
        _ => false,
    }
}

fn actual_resampler_label(
    tracks: &[&TrackRecord],
    settings: &tonepoet_pipeline::PipelineSettings,
) -> &'static str {
    // SSRC is unambiguous: if the SSRC binary ran, it was the resampler.
    // Check this first to avoid false-matching on preprocessing commands
    // like "Decode to PCM for SSRC" which use ffmpeg, not SSRC itself.
    for track in tracks {
        if track
            .commands
            .iter()
            .any(|command| command.binary == ToolBinary::Ssrc)
        {
            return "SSRC";
        }
    }
    for track in tracks {
        for command in &track.commands {
            if !command_record_performs_resampling(command) {
                continue;
            }
            return match command.binary {
                ToolBinary::Sox => "SoX",
                ToolBinary::Ffmpeg => "soxr",
                _ => preferred_resampler_label(settings),
            };
        }
    }
    preferred_resampler_label(settings)
}

fn target_sample_rate_setting_label(
    source: &PreparedSource,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> String {
    match settings.target_sample_rate {
        RateTarget::PcmHz(hz) => format_sample_rate(hz),
        RateTarget::Dsd(rate) => dsd_rate_label(rate).to_string(),
        RateTarget::Source => {
            let labels = source
                .tracks
                .iter()
                .filter_map(|track| {
                    resolved_target_rate_hz(track, settings)
                        .filter(|target_rate| Some(*target_rate) != track.scalar_sample_rate())
                        .map(|target_rate| target_rate_setting_label_for_hz(target_rate, settings))
                })
                .collect::<BTreeSet<_>>();
            match labels.len() {
                0 => "source".to_string(),
                1 => labels.into_iter().next().unwrap_or_else(|| "source".to_string()),
                _ => format!(
                    "source-derived ({})",
                    labels.into_iter().collect::<Vec<_>>().join(", ")
                ),
            }
        }
    }
}

fn target_rate_setting_label_for_hz(
    rate_hz: u32,
    settings: &tonepoet_pipeline::PipelineSettings,
) -> String {
    if settings.target_format.is_dsd() {
        DsdRate::from_hz(rate_hz)
            .map(dsd_rate_label)
            .map(str::to_string)
            .unwrap_or_else(|| format_sample_rate(rate_hz))
    } else {
        format_sample_rate(rate_hz)
    }
}

fn bit_depth_target_label(target: BitDepthTarget) -> String {
    match target {
        BitDepthTarget::Source => "source".to_string(),
        BitDepthTarget::Pcm(depth) => pcm_bit_depth_label(depth).to_string(),
    }
}

