fn enrich_source_with_label_info(source: &mut PreparedSource, container: &Path, req: &PipelineRequest) {
    super::source_heuristics::maybe_enrich(
        source,
        container,
        req.source.archive_password.as_ref().map(|s| s.expose()),
        req.naming.folder_template.as_deref(),
    );
    super::label_resolver::enrich_with_label_info(
        &mut source.album_metadata,
        container,
        super::label_resolver::dictionary_label_resolver(),
    );
}

fn request_batch_resolved_identity(req: &PipelineRequest) -> Option<&BatchResolvedAlbumIdentity> {
    req.batch_resolved_identity
        .as_ref()
        .or_else(|| req.album_batch.as_ref().and_then(|batch| batch.resolved_identity()))
}

struct PipelineActionCancellation<'a>(&'a CancellationToken);

impl ActionCancellation for PipelineActionCancellation<'_> {
    fn is_cancelled(&self) -> bool {
        self.0.is_cancelled()
    }
}

#[derive(Debug)]
struct PipelineActionExecution {
    report: ActionPhaseReport,
    error: Option<String>,
    recoverable_interruption: bool,
}

fn absolute_normalized_action_path(path: &Path) -> PathBuf {
    if path.is_absolute() {
        normalize_path(path)
    } else {
        std::env::current_dir()
            .map(|cwd| normalize_path(&cwd.join(path)))
            .unwrap_or_else(|_| normalize_path(path))
    }
}


#[derive(Debug, Clone, PartialEq, Eq)]
enum ConversionActionAlbumScope {
    Disabled,
    ProperSubdirectory,
    FlatLayoutSkipped { reason: String },
}

fn conversion_action_planned_album_dir(req: &PipelineRequest) -> PathBuf {
    req.album_batch
        .as_ref()
        .map(|batch| absolute_normalized_action_path(&batch.album_output_dir))
        .unwrap_or_else(|| {
            let output_root = absolute_normalized_action_path(&req.output_root);
            if req.naming.per_album_subdir {
                output_root.join(sanitize_component(&req.item_id))
            } else {
                output_root
            }
        })
}

/// This decision is deliberately lexical and side-effect free. It must run
/// before action capabilities, locks, identity sidecars, journals, or batch
/// drain authority are created. A trusted configured symlink route is opened
/// only after a proper album subdirectory has been established.
fn conversion_action_album_scope(
    req: &PipelineRequest,
    album_dir: &Path,
) -> Result<ConversionActionAlbumScope, String> {
    if req.actions.is_empty() {
        return Ok(ConversionActionAlbumScope::Disabled);
    }
    let output_root = absolute_normalized_action_path(&req.output_root);
    let album_dir = absolute_normalized_action_path(album_dir);
    if album_dir == output_root {
        return Ok(ConversionActionAlbumScope::FlatLayoutSkipped {
            reason: format!(
                "conversion actions skipped: flat output layout uses the shared output root {}",
                output_root.display()
            ),
        });
    }
    if !album_dir.starts_with(&output_root) {
        return Err(format!(
            "conversion actions refused: rendered album directory must be inside output root ({} vs {})",
            album_dir.display(),
            output_root.display()
        ));
    }
    Ok(ConversionActionAlbumScope::ProperSubdirectory)
}

fn conversion_action_scope_for_request(
    req: &PipelineRequest,
) -> Result<ConversionActionAlbumScope, String> {
    conversion_action_album_scope(req, &conversion_action_planned_album_dir(req))
}

fn conversion_actions_effective_for_request(req: &PipelineRequest) -> io::Result<bool> {
    conversion_action_scope_for_request(req)
        .map(|scope| matches!(scope, ConversionActionAlbumScope::ProperSubdirectory))
        .map_err(|message| io::Error::new(io::ErrorKind::InvalidInput, message))
}

fn action_run_identity(req: &PipelineRequest) -> String {
    req.album_batch
        .as_ref()
        .map(|batch| batch.conversion_log_batch_id.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| format!("{}:{}", req.job_id, req.item_id))
}

fn action_album_identity(req: &PipelineRequest, album_dir: &Path) -> String {
    let mut identity = String::from("tonepoet-action-album-v1\n");
    identity.push_str("album_dir=");
    identity.push_str(&absolute_normalized_action_path(album_dir).to_string_lossy());
    identity.push('\n');
    if let Some(batch) = req.album_batch.as_ref() {
        identity.push_str("batch_id=");
        identity.push_str(batch.conversion_log_batch_id.trim());
        identity.push('\n');
        identity.push_str("source_root=");
        identity.push_str(&absolute_normalized_action_path(&batch.source_grouping_root).to_string_lossy());
        identity.push('\n');
    } else {
        identity.push_str("source=");
        identity.push_str(&absolute_normalized_action_path(&req.container).to_string_lossy());
        identity.push('\n');
    }
    identity
}

fn action_coordination_dir(req: &PipelineRequest) -> PathBuf {
    conversion_log_batch_coordination_album_dir(req).unwrap_or_else(|| {
        absolute_normalized_action_path(&req.output_root)
            .join(".tonepoet-actions")
            .join(sanitize_component(&format!("{}-{}", req.job_id, req.item_id)))
    })
}

pub(crate) fn action_semantics() -> ActionSemantics {
    ActionSemantics {
        wildcard_matches: conversion_action_wildcard_matches,
        render_template: conversion_action_render_template,
        sanitize_component: conversion_action_sanitize_component,
        fixcaps: crate::convert::renaming::capitalize_title,
        disc_number_for_path: conversion_action_disc_number_for_path,
    }
}

fn action_protected_sources(req: &PipelineRequest) -> BTreeSet<PathBuf> {
    let mut paths = BTreeSet::new();
    if let Some(batch) = req.album_batch.as_ref() {
        for source in batch.source_paths() {
            paths.insert(absolute_normalized_action_path(source));
        }
    }
    if paths.is_empty() {
        paths.insert(absolute_normalized_action_path(&req.container));
    }
    paths
}

fn canonicalize_trusted_action_route(path: &Path) -> Result<PathBuf, ActionError> {
    let absolute = absolute_normalized_action_path(path);
    let mut existing = absolute.as_path();
    let mut suffix = Vec::new();
    loop {
        match fs::symlink_metadata(existing) {
            Ok(_) => break,
            Err(error) if error.kind() == io::ErrorKind::NotFound => {
                let component = existing.file_name().ok_or_else(|| {
                    ActionError::UnsafePath(format!(
                        "configured action route has no existing ancestor: {}",
                        absolute.display()
                    ))
                })?;
                suffix.push(component.to_os_string());
                existing = existing.parent().ok_or_else(|| {
                    ActionError::UnsafePath(format!(
                        "configured action route has no parent: {}",
                        absolute.display()
                    ))
                })?;
            }
            Err(error) => return Err(error.into()),
        }
    }
    let mut resolved = fs::canonicalize(existing)?;
    for component in suffix.into_iter().rev() {
        resolved.push(component);
    }
    Ok(resolved)
}

fn rebase_action_path(
    path: &Path,
    lexical_root: &Path,
    trusted_root: &Path,
) -> PathBuf {
    let absolute = absolute_normalized_action_path(path);
    absolute
        .strip_prefix(lexical_root)
        .map(|relative| trusted_root.join(relative))
        .unwrap_or(absolute)
}

#[derive(Debug)]
struct PipelineOutputCapability {
    logical_root: PathBuf,
    capability: PinnedDirectoryCapability,
    /// Exact published album descriptor when this binding comes from the
    /// publication authority. Initial PRE execution before conversion leaves
    /// this unset because the album root does not exist yet.
    album: Option<PinnedDirectoryCapability>,
}

impl PipelineOutputCapability {
    fn capture_for_actions(req: &PipelineRequest) -> Result<Option<Self>, ActionError> {
        if req.actions.is_empty() {
            return Ok(None);
        }
        match conversion_action_scope_for_request(req).map_err(ActionError::Conflict)? {
            ConversionActionAlbumScope::Disabled | ConversionActionAlbumScope::FlatLayoutSkipped { .. } => {
                return Ok(None);
            }
            ConversionActionAlbumScope::ProperSubdirectory => {}
        }
        let logical_root = absolute_normalized_action_path(&req.output_root);
        fs::create_dir_all(&logical_root)?;
        let capability = PinnedDirectoryCapability::open_trusted(&logical_root)?;
        Ok(Some(Self {
            logical_root,
            capability,
            album: None,
        }))
    }

    #[allow(dead_code)] // bundle-provided API surface, not yet wired to a caller
    fn try_clone(&self) -> Result<Self, ActionError> {
        Ok(Self {
            logical_root: self.logical_root.clone(),
            capability: self.capability.try_clone()?,
            album: self
                .album
                .as_ref()
                .map(PinnedDirectoryCapability::try_clone)
                .transpose()?,
        })
    }

    #[allow(dead_code)] // bundle-provided API surface, not yet wired to a caller
    fn io_path(&self, stable: &Path) -> Result<PathBuf, ActionError> {
        let stable = absolute_normalized_action_path(stable);
        let relative = stable.strip_prefix(&self.logical_root).map_err(|_| {
            ActionError::UnsafePath(format!(
                "coordination path {} is outside retained output root {}",
                stable.display(),
                self.logical_root.display()
            ))
        })?;
        Ok(self.capability.descriptor_path()?.join(relative))
    }
}

fn pre_action_context(req: &PipelineRequest) -> Result<ActionContext, ActionError> {
    pre_action_context_with_output_capability(req, None)
}

fn pre_action_context_with_output_capability(
    req: &PipelineRequest,
    retained_output: Option<&PipelineOutputCapability>,
) -> Result<ActionContext, ActionError> {
    let source_path = absolute_normalized_action_path(&req.container);
    let source_is_directory = source_path.is_dir();
    // Album batches anchor the pre-action subject (and subject/source
    // capability scopes) at the batch source grouping root, NOT the track's
    // own directory: participants of a multi-disc batch live in sibling disc
    // subdirectories, and per-track anchors would give every participant a
    // different scope identity for the SAME album-scoped journal.
    let batch_source_scope_root = req
        .album_batch
        .as_ref()
        .map(|batch| absolute_normalized_action_path(&batch.source_grouping_root));
    let subject_dir = if let Some(root) = batch_source_scope_root.clone() {
        root
    } else if source_is_directory {
        source_path.clone()
    } else {
        source_path.parent().map(Path::to_path_buf).ok_or_else(|| {
            ActionError::UnsafePath(format!(
                "pre-action source has no parent directory: {}",
                source_path.display()
            ))
        })?
    };
    let lexical_output_root = absolute_normalized_action_path(&req.output_root);
    let output_root = retained_output
        .map(|binding| binding.logical_root.clone())
        .unwrap_or(canonicalize_trusted_action_route(&req.output_root)?);
    let album_dir = req
        .album_batch
        .as_ref()
        .map(|batch| {
            rebase_action_path(
                &batch.album_output_dir,
                &lexical_output_root,
                &output_root,
            )
        })
        .unwrap_or_else(|| output_root.join(sanitize_component(&req.item_id)));
    let coordination_dir = if retained_output.is_some() {
        absolute_normalized_action_path(&action_coordination_dir(req))
    } else {
        canonicalize_trusted_action_route(&action_coordination_dir(req))?
    };
    let journal_dir = coordination_dir.join(".tonepoet-action-journals");

    let mut retained_album_capability = None;
    let mut retained_output_capability = None;
    let mut retained_journal_capability = None;
    let mut coordination_io_dir = None;
    if let Some(binding) = retained_output {
        let album_relative = album_dir.strip_prefix(&binding.logical_root).map_err(|_| {
            ActionError::UnsafePath(format!(
                "pre-action album root {} is outside retained output root {}",
                album_dir.display(),
                binding.logical_root.display()
            ))
        })?;
        if let Some(album) = binding.album.as_ref() {
            retained_album_capability = Some(Arc::new(album.try_clone()?));
        } else {
            match binding.capability.open_directory_descendant(album_relative, false, 0o755) {
                Ok(album_capability) => retained_album_capability = Some(Arc::new(album_capability)),
                Err(error) if error.raw_os_error() == Some(libc::ENOENT) => {}
                Err(error) => return Err(error.into()),
            }
        }
        let coordination_relative = coordination_dir.strip_prefix(&binding.logical_root).map_err(|_| {
            ActionError::UnsafePath(format!(
                "pre-action coordination root {} is outside retained output root {}",
                coordination_dir.display(),
                binding.logical_root.display()
            ))
        })?;
        let coordination_capability = binding
            .capability
            .open_directory_descendant(coordination_relative, true, 0o700)?;
        coordination_io_dir = Some(
            binding
                .capability
                .descriptor_path()?
                .join(coordination_relative),
        );
        let journal_capability = coordination_capability.open_directory_child(
            std::ffi::OsStr::new(".tonepoet-action-journals"),
            true,
            0o700,
        )?;
        retained_journal_capability = Some(Arc::new(journal_capability));
        retained_output_capability = Some(Arc::new(binding.capability.try_clone()?));
    }

    Ok(ActionContext {
        run_identity: action_run_identity(req),
        album_identity: action_album_identity(req, &album_dir),
        phase: ActionPhase::Pre,
        subject_dir,
        source_path,
        source_is_directory,
        output_root,
        album_dir,
        environment_album_dir: None,
        retained_album_capability,
        retained_output_capability,
        retained_journal_capability,
        coordination_io_dir,
        protected_sources: action_protected_sources(req),
        protected_generated_paths: BTreeSet::new(),
        album_tokens: conversion_action_request_tokens(req)?,
        disc_count: request_batch_resolved_identity(req).and_then(|identity| identity.total_discs),
        journal_dir,
        batch_source_scope_root,
        explicit_scope: false,
        semantics: action_semantics(),
    })
}

pub(crate) fn conversion_action_pre_preview_context(
    req: &PipelineRequest,
) -> Result<ActionContext, ActionError> {
    match conversion_action_scope_for_request(req) {
        Ok(ConversionActionAlbumScope::ProperSubdirectory) => {}
        Ok(ConversionActionAlbumScope::Disabled) => {
            return Err(ActionError::Conflict(
                "pre-action preview requires a configured action pipeline".to_string(),
            ));
        }
        Ok(ConversionActionAlbumScope::FlatLayoutSkipped { reason }) => {
            return Err(ActionError::Conflict(reason));
        }
        Err(error) => return Err(ActionError::Conflict(error)),
    }
    let mut context = pre_action_context(req)?;
    context.run_identity = format!("wizard-preview:{}", req.item_id);
    context.explicit_scope = true;
    Ok(context)
}

fn post_action_context(
    req: &PipelineRequest,
    source: &PreparedSource,
    artifacts: Option<&ArtifactSet>,
    published: &PublishedAlbum,
) -> Result<ActionContext, ActionError> {
    let stable_album_dir = absolute_normalized_action_path(&published.album_dir);
    post_action_context_with_capabilities(
        req,
        source,
        artifacts,
        published,
        &stable_album_dir,
        None,
        None,
    )
}

/// Build a post-action context with stable durable logical paths while
/// injecting exact retained directory objects for live I/O. Descriptor
/// namespace routes are runtime access mechanisms only and never enter the
/// journal, election identity, or durable report.
fn post_action_context_with_capabilities(
    req: &PipelineRequest,
    source: &PreparedSource,
    artifacts: Option<&ArtifactSet>,
    published: &PublishedAlbum,
    stable_album_dir: &Path,
    retained_album: Option<PinnedDirectoryCapability>,
    retained_output: Option<PinnedDirectoryCapability>,
) -> Result<ActionContext, ActionError> {
    let source_path = absolute_normalized_action_path(&req.container);
    let lexical_album_dir = absolute_normalized_action_path(&published.album_dir);
    let album_dir = absolute_normalized_action_path(stable_album_dir);
    let output_root = absolute_normalized_action_path(&req.output_root);
    let coordination_dir = absolute_normalized_action_path(&action_coordination_dir(req));
    let journal_dir = coordination_dir.join(".tonepoet-action-journals");

    let mut retained_output_capability = None;
    let mut retained_journal_capability = None;
    let mut coordination_io_dir = None;
    if let Some(output_capability) = retained_output {
        let coordination_relative = coordination_dir.strip_prefix(&output_root).map_err(|_| {
            ActionError::UnsafePath(format!(
                "post-action coordination root {} is outside retained output root {}",
                coordination_dir.display(),
                output_root.display()
            ))
        })?;
        let coordination_capability = output_capability
            .open_directory_descendant(coordination_relative, true, 0o700)?;
        coordination_io_dir = Some(
            output_capability
                .descriptor_path()?
                .join(coordination_relative),
        );
        let journal_capability = coordination_capability.open_directory_child(
            std::ffi::OsStr::new(".tonepoet-action-journals"),
            true,
            0o700,
        )?;
        retained_journal_capability = Some(Arc::new(journal_capability));
        retained_output_capability = Some(Arc::new(output_capability));
    }

    let mut protected_generated_paths = BTreeSet::new();
    protected_generated_paths.insert(album_dir.join("conversion.log"));
    protected_generated_paths.insert(conversion_action_identity_path(&album_dir));
    if let Some(artifacts) = artifacts {
        for sidecar in &artifacts.sidecars {
            if matches!(&sidecar.kind, SidecarKind::ConversionLog | SidecarKind::CueSheet) {
                protected_generated_paths.insert(rebase_action_path(
                    &sidecar.final_path,
                    &lexical_album_dir,
                    &album_dir,
                ));
            }
        }
    }
    for entry in &published.entries {
        if matches!(
            &entry.role,
            PublishRole::Sidecar(SidecarKind::ConversionLog | SidecarKind::CueSheet)
        ) {
            protected_generated_paths.insert(rebase_action_path(
                &entry.final_path,
                &lexical_album_dir,
                &album_dir,
            ));
        }
    }
    Ok(ActionContext {
        run_identity: action_run_identity(req),
        album_identity: action_album_identity(req, &album_dir),
        phase: ActionPhase::Post,
        subject_dir: album_dir.clone(),
        source_path,
        source_is_directory: req.container.is_dir(),
        output_root,
        album_dir: album_dir.clone(),
        environment_album_dir: Some(album_dir),
        retained_album_capability: retained_album.map(Arc::new),
        retained_output_capability,
        retained_journal_capability,
        coordination_io_dir,
        protected_sources: action_protected_sources(req),
        protected_generated_paths,
        album_tokens: conversion_action_album_tokens(source, &req.settings),
        disc_count: source
            .album_metadata
            .total_discs
            .or_else(|| {
                request_batch_resolved_identity(req).and_then(|identity| identity.total_discs)
            }),
        journal_dir,
        batch_source_scope_root: req
            .album_batch
            .as_ref()
            .map(|batch| absolute_normalized_action_path(&batch.source_grouping_root)),
        explicit_scope: false,
        semantics: action_semantics(),
    })
}

fn published_album_from_manifest_skip(
    album_dir: &Path,
    manifest: &super::manifest::ConversionManifest,
    manifest_path: PathBuf,
) -> Result<PublishedAlbum, String> {
    let mut entries = Vec::with_capacity(manifest.tracks.len());
    for track in &manifest.tracks {
        let final_path = super::manifest::resolve_manifest_output_path(album_dir, &track.output_path)
            .map_err(|error| format!(
                "manifest skip contains an unsafe output path {}: {error}",
                track.output_path.display()
            ))?;
        entries.push(PublishedEntry {
            final_path,
            role: PublishRole::Audio,
            bytes: track.output_size,
        });
    }
    Ok(PublishedAlbum {
        album_dir: album_dir.to_path_buf(),
        entries,
        manifest_path: Some(manifest_path),
        batch_completion: None,
    })
}

async fn finalize_manifest_skip(
    req: &PipelineRequest,
    reporter: &dyn PipelineReporter,
    source: PreparedSource,
    plan: AlbumPlan,
    mut stages: Vec<StageRecord>,
    manifest: super::manifest::ConversionManifest,
    manifest_path: PathBuf,
) -> PipelineReport {
    let published = match published_album_from_manifest_skip(
        &plan.album_dir,
        &manifest,
        manifest_path,
    ) {
        Ok(published) => Some(published),
        Err(error) => {
            let record = stage_record(PipelineStage::Publish, StageOutcome::Failed(error));
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            stages.push(record);
            None
        }
    };
    if published.is_some() {
        if !req.actions.pre.is_empty() {
            let record = stage_record(PipelineStage::PreActions, StageOutcome::Skipped);
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            stages.push(record);
        }
        let publish_record = stage_record(PipelineStage::Publish, StageOutcome::Skipped);
        emit_stage_finished(reporter, &req.item_id, publish_record.clone()).await;
        stages.push(publish_record);
        if !req.actions.post.is_empty() {
            let outcome = post_action_outcome_with_terminal_authority(
                req,
                None,
                StageOutcome::Skipped,
                true,
            );
            let record = stage_record(PipelineStage::PostActions, outcome);
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            stages.push(record);
        }
    }
    let outcome = if published.is_some() {
        AlbumOutcome::Complete {
            tracks: Vec::new(),
            stages,
        }
    } else {
        AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::PublishFailed,
        }
    };
    finalize_report(
        req,
        reporter,
        Some(source),
        Some(plan),
        None,
        published,
        outcome,
    )
    .await
}

enum PreMaterializationActionOutcome {
    Continue { ran_pre_actions: bool },
    Finished(PipelineReport),
}

async fn finalize_pre_materialization_manifest_skip(
    req: &PipelineRequest,
    reporter: &dyn PipelineReporter,
    album_dir: PathBuf,
    manifest: super::manifest::ConversionManifest,
    manifest_path: PathBuf,
    mut stages: Vec<StageRecord>,
) -> PipelineReport {
    let published = match published_album_from_manifest_skip(
        &album_dir,
        &manifest,
        manifest_path,
    ) {
        Ok(published) => Some(published),
        Err(error) => {
            let record = stage_record(PipelineStage::Publish, StageOutcome::Failed(error));
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            stages.push(record);
            None
        }
    };

    if published.is_some() {
        for stage in [
            PipelineStage::PreActions,
            PipelineStage::Materialize,
            PipelineStage::PlanOutputs,
            PipelineStage::Publish,
            PipelineStage::PostActions,
        ] {
            let configured = match stage {
                PipelineStage::PreActions => !req.actions.pre.is_empty(),
                PipelineStage::PostActions => !req.actions.post.is_empty(),
                _ => true,
            };
            if configured {
                let outcome = if stage == PipelineStage::PostActions {
                    post_action_outcome_with_terminal_authority(
                        req,
                        None,
                        StageOutcome::Skipped,
                        true,
                    )
                } else {
                    StageOutcome::Skipped
                };
                let record = stage_record(stage, outcome);
                emit_stage_finished(reporter, &req.item_id, record.clone()).await;
                stages.push(record);
            }
        }
    }

    let plan = AlbumPlan {
        album_dir,
        album_dirs: Vec::new(),
        entries: Vec::new(),
    };
    let outcome = if published.is_some() {
        AlbumOutcome::Complete {
            tracks: Vec::new(),
            stages,
        }
    } else {
        AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::PublishFailed,
        }
    };
    finalize_report(req, reporter, None, Some(plan), None, published, outcome).await
}

async fn decide_rerun_after_reference_preflight(
    req: &PipelineRequest,
    source: &PreparedSource,
    album_plan: &AlbumPlan,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
) -> super::rerun::RerunDecision {
    let prepared_source_is_dsd = source_is_dsd(source);
    if !tonepoet_pipeline::selects_reference_dsd_to_pcm(
        &req.settings,
        prepared_source_is_dsd,
    ) || req.settings.dsd.from_dsd.pathway
        != tonepoet_pipeline::DsdSourcePathway::Reference
    {
        return super::rerun::decide_rerun(
            &album_plan.album_dir,
            &req.settings,
            req.publish.overwrite,
        );
    }
    let Some(track) = source.tracks.first().filter(|_| source.tracks.len() == 1) else {
        return super::rerun::RerunDecision::Redo {
            reason: super::rerun::RerunReason::NativePreflightFailed(
                "P0 Reference rerun preflight requires exactly one singleton track".to_string(),
            ),
            warning: Some(
                "native Reference rerun preflight could not establish singleton authority; conversion will be replanned"
                    .to_string(),
            ),
            publish_overwrite: OverwritePolicy::ReplaceWithBackup,
        };
    };
    let Some(entry) = album_plan
        .entries
        .iter()
        .find(|entry| entry.track_id == track.id)
    else {
        return super::rerun::RerunDecision::Redo {
            reason: super::rerun::RerunReason::NativePreflightFailed(
                "P0 Reference album plan has no output for its singleton track".to_string(),
            ),
            warning: Some(
                "native Reference rerun preflight could not bind the planned output; conversion will be replanned"
                    .to_string(),
            ),
            publish_overwrite: OverwritePolicy::ReplaceWithBackup,
        };
    };

    match preflight_reference_rerun_authority(
        req,
        track,
        &entry.final_path,
        runner,
        cancel,
    )
    .await
    {
        Ok(Some(authority)) => super::rerun::decide_rerun_with_reference_preflight(
            &album_plan.album_dir,
            &req.settings,
            req.publish.overwrite,
            &authority,
        ),
        Ok(None) => super::rerun::RerunDecision::Redo {
            reason: super::rerun::RerunReason::NativePreflightFailed(
                "native-v2 settings did not produce Reference preflight authority".to_string(),
            ),
            warning: Some(
                "native Reference rerun authority was unavailable; conversion will be replanned"
                    .to_string(),
            ),
            publish_overwrite: OverwritePolicy::ReplaceWithBackup,
        },
        Err(err) => super::rerun::RerunDecision::Redo {
            reason: super::rerun::RerunReason::NativePreflightFailed(err.to_string()),
            warning: Some(format!(
                "native Reference rerun preflight failed; conversion will proceed through the same fail-closed execution gate: {err}"
            )),
            publish_overwrite: OverwritePolicy::ReplaceWithBackup,
        },
    }
}

/// For a batch with pre-actions, perform the rerun decision and elected pre
/// phase before any worker enters source materialization. The dispatcher must
/// have persisted an album directory produced by the canonical planner; a
/// provisional directory is rejected rather than allowing pre-actions to race
/// a later manifest skip or run against the wrong album identity.
async fn prepare_batch_pre_actions_before_materialization(
    req: &PipelineRequest,
    retained_output: Option<&PipelineOutputCapability>,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    stages: &mut Vec<StageRecord>,
) -> PreMaterializationActionOutcome {
    if req.actions.pre.is_empty() || req.album_batch.is_none() {
        return PreMaterializationActionOutcome::Continue {
            ran_pre_actions: false,
        };
    }
    if tonepoet_pipeline::selects_reference_dsd_to_pcm(&req.settings, true)
        && req.settings.dsd.from_dsd.pathway
            == tonepoet_pipeline::DsdSourcePathway::Reference
    {
        // Native Reference skip authority cannot be established from settings
        // alone. Defer PRE actions until source planning and the exact
        // source/toolchain preflight have proved this is not a manifest skip.
        return PreMaterializationActionOutcome::Continue {
            ran_pre_actions: false,
        };
    }
    let batch = req.album_batch.as_ref().expect("checked above");
    if !batch.album_output_dir_is_planner_resolved() {
        let message = format!(
            "pre-actions require a canonical dispatch-time album directory before materialization; batch {} still has provisional output {}",
            batch.conversion_log_batch_id,
            batch.album_output_dir.display(),
        );
        let record = stage_record(PipelineStage::PreActions, StageOutcome::Failed(message));
        emit_stage_finished(reporter, &req.item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages: std::mem::take(stages),
            reason: BlockReason::RequiredStageFailure(PipelineStage::PreActions),
        };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
            req,
            &outcome,
        );
        return PreMaterializationActionOutcome::Finished(
            finalize_report(req, reporter, None, None, None, published, outcome).await,
        );
    }

    let album_dir = normalize_path(&batch.album_output_dir);
    if let super::rerun::RerunDecision::Skip {
        manifest,
        manifest_path,
    } = super::rerun::decide_rerun(&album_dir, &req.settings, req.publish.overwrite)
    {
        return PreMaterializationActionOutcome::Finished(
            finalize_pre_materialization_manifest_skip(
                req,
                reporter,
                album_dir,
                manifest,
                manifest_path,
                std::mem::take(stages),
            )
            .await,
        );
    }

    let record = execute_pre_actions_stage(req, retained_output, reporter, cancel).await;
    let failed = matches!(record.outcome, StageOutcome::Failed(_));
    stages.push(record);
    if failed {
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages: std::mem::take(stages),
            reason: BlockReason::RequiredStageFailure(PipelineStage::PreActions),
        };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
            req,
            &outcome,
        );
        return PreMaterializationActionOutcome::Finished(
            finalize_report(req, reporter, None, None, None, published, outcome).await,
        );
    }

    PreMaterializationActionOutcome::Continue {
        ran_pre_actions: true,
    }
}

struct PreparedActionElection {
    coordination_dir: PathBuf,
    election_identity: ActionElectionIdentity,
    election: ActionElection,
}

fn prepare_action_election(
    req: &PipelineRequest,
    context: &ActionContext,
) -> Result<PreparedActionElection, ActionError> {
    let pipeline = &req.actions;
    let election_identity = ActionElectionIdentity::new(
        context.run_identity.clone(),
        context.album_identity.clone(),
        context.phase,
        pipeline,
    )?;
    // Durable action identity remains the stable logical path in `context`.
    // Runtime coordination I/O may instead use a descriptor-backed route that
    // reaches the exact retained output-root object. Never persist that route
    // in a journal or election identity.
    let coordination_dir = context
        .coordination_io_dir
        .clone()
        .unwrap_or_else(|| action_coordination_dir(req));
    if let Some(batch) = req.album_batch.as_ref() {
        let batch_id = batch.conversion_log_batch_id.trim();
        if !batch_id.is_empty() && is_generated_conversion_log_batch_id(batch_id) {
            ensure_conversion_log_batch_workspace_owned_for_request_at(req, &coordination_dir)
                .map_err(|error| {
                    ActionError::Election(format!(
                        "could not establish strong parent workspace ownership and participant drain authority before {} actions: {error}",
                        context.phase.as_str()
                    ))
                })?;
        }
    }
    let election = with_album_publish_lock_for_companion_copy(&coordination_dir, || {
        elect_action_runner(&coordination_dir, &election_identity, true)
    })
    .map_err(|error| ActionError::Election(error.to_string()))??;
    Ok(PreparedActionElection {
        coordination_dir,
        election_identity,
        election,
    })
}


/// Diagnosable phase-failure summary: the phase name plus every recorded
/// per-action error. "completed with errors" without WHICH errors is
/// undiagnosable in the field.
fn action_phase_error_summary(
    report: &crate::convert::pipeline::actions::ActionPhaseReport,
    phase: &str,
) -> String {
    let mut details: Vec<String> = report
        .actions
        .iter()
        .filter_map(|action| {
            action
                .error
                .as_ref()
                .map(|error| format!("action {} ({}): {error}", action.index + 1, action.kind))
        })
        .collect();
    if details.is_empty() {
        details.push("no per-action detail recorded".to_string());
    }
    format!("{phase} action phase completed with errors: {}", details.join("; "))
}

fn execute_prepared_action_election_with_runner(
    req: &PipelineRequest,
    context: &ActionContext,
    cancel: &CancellationToken,
    prepared: PreparedActionElection,
    scripts: &dyn ActionScriptRunner,
) -> Result<PipelineActionExecution, ActionError> {
    let pipeline = &req.actions;
    let cancellation = PipelineActionCancellation(cancel);
    let filesystem = CapabilityActionFilesystem::new();
    let engine = ActionEngine {
        filesystem: &filesystem,
        scripts,
    };
    let coordination_dir = prepared.coordination_dir;
    let election_identity = prepared.election_identity;
    let mut next_election = Some(prepared.election);

    loop {
        let election = match next_election.take() {
            Some(election) => election,
            None => with_album_publish_lock_for_companion_copy(&coordination_dir, || {
                elect_action_runner(&coordination_dir, &election_identity, true)
            })
            .map_err(|error| ActionError::Election(error.to_string()))??,
        };

        match election {
            ActionElection::Complete(report) => {
                return Ok(PipelineActionExecution {
                    error: report.has_errors().then(|| {
                        action_phase_error_summary(&report, context.phase.as_str())
                    }),
                    recoverable_interruption: report.recovery_required,
                    report,
                });
            }
            ActionElection::Wait(waiter) => {
                match waiter.wait(&cancellation, Duration::from_millis(100)) {
                    Ok(report) => {
                        return Ok(PipelineActionExecution {
                            error: report.has_errors().then(|| {
                                action_phase_error_summary(&report, context.phase.as_str())
                            }),
                            recoverable_interruption: report.recovery_required,
                            report,
                        });
                    }
                    Err(ActionError::Election(message))
                        if message.contains("must re-elect")
                            || message.contains("disappeared without a durable result") =>
                    {
                        continue;
                    }
                    Err(error) => return Err(error),
                }
            }
            ActionElection::Runner(guard) => {
                let execution = engine.execute_phase(pipeline, context, &cancellation);
                let report = match &execution {
                    Ok(report) => report.clone(),
                    Err(error) => engine
                        .durable_phase_report(pipeline, context)?
                        .unwrap_or_else(|| {
                            phase_level_action_failure_report(
                                pipeline,
                                context.phase,
                                error.to_string(),
                            )
                        }),
                };
                match execution {
                    Ok(_) => {
                        with_album_publish_lock_for_companion_copy(&coordination_dir, || {
                            guard.finish(&report)
                        })
                        .map_err(|error| ActionError::Election(error.to_string()))??;
                        return Ok(PipelineActionExecution {
                            error: report.has_errors().then(|| {
                                action_phase_error_summary(&report, context.phase.as_str())
                            }),
                            recoverable_interruption: report.recovery_required,
                            report,
                        });
                    }
                    Err(error @ ActionError::Interrupted(_)) => {
                        with_album_publish_lock_for_companion_copy(&coordination_dir, || {
                            guard.release_for_recovery()
                        })
                        .map_err(|lock_error| ActionError::Election(lock_error.to_string()))??;
                        return Ok(PipelineActionExecution {
                            report,
                            error: Some(error.to_string()),
                            recoverable_interruption: true,
                        });
                    }
                    Err(error) => {
                        with_album_publish_lock_for_companion_copy(&coordination_dir, || {
                            guard.finish(&report)
                        })
                        .map_err(|lock_error| ActionError::Election(lock_error.to_string()))??;
                        return Ok(PipelineActionExecution {
                            report,
                            error: Some(error.to_string()),
                            recoverable_interruption: false,
                        });
                    }
                }
            }
        }
    }
}

fn run_elected_action_phase_with_runner(
    req: &PipelineRequest,
    context: &ActionContext,
    cancel: &CancellationToken,
    scripts: &dyn ActionScriptRunner,
) -> Result<PipelineActionExecution, ActionError> {
    if req.actions.for_phase(context.phase).is_empty() {
        return Ok(PipelineActionExecution {
            report: ActionPhaseReport {
                phase: Some(context.phase),
                ..ActionPhaseReport::default()
            },
            error: None,
            recoverable_interruption: false,
        });
    }
    let prepared = prepare_action_election(req, context)?;
    execute_prepared_action_election_with_runner(req, context, cancel, prepared, scripts)
}

fn phase_level_action_failure_report(
    pipeline: &super::actions::ActionPipeline,
    phase: ActionPhase,
    error: String,
) -> ActionPhaseReport {
    let actions = pipeline
        .for_phase(phase)
        .iter()
        .enumerate()
        .map(|(index, action)| ActionResult {
            index,
            kind: action.kind_name().to_string(),
            status: if index == 0 {
                ActionResultStatus::Failed
            } else {
                ActionResultStatus::SkippedAfterFailure
            },
            operations: Vec::new(),
            error: Some(if index == 0 {
                error.clone()
            } else {
                "phase stopped before this action after an earlier phase-level failure"
                    .to_string()
            }),
            notices: Vec::new(),
        })
        .collect();
    ActionPhaseReport {
        phase: Some(phase),
        actions,
        notices: vec![error],
        recovery_required: false,
        cancelled: false,
    }
}

fn phase_level_recovery_required_report(
    pipeline: &super::actions::ActionPipeline,
    phase: ActionPhase,
    error: String,
) -> ActionPhaseReport {
    let mut report = phase_level_action_failure_report(pipeline, phase, error);
    report.recovery_required = true;
    report
}

fn pre_action_context_for_publication_binding(
    req: &PipelineRequest,
    binding: &PublicationCapabilityBinding,
) -> Result<ActionContext, ActionError> {
    let retained_output = PipelineOutputCapability {
        logical_root: binding.logical_output_root.clone(),
        capability: binding.output_root.try_clone()?,
        album: Some(binding.album.try_clone()?),
    };
    pre_action_context_with_output_capability(req, Some(&retained_output))
}

fn post_action_context_for_publication_binding(
    req: &PipelineRequest,
    source: &PreparedSource,
    published: &PublishedAlbum,
    binding: &PublicationCapabilityBinding,
) -> Result<ActionContext, ActionError> {
    post_action_context_with_capabilities(
        req,
        source,
        None,
        published,
        &binding.logical_album_dir,
        Some(binding.album.try_clone()?),
        Some(binding.output_root.try_clone()?),
    )
}

fn collect_durable_action_reports(
    req: &PipelineRequest,
    source: Option<&PreparedSource>,
    published: Option<&PublishedAlbum>,
) -> Vec<ActionPhaseReport> {
    collect_durable_action_reports_with_binding(req, source, published, None)
}

/// Publish-time album identity attestation. While the publication authority
/// is bound, publish the album's materialized identity attestation from the
/// PRE journal's parent-anchored scope record. Publication precedes every
/// finalize that can observe the album, so this closes the finalize-order
/// window where a no-binding participant (e.g. a failed item) validates the
/// pre journal before any with-binding finalizer has attested. The attestation
/// is no-clobber: concurrent publishers converge or fail closed.
fn attest_publication_album_scope_best_effort(
    req: &PipelineRequest,
    binding: Option<&PublicationCapabilityBinding>,
) {
    let Some(binding) = binding else { return };
    if req.actions.for_phase(ActionPhase::Pre).is_empty() {
        return;
    }
    let result = (|| -> Result<(), ActionError> {
        let context = pre_action_context_for_publication_binding(req, binding)?;
        let filesystem = CapabilityActionFilesystem::new();
        let scripts = ProcessGroupScriptRunner;
        let engine = ActionEngine {
            filesystem: &filesystem,
            scripts: &scripts,
        };
        engine.attest_pre_album_scope_for_publication(&req.actions, &context)
    })();
    if let Err(error) = result {
        log::warn!(
            "publish-time album identity attestation failed for {}: {error}",
            req.item_id
        );
    }
}

fn collect_durable_action_reports_with_binding(
    req: &PipelineRequest,
    source: Option<&PreparedSource>,
    published: Option<&PublishedAlbum>,
    binding: Option<&PublicationCapabilityBinding>,
) -> Vec<ActionPhaseReport> {
    if matches!(
        conversion_action_scope_for_request(req),
        Ok(ConversionActionAlbumScope::Disabled)
            | Ok(ConversionActionAlbumScope::FlatLayoutSkipped { .. })
    ) {
        return Vec::new();
    }
    let mut reports = Vec::new();
    let retirement_coord_dir = match binding {
        Some(binding) => match binding.coordination_dir(req) {
            Ok(coord_dir) => Some(coord_dir),
            Err(error) => {
                reports.push(phase_level_recovery_required_report(
                    &req.actions,
                    ActionPhase::Pre,
                    format!(
                        "durable action coordination context construction failed: {error}"
                    ),
                ));
                None
            }
        },
        None => conversion_log_batch_coordination_album_dir(req),
    };
    if let Some(coord_dir) = retirement_coord_dir.as_deref() {
        match conversion_log_batch_materialization_authorities_retired_at(req, coord_dir) {
            Ok(true) => return Vec::new(),
            Ok(false) => {}
            Err(error) => reports.push(phase_level_recovery_required_report(
                &req.actions,
                ActionPhase::Pre,
                format!("terminal materialization-authority retirement record is invalid: {error}"),
            )),
        }
    }
    let scripts = ProcessGroupScriptRunner;
    let pre_context = if req.actions.for_phase(ActionPhase::Pre).is_empty() {
        None
    } else {
        match binding {
            Some(binding) => match pre_action_context_for_publication_binding(req, binding) {
                Ok(context) => Some(context),
                Err(error) => {
                    reports.push(phase_level_recovery_required_report(
                        &req.actions,
                        ActionPhase::Pre,
                        format!("durable pre-action context construction failed: {error}"),
                    ));
                    None
                }
            },
            None => match pre_action_context(req) {
                Ok(context) => Some(context),
                Err(error) => {
                    reports.push(phase_level_recovery_required_report(
                        &req.actions,
                        ActionPhase::Pre,
                        format!("durable pre-action context construction failed: {error}"),
                    ));
                    None
                }
            },
        }
    };
    let post_context = if req.actions.for_phase(ActionPhase::Post).is_empty() {
        None
    } else {
        match (source, published) {
            (Some(source), Some(published)) => match binding {
            Some(binding) => match post_action_context_for_publication_binding(
                req,
                source,
                published,
                binding,
            ) {
                Ok(context) => Some(context),
                Err(error) => {
                    reports.push(phase_level_recovery_required_report(
                        &req.actions,
                        ActionPhase::Post,
                        format!("durable post-action context construction failed: {error}"),
                    ));
                    None
                }
            },
            None => match post_action_context(req, source, None, published) {
                Ok(context) => Some(context),
                Err(error) => {
                    reports.push(phase_level_recovery_required_report(
                        &req.actions,
                        ActionPhase::Post,
                        format!("durable post-action context construction failed: {error}"),
                    ));
                    None
                }
            },
        },
            _ => None,
        }
    };
    let contexts = [pre_context, post_context];
    for context in contexts.into_iter().flatten() {
        // A fresh capability registry per context: pre and post pin the
        // SAME scope ids ("subject", "source") to DIFFERENT directories, so
        // sharing one filesystem across both fabricates scope conflicts.
        let filesystem = CapabilityActionFilesystem::new();
        let engine = ActionEngine {
            filesystem: &filesystem,
            scripts: &scripts,
        };
        match engine.durable_phase_report(&req.actions, &context) {
            Ok(Some(report)) if !report.actions.is_empty() || !report.notices.is_empty() => {
                reports.push(report)
            }
            Ok(_) => {}
            Err(error) => reports.push(ActionPhaseReport {
                phase: Some(context.phase),
                notices: vec![format!("durable action report validation failed: {error}")],
                recovery_required: true,
                ..ActionPhaseReport::default()
            }),
        }
    }
    reports
}

fn remove_preserved_source_album_artist_tag(album: &mut AlbumMetadata) {
    album
        .extra
        .remove(PRESERVED_SOURCE_ALBUM_ARTIST_TAG_EXTRA_KEY);
    album
        .extra
        .remove(PRESERVED_SOURCE_NAMING_ARTIST_EXTRA_KEY);
    album
        .extra
        .remove(LEGACY_ALBUM_ARTIST_TAG_OVERRIDE_EXTRA_KEY);
}

fn apply_batch_identity_and_request_metadata(source: &mut PreparedSource, req: &PipelineRequest) {
    if let Some(identity) = request_batch_resolved_identity(req) {
        preserve_source_tags_for_organizational_identity(source);
        if let Some(album) = identity.album.as_ref() {
            source.album_metadata.album = Some(album.clone());
        }
        if let Some(album_artist) = identity.album_artist.as_ref() {
            source.album_metadata.album_artist = Some(album_artist.clone()).into();
        }
        if let Some(date) = identity.date.as_ref() {
            source.album_metadata.date = Some(date.clone());
        }
        if let Some(total_discs) = identity.total_discs {
            source.album_metadata.total_discs = Some(total_discs);
        }
        for track in &mut source.tracks {
            let disc = identity
                .disc_number_for_path(&source.container)
                .or_else(|| identity.disc_number_for_path(track_source_identity_path(track)));
            if let Some(disc) = disc {
                if track.id.disc_number.is_none() {
                    track.id.disc_number = Some(disc);
                }
                if track.metadata.disc_number.is_none() {
                    track.metadata.disc_number = Some(disc);
                }
            }
        }
    }

    match &req.metadata_overrides.album_artist {
        MetadataTextOverride::Keep => {}
        MetadataTextOverride::Clear => {
            source.album_metadata.album_artist = None.into();
            remove_preserved_source_album_artist_tag(&mut source.album_metadata);
            source
                .album_metadata
                .extra
                .remove(EXPLICIT_ALBUM_ARTIST_OVERRIDE_EXTRA_KEY);
            source.album_metadata.extra.insert(
                EXPLICIT_ALBUM_ARTIST_CLEAR_EXTRA_KEY.to_string(),
                "1".to_string(),
            );
            for track in &mut source.tracks {
                track.metadata.album_artist = None.into();
                track
                    .metadata
                    .extra
                    .remove(EXPLICIT_ALBUM_ARTIST_OVERRIDE_EXTRA_KEY);
                track.metadata.extra.insert(
                    EXPLICIT_ALBUM_ARTIST_CLEAR_EXTRA_KEY.to_string(),
                    "1".to_string(),
                );
            }
        }
        MetadataTextOverride::Set(value) => {
            let value = value.trim();
            if !value.is_empty() {
                source.album_metadata.album_artist = Some(value.to_string()).into();
                remove_preserved_source_album_artist_tag(&mut source.album_metadata);
                source
                    .album_metadata
                    .extra
                    .remove(EXPLICIT_ALBUM_ARTIST_CLEAR_EXTRA_KEY);
                source.album_metadata.extra.insert(
                    EXPLICIT_ALBUM_ARTIST_OVERRIDE_EXTRA_KEY.to_string(),
                    value.to_string(),
                );
                for track in &mut source.tracks {
                    track.metadata.album_artist = Some(value.to_string()).into();
                    track
                        .metadata
                        .extra
                        .remove(EXPLICIT_ALBUM_ARTIST_CLEAR_EXTRA_KEY);
                    track.metadata.extra.insert(
                        EXPLICIT_ALBUM_ARTIST_OVERRIDE_EXTRA_KEY.to_string(),
                        value.to_string(),
                    );
                }
            }
        }
    }
}

fn preserve_source_tags_for_organizational_identity(source: &mut PreparedSource) {
    let album = &mut source.album_metadata;
    if !album.extra.contains_key(PRESERVED_SOURCE_ALBUM_TAG_EXTRA_KEY) {
        if let Some(original) = album
            .extra
            .get("album")
            .cloned()
            .or_else(|| album.album.clone())
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty())
        {
            album
                .extra
                .insert(PRESERVED_SOURCE_ALBUM_TAG_EXTRA_KEY.to_string(), original);
        }
    }
    if !album
        .extra
        .contains_key(PRESERVED_SOURCE_ALBUM_ARTIST_TAG_EXTRA_KEY)
    {
        if let Some(original) = album
            .album_artist
            .as_ref()
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty())
        {
            album.extra.insert(
                PRESERVED_SOURCE_ALBUM_ARTIST_TAG_EXTRA_KEY.to_string(),
                original,
            );
        }
    }

    // A common source layout has no ALBUMARTIST tag at all: the album-level
    // naming identity falls back to the first track ARTIST. Batch resolution
    // subsequently fills album_artist with an organizational spelling, which
    // otherwise shadows that fallback. Preserve the pre-mutation naming value
    // separately from tag-writing authority so folder tokens retain the exact
    // source spelling without inventing an ALBUMARTIST metadata tag.
    if !album
        .extra
        .contains_key(PRESERVED_SOURCE_NAMING_ARTIST_EXTRA_KEY)
        && !album
            .extra
            .contains_key(PRESERVED_SOURCE_ALBUM_ARTIST_TAG_EXTRA_KEY)
    {
        if let Some(original) = source
            .tracks
            .iter()
            .find_map(|track| track.metadata.artist.as_deref())
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            album.extra.insert(
                PRESERVED_SOURCE_NAMING_ARTIST_EXTRA_KEY.to_string(),
                original.to_string(),
            );
        }
    }
}

fn track_source_identity_path(track: &PreparedTrack) -> &Path {
    match &track.source_ref {
        TrackSourceRef::StagedFile(path) => path.as_path(),
        TrackSourceRef::CueStreamSegment { source_image, .. }
        | TrackSourceRef::CueSegmentCarrier { source_image, .. } => source_image.as_path(),
        TrackSourceRef::ImageSegment { image, .. } => image.as_path(),
        TrackSourceRef::SacdTrack { iso, .. } => iso.as_path(),
        TrackSourceRef::DvdaTrack { volume_source, .. } => volume_source.root_or_image().as_path(),
        TrackSourceRef::DvdVideoTrack { source, .. } => source.as_path(),
        TrackSourceRef::BluRayTrack { source, .. } => source.as_path(),
    }
}


// ===========================================================================
// Scheduler split points
// ===========================================================================

/// Materialization result used by the processor-level shared scheduler.
pub enum ScheduledMaterialization {
    Ready(ScheduledAlbum),
    Finished(PipelineReport),
}

/// Album state held by the global scheduler between materialization, track
/// encoding, and album-level post-processing. The run lock stays alive for the
/// whole album so two workers cannot mutate the same staging root.
pub struct ScheduledAlbum {
    pub req: PipelineRequest,
    pub item_id: String,
    pub staging: StagingDir,
    pub source: PreparedSource,
    pub plan: AlbumPlan,
    pub stages: Vec<StageRecord>,
    pub(crate) source_replaygain: Option<crate::convert::replaygain::ReplayGainSourceScan>,
    action_output: Option<PipelineOutputCapability>,
    _run_lock: FileLock,
}

impl ScheduledAlbum {
    pub fn track_count(&self) -> usize {
        self.source.tracks.len()
    }

    pub fn allow_partial(&self) -> bool {
        self.req.failure_policy == FailurePolicy::AllowPartialAlbum
    }

    pub fn convert_root(&self) -> PathBuf {
        self.staging.root.join("converted")
    }

    pub fn planned_final_path(&self, track_id: &TrackId) -> Option<PathBuf> {
        self.plan
            .entries
            .iter()
            .find(|entry| &entry.track_id == track_id)
            .map(|entry| entry.final_path.clone())
    }
}

#[cfg(test)]
pub(crate) fn scheduled_album_for_test(
    req: PipelineRequest,
    item_id: String,
    staging: StagingDir,
    source: PreparedSource,
    plan: AlbumPlan,
    stages: Vec<StageRecord>,
    run_lock_parent: &Path,
) -> ScheduledAlbum {
    let run_lock = acquire_run_lock(run_lock_parent, &req.job_id, &req.item_id)
        .expect("scheduled album test run lock");
    ScheduledAlbum {
        req,
        item_id,
        staging,
        source,
        plan,
        stages,
        source_replaygain: None,
        action_output: None,
        _run_lock: run_lock,
    }
}

async fn execute_pre_actions_stage_with_runner(
    req: &PipelineRequest,
    retained_output: Option<&PipelineOutputCapability>,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    scripts: &dyn ActionScriptRunner,
) -> StageRecord {
    emit_stage_started(reporter, &req.item_id, PipelineStage::PreActions).await;
    let outcome = match conversion_action_scope_for_request(req) {
        Ok(ConversionActionAlbumScope::FlatLayoutSkipped { reason }) => {
            log::warn!("{reason}");
            StageOutcome::Skipped
        }
        Ok(ConversionActionAlbumScope::Disabled) => StageOutcome::Skipped,
        Err(error) => StageOutcome::Failed(error),
        Ok(ConversionActionAlbumScope::ProperSubdirectory) => {
            match pre_action_context_with_output_capability(req, retained_output)
                .and_then(|context| run_elected_action_phase_with_runner(req, &context, cancel, scripts))
            {
                Ok(execution) if execution.error.is_none() && !execution.report.has_errors() => {
                    StageOutcome::Ok
                }
                Ok(execution) => StageOutcome::Failed(execution.error.unwrap_or_else(|| {
                    if execution.recoverable_interruption {
                        "pre actions were interrupted after mutation; durable recovery is required"
                            .to_string()
                    } else {
                        "pre action pipeline completed with errors".to_string()
                    }
                })),
                Err(error) => StageOutcome::Failed(error.to_string()),
            }
        }
    };
    let record = stage_record(PipelineStage::PreActions, outcome);
    emit_stage_finished(reporter, &req.item_id, record.clone()).await;
    record
}

async fn execute_pre_actions_stage(
    req: &PipelineRequest,
    retained_output: Option<&PipelineOutputCapability>,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
) -> StageRecord {
    let scripts = ProcessGroupScriptRunner;
    execute_pre_actions_stage_with_runner(req, retained_output, reporter, cancel, &scripts).await
}

fn post_action_outcome_with_terminal_authority(
    req: &PipelineRequest,
    coordination_io_dir: Option<&Path>,
    outcome: StageOutcome,
    terminal: bool,
) -> StageOutcome {
    if !terminal {
        return outcome;
    }
    let terminal_result = match coordination_io_dir {
        Some(coord_dir) => mark_conversion_log_batch_post_actions_terminal_at(req, coord_dir),
        None => mark_conversion_log_batch_post_actions_terminal(req),
    };
    match terminal_result {
        Ok(()) => outcome,
        Err(error) => {
            let authority_error = format!(
                "post-action result could not be committed to durable batch lifecycle authority: {error}"
            );
            match outcome {
                StageOutcome::Failed(message) => {
                    StageOutcome::Failed(format!("{message}; {authority_error}"))
                }
                StageOutcome::Ok
                | StageOutcome::NotRequested
                | StageOutcome::Skipped
                | StageOutcome::SkippedWithReason(_) => StageOutcome::Failed(authority_error),
            }
        }
    }
}


#[derive(Debug)]
struct ActionCoordinationIoBinding {
    _output_root: PinnedDirectoryCapability,
    io_dir: PathBuf,
}

impl ActionCoordinationIoBinding {
    fn capture(
        req: &PipelineRequest,
        lock: &ExplicitActionRunLock,
    ) -> Result<Self, ActionError> {
        let logical_output_root = lock.logical_output_root().ok_or_else(|| {
            ActionError::Conflict(
                "action transition lacks a retained logical output root".to_string(),
            )
        })?;
        let output_root = lock.retained_output_root()?.ok_or_else(|| {
            ActionError::Conflict(
                "action transition lacks a retained output-root capability".to_string(),
            )
        })?;
        let stable = absolute_normalized_action_path(&action_coordination_dir(req));
        let relative = stable.strip_prefix(logical_output_root).map_err(|_| {
            ActionError::UnsafePath(format!(
                "action coordination directory {} is outside retained output root {}",
                stable.display(),
                logical_output_root.display()
            ))
        })?;
        let _coordination = output_root.open_directory_descendant(relative, true, 0o700)?;
        let io_dir = output_root.descriptor_path()?.join(relative);
        Ok(Self {
            _output_root: output_root,
            io_dir,
        })
    }
}

#[derive(Debug)]
struct PublicationCapabilityBinding {
    logical_output_root: PathBuf,
    output_root: PinnedDirectoryCapability,
    logical_album_dir: PathBuf,
    album: PinnedDirectoryCapability,
}

impl PublicationCapabilityBinding {
    fn capture(
        lock: &ExplicitActionRunLock,
        logical_album_dir: &Path,
    ) -> Result<Option<Self>, PublishError> {
        let Some(logical_output_root) = lock.logical_output_root().map(Path::to_path_buf) else {
            return Ok(None);
        };
        let output_root = lock.retained_output_root().map_err(|error| {
            PublishError::Io(io::Error::new(
                io::ErrorKind::Other,
                format!("could not retain output coordination capability: {error}"),
            ))
        })?.ok_or_else(|| {
            PublishError::Io(io::Error::new(
                io::ErrorKind::Other,
                "publication authority lost its output coordination capability",
            ))
        })?;
        let album = lock.retained_publication_album().map_err(|error| {
            PublishError::Io(io::Error::new(
                io::ErrorKind::Other,
                format!("could not retain published album capability: {error}"),
            ))
        })?;
        Ok(Some(Self {
            logical_output_root,
            output_root,
            logical_album_dir: absolute_normalized_action_path(logical_album_dir),
            album,
        }))
    }

    fn coordination_dir(&self, req: &PipelineRequest) -> Result<PathBuf, io::Error> {
        let stable = conversion_log_batch_coordination_album_dir(req).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "conversion-log batch coordination requires album batch context",
            )
        })?;
        let relative = stable.strip_prefix(&self.logical_output_root).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "coordination directory {} is outside retained output root {}",
                    stable.display(),
                    self.logical_output_root.display()
                ),
            )
        })?;
        let _coordination = self
            .output_root
            .open_directory_descendant(relative, true, 0o700)
            .map_err(|error| io::Error::new(io::ErrorKind::Other, error.to_string()))?;
        self.output_root
            .descriptor_path()
            .map(|root| root.join(relative))
            .map_err(|error| io::Error::new(io::ErrorKind::Other, error.to_string()))
    }

    fn io_path(&self, stable: &Path) -> Result<PathBuf, io::Error> {
        let stable = absolute_normalized_action_path(stable);
        if stable == self.logical_album_dir || path_is_under_root(&stable, &self.logical_album_dir) {
            let relative = stable.strip_prefix(&self.logical_album_dir).map_err(|_| {
                io::Error::new(io::ErrorKind::InvalidInput, "album path rebase failed")
            })?;
            return self
                .album
                .descriptor_path()
                .map(|root| root.join(relative))
                .map_err(|error| io::Error::new(io::ErrorKind::Other, error.to_string()));
        }
        let relative = stable.strip_prefix(&self.logical_output_root).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "transaction path {} is outside retained output root {}",
                    stable.display(),
                    self.logical_output_root.display()
                ),
            )
        })?;
        self.output_root
            .descriptor_path()
            .map(|root| root.join(relative))
            .map_err(|error| io::Error::new(io::ErrorKind::Other, error.to_string()))
    }

    fn stable_path(&self, runtime: &Path) -> PathBuf {
        if let Ok(album_root) = self.album.descriptor_path() {
            if let Ok(relative) = runtime.strip_prefix(&album_root) {
                return self.logical_album_dir.join(relative);
            }
        }
        if let Ok(output_root) = self.output_root.descriptor_path() {
            if let Ok(relative) = runtime.strip_prefix(&output_root) {
                return self.logical_output_root.join(relative);
            }
        }
        runtime.to_path_buf()
    }
}

#[derive(Debug)]
enum AlbumActionPublishAuthority {
    NoActionsUntracked,
    NoActionsLocked {
        lock: Option<ExplicitActionRunLock>,
        retire_identity_after_publish: bool,
    },
    FlatLayoutSkipped { reason: String },
    MultiRootTransition {
        locks: Vec<ExplicitActionRunLock>,
        retire_identity_after_publish: Vec<bool>,
        post_skip_reason: Option<String>,
    },
    Locked(Option<ExplicitActionRunLock>),
}

impl AlbumActionPublishAuthority {
    fn lock(&self) -> Option<&ExplicitActionRunLock> {
        match self {
            Self::Locked(lock) | Self::NoActionsLocked { lock, .. } => lock.as_ref(),
            Self::NoActionsUntracked
            | Self::FlatLayoutSkipped { .. }
            | Self::MultiRootTransition { .. } => None,
        }
    }

    fn take_lock(&mut self) -> Option<ExplicitActionRunLock> {
        match self {
            Self::Locked(lock) | Self::NoActionsLocked { lock, .. } => lock.take(),
            Self::NoActionsUntracked
            | Self::FlatLayoutSkipped { .. }
            | Self::MultiRootTransition { .. } => None,
        }
    }

    fn release_publication_lock(&mut self) {
        if let Some(lock) = match self {
            Self::Locked(lock) | Self::NoActionsLocked { lock, .. } => lock.as_mut(),
            Self::NoActionsUntracked
            | Self::FlatLayoutSkipped { .. }
            | Self::MultiRootTransition { .. } => None,
        } {
            lock.release_publication_authority();
        }
    }

    fn release_all_authority(&mut self) {
        drop(self.take_lock());
        self.release_multi_root_authority();
    }

    fn multi_root_locks(&self) -> Option<&[ExplicitActionRunLock]> {
        match self {
            Self::MultiRootTransition { locks, .. } => Some(locks),
            _ => None,
        }
    }

    fn release_multi_root_authority(&mut self) {
        if let Self::MultiRootTransition { locks, .. } = self {
            locks.clear();
        }
    }

    fn reject_late_action_authority(&self) -> bool {
        matches!(self, Self::NoActionsUntracked)
    }
}

fn published_album_bound_to_authority(
    published: &PublishedAlbum,
    lock: &ExplicitActionRunLock,
) -> Result<PublishedAlbum, PublishError> {
    let bound_album_dir = lock.descriptor_relative_album_dir().map_err(|error| {
        PublishError::Io(io::Error::new(
            io::ErrorKind::Other,
            format!("could not bind published album to retained authority: {error}"),
        ))
    })?;
    let lexical_album_dir = absolute_normalized_action_path(&published.album_dir);
    let mut bound = published.clone();
    bound.album_dir = bound_album_dir.clone();
    for entry in &mut bound.entries {
        entry.final_path = rebase_action_path(
            &entry.final_path,
            &lexical_album_dir,
            &bound_album_dir,
        );
    }
    if let Some(manifest_path) = bound.manifest_path.as_mut() {
        *manifest_path = rebase_action_path(
            manifest_path,
            &lexical_album_dir,
            &bound_album_dir,
        );
    }
    Ok(bound)
}

fn prepare_identity_transition_for_publish_locked(
    album_dir: &Path,
    lock: &ExplicitActionRunLock,
    publication_kind: &str,
) -> Result<bool, PublishError> {
    let _recovered_invalidation = recover_identity_invalidation_locked(album_dir, lock)
        .map_err(|error| PublishError::Io(io::Error::new(io::ErrorKind::Other, error)))?;
    ensure_album_publication_has_no_unresolved_explicit_state(lock, album_dir).map_err(|error| {
        PublishError::Io(io::Error::new(
            io::ErrorKind::Other,
            format!(
                "{publication_kind} album publish found unresolved manual recovery authority: {error}"
            ),
        ))
    })?;
    let album = lock.album_capability().map_err(|error| {
        PublishError::Io(io::Error::new(
            io::ErrorKind::Other,
            format!("could not retain publication album capability: {error}"),
        ))
    })?;
    let identity_present = album
        .read_regular_child_optional(std::ffi::OsStr::new(CONVERSION_ACTION_IDENTITY_FILE))
        .map_err(|error| {
            PublishError::Io(io::Error::new(
                io::ErrorKind::Other,
                format!("could not inspect canonical action identity: {error}"),
            ))
        })?
        .is_some();
    if identity_present {
        stage_identity_invalidation_locked(album_dir, lock)
            .map_err(|error| PublishError::Io(io::Error::new(io::ErrorKind::Other, error)))?;
    }
    Ok(identity_present)
}

fn acquire_album_action_authority_for_publish(
    req: &PipelineRequest,
    album_dir: &Path,
    retained_output: Option<&PipelineOutputCapability>,
) -> Result<AlbumActionPublishAuthority, PublishError> {
    match conversion_action_album_scope(req, album_dir).map_err(|message| {
        PublishError::Io(io::Error::new(io::ErrorKind::InvalidInput, message))
    })? {
        ConversionActionAlbumScope::Disabled => {
            // Preserve the historical empty-pipeline path unless the album
            // already carries action identity/recovery authority. The normal
            // publisher's existing shared-filesystem album lock serializes the
            // first identity import. After taking that lock, publication
            // rechecks that no authority appeared; if one did, it aborts before
            // mutation and the retry enters the locked transition below.
            let has_action_authority = album_dir.is_dir()
                && (album_dir.join(CONVERSION_ACTION_IDENTITY_FILE).exists()
                    || album_dir.join(CONVERSION_ACTION_IDENTITY_INVALIDATION_FILE).exists()
                    || album_dir.join(".tonepoet-actions-manual").exists());
            if !has_action_authority {
                return Ok(AlbumActionPublishAuthority::NoActionsUntracked);
            }
            let lock = match retained_output {
                Some(binding) => acquire_explicit_action_run_lock_for_album_under_output_capability(
                    album_dir,
                    &binding.logical_root,
                    &binding.capability,
                ),
                None => acquire_explicit_action_run_lock_for_album_in_output_root(
                    album_dir,
                    &req.output_root,
                ),
            }.map_err(|error| {
                PublishError::Io(io::Error::new(
                    io::ErrorKind::Other,
                    format!(
                        "could not serialize actionless album republication with existing identity/manual authority: {error}"
                    ),
                ))
            })?;
            let retire_identity_after_publish =
                prepare_identity_transition_for_publish_locked(album_dir, &lock, "actionless")?;
            Ok(AlbumActionPublishAuthority::NoActionsLocked {
                lock: Some(lock),
                retire_identity_after_publish,
            })
        }
        ConversionActionAlbumScope::FlatLayoutSkipped { reason } => {
            // SR-2: make the flat-layout decision before opening any action
            // authority or persisting any action-owned file in the shared root.
            Ok(AlbumActionPublishAuthority::FlatLayoutSkipped { reason })
        }
        ConversionActionAlbumScope::ProperSubdirectory => {
            // Per-track publishes of an action-enabled album arrive
            // concurrently from the worker pool; they must WAIT on the album
            // authority (interactive acquisitions fail fast instead).
            let lock = match retained_output {
                Some(binding) => acquire_blocking_action_run_lock_for_album_under_output_capability(
                    album_dir,
                    &binding.logical_root,
                    &binding.capability,
                ),
                None => acquire_blocking_action_run_lock_for_album_in_output_root(
                    album_dir,
                    &req.output_root,
                ),
            }.map_err(|error| {
                PublishError::Io(io::Error::new(
                    io::ErrorKind::Other,
                    format!(
                        "could not acquire stable album identity/manual-run authority before publish: {error}"
                    ),
                ))
            })?;
            if album_dir.is_dir() {
                let _identity_was_present =
                    prepare_identity_transition_for_publish_locked(album_dir, &lock, "action-enabled")?;
            }
            Ok(AlbumActionPublishAuthority::Locked(Some(lock)))
        }
    }
}

fn acquire_album_action_authority_for_plan(
    req: &PipelineRequest,
    plan: &AlbumPlan,
    retained_output: Option<&PipelineOutputCapability>,
) -> Result<AlbumActionPublishAuthority, PublishError> {
    let mut album_dirs = planned_album_dirs(plan);
    if album_dirs.len() <= 1 {
        return acquire_album_action_authority_for_publish(req, &plan.album_dir, retained_output);
    }
    if req.actions.is_empty() {
        return Ok(AlbumActionPublishAuthority::NoActionsUntracked);
    }

    album_dirs.sort_by(|left, right| {
        absolute_normalized_action_path(left).cmp(&absolute_normalized_action_path(right))
    });
    album_dirs.dedup_by(|left, right| {
        absolute_normalized_action_path(left) == absolute_normalized_action_path(right)
    });

    // A configured pre-only pipeline must not disable a supported multi-root
    // layout. Hold every rendered root's shared-filesystem publication lock in
    // deterministic order across the umbrella transaction. Post actions have
    // no unambiguous single album scope, so they are explicitly skipped after
    // successful publication rather than turning publication into a failure.
    let mut locks = Vec::with_capacity(album_dirs.len());
    let mut retire_identity_after_publish = Vec::with_capacity(album_dirs.len());
    for album_dir in &album_dirs {
        let lock = match retained_output {
            Some(binding) => acquire_blocking_album_publication_lock_for_album_under_output_capability(
                album_dir,
                &binding.logical_root,
                &binding.capability,
            ),
            None => acquire_blocking_album_publication_lock_for_album_in_output_root(
                album_dir,
                &req.output_root,
            ),
        }
        .map_err(|error| {
            PublishError::Io(io::Error::new(
                io::ErrorKind::Other,
                format!(
                    "could not acquire ordered multi-root publication authority for {}: {error}",
                    album_dir.display()
                ),
            ))
        })?;
        let retire = if album_dir.is_dir() {
            prepare_identity_transition_for_publish_locked(
                album_dir,
                &lock,
                "multi-root action pipeline",
            )?
        } else {
            false
        };
        locks.push(lock);
        retire_identity_after_publish.push(retire);
    }

    let post_skip_reason = (!req.actions.post.is_empty()).then(|| {
        format!(
            "post actions were skipped because this conversion publishes {} independent rendered album roots and has no single safe post-action album scope",
            album_dirs.len()
        )
    });
    Ok(AlbumActionPublishAuthority::MultiRootTransition {
        locks,
        retire_identity_after_publish,
        post_skip_reason,
    })
}

fn retire_multi_root_action_identities(
    published: &PublishedAlbum,
    authority: &AlbumActionPublishAuthority,
) -> Result<Option<String>, String> {
    let AlbumActionPublishAuthority::MultiRootTransition {
        locks,
        retire_identity_after_publish,
        post_skip_reason,
    } = authority
    else {
        return Ok(None);
    };
    if locks.len() != retire_identity_after_publish.len() {
        return Err("multi-root identity retirement authority is internally inconsistent".to_string());
    }
    for (lock, retire) in locks.iter().zip(retire_identity_after_publish) {
        if *retire {
            retire_conversion_action_identity_locked(published, lock).map_err(|error| {
                format!(
                    "could not retire stale action identity for multi-root album {}: {error}",
                    lock.canonical_album_dir().display()
                )
            })?;
        }
    }
    Ok(post_skip_reason.clone())
}

async fn execute_post_actions_stage_with_runner(
    req: &PipelineRequest,
    source: &PreparedSource,
    artifacts: Option<&ArtifactSet>,
    published: &PublishedAlbum,
    authority: &mut AlbumActionPublishAuthority,
    gate: PostActionGate,
    album_is_fully_successful: bool,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    scripts: &dyn ActionScriptRunner,
) -> Option<StageRecord> {
    // Pre-only pipelines do not require a post-publication identity. If an
    // earlier generation carried one, retire it under the publication lock;
    // otherwise preserve the historical no-post-actions path.
    if req.actions.post.is_empty() {
        let retirement = match authority {
            AlbumActionPublishAuthority::NoActionsLocked {
                lock: Some(lock),
                retire_identity_after_publish: true,
            } => retire_conversion_action_identity_locked(published, lock),
            AlbumActionPublishAuthority::MultiRootTransition { .. } => {
                retire_multi_root_action_identities(published, authority).map(|_| ())
            }
            _ => Ok(()),
        };
        authority.release_all_authority();
        if let Err(error) = retirement {
            emit_stage_started(reporter, &req.item_id, PipelineStage::PostActions).await;
            let record = stage_record(
                PipelineStage::PostActions,
                StageOutcome::Failed(format!(
                    "publication could not retire stale action identity: {error}"
                )),
            );
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            return Some(record);
        }
        return None;
    }

    if matches!(authority, AlbumActionPublishAuthority::MultiRootTransition { .. }) {
        emit_stage_started(reporter, &req.item_id, PipelineStage::PostActions).await;
        let result = retire_multi_root_action_identities(published, authority);
        authority.release_all_authority();
        let outcome = match result {
            Ok(Some(reason)) => {
                log::warn!("{reason}");
                StageOutcome::Skipped
            }
            Ok(None) => StageOutcome::Skipped,
            Err(error) => StageOutcome::Failed(error),
        };
        let record = stage_record(PipelineStage::PostActions, outcome);
        emit_stage_finished(reporter, &req.item_id, record.clone()).await;
        return Some(record);
    }

    if let AlbumActionPublishAuthority::FlatLayoutSkipped { reason } = authority {
        if req.actions.post.is_empty() {
            return None;
        }
        log::warn!("{reason}");
        emit_stage_started(reporter, &req.item_id, PipelineStage::PostActions).await;
        let record = stage_record(PipelineStage::PostActions, StageOutcome::Skipped);
        emit_stage_finished(reporter, &req.item_id, record.clone()).await;
        return Some(record);
    }

    if authority.lock().is_none() {
        let record = stage_record(
            PipelineStage::PostActions,
            StageOutcome::Failed(
                "action-enabled conversion reached identity persistence without album authority"
                    .to_string(),
            ),
        );
        emit_stage_finished(reporter, &req.item_id, record.clone()).await;
        return Some(record);
    }

    // While the album authority is held, publish the PRE journal's album
    // identity attestation. Every participant passes here before its
    // finalize, so a no-binding finalize (or one arriving before the
    // binding owner's) can authenticate the publish-created album root.
    if let Some(lock) = authority.lock() {
        match PublicationCapabilityBinding::capture(lock, lock.canonical_album_dir()) {
            Ok(attest_binding) => {
                attest_publication_album_scope_best_effort(req, attest_binding.as_ref())
            }
            Err(error) => log::warn!(
                "post-stage album identity attestation binding failed for {}: {error}",
                req.item_id
            ),
        }
    }

    let action_coordination = match authority
        .lock()
        .map(|lock| ActionCoordinationIoBinding::capture(req, lock))
        .transpose()
    {
        Ok(binding) => binding,
        Err(error) => {
            authority.release_all_authority();
            let record = stage_record(
                PipelineStage::PostActions,
                StageOutcome::Failed(format!(
                    "post actions refused because output-root coordination could not be retained: {error}"
                )),
            );
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            return Some(record);
        }
    };

    // Establish ownership and the immutable participant/post-action lifecycle
    // manifest before an elected post action can reach any terminal result.
    if req.album_batch.is_some() && !req.actions.post.is_empty() {
        let ownership_result = match action_coordination.as_ref() {
            Some(binding) => ensure_conversion_log_batch_workspace_owned_for_request_at(
                req,
                &binding.io_dir,
            ),
            None => ensure_conversion_log_batch_workspace_owned_for_request(req),
        };
        if let Err(error) = ownership_result {
            authority.release_all_authority();
            let record = stage_record(
                PipelineStage::PostActions,
                StageOutcome::Failed(format!(
                    "post actions refused because batch recovery/drain authority could not be established: {error}"
                )),
            );
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            return Some(record);
        }
    }

    if album_is_fully_successful {
        let persist_result = authority
            .lock()
            .ok_or_else(|| {
                "action-enabled conversion lost album authority before identity persistence"
                    .to_string()
            })
            .and_then(|identity_lock| {
                persist_conversion_action_identity_locked(req, source, published, identity_lock)
            });
        if let Err(error) = persist_result {
            authority.release_all_authority();
            let outcome = post_action_outcome_with_terminal_authority(
                req,
                action_coordination.as_ref().map(|binding| binding.io_dir.as_path()),
                StageOutcome::Failed(format!(
                    "actions refused because canonical action identity could not be persisted: {error}"
                )),
                !req.actions.post.is_empty(),
            );
            let record = stage_record(PipelineStage::PostActions, outcome);
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            return Some(record);
        }
    }

    if req.actions.post.is_empty() {
        authority.release_all_authority();
        return None;
    }
    if !album_is_fully_successful {
        authority.release_all_authority();
        let outcome = post_action_outcome_with_terminal_authority(
            req,
            action_coordination.as_ref().map(|binding| binding.io_dir.as_path()),
            StageOutcome::Failed(
                "post actions skipped because the album did not complete successfully".to_string(),
            ),
            true,
        );
        let record = stage_record(PipelineStage::PostActions, outcome);
        emit_stage_finished(reporter, &req.item_id, record.clone()).await;
        return Some(record);
    }

    match gate {
        PostActionGate::NotReady => {
            authority.release_all_authority();
            return None;
        }
        PostActionGate::Failed => {
            authority.release_all_authority();
            let outcome = post_action_outcome_with_terminal_authority(
                req,
                action_coordination.as_ref().map(|binding| binding.io_dir.as_path()),
                StageOutcome::Failed(
                    "post actions skipped because companion finalization did not satisfy its warning-free success gate"
                        .to_string(),
                ),
                true,
            );
            let record = stage_record(PipelineStage::PostActions, outcome);
            emit_stage_finished(reporter, &req.item_id, record.clone()).await;
            return Some(record);
        }
        PostActionGate::Ready => {}
    }

    emit_stage_started(reporter, &req.item_id, PipelineStage::PostActions).await;

    // While the publication lock is still held, pin the exact published album
    // object and establish the durable election/claim that authorizes the post
    // phase. The lock is then released before any waiter polling, filesystem
    // action, or arbitrary script executes. The retained album descriptor keeps
    // every action path bound to the published object across parent renames or
    // mount/path replacement.
    let prepared = (|| -> Result<
        (
            PinnedDirectoryCapability,
            ActionContext,
            PreparedActionElection,
        ),
        ActionError,
    > {
        let identity_lock = authority.lock().ok_or_else(|| {
            ActionError::Conflict(
                "post-action transition lost album publication authority".to_string(),
            )
        })?;
        let retained_album = identity_lock.retained_publication_album()?;
        let retained_output = identity_lock.retained_output_root()?.ok_or_else(|| {
            ActionError::Conflict(
                "post-action transition lost retained output-root capability".to_string(),
            )
        })?;
        let context = post_action_context_with_capabilities(
            req,
            source,
            artifacts,
            published,
            identity_lock.canonical_album_dir(),
            Some(retained_album.try_clone()?),
            Some(retained_output),
        )?;
        let election = prepare_action_election(req, &context)?;
        Ok((retained_album, context, election))
    })();

    if prepared.is_ok() {
        authority.release_publication_lock();
    } else {
        authority.release_all_authority();
    }

    let (outcome, terminal) = match prepared.and_then(
        |(retained_album, context, election)| {
            let execution = execute_prepared_action_election_with_runner(
                req,
                &context,
                cancel,
                election,
                scripts,
            );
            // Keep the descriptor alive through the complete action phase.
            drop(retained_album);
            execution
        },
    ) {
        Ok(execution) if execution.error.is_none() && !execution.report.has_errors() => {
            (StageOutcome::Ok, true)
        }
        Ok(execution) => {
            let recoverable_interruption = execution.recoverable_interruption;
            let message = execution.error.unwrap_or_else(|| {
                if recoverable_interruption {
                    "post actions were interrupted after mutation; durable recovery is required"
                        .to_string()
                } else {
                    "post action pipeline completed with errors".to_string()
                }
            });
            (StageOutcome::Failed(message), !recoverable_interruption)
        }
        Err(error) => {
            // Election/ownership/journal errors are not a terminal action
            // decision. Preserve the workspace so a restored queue or manual
            // recovery can re-establish authority and retry safely.
            (StageOutcome::Failed(error.to_string()), false)
        }
    };
    authority.release_all_authority();
    let outcome = post_action_outcome_with_terminal_authority(
        req,
        action_coordination.as_ref().map(|binding| binding.io_dir.as_path()),
        outcome,
        terminal,
    );
    let record = stage_record(PipelineStage::PostActions, outcome);
    emit_stage_finished(reporter, &req.item_id, record.clone()).await;
    Some(record)
}

async fn execute_post_actions_stage(
    req: &PipelineRequest,
    source: &PreparedSource,
    artifacts: Option<&ArtifactSet>,
    published: &PublishedAlbum,
    authority: &mut AlbumActionPublishAuthority,
    gate: PostActionGate,
    album_is_fully_successful: bool,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
) -> Option<StageRecord> {
    let scripts = ProcessGroupScriptRunner;
    execute_post_actions_stage_with_runner(
        req,
        source,
        artifacts,
        published,
        authority,
        gate,
        album_is_fully_successful,
        reporter,
        cancel,
        &scripts,
    )
    .await
}


fn register_execution_claims(
    req: &PipelineRequest,
    family: crate::concurrency::LeaseFamily,
    claims: Vec<crate::concurrency::PathClaim>,
    coordination_group: Option<String>,
) -> Result<(), String> {
    if crate::concurrency::runtime_execution_id(&req.item_id).is_none() {
        return Ok(());
    }
    let lease = crate::concurrency::MutationClaimGuard::acquire_grouped(
        family, claims, coordination_group
    )?.into_lease();
    crate::concurrency::register_runtime_supplemental_lease(&req.item_id, Arc::new(lease))
}

fn admit_initial_conversion_claims(req: &mut PipelineRequest) -> Result<(), String> {
    let Some(execution_id) = crate::concurrency::runtime_execution_id(&req.item_id) else {
        return Ok(());
    };
    // Resolve the mutable namespace aliases before taking registry authority.
    // The claims retain the lexical namespace identities, while the request is
    // rebound to the admitted resolved I/O identities for every later stage.
    let source_scope = if std::fs::metadata(&req.container).is_ok_and(|metadata| metadata.is_dir()) {
        crate::concurrency::ClaimScope::Subtree
    } else {
        crate::concurrency::ClaimScope::Exact
    };
    let source = crate::concurrency::PathClaim::resolve(
        &req.container,
        crate::concurrency::ClaimMode::Read,
        source_scope,
    )?;
    let output_namespace = crate::concurrency::PathClaim::resolve(
        &req.output_root,
        crate::concurrency::ClaimMode::Read,
        crate::concurrency::ClaimScope::Exact,
    )?;
    let admitted_source = source.identity.resolved_io_path.clone();
    let admitted_output_root = output_namespace.identity.resolved_io_path.clone();
    register_execution_claims(
        req,
        crate::concurrency::LeaseFamily::ExecutionClaim { execution_id },
        vec![source, output_namespace],
        None,
    )?;
    req.container = admitted_source;
    req.output_root = admitted_output_root;
    Ok(())
}

fn planner_output_coordination_group(req: &PipelineRequest) -> Option<String> {
    req.album_batch
        .as_ref()
        .map(|batch| format!("album-batch:{}", batch.conversion_log_batch_id))
}

/// If the dispatcher already carries planner-authoritative album output
/// identity, admit that namespace before any pre-action can mutate it. Returns
/// the admitted resolved identity so ordinary planning can prove it did not
/// silently redirect the destination later.
fn admit_planner_resolved_output_claim(req: &mut PipelineRequest) -> Result<Option<PathBuf>, String> {
    let Some(execution_id) = crate::concurrency::runtime_execution_id(&req.item_id) else {
        return Ok(None);
    };
    let Some(batch) = req
        .album_batch
        .as_ref()
        .filter(|batch| batch.album_output_dir_is_planner_resolved)
    else {
        return Ok(None);
    };
    let output = crate::concurrency::PathClaim::resolve(
        &batch.album_output_dir,
        crate::concurrency::ClaimMode::Write,
        crate::concurrency::ClaimScope::Subtree,
    )?;
    let admitted = output.identity.resolved_io_path.clone();
    let coordination_group = planner_output_coordination_group(req);
    register_execution_claims(
        req,
        crate::concurrency::LeaseFamily::ExecutionClaim { execution_id },
        vec![output],
        coordination_group,
    )?;
    if let Some(batch) = req.album_batch.as_mut() {
        batch.album_output_dir = admitted.clone();
    }
    Ok(Some(admitted))
}

fn admit_planned_output_claim(
    req: &PipelineRequest,
    plan: &AlbumPlan,
    already_admitted: Option<&Path>,
) -> Result<(), String> {
    let Some(execution_id) = crate::concurrency::runtime_execution_id(&req.item_id) else {
        return Ok(());
    };
    let output = crate::concurrency::PathClaim::resolve(
        &plan.album_dir,
        crate::concurrency::ClaimMode::Write,
        crate::concurrency::ClaimScope::Subtree,
    )?;
    if let Some(admitted) = already_admitted {
        if output.identity.resolved_io_path != admitted {
            return Err(format!(
                "output planning redirected planner-authoritative album namespace from '{}' to '{}'",
                admitted.display(),
                output.identity.resolved_io_path.display(),
            ));
        }
        return Ok(());
    }
    // Independent single-file siblings in one dispatcher-authored album batch
    // intentionally co-hold the album output claim. The run-unique batch id is
    // written into each sibling's own durable ExecutionClaim descriptor, so a
    // crash leaves every participant independently RecoveryReserved.
    let coordination_group = planner_output_coordination_group(req);
    register_execution_claims(
        req,
        crate::concurrency::LeaseFamily::ExecutionClaim { execution_id },
        vec![output],
        coordination_group,
    )
}

/// Run validation, staging setup, source materialization, and output planning.
/// Track conversion is intentionally not performed here; the caller submits
/// each ready track as an independent shared-pool work unit.
pub async fn prepare_pipeline_item_for_scheduler(
    req: PipelineRequest,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    tool_paths: &HashMap<String, PathBuf>,
) -> ScheduledMaterialization {
    let req = req;
    let item_id = req.item_id.clone();
    if crate::concurrency::runtime_execution_id(&item_id).is_some() {
        crate::concurrency::with_runtime_execution_scope(
            item_id,
            prepare_pipeline_item_for_scheduler_scoped_inner(req, runner, reporter, cancel, tool_paths),
        ).await
    } else {
        prepare_pipeline_item_for_scheduler_scoped_inner(req, runner, reporter, cancel, tool_paths).await
    }
}

async fn prepare_pipeline_item_for_scheduler_scoped_inner(
    mut req: PipelineRequest,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    tool_paths: &HashMap<String, PathBuf>,
) -> ScheduledMaterialization {
    let item_id = req.item_id.clone();
    let mut stages = Vec::new();
    let source: Option<PreparedSource> = None;
    let plan: Option<AlbumPlan> = None;

    if cancel.is_cancelled() {
        let published = finalize_cancelled_conversion_log_batch_if_needed(&req);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::Cancelled,
        };
        return ScheduledMaterialization::Finished(
            finalize_report(&req, reporter, source, plan, None, published, outcome).await,
        );
    }

    if let Err(err) = validate_request(&req) {
        let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(err.to_string()));
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::MaterializeFailed,
        };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
            &req,
            &outcome,
        );
        return ScheduledMaterialization::Finished(
            finalize_report(&req, reporter, source, plan, None, published, outcome).await,
        );
    }

    if let Err(error) = admit_initial_conversion_claims(&mut req) {
        let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(format!("concurrency admission failed: {error}")));
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked { successful: Vec::new(), failed: Vec::new(), stages, reason: BlockReason::MaterializeFailed };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(&req, &outcome);
        return ScheduledMaterialization::Finished(finalize_report(&req, reporter, source, plan, None, published, outcome).await);
    }

    let admitted_planner_output = match admit_planner_resolved_output_claim(&mut req) {
        Ok(admitted) => admitted,
        Err(error) => {
            emit_stage_started(reporter, &item_id, PipelineStage::PreActions).await;
            let record = stage_record(PipelineStage::PreActions, StageOutcome::Failed(format!("output concurrency admission failed before pre-actions: {error}")));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked { successful: Vec::new(), failed: Vec::new(), stages, reason: BlockReason::RequiredStageFailure(PipelineStage::PreActions) };
            let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(&req, &outcome);
            return ScheduledMaterialization::Finished(finalize_report(&req, reporter, source, plan, None, published, outcome).await);
        }
    };

    if let Err(error) = preflight_album_conversion_tools(&req, runner) {
        emit_stage_started(reporter, &item_id, PipelineStage::Convert).await;
        let record = stage_record(PipelineStage::Convert, StageOutcome::Failed(error));
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::RequiredStageFailure(PipelineStage::Convert),
        };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
            &req,
            &outcome,
        );
        return ScheduledMaterialization::Finished(
            finalize_report(&req, reporter, source, plan, None, published, outcome).await,
        );
    }

    let action_output = match PipelineOutputCapability::capture_for_actions(&req) {
        Ok(binding) => binding,
        Err(error) => {
            emit_stage_started(reporter, &item_id, PipelineStage::PreActions).await;
            let record = stage_record(
                PipelineStage::PreActions,
                StageOutcome::Failed(format!(
                    "could not retain one output/coordination root for the action transaction: {error}"
                )),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason: BlockReason::RequiredStageFailure(PipelineStage::PreActions),
            };
            let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
                &req,
                &outcome,
            );
            return ScheduledMaterialization::Finished(
                finalize_report(&req, reporter, source, plan, None, published, outcome).await,
            );
        }
    };

    let pre_actions_ran_before_materialization =
        match prepare_batch_pre_actions_before_materialization(
            &req,
            action_output.as_ref(),
            reporter,
            cancel,
            &mut stages,
        )
        .await
        {
            PreMaterializationActionOutcome::Continue { ran_pre_actions } => ran_pre_actions,
            PreMaterializationActionOutcome::Finished(report) => {
                return ScheduledMaterialization::Finished(report)
            }
        };

    conservative_output_capacity_preflight(&req);

    emit_stage_started(reporter, &item_id, PipelineStage::Materialize).await;
    let materialization = materialize_with_optional_disk_retry(
        &req,
        select_staging_parent_for(&req),
        runner,
        Some(reporter),
        tool_paths,
        cancel,
    )
    .await;
    let (attempt, materialized) = match materialization {
        MaterializationRun::Attempted { attempt, result } => (attempt, result),
        MaterializationRun::FailedBeforeAttempt { error, context } => {
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(error.to_string()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason: BlockReason::MaterializeFailed,
            };
            let published = publish_pre_materialization_terminal_batch_failure_or_finalize(
                &req,
                &outcome,
                context,
            );
            return ScheduledMaterialization::Finished(
                finalize_report(&req, reporter, source, plan, None, published, outcome).await,
            );
        }
    };
    let (_run_lock, staging) = attempt.into_parts();

    let mut prepared = match materialized {
        Ok(prepared) => {
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Ok);
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            prepared
        }
        Err(MaterializeError::BlockedSource { message, blocked }) => {
            let blocked = *blocked;
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(message.clone()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let failed = blocked_track_records(&blocked.source, &message);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed,
                stages,
                reason: BlockReason::EncryptedSource,
            };
            let source = Some(blocked.source);
            let published = publish_terminal_conversion_log_fragment_if_needed(
                &req,
                source.as_ref(),
                None,
                &outcome,
                staging,
                Some(runner),
            );
            return ScheduledMaterialization::Finished(
                finalize_report(
                    &req,
                    reporter,
                    source,
                    None,
                    None,
                    published,
                    outcome,
                )
                .await,
            );
        }
        Err(err) => {
            let reason = if matches!(err, MaterializeError::Cancelled) {
                BlockReason::Cancelled
            } else {
                BlockReason::MaterializeFailed
            };
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(err.to_string()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason,
            };
            let published = if matches!(outcome, AlbumOutcome::Blocked { reason: BlockReason::Cancelled, .. }) {
                finalize_cancelled_conversion_log_batch_if_needed(&req)
            } else {
                publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    None,
                    None,
                    &outcome,
                    staging,
                    Some(runner),
                )
            };
            return ScheduledMaterialization::Finished(
                finalize_report(&req, reporter, None, None, None, published, outcome).await,
            );
        }
    };

    if cancel.is_cancelled() {
        let published = finalize_cancelled_conversion_log_batch_if_needed(&req);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::Cancelled,
        };
        return ScheduledMaterialization::Finished(
            finalize_report(&req, reporter, Some(prepared), None, None, published, outcome).await,
        );
    }

    enrich_source_with_label_info(&mut prepared, &req.container, &req);
    apply_batch_identity_and_request_metadata(&mut prepared, &req);

    emit_stage_started(reporter, &item_id, PipelineStage::PlanOutputs).await;
    let album_plan = match plan_outputs(&prepared, &req) {
        Ok(album_plan) => {
            let record = stage_record(PipelineStage::PlanOutputs, StageOutcome::Ok);
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            album_plan
        }
        Err(err) => {
            let plan_error = err.to_string();
            let record = stage_record(PipelineStage::PlanOutputs, StageOutcome::Failed(plan_error.clone()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let failed = failed_track_records(
                &prepared,
                &format!("output planning failed: {plan_error}"),
            );
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed,
                stages,
                reason: BlockReason::PlanFailed,
            };
            let published = publish_terminal_conversion_log_fragment_if_needed(
                &req,
                Some(&prepared),
                None,
                &outcome,
                staging,
                Some(runner),
            );
            return ScheduledMaterialization::Finished(
                finalize_report(&req, reporter, Some(prepared), None, None, published, outcome).await,
            );
        }
    };

    if let Err(error) = admit_planned_output_claim(&req, &album_plan, admitted_planner_output.as_deref()) {
        let record = stage_record(PipelineStage::PlanOutputs, StageOutcome::Failed(format!("output concurrency admission failed: {error}")));
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked { successful: Vec::new(), failed: Vec::new(), stages, reason: BlockReason::PlanFailed };
        let published = publish_terminal_conversion_log_fragment_if_needed(&req, Some(&prepared), None, &outcome, staging, Some(runner));
        return ScheduledMaterialization::Finished(finalize_report(&req, reporter, Some(prepared), Some(album_plan), None, published, outcome).await);
    }

    if let super::rerun::RerunDecision::Skip {
        manifest,
        manifest_path,
    } = decide_rerun_after_reference_preflight(
        &req,
        &prepared,
        &album_plan,
        runner,
        cancel,
    )
    .await
    {
        if !pre_actions_ran_before_materialization {
            return ScheduledMaterialization::Finished(
                finalize_manifest_skip(
                    &req,
                    reporter,
                    prepared,
                    album_plan,
                    stages,
                    manifest,
                    manifest_path,
                )
                .await,
            );
        }
        log::warn!(
            "manifest became skippable after this run durably completed pre-actions; proceeding with publication so actions are never attributed to an all-skipped run: job_id={}, item_id={}, album_dir={}",
            req.job_id,
            req.item_id,
            album_plan.album_dir.display(),
        );
    }

    if !req.actions.pre.is_empty() && !pre_actions_ran_before_materialization {
        let record = execute_pre_actions_stage(&req, action_output.as_ref(), reporter, cancel).await;
        let failed = matches!(record.outcome, StageOutcome::Failed(_));
        stages.push(record);
        if failed {
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason: BlockReason::RequiredStageFailure(PipelineStage::PreActions),
            };
            let published = publish_terminal_conversion_log_fragment_if_needed(
                &req,
                Some(&prepared),
                None,
                &outcome,
                staging,
                Some(runner),
            );
            return ScheduledMaterialization::Finished(
                finalize_report(
                    &req,
                    reporter,
                    Some(prepared),
                    Some(album_plan),
                    None,
                    published,
                    outcome,
                )
                .await,
            );
        }
    }

    ScheduledMaterialization::Ready(ScheduledAlbum {
        item_id,
        req,
        staging,
        source: prepared,
        plan: album_plan,
        stages,
        source_replaygain: None,
        action_output,
        _run_lock,
    })
}

/// Encode one contiguous set of streamable CUE tracks that share one image.
///
/// The ordinary per-track planner remains authoritative. We coalesce only when
/// every track independently plans as one source-rate/no-DSP FFmpeg encode.
/// Otherwise the group falls back to the established per-track realization +
/// encode path, staging at most one carrier at a time.
async fn encode_cue_stream_group_fallback(
    tracks: Vec<ScheduledCueStreamTrack>,
    req: &PipelineRequest,
    staging_root: &Path,
    staging_job: &str,
    convert_root: &Path,
    tool_paths: &HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    runner: &dyn ToolRunner,
    reporter: Option<&dyn PipelineReporter>,
    cancel: &CancellationToken,
) -> Vec<ScheduledTrackOutput> {
    let mut outputs = Vec::with_capacity(tracks.len());
    for input in tracks {
        if cancel.is_cancelled() {
            outputs.push(scheduled_worker_failure_output(
                input.index,
                &input.track,
                None,
                Some(input.final_path),
                "album cancelled before CUE fallback conversion".to_string(),
            ));
            continue;
        }
        let fallback_path = match &input.track.source_ref {
            TrackSourceRef::CueStreamSegment { fallback_path, .. } => Some(fallback_path.clone()),
            _ => None,
        };
        let result = convert_one_track_work(
            input.index,
            input.track.clone(),
            input.final_path.clone(),
            req.clone(),
            staging_root.to_path_buf(),
            staging_job.to_string(),
            convert_root.to_path_buf(),
            runner,
            tool_paths.clone(),
            cancel.clone(),
            tool_concurrency_limits.clone(),
            reporter,
        )
        .await;
        // Lazy stream fallback carriers are private conversion inputs. Once
        // this track reaches a terminal encode result, no later stage reads
        // them; retire each immediately so fallback peak disk usage is O(1)
        // track instead of gradually recreating the eager album footprint.
        if let Some(path) = fallback_path {
            let _ = fs::remove_file(path);
        }
        match result {
            Ok(output) => outputs.push(output),
            Err(error) => outputs.push(scheduled_worker_failure_output(
                input.index,
                &input.track,
                None,
                Some(input.final_path),
                format!("CUE fallback conversion worker failed: {error}"),
            )),
        }
    }
    outputs
}

fn cue_stream_decoder_command(
    decode_path: &Path,
    carrier: CueSegmentCarrier,
) -> ToolCommand {
    ToolCommand {
        environment_policy: tonepoet_pipeline::CommandEnvironmentPolicy::InheritAndSet,
        binary: ToolBinary::Ffmpeg,
        args: vec![
            "-v".into(),
            "error".into(),
            "-hide_banner".into(),
            "-nostdin".into(),
            "-i".into(),
            decode_path.display().to_string(),
            "-map".into(),
            "0:a:0".into(),
            "-vn".into(),
            "-sn".into(),
            "-dn".into(),
            "-f".into(),
            carrier.raw_format_name().into(),
            "-c:a".into(),
            carrier.codec_name().into(),
            "pipe:1".into(),
        ],
        secret_args: vec![],
        cwd: None,
        env: vec![],
        timeout: DEFAULT_CONVERT_TIMEOUT,
    }
}

fn cue_stream_consumer_command(
    plan: &CueStreamDirectTrackPlan,
    sample_rate: u32,
    channels: u16,
    carrier: CueSegmentCarrier,
) -> Result<ToolCommand, ConvertError> {
    let mut command = planned_command_to_tool_command(
        &plan.planned_command,
        DEFAULT_PLANNED_COMMAND_TIMEOUT,
    )?;
    let work_output = plan.work_output()?;
    let mut args = match &plan.planned_command.tool {
        tonepoet_pipeline::ToolIdentifier::Ffmpeg => {
            let mut args = vec![
                "-y".to_string(),
                "-hide_banner".to_string(),
                "-nostdin".to_string(),
                "-f".to_string(),
                carrier.raw_format_name().to_string(),
                "-ar".to_string(),
                sample_rate.to_string(),
                "-ac".to_string(),
                channels.to_string(),
                "-i".to_string(),
                "pipe:0".to_string(),
                "-map".to_string(),
                "0:a:0".to_string(),
            ];
            args.extend(plan.ffmpeg_output_args()?.iter().cloned());
            args
        }
        tonepoet_pipeline::ToolIdentifier::Sox => {
            if carrier != CueSegmentCarrier::PcmS32LeWav {
                return Err(ConvertError::Backend(
                    "direct SoX CUE streaming requires Tonepoet's raw s32 integer transport".to_string(),
                ));
            }
            let mut args = vec![
                "-S".to_string(),
                "-D".to_string(),
                "-t".to_string(),
                "raw".to_string(),
                "-e".to_string(),
                "signed-integer".to_string(),
                "-b".to_string(),
                "32".to_string(),
                "-L".to_string(),
                "-r".to_string(),
                sample_rate.to_string(),
                "-c".to_string(),
                channels.to_string(),
                "-".to_string(),
            ];
            args.extend(plan.sox_output_args()?.iter().cloned());
            args
        }
        other => {
            return Err(ConvertError::Backend(format!(
                "direct CUE stream consumer does not support planner tool {other:?}"
            )));
        }
    };
    args.push(work_output.display().to_string());
    command.args = args;
    command.timeout = DEFAULT_CONVERT_TIMEOUT;
    Ok(command)
}

fn cue_stream_byte_range(
    start_sample: u64,
    samples: u64,
    channels: u16,
    carrier: CueSegmentCarrier,
) -> Option<(u64, u64)> {
    let bytes_per_frame = carrier
        .bytes_per_sample()
        .checked_mul(u64::from(channels))?;
    let start_byte = start_sample.checked_mul(bytes_per_frame)?;
    let byte_len = samples.checked_mul(bytes_per_frame)?;
    (byte_len > 0).then_some((start_byte, byte_len))
}

fn cue_source_replaygain_eligible(source: &PreparedSource, req: &PipelineRequest) -> bool {
    if req.stages.replaygain != StageRequirement::Enabled
        || req.merge
        || !req.settings.target_format.is_pcm_lossless()
        || matches!(req.settings.target_format, PlannerAudioFormat::WavPack)
            && req.settings.wavpack.hybrid
        || !matches!(replaygain_format_support(req), ReplayGainFormatSupport::Supported)
        || !matches!(
            inherited_replaygain_tag_policy(Some(source), &req.settings),
            ReplayGainInheritedTagPolicy::Trust
        )
    {
        return false;
    }
    // A future target-channel/downmix setting must become part of the
    // signal-equivalence predicate before this optimization may use it.
    source.tracks.iter().all(|track| {
        matches!(
            &track.source_ref,
            TrackSourceRef::CueStreamSegment { channels: 1 | 2, .. }
        )
    })
}

fn cue_stream_analysis_wav_header(
    sample_rate: u32,
    channels: u16,
    carrier: CueSegmentCarrier,
    samples: u64,
) -> io::Result<Vec<u8>> {
    if channels == 0 || sample_rate == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ReplayGain stream header requires non-zero rate and channels",
        ));
    }
    let bytes_per_sample = u16::try_from(carrier.bytes_per_sample()).map_err(|_| {
        io::Error::new(io::ErrorKind::InvalidInput, "PCM sample width does not fit WAV")
    })?;
    let block_align = channels.checked_mul(bytes_per_sample).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "PCM block alignment overflow")
    })?;
    let byte_rate = sample_rate.checked_mul(u32::from(block_align)).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "PCM byte rate overflow")
    })?;
    let data_bytes = samples
        .checked_mul(u64::from(block_align))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "PCM data size overflow"))?;
    let format_tag: u16 = match carrier {
        CueSegmentCarrier::PcmS32LeWav => 1,
        CueSegmentCarrier::PcmF32LeWav | CueSegmentCarrier::PcmF64LeWav => 3,
    };
    let bits = u16::try_from(carrier.bit_depth()).map_err(|_| {
        io::Error::new(io::ErrorKind::InvalidInput, "PCM bit depth does not fit WAV")
    })?;

    let mut header = Vec::with_capacity(80);
    let riff_size = data_bytes.checked_add(36).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "RIFF size overflow")
    })?;
    if riff_size <= u64::from(u32::MAX) {
        header.extend_from_slice(b"RIFF");
        header.extend_from_slice(&(riff_size as u32).to_le_bytes());
        header.extend_from_slice(b"WAVE");
    } else {
        header.extend_from_slice(b"RF64");
        header.extend_from_slice(&u32::MAX.to_le_bytes());
        header.extend_from_slice(b"WAVE");
        header.extend_from_slice(b"ds64");
        header.extend_from_slice(&28_u32.to_le_bytes());
        let rf64_riff_size = data_bytes.checked_add(72).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "RF64 size overflow")
        })?;
        header.extend_from_slice(&rf64_riff_size.to_le_bytes());
        header.extend_from_slice(&data_bytes.to_le_bytes());
        header.extend_from_slice(&samples.to_le_bytes());
        header.extend_from_slice(&0_u32.to_le_bytes());
    }
    header.extend_from_slice(b"fmt ");
    header.extend_from_slice(&16_u32.to_le_bytes());
    header.extend_from_slice(&format_tag.to_le_bytes());
    header.extend_from_slice(&channels.to_le_bytes());
    header.extend_from_slice(&sample_rate.to_le_bytes());
    header.extend_from_slice(&byte_rate.to_le_bytes());
    header.extend_from_slice(&block_align.to_le_bytes());
    header.extend_from_slice(&bits.to_le_bytes());
    header.extend_from_slice(b"data");
    let data_size_field = if riff_size <= u64::from(u32::MAX) {
        u32::try_from(data_bytes).map_err(|_| {
            io::Error::new(io::ErrorKind::InvalidInput, "RIFF data size overflow")
        })?
    } else {
        u32::MAX
    };
    header.extend_from_slice(&data_size_field.to_le_bytes());
    Ok(header)
}

#[cfg(unix)]
fn create_cue_replaygain_fifo(path: &Path) -> io::Result<()> {
    use rustix::fs::{mknodat, FileType, Mode, CWD};
    let _ = fs::remove_file(path);
    // rustix 0.38 has no `mkfifoat`; `mknodat(FileType::Fifo, …)` is the exact
    // equivalent (mkfifoat is just mknodat with S_IFIFO) and stays safe/no-unsafe.
    mknodat(CWD, path, FileType::Fifo, Mode::RUSR | Mode::WUSR, 0).map_err(io::Error::from)
}

#[cfg(not(unix))]
fn create_cue_replaygain_fifo(_path: &Path) -> io::Result<()> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "CUE ReplayGain stream mirroring requires Unix FIFOs",
    ))
}

fn cue_stream_groups(tracks: &[ScheduledCueStreamTrack]) -> Vec<Vec<ScheduledCueStreamTrack>> {
    let mut groups: Vec<Vec<ScheduledCueStreamTrack>> = Vec::new();
    for input in tracks {
        let belongs_to_last = groups.last().and_then(|group| group.first()).is_some_and(|first| {
            match (&first.track.source_ref, &input.track.source_ref) {
                (
                    TrackSourceRef::CueStreamSegment {
                        source_image: left_source,
                        decode_path: left_decode,
                        carrier: left_carrier,
                        channels: left_channels,
                        image_samples: left_samples,
                        ..
                    },
                    TrackSourceRef::CueStreamSegment {
                        source_image: right_source,
                        decode_path: right_decode,
                        carrier: right_carrier,
                        channels: right_channels,
                        image_samples: right_samples,
                        ..
                    },
                ) => {
                    left_source == right_source
                        && left_decode == right_decode
                        && left_carrier == right_carrier
                        && left_channels == right_channels
                        && left_samples == right_samples
                        && first.track.sample_rate == input.track.sample_rate
                }
                _ => false,
            }
        });
        if belongs_to_last {
            groups.last_mut().expect("group exists").push(input.clone());
        } else {
            groups.push(vec![input.clone()]);
        }
    }
    groups
}

fn cue_stream_album_direct_preflight(
    tracks: &[ScheduledCueStreamTrack],
    req: &PipelineRequest,
    convert_root: &Path,
) -> bool {
    for input in tracks {
        let fallback_path = match &input.track.source_ref {
            TrackSourceRef::CueStreamSegment { fallback_path, .. } => fallback_path,
            _ => return false,
        };
        let staged_path = staged_audio_path(
            convert_root,
            &input.final_path,
            &input.track.id,
            &req.settings.target_format,
        );
        let planned = prepare_cue_stream_direct_track_plan(
            req,
            &input.track,
            fallback_path,
            &staged_path,
            convert_root,
        );
        match planned {
            Ok(Some(plan)) => cleanup_cue_stream_direct_track_plan(&plan),
            Ok(None) | Err(_) => return false,
        }
    }
    true
}

fn cue_source_replaygain_scan_command(
    grouping: crate::convert::replaygain::LoudgainGrouping,
    prevent_clipping: bool,
    paths: &[PathBuf],
    cwd: PathBuf,
) -> ToolCommand {
    ToolCommand {
        environment_policy: tonepoet_pipeline::CommandEnvironmentPolicy::InheritAndSet,
        binary: ToolBinary::Loudgain,
        args: crate::convert::replaygain::loudgain_scan_args(
            grouping,
            prevent_clipping,
            paths,
        ),
        secret_args: vec![],
        cwd: Some(cwd),
        env: vec![],
        // Source-pass analysis consumes live FIFOs behind the sequential
        // encoders, so its healthy lifetime is the conversion work unit. Keep
        // the ordinary post-hoc loudgain scan's shorter timeout unchanged.
        timeout: DEFAULT_CONVERT_TIMEOUT,
    }
}

fn cue_stream_replaygain_mirrors(
    tracks: &[ScheduledCueStreamTrack],
    root: &Path,
) -> io::Result<(PathBuf, Vec<PathBuf>, BTreeMap<usize, ToolStreamMirror>)> {
    let dir = root.join(".cue-replaygain-stream");
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir)?;

    let build = (|| -> io::Result<(Vec<PathBuf>, BTreeMap<usize, ToolStreamMirror>)> {
        let mut relative_paths = Vec::with_capacity(tracks.len());
        let mut mirrors = BTreeMap::new();
        for (ordinal, input) in tracks.iter().enumerate() {
            let (carrier, channels, samples) = match &input.track.source_ref {
                TrackSourceRef::CueStreamSegment {
                    carrier,
                    channels,
                    samples,
                    ..
                } => (*carrier, *channels, *samples),
                _ => {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "ReplayGain mirror requested for a non-stream CUE track",
                    ))
                }
            };
            let sample_rate = input.track.sample_rate.filter(|rate| *rate > 0).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "CUE ReplayGain track has no sample rate",
                )
            })?;
            let name = format!("track-{:03}.wav", ordinal + 1);
            let absolute = dir.join(&name);
            create_cue_replaygain_fifo(&absolute)?;
            relative_paths.push(PathBuf::from(name));
            mirrors.insert(
                input.index,
                ToolStreamMirror {
                    path: absolute,
                    prefix: cue_stream_analysis_wav_header(
                        sample_rate,
                        channels,
                        carrier,
                        samples,
                    )?,
                },
            );
        }
        Ok((relative_paths, mirrors))
    })();

    match build {
        Ok((relative_paths, mirrors)) => Ok((dir, relative_paths, mirrors)),
        Err(error) => {
            // FIFOs are an optional analysis sidecar, not durable conversion
            // state. A partial setup must leave no stale readers/writers for a
            // fallback or retry to trip over.
            let _ = fs::remove_dir_all(&dir);
            Err(error)
        }
    }
}

pub async fn encode_cue_stream_album_for_scheduler_with_tool_limits_and_version_cache(
    tracks: Vec<ScheduledCueStreamTrack>,
    source: PreparedSource,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    version_cache: Option<Arc<Mutex<HashMap<ToolBinary, String>>>>,
    reporter: &dyn PipelineReporter,
    cancel: CancellationToken,
) -> ScheduledCueStreamBatch {
    let runner = real_tool_runner_with_optional_version_cache(
        tool_paths.clone(),
        version_cache,
        &req.item_id,
    );
    let groups = cue_stream_groups(&tracks);
    let source_rg = cue_source_replaygain_eligible(&source, &req)
        && runner.tool_available(ToolBinary::Loudgain)
        && cue_stream_album_direct_preflight(&tracks, &req, &convert_root);

    if !source_rg {
        let mut outputs = Vec::with_capacity(tracks.len());
        for group in groups {
            outputs.extend(
                Box::pin(encode_cue_stream_group_with_runner(
                    group,
                    req.clone(),
                    staging_root.clone(),
                    staging_job.clone(),
                    convert_root.clone(),
                    tool_paths.clone(),
                    tool_concurrency_limits.clone(),
                    &runner,
                    Some(reporter),
                    cancel.clone(),
                    None,
                ))
                .await,
            );
        }
        return ScheduledCueStreamBatch {
            outputs,
            source_replaygain: None,
        };
    }

    let (rg_dir, rg_paths, mirrors) = match cue_stream_replaygain_mirrors(&tracks, &convert_root) {
        Ok(value) => value,
        Err(error) => {
            log::warn!(
                "source-pass ReplayGain setup failed for job {}; using output-measured ReplayGain: {error}",
                req.job_id
            );
            let mut outputs = Vec::with_capacity(tracks.len());
            for group in groups {
                outputs.extend(
                    Box::pin(encode_cue_stream_group_with_runner(
                        group,
                        req.clone(),
                        staging_root.clone(),
                        staging_job.clone(),
                        convert_root.clone(),
                        tool_paths.clone(),
                        tool_concurrency_limits.clone(),
                        &runner,
                        Some(reporter),
                        cancel.clone(),
                        None,
                    ))
                    .await,
                );
            }
            return ScheduledCueStreamBatch {
                outputs,
                source_replaygain: None,
            };
        }
    };

    let mode = req
        .settings
        .replay_gain
        .mode
        .unwrap_or(tonepoet_pipeline::ReplayGainMode::Both);
    let grouping = if matches!(
        mode,
        tonepoet_pipeline::ReplayGainMode::Album | tonepoet_pipeline::ReplayGainMode::Both
    ) {
        crate::convert::replaygain::LoudgainGrouping::Album
    } else {
        crate::convert::replaygain::LoudgainGrouping::Track
    };
    let scan_cmd = cue_source_replaygain_scan_command(
        grouping,
        req.settings.replay_gain.prevent_clipping,
        &rg_paths,
        rg_dir.clone(),
    );
    let rg_cancel = cancel.child_token();
    let analysis_cancel = rg_cancel.clone();
    let analysis_limits = tool_concurrency_limits.clone();
    // The production album path polls analysis and conversion concurrently.
    // Keep both album-sized futures behind heap boundaries so the scheduler's
    // `join!` does not re-aggregate the stack depth removed below.
    let analysis = Box::pin(async {
        let result = run_tool_command_with_concurrency(
            scan_cmd,
            &runner,
            &analysis_cancel,
            analysis_limits.as_ref(),
        )
        .await;
        if result.is_err() {
            analysis_cancel.cancel();
        }
        result
    });
    let conversion_cancel = rg_cancel.clone();
    let conversion = Box::pin(async {
        let mut outputs = Vec::with_capacity(tracks.len());
        let mut direct = true;
        for group in groups {
            let group_outputs = Box::pin(encode_cue_stream_group_with_runner(
                group,
                req.clone(),
                staging_root.clone(),
                staging_job.clone(),
                convert_root.clone(),
                tool_paths.clone(),
                tool_concurrency_limits.clone(),
                &runner,
                Some(reporter),
                conversion_cancel.clone(),
                Some(&mirrors),
            ))
            .await;
            if group_outputs.iter().any(|output| !output.ok || output.record.realized_input.is_some()) {
                direct = false;
                conversion_cancel.cancel();
            }
            outputs.extend(group_outputs);
            // This album-scoped work unit owns accounting for every coalesced
            // CUE track. Even after cancellation, keep walking the remaining
            // groups: the group encoder emits cheap terminal cancellation
            // records without starting tools, preventing scheduler accounting
            // from being left short of `pending.expected`.
        }
        (outputs, direct)
    });

    let (analysis_result, (mut outputs, direct)) = tokio::join!(analysis, conversion);
    let _ = fs::remove_dir_all(&rg_dir);

    if !direct && !cancel.is_cancelled() {
        // A source-RG sidecar failure is an optimization failure, never an
        // album conversion failure. Re-run through the established non-mirrored
        // streaming/fallback path and let ReplayGain scan the outputs later.
        outputs.clear();
        for group in cue_stream_groups(&tracks) {
            outputs.extend(
                Box::pin(encode_cue_stream_group_with_runner(
                    group,
                    req.clone(),
                    staging_root.clone(),
                    staging_job.clone(),
                    convert_root.clone(),
                    tool_paths.clone(),
                    tool_concurrency_limits.clone(),
                    &runner,
                    Some(reporter),
                    cancel.clone(),
                    None,
                ))
                .await,
            );
        }
        return ScheduledCueStreamBatch {
            outputs,
            source_replaygain: None,
        };
    }

    let source_replaygain = match analysis_result {
        Ok(output) if direct && outputs.len() == tracks.len() && outputs.iter().all(|o| o.ok) => {
            match crate::convert::replaygain::parse_loudgain_scan_output(
                &output.stdout_tail,
                tracks.len(),
                grouping,
            ) {
                Ok(scan) => Some(scan),
                Err(error) => {
                    log::warn!(
                        "source-pass ReplayGain output could not be parsed for job {}; using output-measured ReplayGain: {error}",
                        req.job_id
                    );
                    None
                }
            }
        }
        Ok(_) => None,
        Err(error) => {
            log::warn!(
                "source-pass ReplayGain failed for job {}; using output-measured ReplayGain: {error}",
                req.job_id
            );
            None
        }
    };
    ScheduledCueStreamBatch {
        outputs,
        source_replaygain,
    }
}

pub async fn encode_cue_stream_group_for_scheduler_with_tool_limits_and_version_cache(
    tracks: Vec<ScheduledCueStreamTrack>,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    version_cache: Option<Arc<Mutex<HashMap<ToolBinary, String>>>>,
    reporter: &dyn PipelineReporter,
    cancel: CancellationToken,
) -> Vec<ScheduledTrackOutput> {
    let runner = real_tool_runner_with_optional_version_cache(
        tool_paths.clone(),
        version_cache,
        &req.item_id,
    );
    Box::pin(encode_cue_stream_group_with_runner(
        tracks,
        req,
        staging_root,
        staging_job,
        convert_root,
        tool_paths,
        tool_concurrency_limits,
        &runner,
        Some(reporter),
        cancel,
        None,
    ))
    .await
}

fn cue_stream_shared_producer_record_for_error(
    producer: &ToolCommand,
    error: &ToolSegmentedPipelineError,
    track_count: usize,
) -> CommandRecord {
    let sanitized_args = producer.sanitized_args();
    let matches_producer = |record: &CommandRecord| {
        record.binary == producer.binary
            && record.sanitized_args == sanitized_args
            && record.cwd == producer.cwd
    };
    let mut record = command_from_tool_error(&error.error)
        .filter(|record| matches_producer(record))
        .or_else(|| {
            error
                .other_commands
                .iter()
                .find(|record| matches_producer(record))
                .cloned()
        })
        .unwrap_or_else(|| CommandRecord {
            description: None,
            binary: producer.binary,
            sanitized_args: sanitized_args.clone(),
            cwd: producer.cwd.clone(),
            environment_policy: producer.environment_policy,
            environment: producer.sanitized_environment(),
            env_keys: producer.env_keys(),
            exit: None,
            stdout_tail: String::new(),
            stderr_tail: String::new(),
            elapsed: Duration::ZERO,
        });
    record.description = Some(format!(
        "Shared CUE image decode for {track_count} streamed track(s)"
    ));
    record
}

async fn finalize_cue_stream_consumer_output(
    input: ScheduledCueStreamTrack,
    staged_path: PathBuf,
    plan: CueStreamDirectTrackPlan,
    consumer_output: ToolOutput,
    producer_record: &CommandRecord,
    source_decode_path: &Path,
    req: &PipelineRequest,
    runner: &dyn ToolRunner,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<&Arc<ToolConcurrencyLimits>>,
) -> ScheduledTrackOutput {
    let metadata_satisfaction = plan.metadata_satisfaction;
    let output = async {
        finalize_cue_stream_direct_track_plan(&plan)?;
        let bytes_out = file_len(&staged_path);
        if bytes_out.unwrap_or(0) == 0 {
            return Err(ConvertError::TrackValidation(format!(
                "streaming CUE planner did not produce output: {}",
                staged_path.display()
            )));
        }
        let expected = post_encode_expected_samples_for_track(
            &input.track,
            source_decode_path,
            &req.settings,
            runner,
            cancel,
            tool_concurrency_limits,
        )
        .await?;
        let validation = validate_encoded_output_with_tool_limits(
            &staged_path,
            expected,
            expected_post_encode_depth_for_track(&input.track, &req.settings),
            &req.settings.target_format,
            runner,
            cancel,
            tool_concurrency_limits,
        )
        .await?;

        let bytes_in = match &input.track.source_ref {
            TrackSourceRef::CueStreamSegment {
                samples,
                channels,
                carrier,
                ..
            } => samples
                .checked_mul(u64::from(*channels))
                .and_then(|value| value.checked_mul(carrier.bytes_per_sample())),
            _ => None,
        };
        let mut consumer_record = consumer_output.command;
        consumer_record.description = Some(format!(
            "Direct encode from shared CUE PCM stream for track {}",
            input.track.id.source_ordinal
        ));
        let record = TrackRecord {
            track_id: input.track.id.clone(),
            outcome: TrackOutcome::Ok,
            source_ref: input.track.source_ref.clone(),
            realized_input: None,
            output_file: Some(staged_path.clone()),
            commands: vec![producer_record.clone(), consumer_record],
            bytes_in,
            bytes_out,
            duration: Some(consumer_output.elapsed),
            verified_output_bit_depth: validation.measured_depth,
            dsd_dst_stats: None,
        };
        let artifact = TrackArtifact {
            reference_evidence: None,
            planned_command_hash: plan.command_hash.clone(),
            track_id: input.track.id.clone(),
            staged_path: staged_path.clone(),
            final_path: input.final_path.clone(),
            samples: validation
                .samples
                .or(expected.map(|value| value.samples))
                .or(input.track.expected_samples),
            metadata_satisfaction: plan.metadata_satisfaction,
            metadata_required: plan.metadata_required,
        };
        Ok::<_, ConvertError>((record, artifact))
    }
    .await;

    cleanup_cue_stream_direct_track_plan(&plan);
    match output {
        Ok((record, artifact)) => ScheduledTrackOutput {
            index: input.index,
            record,
            artifact: Some(artifact),
            ok: true,
            metadata_satisfaction,
        },
        Err(error) => ScheduledTrackOutput {
            index: input.index,
            record: failed_track_record(
                &input.track,
                None,
                Some(staged_path),
                vec![producer_record.clone()],
                error.to_string(),
            ),
            artifact: None,
            ok: false,
            metadata_satisfaction: PlannedMetadataSatisfaction::none(),
        },
    }
}

async fn encode_cue_stream_group_with_runner(
    tracks: Vec<ScheduledCueStreamTrack>,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    runner: &dyn ToolRunner,
    reporter: Option<&dyn PipelineReporter>,
    cancel: CancellationToken,
    mirrors: Option<&BTreeMap<usize, ToolStreamMirror>>,
) -> Vec<ScheduledTrackOutput> {
    if tracks.is_empty() {
        return Vec::new();
    }

    let first_source = match &tracks[0].track.source_ref {
        TrackSourceRef::CueStreamSegment {
            decode_path,
            carrier,
            channels,
            image_samples,
            source_image,
            ..
        } => (
            decode_path.clone(),
            *carrier,
            *channels,
            *image_samples,
            source_image.clone(),
        ),
        _ => {
            return Box::pin(encode_cue_stream_group_fallback(
                tracks,
                &req,
                &staging_root,
                &staging_job,
                &convert_root,
                &tool_paths,
                tool_concurrency_limits,
                runner,
                reporter,
                &cancel,
            ))
            .await;
        }
    };

    let Some(sample_rate) = tracks[0].track.sample_rate.filter(|value| *value > 0) else {
        return Box::pin(encode_cue_stream_group_fallback(
            tracks,
            &req,
            &staging_root,
            &staging_job,
            &convert_root,
            &tool_paths,
            tool_concurrency_limits,
            runner,
            reporter,
            &cancel,
        ))
        .await;
    };

    // One group is exactly one decoder authority. Do not merge FILE blocks,
    // PCM representations, channel layouts, or rate facts even when their
    // paths happen to resolve to the same inode.
    if tracks.iter().any(|input| {
        input.track.sample_rate != Some(sample_rate)
            || match &input.track.source_ref {
                TrackSourceRef::CueStreamSegment {
                    decode_path,
                    carrier,
                    channels,
                    image_samples,
                    source_image,
                    start_sample,
                    samples,
                    ..
                } => {
                    decode_path != &first_source.0
                        || carrier != &first_source.1
                        || channels != &first_source.2
                        || image_samples != &first_source.3
                        || source_image != &first_source.4
                        || start_sample
                            .checked_add(*samples)
                            .map(|end| end > *image_samples)
                            .unwrap_or(true)
                }
                _ => true,
            }
    }) {
        return Box::pin(encode_cue_stream_group_fallback(
            tracks,
            &req,
            &staging_root,
            &staging_job,
            &convert_root,
            &tool_paths,
            tool_concurrency_limits,
            runner,
            reporter,
            &cancel,
        ))
        .await;
    }

    let mut planned: Vec<(ScheduledCueStreamTrack, PathBuf, CueStreamDirectTrackPlan)> =
        Vec::with_capacity(tracks.len());
    for input in &tracks {
        let fallback_path = match &input.track.source_ref {
            TrackSourceRef::CueStreamSegment { fallback_path, .. } => fallback_path,
            _ => unreachable!("validated above"),
        };
        let staged_path = staged_audio_path(
            &convert_root,
            &input.final_path,
            &input.track.id,
            &req.settings.target_format,
        );
        if let Some(parent) = staged_path.parent() {
            if fs::create_dir_all(parent).is_err() {
                for (_, _, plan) in &planned {
                    cleanup_cue_stream_direct_track_plan(plan);
                }
                return Box::pin(encode_cue_stream_group_fallback(
                    tracks,
                    &req,
                    &staging_root,
                    &staging_job,
                    &convert_root,
                    &tool_paths,
                    tool_concurrency_limits,
                    runner,
                    reporter,
                    &cancel,
                ))
                .await;
            }
        }
        match prepare_cue_stream_direct_track_plan(
            &req,
            &input.track,
            fallback_path,
            &staged_path,
            &convert_root,
        ) {
            Ok(Some(plan)) => planned.push((input.clone(), staged_path, plan)),
            Ok(None) | Err(_) => {
                for (_, _, plan) in &planned {
                    cleanup_cue_stream_direct_track_plan(plan);
                }
                return Box::pin(encode_cue_stream_group_fallback(
                    tracks,
                    &req,
                    &staging_root,
                    &staging_job,
                    &convert_root,
                    &tool_paths,
                    tool_concurrency_limits,
                    runner,
                    reporter,
                    &cancel,
                ))
                .await;
            }
        }
    }

    let mut segments = Vec::with_capacity(planned.len());
    for (input, _, plan) in &planned {
        let (start_sample, samples) = match &input.track.source_ref {
            TrackSourceRef::CueStreamSegment {
                start_sample,
                samples,
                ..
            } => (*start_sample, *samples),
            _ => unreachable!("validated above"),
        };
        let Some((start_byte, byte_len)) = cue_stream_byte_range(
            start_sample,
            samples,
            first_source.2,
            first_source.1,
        ) else {
            for (_, _, plan) in &planned {
                cleanup_cue_stream_direct_track_plan(plan);
            }
            return Box::pin(encode_cue_stream_group_fallback(
                tracks,
                &req,
                &staging_root,
                &staging_job,
                &convert_root,
                &tool_paths,
                tool_concurrency_limits,
                runner,
                reporter,
                &cancel,
            ))
            .await;
        };
        let consumer = match cue_stream_consumer_command(
            plan,
            sample_rate,
            first_source.2,
            first_source.1,
        ) {
            Ok(command) => command,
            Err(_) => {
                for (_, _, plan) in &planned {
                    cleanup_cue_stream_direct_track_plan(plan);
                }
                return Box::pin(encode_cue_stream_group_fallback(
                    tracks,
                    &req,
                    &staging_root,
                    &staging_job,
                    &convert_root,
                    &tool_paths,
                    tool_concurrency_limits,
                    runner,
                    reporter,
                    &cancel,
                ))
                .await;
            }
        };
        if let Ok(work_output) = plan.work_output() {
            if let Some(parent) = work_output.parent() {
                if fs::create_dir_all(parent).is_err() {
                    for (_, _, plan) in &planned {
                        cleanup_cue_stream_direct_track_plan(plan);
                    }
                    return Box::pin(encode_cue_stream_group_fallback(
                        tracks,
                        &req,
                        &staging_root,
                        &staging_job,
                        &convert_root,
                        &tool_paths,
                        tool_concurrency_limits,
                        runner,
                        reporter,
                        &cancel,
                    ))
                    .await;
                }
            }
            let _ = fs::remove_file(work_output);
        }
        segments.push(ToolStreamSegment {
            start_byte,
            byte_len,
            consumer,
            mirror: mirrors.and_then(|values| values.get(&input.index).cloned()),
            stop_producer_after: false,
        });
    }

    // Exact-PCM CueStreamSegment sources carry authoritative image_samples.
    // If the final selected bounded segment ends before the image does, bytes
    // after that point are unselected and the transport may stop the producer
    // rather than decoding/discarding the rest of the image. A selection that
    // reaches the exact image end keeps natural-EOF supervision unchanged.
    let image_byte_len = cue_stream_byte_range(
        0,
        first_source.3,
        first_source.2,
        first_source.1,
    )
    .and_then(|(_, byte_len)| (byte_len > 0).then_some(byte_len));
    if let (Some(last), Some(image_byte_len)) = (segments.last_mut(), image_byte_len) {
        if let Some(selected_end) = last.start_byte.checked_add(last.byte_len) {
            last.stop_producer_after = selected_end < image_byte_len;
        }
    }

    // The producer emits exactly the carrier PCM representation that the old
    // materializer wrote to per-track WAVs. The transport splits on whole PCM
    // frame byte offsets and starts one encoder at a time, so decoder count is
    // O(images) while live encoder/intermediate state remains O(1 track).
    let producer = cue_stream_decoder_command(&first_source.0, first_source.1);
    let producer_for_records = producer.clone();
    // This boundary separates the large group-planning/finalization future
    // from the segmented transport state. It executes once per decoder group,
    // so stack safety does not add allocation to the 64 KiB transfer loop.
    let execution = Box::pin(run_segmented_tool_pipeline_with_concurrency(
        producer,
        segments,
        runner,
        &cancel,
        tool_concurrency_limits.as_ref(),
    ))
    .await;

    let pipeline_output = match execution {
        Ok(output) => output,
        Err(error) => {
            // Admission fallback is decided above, before the producer starts.
            // Once a segmented execution has been attempted, a decoder, encoder,
            // pipe, or filesystem failure is the real failure. Retrying the same
            // album through large carrier WAVs is both expensive and actively
            // harmful for failures such as disk-full or corrupt input.
            match error {
                SegmentedPipelineExecutionError::Admission(error) => {
                    let message = error.to_string();
                    let mut outputs = Vec::with_capacity(planned.len());
                    for (input, staged_path, plan) in planned {
                        cleanup_cue_stream_direct_track_plan(&plan);
                        outputs.push(ScheduledTrackOutput {
                            index: input.index,
                            record: failed_track_record(
                                &input.track,
                                None,
                                Some(staged_path),
                                Vec::new(),
                                message.clone(),
                            ),
                            artifact: None,
                            ok: false,
                            metadata_satisfaction: PlannedMetadataSatisfaction::none(),
                        });
                    }
                    return outputs;
                }
                SegmentedPipelineExecutionError::Tool(error) => {
                    let preserve_completed_prefix =
                        req.failure_policy == FailurePolicy::AllowPartialAlbum
                            && !cancel.is_cancelled()
                            && !error.completed_consumers.is_empty()
                            && error.completed_consumers.len() <= planned.len();
                    if preserve_completed_prefix {
                        let producer_record = cue_stream_shared_producer_record_for_error(
                            &producer_for_records,
                            &error,
                            planned.len(),
                        );
                        let mut commands = error.other_commands.clone();
                        if let Some(command) = command_from_tool_error(&error.error) {
                            commands.push(command);
                        }
                        let message = error.error.to_string();
                        let completed_len = error.completed_consumers.len();
                        let mut planned_iter = planned.into_iter();
                        let mut outputs = Vec::with_capacity(completed_len + planned_iter.len());

                        for consumer_output in error.completed_consumers {
                            let Some((input, staged_path, plan)) = planned_iter.next() else {
                                break;
                            };
                            outputs.push(
                                Box::pin(finalize_cue_stream_consumer_output(
                                    input,
                                    staged_path,
                                    plan,
                                    consumer_output,
                                    &producer_record,
                                    &first_source.0,
                                    &req,
                                    runner,
                                    &cancel,
                                    tool_concurrency_limits.as_ref(),
                                ))
                                .await,
                            );
                        }

                        for (input, staged_path, plan) in planned_iter {
                            cleanup_cue_stream_direct_track_plan(&plan);
                            outputs.push(ScheduledTrackOutput {
                                index: input.index,
                                record: failed_track_record(
                                    &input.track,
                                    None,
                                    Some(staged_path),
                                    commands.clone(),
                                    message.clone(),
                                ),
                                artifact: None,
                                ok: false,
                                metadata_satisfaction: PlannedMetadataSatisfaction::none(),
                            });
                        }
                        return outputs;
                    }

                    let mut commands = error.other_commands;
                    if let Some(command) = command_from_tool_error(&error.error) {
                        commands.push(command);
                    }
                    let message = error.error.to_string();
                    let mut outputs = Vec::with_capacity(planned.len());
                    for (input, staged_path, plan) in planned {
                        cleanup_cue_stream_direct_track_plan(&plan);
                        outputs.push(ScheduledTrackOutput {
                            index: input.index,
                            record: failed_track_record(
                                &input.track,
                                None,
                                Some(staged_path),
                                commands.clone(),
                                message.clone(),
                            ),
                            artifact: None,
                            ok: false,
                            metadata_satisfaction: PlannedMetadataSatisfaction::none(),
                        });
                    }
                    return outputs;
                }
            }
        }
    };
    if pipeline_output.consumers.len() != planned.len() {
        let mut commands = vec![pipeline_output.producer.command.clone()];
        commands.extend(
            pipeline_output
                .consumers
                .iter()
                .map(|output| output.command.clone()),
        );
        let message = format!(
            "segmented CUE pipeline returned {} consumer result(s) for {} planned track(s)",
            pipeline_output.consumers.len(),
            planned.len()
        );
        let mut outputs = Vec::with_capacity(planned.len());
        for (input, staged_path, plan) in planned {
            cleanup_cue_stream_direct_track_plan(&plan);
            outputs.push(ScheduledTrackOutput {
                index: input.index,
                record: failed_track_record(
                    &input.track,
                    None,
                    Some(staged_path),
                    commands.clone(),
                    message.clone(),
                ),
                artifact: None,
                ok: false,
                metadata_satisfaction: PlannedMetadataSatisfaction::none(),
            });
        }
        return outputs;
    }

    let mut producer_record = pipeline_output.producer.command;
    producer_record.description = Some(format!(
        "Shared CUE image decode for {} streamed track(s)",
        planned.len()
    ));
    let consumer_outputs = pipeline_output.consumers;
    let mut outputs = Vec::with_capacity(planned.len());
    for ((input, staged_path, plan), consumer_output) in
        planned.into_iter().zip(consumer_outputs)
    {
        outputs.push(
            Box::pin(finalize_cue_stream_consumer_output(
                input,
                staged_path,
                plan,
                consumer_output,
                &producer_record,
                &first_source.0,
                &req,
                runner,
                &cancel,
                tool_concurrency_limits.as_ref(),
            ))
            .await,
        );
    }
    outputs
}

/// Encode one planned track. The caller controls scheduling; this function only
/// realizes the selected track, runs the planner-selected command chain, and
/// returns a deterministic record/artifact pair.
pub async fn encode_track_for_scheduler(
    track_index: usize,
    track: PreparedTrack,
    final_path: PathBuf,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    reporter: &dyn PipelineReporter,
    cancel: CancellationToken,
) -> Result<ScheduledTrackOutput, String> {
    encode_track_for_scheduler_with_tool_limits(
        track_index,
        track,
        final_path,
        req,
        staging_root,
        staging_job,
        convert_root,
        tool_paths,
        None,
        reporter,
        cancel,
    )
    .await
}

pub async fn encode_track_for_scheduler_with_tool_limits(
    track_index: usize,
    track: PreparedTrack,
    final_path: PathBuf,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    reporter: &dyn PipelineReporter,
    cancel: CancellationToken,
) -> Result<ScheduledTrackOutput, String> {
    encode_track_for_scheduler_with_tool_limits_and_version_cache(
        track_index,
        track,
        final_path,
        req,
        staging_root,
        staging_job,
        convert_root,
        tool_paths,
        tool_concurrency_limits,
        None,
        reporter,
        cancel,
    )
    .await
}

pub async fn encode_track_for_scheduler_with_tool_limits_and_version_cache(
    track_index: usize,
    track: PreparedTrack,
    final_path: PathBuf,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    version_cache: Option<Arc<Mutex<HashMap<ToolBinary, String>>>>,
    reporter: &dyn PipelineReporter,
    cancel: CancellationToken,
) -> Result<ScheduledTrackOutput, String> {
    let runner = real_tool_runner_with_optional_version_cache(tool_paths.clone(), version_cache, &req.item_id);
    convert_one_track_work(
        track_index,
        track,
        final_path,
        req,
        staging_root,
        staging_job,
        convert_root,
        &runner,
        tool_paths,
        cancel,
        tool_concurrency_limits,
        Some(reporter),
    )
    .await
}

/// Realize one image-segment or SACD track as its own scheduler work unit.
/// Failures become normal failed track outputs so album policy, logging, and
/// durable reports stay deterministic.
pub async fn realize_track_for_scheduler(
    track_index: usize,
    track: PreparedTrack,
    final_path: PathBuf,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    reporter: &dyn PipelineReporter,
    cancel: CancellationToken,
) -> Result<ScheduledRealizedTrack, ScheduledTrackOutput> {
    realize_track_for_scheduler_with_tool_limits(
        track_index,
        track,
        final_path,
        req,
        staging_root,
        staging_job,
        convert_root,
        tool_paths,
        None,
        reporter,
        cancel,
    )
    .await
}

pub async fn realize_track_for_scheduler_with_tool_limits(
    track_index: usize,
    track: PreparedTrack,
    final_path: PathBuf,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    reporter: &dyn PipelineReporter,
    cancel: CancellationToken,
) -> Result<ScheduledRealizedTrack, ScheduledTrackOutput> {
    realize_track_for_scheduler_with_tool_limits_and_version_cache(
        track_index,
        track,
        final_path,
        req,
        staging_root,
        staging_job,
        convert_root,
        tool_paths,
        tool_concurrency_limits,
        None,
        reporter,
        cancel,
    )
    .await
}

pub async fn realize_track_for_scheduler_with_tool_limits_and_version_cache(
    track_index: usize,
    track: PreparedTrack,
    final_path: PathBuf,
    req: PipelineRequest,
    staging_root: PathBuf,
    staging_job: String,
    convert_root: PathBuf,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    version_cache: Option<Arc<Mutex<HashMap<ToolBinary, String>>>>,
    reporter: &dyn PipelineReporter,
    cancel: CancellationToken,
) -> Result<ScheduledRealizedTrack, ScheduledTrackOutput> {
    let staging = StagingDir::borrowed(staging_root.clone(), staging_job.clone());
    let runner = real_tool_runner_with_optional_version_cache(tool_paths, version_cache, &req.item_id);
    let staged_path = staged_audio_path(&convert_root, &final_path, &track.id, &req.settings.target_format);
    let mut progress_tracker = OperationProgressTracker::new(req.item_id.clone(), PipelineStage::Convert, Some(reporter));
    match realize_track_with_tool_limits_and_stats(
        &track.source_ref,
        Some(&track),
        &req,
        &staging,
        &runner,
        &cancel,
        tool_concurrency_limits,
        Some(&mut progress_tracker),
    )
    .await
    {
        Ok(realized) => Ok(ScheduledRealizedTrack {
            index: track_index,
            track,
            final_path,
            realized_path: realized.path,
            realized_dsd_dst_stats: realized.dsd_dst_stats,
            req,
            staging_root,
            staging_job,
            convert_root,
            cancel,
        }),
        Err(err) => {
            let record = failed_track_record(&track, None, Some(staged_path), Vec::new(), err.to_string());
            Err(ScheduledTrackOutput { index: track_index, record, artifact: None, ok: false, metadata_satisfaction: PlannedMetadataSatisfaction::none() })
        }
    }
}

/// Encode a track that a prior scheduler work unit already realized. This is
/// used for CUE segment splits and SACD track extraction so realization and
/// encoding can occupy independent shared-pool slots.
pub async fn encode_realized_track_for_scheduler(
    realized: ScheduledRealizedTrack,
    tool_paths: HashMap<String, PathBuf>,
    reporter: &dyn PipelineReporter,
) -> Result<ScheduledTrackOutput, String> {
    encode_realized_track_for_scheduler_with_tool_limits(realized, tool_paths, None, reporter).await
}

pub async fn encode_realized_track_for_scheduler_with_tool_limits(
    realized: ScheduledRealizedTrack,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    reporter: &dyn PipelineReporter,
) -> Result<ScheduledTrackOutput, String> {
    encode_realized_track_for_scheduler_with_tool_limits_and_version_cache(
        realized,
        tool_paths,
        tool_concurrency_limits,
        None,
        reporter,
    )
    .await
}

pub async fn encode_realized_track_for_scheduler_with_tool_limits_and_version_cache(
    realized: ScheduledRealizedTrack,
    tool_paths: HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
    version_cache: Option<Arc<Mutex<HashMap<ToolBinary, String>>>>,
    reporter: &dyn PipelineReporter,
) -> Result<ScheduledTrackOutput, String> {
    let runner = real_tool_runner_with_optional_version_cache(tool_paths.clone(), version_cache, &realized.req.item_id);
    let staged_path = staged_audio_path(
        &realized.convert_root,
        &realized.final_path,
        &realized.track.id,
        &realized.req.settings.target_format,
    );
    let mut progress_tracker = OperationProgressTracker::new(realized.req.item_id.clone(), PipelineStage::Convert, Some(reporter));

    if let Some(parent) = staged_path.parent() {
        if let Err(err) = fs::create_dir_all(parent) {
            let record = failed_track_record(
                &realized.track,
                Some(realized.realized_path),
                Some(staged_path),
                Vec::new(),
                format!("could not create output directory: {err}"),
            );
            return Ok(ScheduledTrackOutput { index: realized.index, record, artifact: None, ok: false, metadata_satisfaction: PlannedMetadataSatisfaction::none() });
        }
    }

    let bytes_in = file_len(&realized.realized_path);
    let executed = execute_planned_track_conversion(
        &realized.req,
        &realized.track,
        &realized.realized_path,
        &staged_path,
        &realized.convert_root,
        &runner,
        &realized.cancel,
        &tool_paths,
        tool_concurrency_limits.clone(),
        &mut progress_tracker,
        0.0,
        1.0,
    )
    .await;

    match executed {
        Ok(executed) => {
            let bytes_out = file_len(&staged_path);
            if bytes_out.unwrap_or(0) == 0 {
                let error = format!("planner did not produce output: {}", staged_path.display());
                let record = failed_track_record(
                    &realized.track,
                    Some(realized.realized_path),
                    Some(staged_path),
                    executed.commands,
                    error,
                );
                Ok(ScheduledTrackOutput { index: realized.index, record, artifact: None, ok: false, metadata_satisfaction: PlannedMetadataSatisfaction::none() })
            } else {
                let post_encode_expected_samples = match post_encode_expected_samples_for_track(
                    &realized.track,
                    &realized.realized_path,
                    &realized.req.settings,
                    &runner,
                    &realized.cancel,
                    tool_concurrency_limits.as_ref(),
                )
                .await
                {
                    Ok(samples) => samples,
                    Err(err) => {
                        let commands = command_from_convert_error(&err);
                        let record = failed_track_record(
                            &realized.track,
                            Some(realized.realized_path),
                            Some(staged_path),
                            commands,
                            err.to_string(),
                        );
                        return Ok(ScheduledTrackOutput { index: realized.index, record, artifact: None, ok: false, metadata_satisfaction: PlannedMetadataSatisfaction::none() });
                    }
                };

                let post_encode_validation = match validate_encoded_output_with_tool_limits(
                    &staged_path,
                    post_encode_expected_samples,
                    expected_post_encode_depth_for_track(&realized.track, &realized.req.settings),
                    &realized.req.settings.target_format,
                    &runner,
                    &realized.cancel,
                    tool_concurrency_limits.as_ref(),
                )
                .await
                {
                    Ok(validation) => validation,
                    Err(err) => {
                        let commands = command_from_convert_error(&err);
                        let record = failed_track_record(
                            &realized.track,
                            Some(realized.realized_path),
                            Some(staged_path),
                            commands,
                            err.to_string(),
                        );
                        return Ok(ScheduledTrackOutput { index: realized.index, record, artifact: None, ok: false, metadata_satisfaction: PlannedMetadataSatisfaction::none() });
                    }
                };
                let actual_samples = post_encode_validation.samples;
                let mut dsd_dst_stats = realized.realized_dsd_dst_stats.clone();
                merge_optional_dsd_dst_stats(
                    &mut dsd_dst_stats,
                    dsd_dst_stats_from_file(&staged_path, None, bytes_out),
                );
                apply_byte_totals_to_stats(&mut dsd_dst_stats, bytes_in, bytes_out);
                let mut commands = executed.commands;
                append_dsd_dst_stats_to_command_descriptions(&mut commands, dsd_dst_stats.as_ref());
                let record = TrackRecord {
                    track_id: realized.track.id.clone(),
                    outcome: TrackOutcome::Ok,
                    source_ref: realized.track.source_ref.clone(),
                    realized_input: Some(realized.realized_path.clone()),
                    output_file: Some(staged_path.clone()),
                    commands,
                    bytes_in,
                    bytes_out,
                    duration: Some(executed.elapsed),
                    verified_output_bit_depth: post_encode_validation.measured_depth,
                    dsd_dst_stats,
                };
                let artifact = TrackArtifact {
                    reference_evidence: executed.reference,
                    track_id: realized.track.id.clone(),
                    staged_path,
                    final_path: realized.final_path,
                    samples: actual_samples
                        .or(post_encode_expected_samples.map(|expectation| expectation.samples))
                        .or(realized.track.expected_samples),
                    metadata_satisfaction: executed.metadata_satisfaction,
                    metadata_required: executed.metadata_required,
                    planned_command_hash: executed.command_hash,
                };
                Ok(ScheduledTrackOutput { index: realized.index, record, artifact: Some(artifact), ok: true, metadata_satisfaction: executed.metadata_satisfaction })
            }
        }
        Err(err) => {
            let error = err.to_string();
            let commands = err.commands;
            let record = failed_track_record(
                &realized.track,
                Some(realized.realized_path),
                Some(staged_path),
                commands,
                error,
            );
            Ok(ScheduledTrackOutput { index: realized.index, record, artifact: None, ok: false, metadata_satisfaction: PlannedMetadataSatisfaction::none() })
        }
    }
}


fn push_stage_and_reaggregate(mut outcome: AlbumOutcome, record: StageRecord, _policy: FailurePolicy) -> AlbumOutcome {
    push_stage(&mut outcome, record);
    outcome
}

fn convert_result_from_scheduled_outputs(
    source: &PreparedSource,
    outputs: Vec<ScheduledTrackOutput>,
    req: &PipelineRequest,
) -> ConvertStageResult {
    let mut records_by_index: Vec<Option<TrackRecord>> = vec![None; source.tracks.len()];
    let mut artifacts_by_index: Vec<Option<TrackArtifact>> = vec![None; source.tracks.len()];
    for output in outputs {
        if output.index < records_by_index.len() {
            records_by_index[output.index] = Some(output.record);
            artifacts_by_index[output.index] = output.artifact;
        }
    }

    let mut records = Vec::with_capacity(source.tracks.len());
    let mut artifacts = Vec::new();
    for (index, track) in source.tracks.iter().enumerate() {
        if let Some(record) = records_by_index.get_mut(index).and_then(Option::take) {
            records.push(record);
        } else {
            records.push(failed_track_record(
                track,
                None,
                None,
                Vec::new(),
                "track worker did not produce a result".to_string(),
            ));
        }
        if let Some(artifact) = artifacts_by_index.get_mut(index).and_then(Option::take) {
            artifacts.push(artifact);
        }
    }

    let failed = records.iter().any(|record| !matches!(record.outcome, TrackOutcome::Ok));
    let record = convert_stage_record_for_tracks(
        &records,
        if failed && req.failure_policy == FailurePolicy::FailAlbumOnAnyTrackFailure {
            StageOutcome::Failed("one or more tracks failed".to_string())
        } else {
            StageOutcome::Ok
        },
    );
    ConvertStageResult {
        tracks: records,
        artifacts: ArtifactSet {
            audio: AudioArtifacts::Tracks(artifacts),
            sidecars: Vec::new(),
        },
        record,
    }
}

/// Run album-level stages after every scheduled track has completed. This is
/// the post-processing gate for merge, metadata, ReplayGain, feature analysis,
/// publish, and durable log. Album-mode ReplayGain can only enter here because
/// the scheduler calls this function after all track work has reported back.
pub async fn finish_pipeline_album_for_scheduler(
    album: ScheduledAlbum,
    track_outputs: Vec<ScheduledTrackOutput>,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
) -> PipelineReport {
    finish_pipeline_album_for_scheduler_with_tool_limits(
        album,
        track_outputs,
        runner,
        reporter,
        cancel,
        None,
    )
    .await
}

pub async fn finish_pipeline_album_for_scheduler_with_tool_limits(
    album: ScheduledAlbum,
    track_outputs: Vec<ScheduledTrackOutput>,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
) -> PipelineReport {
    let action_output = album.action_output;
    let source_replaygain = album.source_replaygain;
    let req = album.req;
    let item_id = req.item_id.clone();
    let staging = album.staging;
    let source_value = album.source;
    let plan_value = album.plan;
    let mut stages = album.stages;
    let source = Some(source_value.clone());
    let plan = Some(plan_value.clone());
    let mut published = None;
    // Assigned in the publish Ok arm; the Err arm diverges, so no initial
    // value is ever read.
    let publication_binding;

    emit_stage_started(reporter, &item_id, PipelineStage::Convert).await;
    let converted = convert_result_from_scheduled_outputs(&source_value, track_outputs, &req);
    emit_stage_finished(reporter, &item_id, converted.record.clone()).await;
    stages.push(converted.record.clone());
    let tracks = converted.tracks.clone();
    let mut artifacts = Some(converted.artifacts);
    let staging_is_scratch = staging.is_scratch_staging();
    let staging_root_for_retry = staging.root.clone();

    macro_rules! return_before_failure_publication_if_retryable_scratch {
        ($outcome:expr) => {{
            let outcome_for_retry = $outcome;
            if should_defer_terminal_failure_publication_for_scratch_retry_with_root(
                &req,
                staging_is_scratch,
                &staging_root_for_retry,
                &outcome_for_retry,
            ) {
                log::warn!(
                    "scratch failure eligible for disk retry; deferring terminal failure publication: job_id={}, item_id={}, disk_staging_path={}, original_error={}",
                    req.job_id,
                    item_id,
                    disk_staging_parent_for(&req).display(),
                    scratch_retry_original_error_from_outcome(&outcome_for_retry),
                );
                return retryable_scratch_failure_report_without_publication(
                    &req,
                    source,
                    plan,
                    artifacts,
                    outcome_for_retry,
                );
            }
        }};
    }

    let mut current_outcome = aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
    if cancel.is_cancelled() {
        current_outcome = cancelled_outcome_from(current_outcome);
        published = publish_cancelled_conversion_log_fragment_and_finalize(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
    }
    if matches!(current_outcome, AlbumOutcome::Partial { .. })
        && artifacts.as_ref().map(audio_artifact_count).unwrap_or(0) == 0
    {
        current_outcome = AlbumOutcome::Blocked {
            successful: successful_tracks_from(&current_outcome),
            failed: failed_tracks_from(&current_outcome),
            stages: stages_from(&current_outcome),
            reason: BlockReason::TrackFailures,
        };
    }
    if matches!(current_outcome, AlbumOutcome::Blocked { .. }) {
        return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
                published = publish_terminal_conversion_log_fragment_if_needed(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
    }

    if req.merge {
        emit_stage_started(reporter, &item_id, PipelineStage::Merge).await;
        match Box::pin(merge_tracks_with_tool_limits(
            artifacts.take().expect("artifacts present"),
            &req,
            &staging,
            runner,
            cancel,
            tool_concurrency_limits.clone(),
        ))
        .await
        {
            Ok((merged_artifacts, record)) => {
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                artifacts = Some(merged_artifacts);
            }
            Err(err) => {
                let record = stage_record(PipelineStage::Merge, StageOutcome::Failed(err.to_string()));
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                current_outcome = aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
                return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
                published = publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    source.as_ref(),
                    artifacts.as_ref(),
                    &current_outcome,
                    staging,
                    Some(runner),
                );
                return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
            }
        }
    } else {
        let record = stage_record(PipelineStage::Merge, StageOutcome::NotRequested);
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
    }

    if req.stages.metadata == StageRequirement::Enabled {
        emit_stage_started(reporter, &item_id, PipelineStage::Metadata).await;
        if planner_metadata_already_satisfied(
            artifacts.as_ref().expect("artifacts present"),
            source.as_ref().expect("source present"),
            &req,
        ) {
            let record = stage_record(
                PipelineStage::Metadata,
                StageOutcome::SkippedWithReason(
                    "already satisfied by the output planner".to_string(),
                ),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
        } else {
            match Box::pin(apply_metadata_with_tool_limits(
                artifacts.as_ref().expect("artifacts present"),
                source.as_ref().expect("source present"),
                &req,
                runner,
                cancel,
                tool_concurrency_limits.clone(),
            ))
            .await
            {
                Ok(record) => {
                    emit_stage_finished(reporter, &item_id, record.clone()).await;
                    stages.push(record);
                }
                Err(err) => {
                    let record = stage_record(PipelineStage::Metadata, StageOutcome::Failed(err.to_string()));
                    emit_stage_finished(reporter, &item_id, record.clone()).await;
                    stages.push(record);
                    current_outcome = aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
                    return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
                published = publish_terminal_conversion_log_fragment_if_needed(
                        &req,
                        source.as_ref(),
                        artifacts.as_ref(),
                        &current_outcome,
                        staging,
                        Some(runner),
                    );
                    return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
                }
            }
        }
    } else {
        let record = stage_record(PipelineStage::Metadata, StageOutcome::NotRequested);
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
    }

    if req.stages.replaygain == StageRequirement::Enabled {
        emit_stage_started(reporter, &item_id, PipelineStage::ReplayGain).await;
        let source_scan_record = source_replaygain.as_ref().and_then(|scan| {
            apply_cue_source_replaygain_if_eligible(
                artifacts.as_ref().expect("artifacts present"),
                source.as_ref(),
                &req,
                scan,
            )
        });
        let replaygain_result = match source_scan_record {
            Some(Ok(record)) => Ok(record),
            Some(Err(error)) => {
                log::warn!(
                    "source-pass ReplayGain tagging failed for job {}; rescanning encoded outputs: {error}",
                    req.job_id
                );
                Box::pin(apply_replaygain_with_source_and_tool_limits(
                    artifacts.as_ref().expect("artifacts present"),
                    source.as_ref(),
                    &req,
                    runner,
                    cancel,
                    tool_concurrency_limits.clone(),
                ))
                .await
            }
            None => Box::pin(apply_replaygain_with_source_and_tool_limits(
                artifacts.as_ref().expect("artifacts present"),
                source.as_ref(),
                &req,
                runner,
                cancel,
                tool_concurrency_limits.clone(),
            ))
            .await,
        };
        match replaygain_result {
            Ok(record) => {
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
            }
            Err(err) => {
                let record = stage_record(PipelineStage::ReplayGain, StageOutcome::Failed(err.to_string()));
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                current_outcome = aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
                return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
                published = publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    source.as_ref(),
                    artifacts.as_ref(),
                    &current_outcome,
                    staging,
                    Some(runner),
                );
                return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
            }
        }
    } else {
        let record = stage_record(PipelineStage::ReplayGain, StageOutcome::NotRequested);
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
    }

    if let Some(artifacts_mut) = artifacts.as_mut() {
        if let Err(err) = Box::pin(verify_reference_artifacts_after_metadata(
            artifacts_mut,
            runner,
            cancel,
            tool_concurrency_limits.as_ref(),
        ))
        .await
        {
            let record = stage_record(
                PipelineStage::Metadata,
                StageOutcome::Failed(format!(
                    "Reference decoded-sample verification after metadata failed: {err}"
                )),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
        }
    }

    current_outcome = aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
    if matches!(current_outcome, AlbumOutcome::Blocked { .. }) {
        return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
                published = publish_terminal_conversion_log_fragment_if_needed(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
    }

    if req.stages.features == StageRequirement::Enabled {
        emit_stage_started(reporter, &item_id, PipelineStage::Features).await;
        match Box::pin(run_features(
            artifacts.take().expect("artifacts present"),
            &current_outcome,
            source.as_ref().expect("source present"),
            &req,
            &staging,
            runner,
            cancel,
        ))
        .await
        {
            Ok((feature_artifacts, record)) => {
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                artifacts = Some(feature_artifacts);
            }
            Err(err) => {
                let record = stage_record(PipelineStage::Features, StageOutcome::Failed(err.to_string()));
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                current_outcome = aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
                return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
                published = publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    source.as_ref(),
                    artifacts.as_ref(),
                    &current_outcome,
                    staging,
                    Some(runner),
                );
                return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
            }
        }
    } else {
        let record = stage_record(PipelineStage::Features, StageOutcome::NotRequested);
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
    }

    current_outcome = aggregate_album_outcome(tracks, stages, req.failure_policy);
    if cancel.is_cancelled() {
        current_outcome = cancelled_outcome_from(current_outcome);
        published = publish_cancelled_conversion_log_fragment_and_finalize(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
    }
    if matches!(current_outcome, AlbumOutcome::Blocked { .. }) {
        return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
                published = publish_terminal_conversion_log_fragment_if_needed(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
    }

    // Native Reference publication always carries manifest-v2 authority.
    // Existing routes retain the opt-in legacy manifest policy.
    let reference_manifest_required = artifacts.as_ref().is_some_and(|artifact_set| match &artifact_set.audio {
        AudioArtifacts::Tracks(tracks) => tracks.iter().any(|track| track.reference_evidence.is_some()),
        AudioArtifacts::Merged(_) => false,
    });
    let conversion_manifest = if req.publish.write_manifest || reference_manifest_required {
        build_manifest_for_album(&req, &source_value, &artifacts, &plan_value)
            .map(Some)
            .map_err(PublishError::Manifest)
    } else {
        Ok(None)
    };

    emit_stage_started(reporter, &item_id, PipelineStage::Publish).await;
    let container_companion_snapshot =
        container_companion_snapshot_before_publish_best_effort(&req, &source_value);
    match conversion_manifest.and_then(|conversion_manifest| {
        artifacts
        .as_ref()
        .ok_or(PublishError::StagingMissing)
        .and_then(|artifact_set| {
            let identity_lock =
                acquire_album_action_authority_for_plan(&req, &plan_value, action_output.as_ref())?;
            let album = publish_album_output_for_plan_with_authority(
                staging,
                artifact_set,
                &req,
                &plan_value,
                req.publish.clone(),
                conversion_manifest.as_ref(),
                identity_lock.lock(),
                identity_lock.multi_root_locks(),
                identity_lock.reject_late_action_authority(),
            )?;
            let transition_album = match identity_lock.lock() {
                Some(lock) => published_album_bound_to_authority(&album, lock)?,
                None => album.clone(),
            };
            let binding = match identity_lock.lock() {
                Some(lock) => PublicationCapabilityBinding::capture(lock, &album.album_dir)?,
                None => match identity_lock.multi_root_locks().and_then(|locks| locks.first()) {
                    Some(lock) => PublicationCapabilityBinding::capture(
                        lock,
                        lock.canonical_album_dir(),
                    )?,
                    None => None,
                },
            };
            Ok((album, transition_album, identity_lock, binding))
        })
    }) {
        Ok((album, transition_album, mut identity_lock, binding)) => {
            publication_binding = binding;
            attest_publication_album_scope_best_effort(&req, publication_binding.as_ref());
            let record = stage_record(PipelineStage::Publish, StageOutcome::Ok);
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            current_outcome = push_stage_and_reaggregate(current_outcome, record, req.failure_policy);
            copy_container_companion_snapshot_after_publish_best_effort(
                &req,
                container_companion_snapshot.as_ref(),
                &transition_album,
            );
            let post_action_gate = copy_companion_artifacts_after_publish_best_effort(
                &req,
                &source_value,
                artifacts.as_ref(),
                &transition_album,
                publication_binding.as_ref(),
            );
            let album_is_fully_successful = matches!(current_outcome, AlbumOutcome::Complete { .. });
            if let Some(action_record) = Box::pin(execute_post_actions_stage(
                &req,
                &source_value,
                artifacts.as_ref(),
                &transition_album,
                &mut identity_lock,
                post_action_gate,
                album_is_fully_successful,
                reporter,
                cancel,
            ))
            .await
            {
                // Post-action failure never rewrites a successful publication
                // into a blocked album. The failed record remains visible in
                // the completed outcome and the durable action report carries
                // per-operation/script details.
                push_stage(&mut current_outcome, action_record);
            }
            published = Some(album);
        }
        Err(err) => {
            let record = stage_record(PipelineStage::Publish, StageOutcome::Failed(err.to_string()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            current_outcome = push_stage_and_reaggregate(current_outcome, record, req.failure_policy);
            current_outcome = AlbumOutcome::Blocked {
                successful: successful_tracks_from(&current_outcome),
                failed: failed_tracks_from(&current_outcome),
                stages: stages_from(&current_outcome),
                reason: BlockReason::PublishFailed,
            };
            return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            return Box::pin(finalize_report(&req, reporter, source, plan, artifacts, published, current_outcome)).await;
        }
    }

    Box::pin(finalize_report_with_binding(
        &req,
        reporter,
        source,
        plan,
        artifacts,
        published,
        current_outcome,
        publication_binding,
    ))
    .await
}

/// Run the staged pipeline for one queue item. `process_item` does not call
/// this yet; PR 4 freezes this orchestration shape for later PRs.
pub async fn run_pipeline_item(
    req: PipelineRequest,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
) -> PipelineReport {
    let tool_paths: HashMap<String, PathBuf> = HashMap::new();
    Box::pin(run_pipeline_item_with_tool_paths(
        req, runner, reporter, cancel, &tool_paths,
    ))
    .await
}

pub async fn run_pipeline_item_with_tool_paths(
    req: PipelineRequest,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    tool_paths: &HashMap<String, PathBuf>,
) -> PipelineReport {
    Box::pin(run_pipeline_item_with_tool_paths_and_tool_limits(
        req,
        runner,
        reporter,
        cancel,
        tool_paths,
        None,
    ))
    .await
}

pub async fn run_pipeline_item_with_tool_paths_and_tool_limits(
    req: PipelineRequest,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    tool_paths: &HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
) -> PipelineReport {
    let req = req;
    let item_id = req.item_id.clone();
    if crate::concurrency::runtime_execution_id(&item_id).is_some() {
        crate::concurrency::with_runtime_execution_scope(
            item_id,
            Box::pin(run_pipeline_item_with_tool_paths_and_tool_limits_scoped_inner(
                req, runner, reporter, cancel, tool_paths, tool_concurrency_limits
            )),
        ).await
    } else {
        Box::pin(run_pipeline_item_with_tool_paths_and_tool_limits_scoped_inner(
            req, runner, reporter, cancel, tool_paths, tool_concurrency_limits
        )).await
    }
}

async fn run_pipeline_item_with_tool_paths_and_tool_limits_scoped_inner(
    req: PipelineRequest,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    tool_paths: &HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
) -> PipelineReport {
    let scratch_retry_root = req.scratch_staging.as_ref().map(|scratch| scratch.root().to_path_buf());
    let retry_on_disk = scratch_retry_root.is_some();
    let disk_retry_req = retry_on_disk.then(|| request_without_scratch_staging(&req));
    let item_id = req.item_id.clone();

    let report = Box::pin(run_pipeline_item_with_tool_paths_and_tool_limits_once(
        req,
        runner,
        reporter,
        cancel,
        tool_paths,
        tool_concurrency_limits.clone(),
    ))
    .await;

    let Some(disk_req) = disk_retry_req else {
        return report;
    };
    if cancel.is_cancelled() || !pipeline_report_requests_scratch_disk_retry(&report) {
        return report;
    }

    let original_error = report
        .scratch_retry_intent
        .as_ref()
        .map(|intent| intent.original_error.clone())
        .unwrap_or_else(|| scratch_retry_original_error_from_outcome(&report.outcome));
    log::warn!(
        "scratch retrying on disk: job_id={}, item_id={}, disk_staging_path={}, original_error={}",
        disk_req.job_id,
        item_id,
        disk_staging_parent_for(&disk_req).display(),
        original_error,
    );
    Box::pin(run_pipeline_item_with_tool_paths_and_tool_limits_once(
        disk_req,
        runner,
        reporter,
        cancel,
        tool_paths,
        tool_concurrency_limits,
    ))
    .await
}

async fn run_pipeline_item_with_tool_paths_and_tool_limits_once(
    mut req: PipelineRequest,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    tool_paths: &HashMap<String, PathBuf>,
    tool_concurrency_limits: Option<Arc<ToolConcurrencyLimits>>,
) -> PipelineReport {
    let item_id = req.item_id.clone();
    let mut source = None;
    let mut plan = None;
    let mut artifacts = None;
    let mut published = None;
    // Assigned in the publish Ok arm; the Err arm diverges, so no initial
    // value is ever read.
    let publication_binding;
    #[allow(unused_assignments)]
    let mut tracks = Vec::new();
    let mut stages = Vec::new();

    if cancel.is_cancelled() {
        let published = finalize_cancelled_conversion_log_batch_if_needed(&req);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::Cancelled,
        };
        return finalize_report(&req, reporter, source, plan, artifacts, published, outcome).await;
    }

    if let Err(err) = validate_request(&req) {
        let record = stage_record(
            PipelineStage::Materialize,
            StageOutcome::Failed(err.to_string()),
        );
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::MaterializeFailed,
        };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
            &req,
            &outcome,
        );
        return finalize_report(&req, reporter, source, plan, artifacts, published, outcome).await;
    }

    if let Err(error) = admit_initial_conversion_claims(&mut req) {
        let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(format!("concurrency admission failed: {error}")));
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked { successful: Vec::new(), failed: Vec::new(), stages, reason: BlockReason::MaterializeFailed };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(&req, &outcome);
        return finalize_report(&req, reporter, source, plan, artifacts, published, outcome).await;
    }

    let admitted_planner_output = match admit_planner_resolved_output_claim(&mut req) {
        Ok(admitted) => admitted,
        Err(error) => {
            emit_stage_started(reporter, &item_id, PipelineStage::PreActions).await;
            let record = stage_record(PipelineStage::PreActions, StageOutcome::Failed(format!("output concurrency admission failed before pre-actions: {error}")));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked { successful: Vec::new(), failed: Vec::new(), stages, reason: BlockReason::RequiredStageFailure(PipelineStage::PreActions) };
            let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(&req, &outcome);
            return finalize_report(&req, reporter, source, plan, artifacts, published, outcome).await;
        }
    };

    if let Err(error) = preflight_album_conversion_tools(&req, runner) {
        emit_stage_started(reporter, &item_id, PipelineStage::Convert).await;
        let record = stage_record(PipelineStage::Convert, StageOutcome::Failed(error));
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::RequiredStageFailure(PipelineStage::Convert),
        };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
            &req,
            &outcome,
        );
        return finalize_report(&req, reporter, source, plan, artifacts, published, outcome).await;
    }

    let action_output = match PipelineOutputCapability::capture_for_actions(&req) {
        Ok(binding) => binding,
        Err(error) => {
            emit_stage_started(reporter, &item_id, PipelineStage::PreActions).await;
            let record = stage_record(
                PipelineStage::PreActions,
                StageOutcome::Failed(format!(
                    "could not retain one output/coordination root for the action transaction: {error}"
                )),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason: BlockReason::RequiredStageFailure(PipelineStage::PreActions),
            };
            let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
                &req,
                &outcome,
            );
            return finalize_report(&req, reporter, source, plan, artifacts, published, outcome).await;
        }
    };

    let pre_actions_ran_before_materialization =
        match prepare_batch_pre_actions_before_materialization(
            &req,
            action_output.as_ref(),
            reporter,
            cancel,
            &mut stages,
        )
        .await
        {
            PreMaterializationActionOutcome::Continue { ran_pre_actions } => ran_pre_actions,
            PreMaterializationActionOutcome::Finished(report) => return report,
        };

    conservative_output_capacity_preflight(&req);

    emit_stage_started(reporter, &item_id, PipelineStage::Materialize).await;
    let materialization = materialize_with_optional_disk_retry(
        &req,
        select_staging_parent_for(&req),
        runner,
        Some(reporter),
        tool_paths,
        cancel,
    )
    .await;
    let (attempt, materialized) = match materialization {
        MaterializationRun::Attempted { attempt, result } => (attempt, result),
        MaterializationRun::FailedBeforeAttempt { error, context } => {
            let record = stage_record(
                PipelineStage::Materialize,
                StageOutcome::Failed(error.to_string()),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason: BlockReason::MaterializeFailed,
            };
            let published = publish_pre_materialization_terminal_batch_failure_or_finalize(
                &req,
                &outcome,
                context,
            );
            return finalize_report(&req, reporter, source, plan, artifacts, published, outcome)
                .await;
        }
    };
    let (_run_lock, staging) = attempt.into_parts();
    let staging_root_for_retry = staging.root.clone();
    let staging_was_scratch_for_retry = staging.is_scratch_staging();

    macro_rules! return_before_failure_publication_if_retryable_scratch {
        ($outcome:expr) => {{
            let outcome_for_retry = $outcome;
            if should_defer_terminal_failure_publication_for_scratch_retry_with_root(
                &req,
                staging_was_scratch_for_retry,
                &staging_root_for_retry,
                &outcome_for_retry,
            ) {
                log::warn!(
                    "scratch failure eligible for disk retry; deferring terminal failure publication: job_id={}, item_id={}, disk_staging_path={}, original_error={}",
                    req.job_id,
                    item_id,
                    disk_staging_parent_for(&req).display(),
                    scratch_retry_original_error_from_outcome(&outcome_for_retry),
                );
                return retryable_scratch_failure_report_without_publication(
                    &req,
                    source,
                    plan,
                    artifacts,
                    outcome_for_retry,
                );
            }
        }};
    }

    match materialized {
        Ok(prepared) => {
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Ok);
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            source = Some(prepared);
        }
        Err(MaterializeError::BlockedSource { message, blocked }) => {
            let blocked = *blocked;
            let record = stage_record(
                PipelineStage::Materialize,
                StageOutcome::Failed(message.clone()),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let failed = blocked_track_records(&blocked.source, &message);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed,
                stages,
                reason: BlockReason::EncryptedSource,
            };
            let source = Some(blocked.source);
            return_before_failure_publication_if_retryable_scratch!(outcome.clone());
            let published = publish_terminal_conversion_log_fragment_if_needed(
                &req,
                source.as_ref(),
                artifacts.as_ref(),
                &outcome,
                staging,
                Some(runner),
            );
            return finalize_report(
                &req,
                reporter,
                source,
                plan,
                artifacts,
                published,
                outcome,
            )
            .await;
        }
        Err(err) => {
            let cancelled = matches!(err, MaterializeError::Cancelled);
            let reason = if cancelled {
                BlockReason::Cancelled
            } else {
                BlockReason::MaterializeFailed
            };
            let record = stage_record(
                PipelineStage::Materialize,
                StageOutcome::Failed(err.to_string()),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason,
            };
            let published = if cancelled {
                finalize_cancelled_conversion_log_batch_if_needed(&req)
            } else {
                return_before_failure_publication_if_retryable_scratch!(outcome.clone());
                publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    None,
                    artifacts.as_ref(),
                    &outcome,
                    staging,
                    Some(runner),
                )
            };
            return finalize_report(&req, reporter, source, plan, artifacts, published, outcome)
                .await;
        }
    }

    if cancel.is_cancelled() {
        let published = finalize_cancelled_conversion_log_batch_if_needed(&req);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::Cancelled,
        };
        return finalize_report(&req, reporter, source, plan, artifacts, published, outcome).await;
    }

    // Enrich album metadata with label/pressing info before planning.
    // Tag-sourced values take priority; the resolver only fills gaps.
    if let Some(ref mut src) = source {
        enrich_source_with_label_info(src, &req.container, &req);
        apply_batch_identity_and_request_metadata(src, &req);
    }

    emit_stage_started(reporter, &item_id, PipelineStage::PlanOutputs).await;
    match plan_outputs(source.as_ref().expect("materialized source present"), &req) {
        Ok(album_plan) => {
            let record = stage_record(PipelineStage::PlanOutputs, StageOutcome::Ok);
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            plan = Some(album_plan);
        }
        Err(err) => {
            let plan_error = err.to_string();
            let record = stage_record(
                PipelineStage::PlanOutputs,
                StageOutcome::Failed(plan_error.clone()),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let failed = failed_track_records(
                source.as_ref().expect("materialized source present"),
                &format!("output planning failed: {plan_error}"),
            );
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed,
                stages,
                reason: BlockReason::PlanFailed,
            };
            return_before_failure_publication_if_retryable_scratch!(outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
                &req,
                source.as_ref(),
                None,
                &outcome,
                staging,
                Some(runner),
            );
            return finalize_report(&req, reporter, source, plan, artifacts, published, outcome)
                .await;
        }
    }

    if let Err(error) = admit_planned_output_claim(&req, plan.as_ref().expect("plan present"), admitted_planner_output.as_deref()) {
        let record = stage_record(PipelineStage::PlanOutputs, StageOutcome::Failed(format!("output concurrency admission failed: {error}")));
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked { successful: Vec::new(), failed: Vec::new(), stages, reason: BlockReason::PlanFailed };
        published = publish_terminal_conversion_log_fragment_if_needed(&req, source.as_ref(), artifacts.as_ref(), &outcome, staging, Some(runner));
        return finalize_report(&req, reporter, source, plan, artifacts, published, outcome).await;
    }

    if let super::rerun::RerunDecision::Skip {
        manifest,
        manifest_path,
    } = decide_rerun_after_reference_preflight(
        &req,
        source.as_ref().expect("source present"),
        plan.as_ref().expect("plan present"),
        runner,
        cancel,
    )
    .await
    {
        if !pre_actions_ran_before_materialization {
            return finalize_manifest_skip(
                &req,
                reporter,
                source.take().expect("source present"),
                plan.take().expect("plan present"),
                stages,
                manifest,
                manifest_path,
            )
            .await;
        }
        log::warn!(
            "manifest became skippable after this run durably completed pre-actions; proceeding with publication so actions are never attributed to an all-skipped run: job_id={}, item_id={}, album_dir={}",
            req.job_id,
            req.item_id,
            plan.as_ref().expect("plan present").album_dir.display(),
        );
    }

    if !req.actions.pre.is_empty() && !pre_actions_ran_before_materialization {
        let record = execute_pre_actions_stage(&req, action_output.as_ref(), reporter, cancel).await;
        let failed = matches!(record.outcome, StageOutcome::Failed(_));
        stages.push(record);
        if failed {
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason: BlockReason::RequiredStageFailure(PipelineStage::PreActions),
            };
            return_before_failure_publication_if_retryable_scratch!(outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
                &req,
                source.as_ref(),
                None,
                &outcome,
                staging,
                Some(runner),
            );
            return finalize_report(
                &req,
                reporter,
                source,
                plan,
                artifacts,
                published,
                outcome,
            )
            .await;
        }
    }

    emit_stage_started(reporter, &item_id, PipelineStage::Convert).await;
    let converted = Box::pin(convert_tracks_with_reporter_with_tool_paths(
        source.as_ref().expect("source present"),
        plan.as_ref().expect("plan present"),
        &req,
        &staging,
        runner,
        cancel,
        Some(reporter),
        tool_paths,
        tool_concurrency_limits.clone(),
    ))
    .await;
    emit_stage_finished(reporter, &item_id, converted.record.clone()).await;
    stages.push(converted.record.clone());
    tracks = converted.tracks.clone();
    artifacts = Some(converted.artifacts);

    let mut current_outcome =
        aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
    if cancel.is_cancelled() {
        current_outcome = cancelled_outcome_from(current_outcome);
        published = publish_cancelled_conversion_log_fragment_and_finalize(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return finalize_report(
            &req,
            reporter,
            source,
            plan,
            artifacts,
            published,
            current_outcome,
        )
        .await;
    }
    if matches!(current_outcome, AlbumOutcome::Partial { .. })
        && artifacts.as_ref().map(audio_artifact_count).unwrap_or(0) == 0
    {
        current_outcome = AlbumOutcome::Blocked {
            successful: successful_tracks_from(&current_outcome),
            failed: failed_tracks_from(&current_outcome),
            stages: stages_from(&current_outcome),
            reason: BlockReason::TrackFailures,
        };
    }
    if matches!(current_outcome, AlbumOutcome::Blocked { .. }) {
        return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return finalize_report(
            &req,
            reporter,
            source,
            plan,
            artifacts,
            published,
            current_outcome,
        )
        .await;
    }

    if req.merge {
        emit_stage_started(reporter, &item_id, PipelineStage::Merge).await;
        match merge_tracks_with_tool_limits(
            artifacts.take().expect("artifacts present"),
            &req,
            &staging,
            runner,
            cancel,
            tool_concurrency_limits.clone(),
        )
        .await
        {
            Ok((merged_artifacts, record)) => {
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                artifacts = Some(merged_artifacts);
            }
            Err(err) => {
                let record =
                    stage_record(PipelineStage::Merge, StageOutcome::Failed(err.to_string()));
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                current_outcome =
                    aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
                return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    source.as_ref(),
                    artifacts.as_ref(),
                    &current_outcome,
                    staging,
                    Some(runner),
                );
                return finalize_report(
                    &req,
                    reporter,
                    source,
                    plan,
                    artifacts,
                    published,
                    current_outcome,
                )
                .await;
            }
        }
    } else {
        let record = stage_record(PipelineStage::Merge, StageOutcome::NotRequested);
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
    }

    if req.stages.metadata == StageRequirement::Enabled {
        emit_stage_started(reporter, &item_id, PipelineStage::Metadata).await;
        if planner_metadata_already_satisfied(
            artifacts.as_ref().expect("artifacts present"),
            source.as_ref().expect("source present"),
            &req,
        ) {
            let record = stage_record(
                PipelineStage::Metadata,
                StageOutcome::SkippedWithReason(
                    "already satisfied by the output planner".to_string(),
                ),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
        } else {
            match apply_metadata_with_tool_limits(
                artifacts.as_ref().expect("artifacts present"),
                source.as_ref().expect("source present"),
                &req,
                runner,
                cancel,
                tool_concurrency_limits.clone(),
            )
            .await
            {
                Ok(record) => {
                    emit_stage_finished(reporter, &item_id, record.clone()).await;
                    stages.push(record);
                }
                Err(err) => {
                    let record = stage_record(
                        PipelineStage::Metadata,
                        StageOutcome::Failed(err.to_string()),
                    );
                    emit_stage_finished(reporter, &item_id, record.clone()).await;
                    stages.push(record);
                    current_outcome =
                        aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
                    return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
                        &req,
                        source.as_ref(),
                        artifacts.as_ref(),
                        &current_outcome,
                        staging,
                        Some(runner),
                    );
                    return finalize_report(
                        &req,
                        reporter,
                        source,
                        plan,
                        artifacts,
                        published,
                        current_outcome,
                    )
                    .await;
                }
            }
        }
    } else {
        let record = stage_record(PipelineStage::Metadata, StageOutcome::NotRequested);
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
    }

    if req.stages.replaygain == StageRequirement::Enabled {
        emit_stage_started(reporter, &item_id, PipelineStage::ReplayGain).await;
        match apply_replaygain_with_source_and_tool_limits(
            artifacts.as_ref().expect("artifacts present"),
            source.as_ref(),
            &req,
            runner,
            cancel,
            tool_concurrency_limits.clone(),
        )
        .await
        {
            Ok(record) => {
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
            }
            Err(err) => {
                let record = stage_record(
                    PipelineStage::ReplayGain,
                    StageOutcome::Failed(err.to_string()),
                );
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                current_outcome =
                    aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
                return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    source.as_ref(),
                    artifacts.as_ref(),
                    &current_outcome,
                    staging,
                    Some(runner),
                );
                return finalize_report(
                    &req,
                    reporter,
                    source,
                    plan,
                    artifacts,
                    published,
                    current_outcome,
                )
                .await;
            }
        }
    } else {
        let record = stage_record(PipelineStage::ReplayGain, StageOutcome::NotRequested);
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
    }

    if let Some(artifacts_mut) = artifacts.as_mut() {
        if let Err(err) = verify_reference_artifacts_after_metadata(
            artifacts_mut,
            runner,
            cancel,
            tool_concurrency_limits.as_ref(),
        )
        .await
        {
            let record = stage_record(
                PipelineStage::Metadata,
                StageOutcome::Failed(format!(
                    "Reference decoded-sample verification after metadata failed: {err}"
                )),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
        }
    }

    current_outcome = aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
    if matches!(current_outcome, AlbumOutcome::Blocked { .. }) {
        return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return finalize_report(
            &req,
            reporter,
            source,
            plan,
            artifacts,
            published,
            current_outcome,
        )
        .await;
    }

    if req.stages.features == StageRequirement::Enabled {
        emit_stage_started(reporter, &item_id, PipelineStage::Features).await;
        match run_features(
            artifacts.take().expect("artifacts present"),
            &current_outcome,
            source.as_ref().expect("source present"),
            &req,
            &staging,
            runner,
            cancel,
        )
        .await
        {
            Ok((feature_artifacts, record)) => {
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                artifacts = Some(feature_artifacts);
            }
            Err(err) => {
                let record = stage_record(
                    PipelineStage::Features,
                    StageOutcome::Failed(err.to_string()),
                );
                emit_stage_finished(reporter, &item_id, record.clone()).await;
                stages.push(record);
                current_outcome =
                    aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
                return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    source.as_ref(),
                    artifacts.as_ref(),
                    &current_outcome,
                    staging,
                    Some(runner),
                );
                return finalize_report(
                    &req,
                    reporter,
                    source,
                    plan,
                    artifacts,
                    published,
                    current_outcome,
                )
                .await;
            }
        }
    } else {
        let record = stage_record(PipelineStage::Features, StageOutcome::NotRequested);
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
    }

    current_outcome = aggregate_album_outcome(tracks.clone(), stages.clone(), req.failure_policy);
    if cancel.is_cancelled() {
        current_outcome = cancelled_outcome_from(current_outcome);
        published = publish_cancelled_conversion_log_fragment_and_finalize(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return finalize_report(
            &req,
            reporter,
            source,
            plan,
            artifacts,
            published,
            current_outcome,
        )
        .await;
    }
    if matches!(current_outcome, AlbumOutcome::Blocked { .. }) {
        return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            published = publish_terminal_conversion_log_fragment_if_needed(
            &req,
            source.as_ref(),
            artifacts.as_ref(),
            &current_outcome,
            staging,
            Some(runner),
        );
        return finalize_report(
            &req,
            reporter,
            source,
            plan,
            artifacts,
            published,
            current_outcome,
        )
        .await;
    }

    emit_stage_started(reporter, &item_id, PipelineStage::Publish).await;
    let container_companion_snapshot = source
        .as_ref()
        .and_then(|source_ref| container_companion_snapshot_before_publish_best_effort(&req, source_ref));
    match artifacts
        .as_ref()
        .ok_or(PublishError::StagingMissing)
        .and_then(|artifact_set| {
            let planned = plan.as_ref().ok_or(PublishError::StagingMissing)?;
            let identity_lock =
                acquire_album_action_authority_for_plan(&req, planned, action_output.as_ref())?;
            let album = publish_album_output_for_plan_with_authority(
                staging,
                artifact_set,
                &req,
                planned,
                req.publish.clone(),
                None,
                identity_lock.lock(),
                identity_lock.multi_root_locks(),
                identity_lock.reject_late_action_authority(),
            )?;
            let transition_album = match identity_lock.lock() {
                Some(lock) => published_album_bound_to_authority(&album, lock)?,
                None => album.clone(),
            };
            let binding = match identity_lock.lock() {
                Some(lock) => PublicationCapabilityBinding::capture(lock, &album.album_dir)?,
                None => match identity_lock.multi_root_locks().and_then(|locks| locks.first()) {
                    Some(lock) => PublicationCapabilityBinding::capture(
                        lock,
                        lock.canonical_album_dir(),
                    )?,
                    None => None,
                },
            };
            Ok((album, transition_album, identity_lock, binding))
        })
    {
        Ok((album, transition_album, mut identity_lock, binding)) => {
            publication_binding = binding;
            attest_publication_album_scope_best_effort(&req, publication_binding.as_ref());
            let record = stage_record(PipelineStage::Publish, StageOutcome::Ok);
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            // Publish is conversion-blocking and belongs in the aggregated
            // conversion outcome. Post actions do not: their stage record is
            // appended afterward so a failed post action remains visible as
            // "completed with action errors" without rewriting a successful
            // conversion into a blocked conversion.
            current_outcome = aggregate_album_outcome(
                tracks.clone(),
                stages.clone(),
                req.failure_policy,
            );
            copy_container_companion_snapshot_after_publish_best_effort(
                &req,
                container_companion_snapshot.as_ref(),
                &transition_album,
            );
            if let Some(source_ref) = source.as_ref() {
                let post_action_gate = copy_companion_artifacts_after_publish_best_effort(
                    &req,
                    source_ref,
                    artifacts.as_ref(),
                    &transition_album,
                    publication_binding.as_ref(),
                );
                let album_is_fully_successful = matches!(current_outcome, AlbumOutcome::Complete { .. });
                if let Some(action_record) = execute_post_actions_stage(
                    &req,
                    source_ref,
                    artifacts.as_ref(),
                    &transition_album,
                    &mut identity_lock,
                    post_action_gate,
                    album_is_fully_successful,
                    reporter,
                    cancel,
                )
                .await
                {
                    push_stage(&mut current_outcome, action_record);
                }
            }
            published = Some(album);
        }
        Err(err) => {
            let record = stage_record(
                PipelineStage::Publish,
                StageOutcome::Failed(err.to_string()),
            );
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            current_outcome = AlbumOutcome::Blocked {
                successful: successful_tracks_from(&current_outcome),
                failed: failed_tracks_from(&current_outcome),
                stages,
                reason: BlockReason::PublishFailed,
            };
            return_before_failure_publication_if_retryable_scratch!(current_outcome.clone());
            return finalize_report(
                &req,
                reporter,
                source,
                plan,
                artifacts,
                published,
                current_outcome,
            )
            .await;
        }
    }

    finalize_report_with_binding(
        &req,
        reporter,
        source,
        plan,
        artifacts,
        published,
        current_outcome,
        publication_binding,
    )
    .await
}

#[derive(Debug, Default)]
struct CompanionCopyStats {
    copied: usize,
    skipped: usize,
    warnings: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PostActionGate {
    /// The album-batch completion/finalization signal has not arrived yet.
    NotReady,
    /// Companion finalization reached the exact warning-free success state.
    Ready,
    /// Companion finalization ran or was attempted but did not satisfy its
    /// existing `is_fully_successful` predicate.
    Failed,
}

fn batch_post_action_completion_gate(
    req: &PipelineRequest,
    coordination_io_dir: Option<&Path>,
) -> PostActionGate {
    if req.album_batch.is_none() {
        return PostActionGate::Ready;
    }
    let status = coordination_io_dir
        .map(|coord_dir| conversion_log_batch_completion_status_at(req, coord_dir))
        .unwrap_or_else(|| conversion_log_batch_completion_status(req));
    match status {
        ConversionLogBatchCompletionStatus::Successful => PostActionGate::Ready,
        ConversionLogBatchCompletionStatus::Incomplete => PostActionGate::NotReady,
        ConversionLogBatchCompletionStatus::NonSuccessful
        | ConversionLogBatchCompletionStatus::Invalid => PostActionGate::Failed,
    }
}

/// Resolve the post-action gate after publication and companion handling.
///
/// The durable completion marker remains the primary authority. The publisher
/// also returns an ephemeral, non-serialized success state captured while the
/// same batch-finalization lock was held. Use that state only when a subsequent
/// marker read reports `Incomplete`; never let it override an explicit failed
/// or malformed durable marker.
///
/// This closes the flat coordinated lifecycle gap without weakening failure
/// semantics. The former fallback candidate — presence of `conversion.log` —
/// was insufficient because failed batches also publish a final log.
fn batch_post_action_completion_gate_after_publish(
    req: &PipelineRequest,
    published: &PublishedAlbum,
    coordination_io_dir: Option<&Path>,
) -> PostActionGate {
    match batch_post_action_completion_gate(req, coordination_io_dir) {
        PostActionGate::NotReady => match published.batch_completion {
            Some(PublishedBatchCompletion::Successful) => PostActionGate::Ready,
            Some(PublishedBatchCompletion::NonSuccessful) => PostActionGate::Failed,
            None => PostActionGate::NotReady,
        },
        gate => gate,
    }
}

impl CompanionCopyStats {
    fn copied(&mut self) {
        self.copied += 1;
    }

    fn skipped(&mut self) {
        self.skipped += 1;
    }

    fn warning(&mut self) {
        self.warnings += 1;
    }

    fn is_fully_successful(&self) -> bool {
        self.warnings == 0
    }
}

/// Coordinate companion copying at the publish/finalization boundary.
///
/// Historical call path: successful materialization publishes audio/sidecars,
/// then calls this hook before the pipeline reports the item complete. Ordinary
/// non-batch conversions still copy immediately from that item's source
/// directory. Resolved album batches do not scan from that per-item hook; they
/// wait until publish emits the album-batch completion signal, then scan the
/// source grouping root once into the planner-resolved album directory.
/// Companions that live INSIDE a self-contained container (lineage.txt,
/// Artwork/ folders and the like extracted from a 7z/ISO) exist only in the
/// materialization staging — which publish consumes before the companion
/// pass runs. Snapshot the eligible files out of the extraction root while
/// staging is still alive; the snapshot is swept into the published album
/// afterwards. The snapshot uses the SAME sweep machinery both ways, so
/// include/exclude lists, folder copying, and nested disc/extras rules apply
/// exactly as they do for folder sources.
fn container_companion_snapshot_before_publish_best_effort(
    req: &PipelineRequest,
    source: &PreparedSource,
) -> Option<StagingDir> {
    match source.kind {
        SourceKind::Archive
        | SourceKind::SacdIso
        | SourceKind::DvdAudio
        | SourceKind::DvdVideo
        | SourceKind::BluRay => {}
        SourceKind::SingleFile | SourceKind::CueImage => return None,
    }
    if req.companion.is_empty() {
        return None;
    }
    let extraction_root = companion_prepared_track_common_source_root(source)?;
    // The snapshot exists to rescue companions from EXTRACTION STAGING that
    // publish is about to delete. Disc-format track refs point back at the
    // ORIGINAL container location (an ISO's parent, the disc root), which is
    // not staging: those roots survive publish and flow through the regular
    // ancestor-gated sweep instead. Snapshotting them here would bypass the
    // dedication gate and re-open the bulk-directory sweep.
    let home = companion_container_home(&req.container);
    if normalize_path(&home).starts_with(normalize_path(&extraction_root)) {
        return None;
    }
    // The snapshot must OUTLIVE publish, which deletes the whole job staging
    // tree (extraction included). Place it beside the job stagings in the
    // durable staging parent; the returned StagingDir removes it on drop.
    let snapshot_parent = disk_staging_parent_for(req);
    if let Err(err) = fs::create_dir_all(&snapshot_parent) {
        log::warn!(
            "container companion snapshot skipped for {}: cannot create staging parent {}: {err}",
            req.item_id,
            snapshot_parent.display()
        );
        return None;
    }
    let snapshot_root = unique_path(&snapshot_parent, ".tonepoet-companion-snapshot");
    if let Err(err) = fs::create_dir_all(&snapshot_root) {
        log::warn!(
            "container companion snapshot skipped for {}: cannot create {}: {err}",
            req.item_id,
            snapshot_root.display()
        );
        return None;
    }
    let snapshot = StagingDir::new(snapshot_root, format!("{}-companion-snapshot", req.job_id));
    let skip_set = companion_source_file_skip_set(req, source);
    let stats = copy_companion_artifacts_from_source_dir_best_effort(
        req,
        &extraction_root,
        &snapshot.root,
        &skip_set,
        &BTreeMap::new(),
        &[],
        req.item_id.as_str(),
    );
    if stats.copied == 0 {
        return None;
    }
    Some(snapshot)
}

fn copy_container_companion_snapshot_after_publish_best_effort(
    req: &PipelineRequest,
    snapshot: Option<&StagingDir>,
    published: &PublishedAlbum,
) {
    let Some(snapshot) = snapshot else {
        return;
    };
    copy_companion_artifacts_from_source_dir_best_effort(
        req,
        &snapshot.root,
        &published.album_dir,
        &BTreeSet::new(),
        &BTreeMap::new(),
        &[],
        req.item_id.as_str(),
    );
}

fn copy_companion_artifacts_after_publish_best_effort(
    req: &PipelineRequest,
    source: &PreparedSource,
    artifacts: Option<&ArtifactSet>,
    published: &PublishedAlbum,
    binding: Option<&PublicationCapabilityBinding>,
) -> PostActionGate {
    let coordination_io_dir = if req.album_batch.is_some() {
        match binding.map(|binding| binding.coordination_dir(req)).transpose() {
            Ok(path) => path,
            Err(error) => {
                log::error!(
                    "companion finalization refused an unbound coordination fallback for {}: {error}",
                    req.item_id
                );
                return PostActionGate::Failed;
            }
        }
    } else {
        None
    };
    let output_io_root = match binding
        .map(|binding| binding.io_path(&req.output_root))
        .transpose()
    {
        Ok(path) => path,
        Err(error) => {
            log::error!(
                "companion finalization refused an unbound output-root fallback for {}: {error}",
                req.item_id
            );
            return PostActionGate::Failed;
        }
    };
    let coordination_io_dir = coordination_io_dir.as_deref();
    let output_io_root = output_io_root.as_deref();

    if should_coordinate_album_batch_companion_copy(req) {
        copy_album_batch_companion_artifacts_once_ready_with_binding_best_effort(
            req,
            artifacts,
            published,
            binding,
            coordination_io_dir,
            output_io_root,
        )
    } else {
        let stats = copy_companion_artifacts_best_effort(req, source, artifacts, published);
        // Album batches without a resolved identity still participate in the
        // same durable terminal protocol. Sweep unrelated stale workspaces
        // here, but never clean the current batch from a companion-copy path:
        // only per-worker finalization may acknowledge the participant, and
        // only the last acknowledged terminal participant may begin cleanup.
        if req.album_batch.is_some() {
            match output_io_root {
                Some(output_root) => {
                    sweep_stale_completed_conversion_log_batch_coordination_for_request_at_best_effort(
                        req,
                        output_root,
                        req.item_id.as_str(),
                    );
                }
                None => sweep_stale_completed_conversion_log_batch_coordination_for_request_best_effort(
                    req,
                    req.item_id.as_str(),
                ),
            }
        }
        if !stats.is_fully_successful() {
            PostActionGate::Failed
        } else {
            batch_post_action_completion_gate_after_publish(req, published, coordination_io_dir)
        }
    }
}

fn should_coordinate_album_batch_companion_copy(req: &PipelineRequest) -> bool {
    req.album_batch
        .as_ref()
        .and_then(|batch| batch.resolved_identity())
        .is_some()
}

fn copy_album_batch_companion_artifacts_once_ready_best_effort(
    req: &PipelineRequest,
    artifacts: Option<&ArtifactSet>,
    published: &PublishedAlbum,
) -> PostActionGate {
    copy_album_batch_companion_artifacts_once_ready_with_binding_best_effort(
        req,
        artifacts,
        published,
        None,
        None,
        None,
    )
}

fn copy_album_batch_companion_artifacts_once_ready_with_binding_best_effort(
    req: &PipelineRequest,
    artifacts: Option<&ArtifactSet>,
    published: &PublishedAlbum,
    binding: Option<&PublicationCapabilityBinding>,
    coordination_io_dir: Option<&Path>,
    output_io_root: Option<&Path>,
) -> PostActionGate {
    if !should_coordinate_album_batch_companion_copy(req) {
        return PostActionGate::NotReady;
    }

    let Some(batch) = req.album_batch.as_ref() else {
        return PostActionGate::NotReady;
    };
    let context = format!("album batch {}", batch.conversion_log_batch_id.trim());
    let ownership_result = match coordination_io_dir {
        Some(coord_dir) => ensure_conversion_log_batch_workspace_owned_for_request_at(req, coord_dir),
        None => ensure_conversion_log_batch_workspace_owned_for_request(req),
    };
    if let Err(error) = ownership_result {
        log::error!(
            "companion finalization refused to mutate unowned conversion-log batch workspace for {context}: {error}"
        );
        return PostActionGate::Failed;
    }
    let _batch_workspace_guard = match coordination_io_dir {
        Some(coord_dir) => activate_conversion_log_batch_workspace_for_request_at_best_effort(
            req,
            coord_dir,
            context.as_str(),
        ),
        None => activate_conversion_log_batch_workspace_for_request_best_effort(
            req,
            context.as_str(),
        ),
    };
    match output_io_root {
        Some(output_root) => {
            sweep_stale_completed_conversion_log_batch_coordination_for_request_at_best_effort(
                req,
                output_root,
                context.as_str(),
            );
        }
        None => sweep_stale_completed_conversion_log_batch_coordination_for_request_best_effort(
            req,
            context.as_str(),
        ),
    }
    let completion_observed = album_batch_companion_finalization_signal(req, published)
        || album_batch_companion_durable_finalization_signal(
            req,
            published,
            coordination_io_dir,
        );

    if req.companion.is_empty() {
        if completion_observed {
            return batch_post_action_completion_gate_after_publish(req, published, coordination_io_dir);
        }
        return PostActionGate::NotReady;
    }

    record_album_batch_disc_destinations_from_artifacts(
        req,
        artifacts,
        published,
        binding,
        output_io_root,
    );
    if completion_observed {
        mark_companion_batch_finalization_pending_at_best_effort(
            req,
            output_io_root,
            context.as_str(),
        );
    }
    if !(completion_observed || companion_batch_finalization_pending_at(req, output_io_root)) {
        return PostActionGate::NotReady;
    }

    let source_dir = batch.source_grouping_root.clone();
    if companion_container_requires_dedicated_dir(&req.container)
        && !companion_dir_is_dedicated_to_container(&source_dir, &req.container)
    {
        log::info!(
            "companion copy skipped for {context}: source container {} sits in a shared directory ({}) that is not dedicated to it; companions come from inside the container only",
            req.container.display(),
            source_dir.display()
        );
        return batch_post_action_completion_gate_after_publish(req, published, coordination_io_dir);
    }
    let finalization_key = companion_batch_finalization_key(req, published, batch);
    let finalization_lock_dir = companion_batch_finalization_lock_dir_at(
        req,
        coordination_io_dir,
        output_io_root,
    )
        .unwrap_or_else(|| published.album_dir.clone());

    match with_album_publish_lock_for_companion_copy(&finalization_lock_dir, || {
        sweep_companion_batch_stale_temp_state_best_effort(&published.album_dir, context.as_str());

        if companion_batch_finalized_in_this_run(finalization_key.as_str()) {
            log::info!(
                "companion copy skipped for {}: batch already finalized in this conversion run",
                context
            );
            clean_companion_batch_transient_state_after_success_best_effort(&published.album_dir, context.as_str());
            clean_companion_batch_disc_destinations_after_success_at_best_effort(
                req,
                output_io_root,
                context.as_str(),
            );
            return batch_post_action_completion_gate_after_publish(req, published, coordination_io_dir);
        }

        let rendered_destinations = match companion_batch_disc_destinations_at(
            req,
            binding,
            output_io_root,
        ) {
            CompanionBatchDiscDestinationReadiness::Ready(destinations) => destinations,
            CompanionBatchDiscDestinationReadiness::Incomplete { observed, expected } => {
                mark_companion_batch_finalization_pending_at_best_effort(
                    req,
                    output_io_root,
                    context.as_str(),
                );
                log::warn!(
                    "companion copy finalization deferred for {}: durable rendered-path records are incomplete ({observed}/{expected}); pending marker retained so a later destination-record writer will retry finalization instead of relying on a one-shot last-track signal",
                    context
                );
                return PostActionGate::NotReady;
            }
            CompanionBatchDiscDestinationReadiness::Unavailable => {
                mark_companion_batch_finalization_pending_at_best_effort(
                    req,
                    output_io_root,
                    context.as_str(),
                );
                log::warn!(
                    "companion copy finalization deferred for {}: durable rendered-path records are unavailable; refusing to scan with recomputed disc destinations",
                    context
                );
                return PostActionGate::NotReady;
            }
        };

        record_album_batch_companion_scan_attempt();
        let source_file_skip_set = companion_batch_source_file_skip_set(&source_dir);
        let stats = copy_companion_artifacts_from_source_dir_best_effort(
            req,
            &source_dir,
            &published.album_dir,
            &source_file_skip_set,
            &rendered_destinations.disc_destinations,
            &rendered_destinations.album_dirs,
            context.as_str(),
        );

        if stats.is_fully_successful() {
            remember_companion_batch_finalized_in_this_run(finalization_key);
            clean_companion_batch_transient_state_after_success_best_effort(&published.album_dir, context.as_str());
            clean_companion_batch_disc_destinations_after_success_at_best_effort(
                req,
                output_io_root,
                context.as_str(),
            );
            batch_post_action_completion_gate_after_publish(req, published, coordination_io_dir)
        } else {
            mark_companion_batch_finalization_pending_at_best_effort(
                req,
                output_io_root,
                context.as_str(),
            );
            log::warn!(
                "companion copy not marked finalized for {}: scan/copy completed with {} warning(s); pending marker retained so a later finalizer call will rescan",
                context,
                stats.warnings
            );
            PostActionGate::Failed
        }
    }) {
        Ok(gate) => gate,
        Err(err) => {
            mark_companion_batch_finalization_pending_at_best_effort(
                req,
                output_io_root,
                context.as_str(),
            );
            log::warn!(
                "companion copy skipped for {}: could not acquire batch companion finalization lock for {}: {err}",
                context,
                finalization_lock_dir.display()
            );
            PostActionGate::Failed
        }
    }
}


fn companion_batch_finalization_lock_dir_at(
    req: &PipelineRequest,
    coordination_io_dir: Option<&Path>,
    output_io_root: Option<&Path>,
) -> Option<PathBuf> {
    coordination_io_dir
        .map(Path::to_path_buf)
        .or_else(|| companion_batch_disc_destination_records_dir_at(req, output_io_root))
}

fn with_album_publish_lock_for_companion_copy<T>(
    album_dir: &Path,
    operation: impl FnOnce() -> T,
) -> Result<T, PublishError> {
    let _publish_lock = acquire_publish_lock(album_dir)?;
    Ok(operation())
}

fn companion_batch_pending_finalization_path_at(
    req: &PipelineRequest,
    output_io_root: Option<&Path>,
) -> Option<PathBuf> {
    Some(
        companion_batch_disc_destination_records_dir_at(req, output_io_root)?
            .join(COMPANION_BATCH_PENDING_FINALIZATION_MARKER_FILE),
    )
}

#[allow(dead_code)] // bundle-provided API surface, not yet wired to a caller
fn companion_batch_finalization_pending(req: &PipelineRequest) -> bool {
    companion_batch_finalization_pending_at(req, None)
}

fn companion_batch_finalization_pending_at(
    req: &PipelineRequest,
    output_io_root: Option<&Path>,
) -> bool {
    companion_batch_pending_finalization_path_at(req, output_io_root)
        .is_some_and(|path| path.is_file())
}

#[allow(dead_code)] // bundle-provided API surface, not yet wired to a caller
fn mark_companion_batch_finalization_pending_best_effort(req: &PipelineRequest, context: &str) {
    mark_companion_batch_finalization_pending_at_best_effort(req, None, context)
}

fn mark_companion_batch_finalization_pending_at_best_effort(
    req: &PipelineRequest,
    output_io_root: Option<&Path>,
    context: &str,
) {
    let Some(path) = companion_batch_pending_finalization_path_at(req, output_io_root) else {
        return;
    };
    if let Some(parent) = path.parent() {
        if let Err(err) = fs::create_dir_all(parent) {
            log::warn!(
                "companion batch pending-finalization marker could not create {} for {}: {err}",
                parent.display(),
                context
            );
            return;
        }
    }

    let body = format!(
        "schema=1\nstate=pending\ncontext={}\n",
        context.replace('\n', " ").replace('\r', " ")
    );
    match fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(&path)
        .and_then(|mut file| {
            use std::io::Write;
            file.write_all(body.as_bytes())?;
            file.sync_all()
        }) {
        Ok(()) => sync_parent_dir_best_effort(&path),
        Err(err) => log::warn!(
            "companion batch pending-finalization marker could not write {} for {}: {err}",
            path.display(),
            context
        ),
    }
}

fn album_batch_companion_durable_finalization_signal(
    req: &PipelineRequest,
    published: &PublishedAlbum,
    coordination_io_dir: Option<&Path>,
) -> bool {
    if req.album_batch.is_none() {
        return false;
    }

    // Batch completion is coordinated in a stable output-root workspace keyed by
    // conversion_log_batch_id, not in whichever rendered album root this track
    // happened to publish. This keeps `%ALBUM% (CD%DISCNUMBER%)` from splitting
    // conversion-log completion and companion finalization by disc.
    if coordination_io_dir
        .map(|coord_dir| conversion_log_batch_is_durably_complete_at(req, coord_dir))
        .unwrap_or_else(|| conversion_log_batch_is_durably_complete(req))
    {
        return true;
    }

    // Compatibility for older/still-in-flight fragment layouts: a current
    // PublishedAlbum with a final conversion.log remains a completion signal.
    let _ = published;
    false
}

fn companion_batch_finalization_key(
    req: &PipelineRequest,
    _published: &PublishedAlbum,
    batch: &AlbumBatchContext,
) -> String {
    let extensions = normalized_companion_extension_set(&req.companion.extensions)
        .into_iter()
        .collect::<Vec<_>>()
        .join("\u{1f}");
    let folders = normalized_companion_folder_set(&req.companion.folders)
        .into_iter()
        .collect::<Vec<_>>()
        .join("\u{1f}");
    let excludes = normalized_companion_exclude_file_set(&req.companion.exclude_files)
        .into_iter()
        .collect::<Vec<_>>()
        .join("\u{1f}");

    let mut key = String::new();
    key.push_str("tonepoet-companion-batch-finalized-v3\n");
    push_finalization_key_line(
        &mut key,
        "conversion_log_batch_id",
        batch.conversion_log_batch_id.trim(),
    );
    push_finalization_key_line(&mut key, "source_grouping_root", &stable_finalization_path_value(&batch.source_grouping_root));
    push_finalization_key_line(&mut key, "output_root", &stable_finalization_path_value(&req.output_root));
    if let Some(coord_dir) = conversion_log_batch_coordination_album_dir(req) {
        push_finalization_key_line(&mut key, "coordination_root", &stable_finalization_path_value(&coord_dir));
    }
    push_finalization_key_line(&mut key, "expected_track_count", &batch.expected_track_count.to_string());
    push_finalization_key_line(&mut key, "extensions", &extensions);
    push_finalization_key_line(&mut key, "folders", &folders);
    push_finalization_key_line(&mut key, "exclude_files", &excludes);
    if let Some(identity) = batch.resolved_identity() {
        push_finalization_key_line(&mut key, "resolved_album", identity.album.as_deref().unwrap_or(""));
        push_finalization_key_line(&mut key, "resolved_album_artist", identity.album_artist.as_deref().unwrap_or(""));
        push_finalization_key_line(&mut key, "resolved_date", identity.date.as_deref().unwrap_or(""));
        push_finalization_key_line(
            &mut key,
            "resolved_total_discs",
            &identity.total_discs.map(|value| value.to_string()).unwrap_or_default(),
        );
        // NOTE: source_disc_numbers keys are now filesystem-*state*-dependent
        // (path_identity::filesystem_identity_key canonicalizes existing paths)
        // rather than the old purely-lexical lowercase form. This finalization
        // key is only compared in-process within a single run (its backing set
        // is a per-run OnceLock), so that state-dependence is harmless here. If
        // this coordination key is ever persisted to a cross-restart recovery
        // journal, revisit the derivation: a source moved/deleted between runs
        // would canonicalize differently (or fall back to lexical) and change
        // the key.
        for (path, disc) in &identity.source_disc_numbers {
            push_finalization_key_line(&mut key, "resolved_source_disc", &format!("{path}={disc}"));
        }
    }
    key
}

fn push_finalization_key_line(out: &mut String, key: &str, value: &str) {
    out.push_str(key);
    out.push('=');
    for ch in value.chars() {
        match ch {
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\\' => out.push_str("\\\\"),
            _ => out.push(ch),
        }
    }
    out.push('\n');
}

fn stable_finalization_path_value(path: &Path) -> String {
    normalize_path(path).to_string_lossy().replace('\\', "/")
}

fn companion_batch_finalized_keys() -> &'static Mutex<BTreeSet<String>> {
    static KEYS: std::sync::OnceLock<Mutex<BTreeSet<String>>> = std::sync::OnceLock::new();
    KEYS.get_or_init(|| Mutex::new(BTreeSet::new()))
}

fn companion_batch_finalized_in_this_run(key: &str) -> bool {
    companion_batch_finalized_keys()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .contains(key)
}

fn remember_companion_batch_finalized_in_this_run(key: String) {
    companion_batch_finalized_keys()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .insert(key);
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
struct CompanionBatchDiscDestinationRecord {
    schema_version: u8,
    track_id: TrackId,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    disc: Option<u32>,
    /// Directory where this track's audio payload rendered. For default disc
    /// subfolder layouts this is the disc directory (for example
    /// `Album/disc 01`); for user-authored per-disc album-folder layouts this
    /// is the rendered album root (for example `Album (CD1)`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    path: Option<PathBuf>,
    /// Rendered album root for this track. Album-level companion folders are
    /// copied to the deterministic set of these roots, not to whichever worker
    /// happened to observe batch completion.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    album_dir: Option<PathBuf>,
}

impl CompanionBatchDiscDestinationRecord {
    fn normalized(mut self) -> Self {
        self.path = self.path.map(|path| normalize_path(&path));
        self.album_dir = self.album_dir.map(|path| normalize_path(&path));
        self
    }
}

