    fn scheduler_cancel_batch_request(
        temp: &Path,
        batch_id: &str,
        item_id: &str,
        expected_track_count: usize,
    ) -> (PipelineRequest, PathBuf) {
        let album_dir = temp.join("out").join("Cancelled Album");
        let source_root = album_dir.join("source-root");
        std::fs::create_dir_all(&source_root).expect("cancel source root");
        std::fs::create_dir_all(temp.join("logs")).expect("cancel log root");
        let mut req = request(
            temp,
            FailurePolicy::FailAlbumOnAnyTrackFailure,
            stage_policy(false, false, false),
            OverwritePolicy::FailIfExists,
        );
        req.job_id = format!("job-{item_id}");
        req.item_id = item_id.to_string();
        req.container = source_root.join(format!("{item_id}.flac"));
        std::fs::write(&req.container, b"placeholder source").expect("cancel source file");
        req.output_root = temp.join("out");
        req.log.root = temp.join("logs");
        req.publish = incremental_test_publish_policy();
        req.album_batch = Some(AlbumBatchContext::new(
            generated_test_batch_id(batch_id),
            expected_track_count,
            album_dir.clone(),
            source_root,
        ));
        req.album_batch_track = Some(AlbumBatchTrackContext::new(2, Some(1), 2));
        (req, album_dir)
    }

    fn seed_scheduler_cancel_fragment(req: &PipelineRequest, album_dir: &Path, batch_id: &str) {
        let expected_track_count = req
            .album_batch
            .as_ref()
            .expect("batch context")
            .expected_track_count;
        let settings_fingerprint = tonepoet_pipeline::fingerprint::settings_fingerprint(&req.settings).to_string();
        let mut fragment = fragment_test_fragment(
            album_dir,
            batch_id,
            Some(settings_fingerprint.as_str()),
            1,
            expected_track_count,
            "Track 1\n  Result: ok\n",
            ConversionLogTrackOutcome::Success,
            fragment_test_time(1),
        );
        // Sibling fragments live in the stable batch coordination workspace;
        // the rendered album dir stays on fragment.rendered_album_dir so the
        // assembled partial log lands in the visible album root.
        let coord_dir = conversion_log_batch_coordination_album_dir(req)
            .expect("scheduler cancel fixtures carry a generated batch id");
        rebind_fragment_test_identity(
            &mut fragment,
            fragment_test_identity_for_request(req, &coord_dir, Some(settings_fingerprint.as_str())),
        );
        write_album_fragment(&coord_dir, "cancelled-existing-track-1.json", &fragment);
    }

    fn canonical_fragment_from_record(
        album_dir: &Path,
        _batch_id: &str,
        source: &PreparedSource,
        req: &PipelineRequest,
        artifacts: &ArtifactSet,
        outcome: &AlbumOutcome,
        record: &TrackRecord,
        generated_at: chrono::DateTime<chrono::Utc>,
    ) -> ConversionLogFragment {
        let source_tracks_by_ordinal = build_source_track_index(source);
        let artifacts_by_track_id = build_track_artifact_index(artifacts);
        let metadata_stage_result = metadata_stage_outcome(outcome);
        let mut section = String::new();
        append_track_log(
            &mut section,
            record,
            source_tracks_by_ordinal
                .get(&record.track_id.source_ordinal)
                .copied(),
            Some(source),
            artifacts_by_track_id.get(&record.track_id).copied(),
            req,
            metadata_stage_result,
        );

        ConversionLogFragment {
            version: CONVERSION_LOG_FRAGMENT_SCHEMA_VERSION,
            expected_track_count: req
                .album_batch
                .as_ref()
                .map(|batch| batch.expected_track_count)
                .expect("canonical fragment tests must use dispatcher album batch expected count"),
            sort_key: conversion_log_fragment_sort_key(req, &record.track_id)
                .expect("dispatcher track context supplies canonical fragment sort key"),
            generated_at,
            settings_fingerprint: None,
            batch_identity: fragment_test_identity_for_request(req, album_dir, None),
            rendered_album_dir: conversion_log_rendered_album_dir_for_track(source, req, artifacts, &record.track_id)
                .map(|path| normalize_path(&path).to_string_lossy().to_string()),
            common: build_conversion_log_common_fragment(outcome, source, req, artifacts),
            track: ConversionLogTrackFragment { section },
            summary: ConversionLogTrackSummary::from_track_record(record),
            stages: outcome_stage_records(outcome).to_vec(),
        }
    }

    fn incremental_fragment_test_plan(
        root: &Path,
        album_dir: &Path,
        stage_name: &str,
        fragment: &ConversionLogFragment,
        audio: Option<(&str, &[u8])>,
        _log_bytes: &[u8],
    ) -> (StagingDir, PublishPlan) {
        let staging = StagingDir::new(root.join(stage_name), stage_name.to_string());
        std::fs::create_dir_all(&staging.root).expect("fragment staging root");

        let mut entries = Vec::new();
        let source_audio_track_count = if audio.is_some() { 1 } else { 0 };
        if let Some((audio_name, audio_bytes)) = audio {
            let staged_audio = staging.root.join(audio_name);
            std::fs::write(&staged_audio, audio_bytes).expect("staged fragment-test audio");
            entries.push(PublishEntry {
                staged_path: staged_audio,
                final_path: album_dir.join(audio_name),
                role: PublishRole::Audio,
            });
        }

        let fragment_name = fragment_file_name(fragment);
        let staged_fragment = staging.root.join(&fragment_name);
        write_fragment_json(&staged_fragment, fragment);
        // The hidden fragment belongs to the batch namespace its identity
        // declares (the stable coordination dir in migrated fixtures), while
        // audio stays in the rendered album dir passed by the caller.
        let fragment_home = PathBuf::from(&fragment.batch_identity.output_album_dir);
        entries.push(PublishEntry {
            staged_path: staged_fragment,
            final_path: conversion_log_fragment_dir(&fragment_home).join(fragment_name),
            role: PublishRole::Sidecar(SidecarKind::Other(
                CONVERSION_LOG_FRAGMENT_SIDE_KIND.to_string(),
            )),
        });

        (
            staging,
            PublishPlan {
                album_dir: album_dir.to_path_buf(),
                entries,
                // Simulate the independent single-file job path: each publish
                // plan sees one current job, while the fragment carries the
                // album-level expected count.
                source_audio_track_count,
                expected_album_track_count: fragment.expected_track_count,
                suppress_incremental_conversion_log_append: false,
                album_batch_completion_order: false,
                write_conversion_log: true,
            },
        )
    }


    fn real_fragment_album_dir(temp: &Path) -> PathBuf {
        temp.join("out").join("Test Artist").join("Test Album")
    }

    fn real_fragment_source_root(temp: &Path) -> PathBuf {
        temp.join("source-root")
    }

    fn real_fragment_unbatched_request(
        temp: &Path,
        job_suffix: &str,
    ) -> PipelineRequest {
        let mut req = log_test_request();
        req.job_id = format!("job-{job_suffix}");
        req.item_id = format!("item-{job_suffix}");
        req.container = real_fragment_source_root(temp).join(format!("{job_suffix}.wav"));
        if let Some(parent) = req.container.parent() {
            std::fs::create_dir_all(parent).expect("real fragment source parent");
        }
        std::fs::write(&req.container, b"source audio placeholder")
            .expect("real fragment source file");
        req.output_root = temp.join("out");
        req.log.root = temp.join("logs");
        std::fs::create_dir_all(&req.output_root).expect("real fragment output root");
        std::fs::create_dir_all(&req.log.root).expect("real fragment log root");
        req.publish = incremental_test_publish_policy();
        req.album_batch = None;
        req.album_batch_track = None;
        req.expected_album_track_count = Some(9999);
        req
    }

    fn real_fragment_unbatched_request_with_track(
        temp: &Path,
        job_suffix: &str,
        source_ordinal: u32,
        disc_number: Option<u32>,
        track_number: u32,
    ) -> PipelineRequest {
        let mut req = real_fragment_unbatched_request(temp, job_suffix);
        req.album_batch_track = Some(AlbumBatchTrackContext::new(
            source_ordinal,
            disc_number,
            track_number,
        ));
        req
    }

    pub(super) fn generated_test_batch_id(label: &str) -> String {
        if is_generated_conversion_log_batch_id(label) {
            return label.to_string();
        }
        let label_hex = label
            .as_bytes()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        let label_hex = if label_hex.is_empty() { "00".to_string() } else { label_hex };
        format!("{CONVERSION_LOG_BATCH_ID_PREFIX}-74657374-{label_hex}-1")
    }

    pub(super) fn generated_current_process_test_batch_id(label: &str) -> String {
        if is_generated_conversion_log_batch_id(label) {
            return label.to_string();
        }
        let label_hex = label
            .as_bytes()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        let label_hex = if label_hex.is_empty() { "00".to_string() } else { label_hex };
        format!(
            "{CONVERSION_LOG_BATCH_ID_PREFIX}-{:x}-{label_hex}-1",
            std::process::id()
        )
    }

    fn real_fragment_dispatched_requests(
        temp: &Path,
        batch_id: &str,
        job_suffixes: &[&str],
    ) -> Vec<PipelineRequest> {
        let requests = job_suffixes
            .iter()
            .enumerate()
            .map(|(index, job_suffix)| {
                let ordinal = u32::try_from(index + 1).unwrap_or(u32::MAX);
                real_fragment_unbatched_request_with_track(temp, job_suffix, ordinal, None, ordinal)
            })
            .collect::<Vec<_>>();
        prepare_independent_single_file_album_batch_for_dispatch_with_batch_id(
            requests,
            generated_test_batch_id(batch_id),
            real_fragment_album_dir(temp),
            real_fragment_source_root(temp),
        )
        .expect("folder dispatcher wires album batch context")
        .requests
    }

    fn real_fragment_request(
        temp: &Path,
        batch_id: &str,
        expected_track_count: usize,
        job_suffix: &str,
    ) -> PipelineRequest {
        let mut suffixes = (1..expected_track_count)
            .map(|index| format!("{job_suffix}-batch-peer-{index}"))
            .collect::<Vec<_>>();
        suffixes.push(job_suffix.to_string());
        let suffix_refs = suffixes.iter().map(String::as_str).collect::<Vec<_>>();
        real_fragment_dispatched_requests(temp, batch_id, &suffix_refs)
            .into_iter()
            .find(|req| req.item_id == format!("item-{job_suffix}"))
            .expect("requested job is part of dispatcher-created album batch")
    }

    fn real_fragment_source(
        temp: &Path,
        disc_number: Option<u32>,
        track_number: u32,
        source_ordinal: u32,
        total_tracks_tag: u32,
    ) -> PreparedSource {
        let mut source = log_test_source();
        let source_root = real_fragment_source_root(temp);
        let disc_component = disc_number
            .map(|disc| format!("Disc {disc}"))
            .unwrap_or_else(|| "Disc 1".to_string());
        source.kind = SourceKind::SingleFile;
        source.container = source_root
            .join(disc_component)
            .join(format!("{track_number:02}.wav"));
        source.tracks.truncate(1);
        source.tracks[0].id = TrackId {
            source_ordinal,
            disc_number,
            track_number,
        };
        source.tracks[0].source_ref = TrackSourceRef::StagedFile(source.container.clone());
        source.tracks[0].metadata.title = Some(format!("Track {track_number}"));
        source.tracks[0].metadata.track_number = Some(track_number);
        source.tracks[0].metadata.disc_number = disc_number;
        source.album_metadata.album = Some("Test Album".to_string());
        source.album_metadata.album_artist = Some("Test Artist".to_string()).into();
        source.album_metadata.total_tracks = total_tracks_tag;
        source.album_metadata.disc_number = disc_number;
        source.provenance.source_kind = SourceKind::SingleFile;
        source
    }

    fn real_fragment_record(
        disc_number: Option<u32>,
        track_number: u32,
        source_ordinal: u32,
        ok: bool,
        output_file: Option<PathBuf>,
    ) -> TrackRecord {
        let mut record = if ok { ok_record() } else { failed_record() };
        record.track_id = TrackId {
            source_ordinal,
            disc_number,
            track_number,
        };
        record.source_ref = TrackSourceRef::StagedFile(PathBuf::from(format!(
            "/source/{track_number:02}.wav"
        )));
        record.realized_input = Some(PathBuf::from(format!("/realized/{track_number:02}.wav")));
        record.output_file = output_file;
        if ok {
            record.outcome = TrackOutcome::Ok;
            record.bytes_out = Some(1024 + u64::from(track_number));
            record.duration = Some(Duration::from_secs(60 + u64::from(track_number)));
            record.verified_output_bit_depth = None;
        } else {
            record.outcome = TrackOutcome::Err(format!("track {track_number} encode failed"));
            record.bytes_out = None;
            record.duration = None;
            record.commands = Vec::new();
        }
        record
    }

    fn real_fragment_audio_artifacts(
        staging: &StagingDir,
        album_dir: &Path,
        disc_number: Option<u32>,
        track_number: u32,
        source_ordinal: u32,
        audio_name: &str,
        audio_bytes: &[u8],
    ) -> ArtifactSet {
        let staged_audio = staging.root.join(audio_name);
        if let Some(parent) = staged_audio.parent() {
            std::fs::create_dir_all(parent).expect("real fragment staged audio parent");
        }
        std::fs::write(&staged_audio, audio_bytes).expect("real fragment staged audio");
        ArtifactSet {
            audio: AudioArtifacts::Tracks(vec![TrackArtifact {
                    reference_evidence: None,
                track_id: TrackId {
                    source_ordinal,
                    disc_number,
                    track_number,
                },
                staged_path: staged_audio,
                final_path: album_dir.join(audio_name),
                samples: Some(44_100),
                metadata_satisfaction: PlannedMetadataSatisfaction::none(),
                metadata_required: PlannedMetadataSatisfaction::none(),
                planned_command_hash: None,
            }]),
            sidecars: Vec::new(),
        }
    }

    fn real_fragment_empty_artifacts() -> ArtifactSet {
        ArtifactSet {
            audio: AudioArtifacts::Tracks(Vec::new()),
            sidecars: Vec::new(),
        }
    }

    async fn real_fragment_plan_through_features(
        temp: &Path,
        stage_name: &str,
        req: &PipelineRequest,
        source: &PreparedSource,
        outcome: &AlbumOutcome,
        artifacts: ArtifactSet,
    ) -> (StagingDir, PublishPlan) {
        let staging = StagingDir::new(temp.join(stage_name), stage_name.to_string());
        std::fs::create_dir_all(&staging.root).expect("real fragment feature staging root");
        let runner = crate::convert::pipeline::tool::StubToolRunner::new();
        let cancel = CancellationToken::new();
        let (staged, _features) = run_features(
            artifacts,
            outcome,
            source,
            req,
            &staging,
            &runner,
            &cancel,
        )
        .await
        .expect("real feature path stages conversion-log sidecars");
        let plan = build_publish_plan_for_fragment_or_fallback(&staged, req)
            .expect("real feature path builds publish plan from staged artifacts");
        (staging, plan)
    }

    async fn publish_successful_real_fragment_job(
        temp: &Path,
        batch_id: &str,
        expected_track_count: usize,
        stage_name: &str,
        job_suffix: &str,
        disc_number: Option<u32>,
        track_number: u32,
        source_ordinal: u32,
        total_tracks_tag: u32,
        audio_name: &str,
        audio_bytes: &[u8],
    ) -> (PipelineRequest, PublishPlan, PublishedAlbum) {
        let album_dir = real_fragment_album_dir(temp);
        std::fs::create_dir_all(temp.join("out")).expect("real fragment output root");
        let mut req = real_fragment_request(temp, batch_id, expected_track_count, job_suffix);
        req.album_batch_track = Some(AlbumBatchTrackContext::new(source_ordinal, disc_number, track_number));
        let source = real_fragment_source(
            temp,
            disc_number,
            track_number,
            source_ordinal,
            total_tracks_tag,
        );
        let staging = StagingDir::new(temp.join(format!("{stage_name}-audio")), format!("{stage_name}-audio"));
        std::fs::create_dir_all(&staging.root).expect("temporary artifact staging root");
        let artifacts = real_fragment_audio_artifacts(
            &staging,
            &album_dir,
            disc_number,
            track_number,
            source_ordinal,
            audio_name,
            audio_bytes,
        );
        let output_file = Some(album_dir.join(audio_name));
        let outcome = AlbumOutcome::Complete {
            tracks: vec![real_fragment_record(
                disc_number,
                track_number,
                source_ordinal,
                true,
                output_file,
            )],
            stages: stage_records(),
        };
        let (feature_staging, plan) = real_fragment_plan_through_features(
            temp,
            stage_name,
            &req,
            &source,
            &outcome,
            artifacts,
        )
        .await;
        let published = publish_album_output(feature_staging, &plan, req.publish.clone(), None)
            .expect("real fragment publish succeeds");
        (req, plan, published)
    }



    #[tokio::test]
    async fn per_disc_album_folder_independent_batch_uses_stable_completion_root_and_finalizes_companions() {
        let _global_state = companion_batch_global_state_test_lock();
        reset_album_batch_companion_scan_attempts();
        let temp = tempfile::tempdir().expect("temp dir");
        let source_root = temp.path().join("source");
        let out = temp.path().join("out");
        let log_root = temp.path().join("logs");
        let disc1 = source_root.join("CD 1");
        let disc2 = source_root.join("CD 2");
        std::fs::create_dir_all(&disc1).expect("disc 1");
        std::fs::create_dir_all(&disc2).expect("disc 2");
        std::fs::create_dir_all(&out).expect("output root");
        std::fs::create_dir_all(&log_root).expect("log root");
        let src1 = disc1.join("01.flac");
        let src2 = disc2.join("01.flac");
        std::fs::write(&src1, b"source audio 1").expect("source audio 1");
        std::fs::write(&src2, b"source audio 2").expect("source audio 2");
        std::fs::write(disc1.join("disc1.log"), b"disc one log").expect("disc 1 log");
        std::fs::write(disc2.join("disc2.log"), b"disc two log").expect("disc 2 log");

        let batch = AlbumBatchContext::from_dispatcher_source_count(
            generated_test_batch_id("per-disc-folder-completion"),
            2,
            out.join("WarGames"),
            source_root.clone(),
        )
        .expect("dispatcher batch")
        .with_resolved_identity(resolved_companion_test_identity(2));

        async fn publish_one_disc(
            temp: &Path,
            out: &Path,
            log_root: &Path,
            batch: &AlbumBatchContext,
            source_path: &Path,
            disc: u32,
            staged_audio_name: &str,
            audio_bytes: &[u8],
        ) -> (PipelineRequest, ArtifactSet, PublishedAlbum) {
            let mut req = log_test_request();
            req.job_id = format!("per-disc-folder-job-{disc}");
            req.item_id = format!("per-disc-folder-item-{disc}");
            req.container = source_path.to_path_buf();
            req.output_root = out.to_path_buf();
            req.log.root = log_root.to_path_buf();
            req.naming.template = "%TRACKNN%".to_string();
            req.naming.folder_template = Some("%ALBUM% (CD%DISCNUMBER%)".to_string());
            req.publish = incremental_test_publish_policy();
            req.companion.extensions = vec!["log".to_string(), "flac".to_string()];
            req.album_batch = Some(batch.clone());
            req.album_batch_track = Some(AlbumBatchTrackContext::new(disc, Some(disc), 1));

            let mut source = log_test_source();
            source.kind = SourceKind::SingleFile;
            source.container = source_path.to_path_buf();
            source.tracks.truncate(1);
            source.tracks[0].id = TrackId {
                source_ordinal: disc,
                disc_number: Some(disc),
                track_number: 1,
            };
            source.tracks[0].source_ref = TrackSourceRef::StagedFile(source_path.to_path_buf());
            source.tracks[0].metadata.title = Some(format!("Disc {disc} Track 1"));
            source.tracks[0].metadata.track_number = Some(1);
            source.tracks[0].metadata.disc_number = Some(disc);
            source.album_metadata.album = Some("WarGames".to_string());
            source.album_metadata.album_artist = Some("Arthur B. Rubinstein".to_string()).into();
            source.album_metadata.total_tracks = 2;
            source.album_metadata.total_discs = Some(2);
            source.album_metadata.disc_number = Some(disc);

            let plan = plan_outputs(&source, &req).expect("per-disc folder plan");
            assert_eq!(
                plan.album_dir,
                out.join(format!("WarGames (CD{disc})")),
                "folder template disc variable must choose the rendered per-disc album root"
            );
            let final_audio = plan.entries[0].final_path.clone();
            let artifact_staging = StagingDir::new(
                temp.join(format!("artifact-disc-{disc}")),
                format!("artifact-disc-{disc}"),
            );
            std::fs::create_dir_all(&artifact_staging.root).expect("artifact staging");
            let staged_audio = artifact_staging.root.join(staged_audio_name);
            std::fs::write(&staged_audio, audio_bytes).expect("staged audio");
            let artifacts = ArtifactSet {
                audio: AudioArtifacts::Tracks(vec![TrackArtifact {
                    reference_evidence: None,
                    track_id: TrackId {
                        source_ordinal: disc,
                        disc_number: Some(disc),
                        track_number: 1,
                    },
                    staged_path: staged_audio,
                    final_path: final_audio.clone(),
                    samples: Some(44_100),
                    metadata_satisfaction: PlannedMetadataSatisfaction::none(),
                    metadata_required: PlannedMetadataSatisfaction::none(),
                    planned_command_hash: None,
                }]),
                sidecars: Vec::new(),
            };
            let outcome = AlbumOutcome::Complete {
                tracks: vec![real_fragment_record(
                    Some(disc),
                    1,
                    disc,
                    true,
                    Some(final_audio),
                )],
                stages: stage_records(),
            };
            let feature_staging = StagingDir::new(
                temp.join(format!("feature-disc-{disc}")),
                format!("feature-disc-{disc}"),
            );
            std::fs::create_dir_all(&feature_staging.root).expect("feature staging");
            let runner = crate::convert::pipeline::tool::StubToolRunner::new();
            let cancel = CancellationToken::new();
            let (staged, _features) = run_features(
                artifacts,
                &outcome,
                &source,
                &req,
                &feature_staging,
                &runner,
                &cancel,
            )
            .await
            .expect("features stage stable batch fragment");
            assert!(
                staged.sidecars.iter().any(|sidecar| {
                    is_conversion_log_fragment_role(&PublishRole::Sidecar(sidecar.kind.clone()))
                        && sidecar.final_path.starts_with(out.join(CONVERSION_LOG_BATCH_COORDINATION_DIR))
                }),
                "hidden conversion-log fragment must be staged under the stable batch root, not the rendered album root"
            );
            let publish_plan = build_publish_plan(&staged, &req, &plan.album_dir)
                .expect("publish plan accepts stable batch fragment outside rendered album root");
            let published = publish_album_output(
                feature_staging,
                &publish_plan,
                req.publish.clone(),
                None,
            )
            .expect("independent per-disc job publishes");
            (req, staged, published)
        }

        let (req1, staged1, published1) = publish_one_disc(
            temp.path(),
            &out,
            &log_root,
            &batch,
            &src1,
            1,
            "disc1.flac",
            b"rendered audio 1",
        )
        .await;
        copy_album_batch_companion_artifacts_once_ready_best_effort(
            &req1,
            Some(&staged1),
            &published1,
        );
        assert_eq!(album_batch_companion_scan_attempts(), 0, "first disc alone must not finalize");

        let (req2, staged2, published2) = publish_one_disc(
            temp.path(),
            &out,
            &log_root,
            &batch,
            &src2,
            2,
            "disc2.flac",
            b"rendered audio 2",
        )
        .await;
        copy_album_batch_companion_artifacts_once_ready_best_effort(
            &req2,
            Some(&staged2),
            &published2,
        );

        assert!(out.join("WarGames (CD1)").join("01.flac").exists());
        assert!(out.join("WarGames (CD2)").join("01.flac").exists());
        assert_eq!(
            std::fs::read(out.join("WarGames (CD1)").join("disc1.log")).unwrap(),
            b"disc one log"
        );
        assert_eq!(
            std::fs::read(out.join("WarGames (CD2)").join("disc2.log")).unwrap(),
            b"disc two log"
        );
        assert!(!out.join("disc 01").exists());
        assert!(!out.join("disc 02").exists());
        // The durable completion marker exists between batch completion and
        // finalization cleanup; after a fully successful finalization the
        // coordination workspace (marker included) is removed by design. The
        // durable OUTCOME is the cleaned workspace plus the rendered logs.
        let coord_dir = conversion_log_batch_coordination_album_dir(&req2)
            .expect("per-disc batch coordination dir");
        // Companion finalization no longer cleans directly: retirement runs
        // through the per-worker terminal protocol — same migration as the
        // uncoordinated task-12 tests.
        let terminal_batch_id = req2
            .album_batch
            .as_ref()
            .expect("batch context")
            .conversion_log_batch_id
            .clone();
        write_conversion_log_batch_workspace_state(
            &coord_dir,
            &terminal_batch_id,
            CONVERSION_LOG_BATCH_WORKSPACE_STATUS_COMPLETE,
        )
        .expect("terminal workspace status");
        // Actionless batches never author drain authority; their cleanup
        // authority skips the drain lifecycle entirely.
        cleanup_conversion_log_batch_coordination_dir_after_success_best_effort(
            &coord_dir,
            "per-disc terminal cleanup",
            ConversionLogBatchCleanupAuthority::CurrentProcessOwnerActionless,
        );
        assert!(
            !coord_dir.exists(),
            "successful finalization cleans the per-dispatch coordination workspace"
        );
        assert!(
            out.join("WarGames (CD1)").join("conversion.log").is_file()
                && out.join("WarGames (CD2)").join("conversion.log").is_file(),
            "independent per-disc jobs assemble the visible log into every rendered album root"
        );
        assert_eq!(album_batch_companion_scan_attempts(), 1);

        copy_album_batch_companion_artifacts_once_ready_best_effort(
            &req1,
            Some(&staged1),
            &published1,
        );
        assert_eq!(
            album_batch_companion_scan_attempts(),
            1,
            "batch-scoped finalization key prevents duplicate scans from a different rendered album root"
        );
        assert_eq!(
            std::fs::read(out.join("WarGames (CD1)").join("disc1.log")).unwrap(),
            b"disc one log",
            "repeat finalizer invocation leaves companion bytes unchanged"
        );
    }


